import { getGlobalValueFromClient } from './request'
import { apiLog } from '../logs'
import { ipcMain } from 'electron'

// 获取当前的角标显示类型
async function getBadgeType() {
  const res = await getGlobalValueFromClient({ globalValueType: 'badge' })
  if (res.globalValue) return res.globalValue
  return 'seq'
}

// 获取角标的配置文字，默认seq，RPA直接返回
export async function getBadgeObject(config) {
  if (config.seq === 'RPA') {
    return {
      taskbarString: config.seq,
      toolbarString: config.seq
    }
  }

  let badgeType = await getBadgeType()
  let taskbarString = config.seq + ''
  let toolbarString = config.seq + ''
  switch (badgeType) {
    case 'name':
      taskbarString = (config.name && config.name.slice(0, 3)) || ''
      toolbarString = (config.name && config.name.slice(0, 10)) || ''
      break
    case 'remark':
      taskbarString = (config.remark && config.remark.slice(0, 3)) || ''
      toolbarString = (config.remark && config.remark.slice(0, 10)) || ''
      break
    case 'empty':
      taskbarString = ''
      toolbarString = ''
      break
    case 'sort':
      const str = config.sort + ''
      taskbarString = str.substring(str.length - 5)
      toolbarString = str.substring(str.length - 5)
      break
    case 'id':
      taskbarString = config.id.slice(-5, config.id.length)
      toolbarString = config.id.slice(-5, config.id.length)
      break
    default:
  }
  return {
    taskbarString,
    toolbarString
  }
}
