import Parser from 'stream-json'
import StreamArray from 'stream-json/streamers/StreamArray'
import { Readable, Transform } from 'stream'
import { apiLog } from '../logs'

// 1MB 阈值（降低阈值以避免 V8 OOM 崩溃，大于此值的数据使用流式解析）
const SIZE_THRESHOLD = 1 * 1024 * 1024

/**
 * 使用流式处理解析大型 JSON 字符串（自动判断数组/对象类型）
 * @param {string} jsonString - JSON 字符串
 * @returns {Promise<any>} 解析后的对象
 */
export async function streamJsonParse(jsonString) {
  // 如果数据较小（小于 1MB），直接使用原生 JSON.parse
  if (!jsonString || jsonString.length < SIZE_THRESHOLD) {
    const sizeKB = jsonString ? Math.round(jsonString.length / 1024) : 0
    apiLog.info(`[streamJsonParse] Using native JSON.parse for small data (${sizeKB}KB < 1MB)`)
    try {
      return JSON.parse(jsonString)
    } catch (err) {
      apiLog.error('[streamJsonParse] Native JSON.parse failed:', err)
      throw err
    }
  }

  // 自动判断是数组还是对象
  const trimmed = jsonString.trim()
  const isArray = trimmed.startsWith('[')
  const sizeMB = Math.round(jsonString.length / 1024 / 1024)
  apiLog.info(`[streamJsonParse] Using stream parsing for large data (${sizeMB}MB), type: ${isArray ? 'Array' : 'Object'}`)

  return new Promise((resolve, reject) => {
    try {
      const results = []

      // 创建可读流
      const stream = Readable.from([jsonString])

      // 根据数据类型选择不同的处理器
      if (isArray) {
        // StreamArray.withParser() 已经包含了 parser，直接使用
        const pipeline = stream.pipe(StreamArray.withParser())

        pipeline.on('data', ({ value }) => {
          results.push(value)
        })

        pipeline.on('end', () => {
          apiLog.info(`[streamJsonParse] Stream parsing completed successfully, parsed ${results.length} items`)
          resolve(results)
        })

        pipeline.on('error', err => {
          apiLog.error('[streamJsonParse] Stream parsing array error:', err.message)
          apiLog.warn('[streamJsonParse] Falling back to native JSON.parse')
          // 失败时回退到原生 JSON.parse
          try {
            const result = JSON.parse(jsonString)
            apiLog.info('[streamJsonParse] Fallback to native JSON.parse succeeded')
            resolve(result)
          } catch (parseErr) {
            apiLog.error('[streamJsonParse] Fallback also failed:', parseErr.message)
            reject(parseErr)
          }
        })
      } else {
        // 对象类型，直接用 parser 解析
        let result = null
        let depth = 0

        const pipeline = stream.pipe(Parser.parser())

        pipeline.on('data', data => {
          if (data.name === 'startObject' || data.name === 'startArray') {
            depth++
            if (depth === 1) {
              result = data.name === 'startObject' ? {} : []
            }
          }
        })

        pipeline.on('end', () => {
          // 如果流式解析失败，回退到 JSON.parse
          if (result === null) {
            apiLog.warn('[streamJsonParse] Stream parsing incomplete, falling back to native JSON.parse')
            try {
              result = JSON.parse(jsonString)
              apiLog.info('[streamJsonParse] Fallback succeeded')
            } catch (parseErr) {
              apiLog.error('[streamJsonParse] Fallback failed:', parseErr.message)
              reject(parseErr)
              return
            }
          } else {
            apiLog.info('[streamJsonParse] Stream parsing completed successfully for object')
          }
          resolve(result || JSON.parse(jsonString))
        })

        pipeline.on('error', err => {
          apiLog.error('[streamJsonParse] Stream parsing object error:', err.message)
          apiLog.warn('[streamJsonParse] Falling back to native JSON.parse')
          // 失败时回退到原生 JSON.parse
          try {
            const result = JSON.parse(jsonString)
            apiLog.info('[streamJsonParse] Fallback to native JSON.parse succeeded')
            resolve(result)
          } catch (parseErr) {
            apiLog.error('[streamJsonParse] Fallback also failed:', parseErr.message)
            reject(parseErr)
          }
        })
      }
    } catch (err) {
      apiLog.error('streamJsonParse setup error:', err)
      // 失败时回退到原生 JSON.parse
      try {
        resolve(JSON.parse(jsonString))
      } catch (parseErr) {
        reject(parseErr)
      }
    }
  })
}

/**
 * 快速估算数据 JSON 序列化后的大小（字节）
 * 基于数据结构长度的 O(1) 估算，用于判断是否需要使用流式处理
 * 采用保守估计策略：宁可多走流式解析也不要漏掉大数据
 * @param {any} data - 要估算的数据
 * @returns {number} 估算的大小（字节）
 */
function estimateDataSize(data) {
  if (!data) return 0

  // 数组：每个元素估算 250 字节（适用于 cookies 等结构化数据场景）
  // cookies 每条约 150-300 字节，取 250 作为保守估计
  if (Array.isArray(data)) {
    return data.length * 250 + 2 // + []
  }

  // 对象：每个属性估算 80 字节
  if (typeof data === 'object') {
    return Object.keys(data).length * 80 + 2 // + {}
  }

  // 字符串：长度 + 引号
  if (typeof data === 'string') {
    return data.length + 2
  }

  // 数字
  if (typeof data === 'number') {
    return 15
  }

  // 布尔值
  if (typeof data === 'boolean') {
    return 5
  }

  // 其他类型
  return 20
}

/**
 * 使用流式处理序列化大型对象为 JSON 字符串
 * @param {any} data - 要序列化的数据
 * @param {Object} options - 选项
 * @param {number} options.space - 缩进空格数，默认 0
 * @returns {Promise<string>} JSON 字符串
 */
export async function streamJsonStringify(data, options = {}) {
  const { space = 0 } = options

  // 如果数据为空或简单类型，直接序列化
  if (!data || typeof data !== 'object') {
    apiLog.info('[streamJsonStringify] Simple type data, using native JSON.stringify')
    return JSON.stringify(data, null, space)
  }

  // 估算数据大小
  const estimatedSize = estimateDataSize(data)
  const estimatedMB = (estimatedSize / 1024 / 1024).toFixed(2)

  // 如果估算小于 1MB，使用原生方法
  if (estimatedSize < SIZE_THRESHOLD) {
    apiLog.info(`[streamJsonStringify] Estimated size: ${estimatedMB}MB < 1MB, using native JSON.stringify`)
    try {
      return JSON.stringify(data, null, space)
    } catch (err) {
      // 原生方法失败，尝试流式处理
      apiLog.warn('[streamJsonStringify] Native JSON.stringify failed, trying stream method:', err.message)
    }
  } else {
    apiLog.info(`[streamJsonStringify] Estimated size: ${estimatedMB}MB >= 1MB, using stream method`)
  }

  return new Promise((resolve, reject) => {
    try {
      const chunks = []

      // 创建转换流
      const stringifyStream = new Transform({
        writableObjectMode: true,
        transform(chunk, encoding, callback) {
          try {
            this.push(JSON.stringify(chunk, null, space))
            callback()
          } catch (err) {
            callback(err)
          }
        }
      })

      stringifyStream.on('data', chunk => {
        chunks.push(chunk)
      })

      stringifyStream.on('end', () => {
        if (Array.isArray(data)) {
          // 数组类型，需要添加 [ 和 ]
          const result = '[' + chunks.join(',') + ']'
          const resultMB = (result.length / 1024 / 1024).toFixed(2)
          apiLog.info(`[streamJsonStringify] Stream stringify completed, result size: ${resultMB}MB`)
          resolve(result)
        } else {
          // 对象类型直接返回
          const result = chunks.join('')
          const resultMB = (result.length / 1024 / 1024).toFixed(2)
          apiLog.info(`[streamJsonStringify] Stream stringify completed, result size: ${resultMB}MB`)
          resolve(result)
        }
      })

      stringifyStream.on('error', err => {
        apiLog.error('[streamJsonStringify] Stream stringify error:', err.message)
        apiLog.warn('[streamJsonStringify] Falling back to native JSON.stringify')
        // 失败时回退到原生 JSON.stringify
        try {
          const result = JSON.stringify(data, null, space)
          apiLog.info('[streamJsonStringify] Fallback succeeded')
          resolve(result)
        } catch (stringifyErr) {
          apiLog.error('[streamJsonStringify] Fallback also failed:', stringifyErr.message)
          reject(stringifyErr)
        }
      })

      // 写入数据
      if (Array.isArray(data)) {
        // 逐个处理数组元素
        for (const item of data) {
          stringifyStream.write(item)
        }
      } else {
        stringifyStream.write(data)
      }

      stringifyStream.end()
    } catch (err) {
      apiLog.error('streamJsonStringify setup error:', err)
      // 失败时回退到原生 JSON.stringify
      try {
        resolve(JSON.stringify(data, null, space))
      } catch (stringifyErr) {
        reject(stringifyErr)
      }
    }
  })
}
