import { getClient } from './client'
import { apiLog } from '../logs'
import axios from 'axios'
import { getNeedsSystemCertificates } from '../utils/systemCertificates'
import https from 'https'

export async function getCacheFileData(url) {
  try {
    const db = await getClient()
    const dbRes = await db('cache_files').select('*').where({ url })

    if (dbRes.length) {
      // 如果存在，对比 last-modified，相同则直接返回data，不同则重新下载
      const obj = dbRes[0]

      const last_modified = obj.last_modified
      const headConfig = {}
      if (getNeedsSystemCertificates()) {
        headConfig.httpsAgent = https.globalAgent
      }
      const res = await axios.head(url, headConfig)

      // 如果head成功，且last_modified不一致时，重新下载一次缓存文件即可
      if (res.status === 200 && last_modified !== res.headers['last-modified']) {
        await saveCacheFile(url)
      }

      // 请求失败，也返回本地缓存文件即可
      return obj.data
    } else {
      // 没有缓存则下载
      await saveCacheFile(url)
    }
  } catch (err) {
    apiLog.error('get cache file data error ==>>>>> ', err)
  }
  return url
}

async function saveCacheFile(url) {
  try {
    const getConfig = { responseType: 'arraybuffer' }
    if (getNeedsSystemCertificates()) {
      getConfig.httpsAgent = https.globalAgent
    }
    const res = await axios.get(url, getConfig)
    if (res.status === 200) {
      const buffer = Buffer.from(res.data, 'binary')
      const data = 'data:image/png;base64,' + buffer.toString('base64')
      const db = await getClient()
      await db('cache_files').insert({ url, data, last_modified: res.headers['last-modified'] }).onConflict('url').merge()
      return data
    }
  } catch (err) {
    apiLog.error('save cache file error ==>>>> ', err)
  }
}
