const stringMap = new Map()

const fingerprintKey = Symbol()
stringMap.set(fingerprintKey, [98, 105, 116, 36, 50, 48, 50, 49])

const ossKey = Symbol()
stringMap.set(
  ossKey,
  [98, 53, 51, 98, 101, 50, 99, 54, 100, 53, 105, 115, 52, 49, 52, 97, 56, 51, 101, 54, 99, 52, 53, 48, 52, 57, 50, 50, 99, 53, 97, 51]
)

const bypassrulesKey = Symbol()
stringMap.set(
  bypassrulesKey,
  [53, 53, 51, 98, 101, 49, 99, 54, 100, 107, 105, 115, 52, 49, 52, 97, 56, 51, 101, 54, 99, 52, 53, 48, 52, 57, 50, 50, 99, 53, 97, 51]
)

const macaddressKey = Symbol()
stringMap.set(
  macaddressKey,
  [53, 53, 51, 98, 101, 49, 99, 54, 100, 98, 102, 57, 52, 49, 52, 97, 56, 51, 101, 54, 99, 52, 53, 48, 52, 57, 50, 50, 99, 53, 97, 50]
)

function getDectyptKey(key) {
  const codes = stringMap.get(key)
  return codes.reduce((acc, cur) => {
    acc = acc + String.fromCodePoint(cur)
    return acc
  }, '')
}

// 获取OSS加密的key
export function getOSSDecryptKey() {
  return getDectyptKey(ossKey)
}

export function getFingerprintDectyptKey() {
  return getDectyptKey(fingerprintKey)
}

export function getBypassrulesKey() {
  return getDectyptKey(bypassrulesKey)
}

export function getMacaddressDecryptKey() {
  return getDectyptKey(macaddressKey)
}
