import { ipcMain } from 'electron'
import schedule from 'node-schedule'
import { getRpaTaskList } from '../interface/request'
import { rpaLogs } from '../logs'
import rpaTaskPool from './pool'
import { RpaTask } from './task'
import { genRandomNum } from '../utils'

// 缓存 JobIds, 记录已经添加的 job，退出登录时，清空，重新登录时，再次扫描
const JobIds = new Set()

// 扫描任务
export async function scanRpaTasks() {
  const list = await getRpaTaskList()

  for (let item of list) {
    if (!schedule.scheduledJobs[item.taskId]) {
      addSchedule(item)
    }
  }
}

// 添加一个schedule，每次添加的时候，都取消掉ID相同的，立即执行的不记录
function addSchedule(taskItem) {
  cancelScheduleJob(taskItem.id)

  // 定时任务的开始时间已过，或者循环任务的结束时间已过，则不添加定时器
  if (taskItem.type === 'time' && new Date(taskItem.startTime).getTime() < Date.now()) return
  if (taskItem.type === 'interval' && new Date(taskItem.endTime).getTime() < Date.now()) return

  const rules = genRules(taskItem)

  rpaLogs.info('add schedule task ==>>> ', taskItem, rules)

  JobIds.add(taskItem.id)
  schedule.scheduleJob(taskItem.id, rules, () => {
    const rpaTask = new RpaTask(taskItem)
    rpaTaskPool.addTask(rpaTask)
  })
}

// 更新一个job
function updateScheduleJob(taskItem) {
  addSchedule(taskItem)
}

// 生成规则，秒随机，防止拥堵
function genRules(taskItem) {
  if (taskItem.type === 'time') return new Date(taskItem.startTime)
  let rule = ''
  // 将传入的时间字符串转换为日期对象，00秒开始，59秒结束，保证随机秒肯定在开始时间和结束时间内执行
  const startDate = new Date(taskItem.startTime + ':00')
  const endDate = new Date(taskItem.endTime + ':59')

  const randomSeconds = genRandomNum(1, 58) // 随机秒，防止都拥堵到整分钟
  const minutes = startDate.getMinutes()
  const hours = startDate.getHours()

  const increase = taskItem.intervalValue // 增量

  if (taskItem.intervalType === 'day') rule = `${randomSeconds} ${minutes} ${hours} */${increase} * *`
  if (taskItem.intervalType === 'hour') rule = `${randomSeconds} ${minutes} ${hours % increase}/${increase} * * *`
  if (taskItem.intervalType === 'minute') rule = `${randomSeconds} ${minutes % increase}/${increase} * * * *`

  return { start: startDate, end: endDate, rule }
}

// 取消一个job
function cancelScheduleJob(taskId) {
  JobIds.delete(taskId)
  schedule.cancelJob(schedule.scheduledJobs[taskId])
}

// 清理掉所有job
export function clearJobs() {
  JobIds.forEach(id => {
    cancelScheduleJob(id)
  })
}

ipcMain.on('update-rpa-schedule-job', (e, type, taskItem) => {
  if (type === 'add') addSchedule(taskItem)
  if (type === 'update') updateScheduleJob(taskItem)
  if (type === 'cancel') cancelScheduleJob(taskItem.id)
})

// 退出登录清理job
ipcMain.on('user-logout', () => {
  rpaLogs.info('on user logout ===>>>>>>> ')
  clearJobs()
})

// 登录用户，重新扫描jobs
ipcMain.on('user-login', (e, userInfo) => {
  rpaLogs.info('on user login ====>>>>>>>> ')
  scanRpaTasks()
})
