import { sshLogs } from '../logs'
import { isPortUsed } from '../server'
import crypto from 'crypto'
import socks from 'socksv5'
import { Client } from 'ssh2'

class ProxyValue {
  constructor() {
    this.port = null
    this.server = null
    this.conn = null
    this.browserIds = new Set()
  }

  // 添加代理，初次建立ssh代理时使用
  addProxy(port, browserId, server) {
    this.port = port
    this.server = server
    this.addBrowser(browserId)
  }

  // 往已有的代理配置里添加浏览器
  addBrowser(browserId) {
    this.browserIds.add(browserId)
  }

  delete(browserId) {
    this.browserIds.delete(browserId)
  }

  isEmpty() {
    return this.browserIds.size === 0
  }

  setConn(conn) {
    this.conn = conn
  }
}

class SSHProxy {
  // ssh 代理转socks5端口，端口从 5550 开始，不设上限
  constructor() {
    this.proxys = new Map() // 代理配置hash => ProxyValue
    this.currentPort = 5550
    this.portMap = new Map() // browserId => port ，防止错乱
  }

  // 启用代理，并返回socks5端口 isCheck => 是否是代理检测
  async getSocksPort(config) {
    const sshConfig = { host: config.host, port: config.port, username: config.proxyUserName, password: config.proxyPassword }
    const hashKey = crypto.createHash('md5').update(JSON.stringify(sshConfig)).digest('hex') // ssh配置生成hashKey，同样的配置使用同样的端口

    sshLogs.info('ssh proxy hash key ==>>>> ', hashKey)

    // 如果存在同样的配置，则直接返回，添加浏览器到使用相同端口的代理中
    if (this.proxys.has(hashKey)) {
      sshLogs.info('same ssh proxy config ==>>>> ', this.proxys.get(hashKey).port)

      const proxyValue = this.proxys.get(hashKey)
      proxyValue.addBrowser(config.id)

      return this.proxys.get(hashKey).port
    }

    await this.getPort(config.id)

    return new Promise((resolve, reject) => {
      const server = socks
        .createServer((info, accept, deny) => {
          // NOTE: you could just use one ssh2 client connection for all forwards, but
          // you could run into server-imposed limits if you have too many forwards open
          // at any given time
          const conn = new Client()
          conn
            .on('ready', () => {
              conn.forwardOut(info.srcAddr, info.srcPort, info.dstAddr, info.dstPort, (err, stream) => {
                if (err) {
                  // conn.end()
                  return deny()
                }

                const clientSocket = accept(true)
                if (clientSocket) {
                  stream
                    .pipe(clientSocket)
                    .pipe(stream)
                    .on('close', () => {
                      // conn.end()
                    })
                } else {
                  // conn.end()
                }

                // 设置 conn 对象
                this.proxys.get(hashKey).setConn(conn)
              })
            })
            .on('error', err => {
              deny()
              reject(err)
            })
            .connect(sshConfig)
        })
        .listen(this.portMap.get(config.id), '127.0.0.1', () => {
          const proxyValue = new ProxyValue()
          proxyValue.addProxy(this.portMap.get(config.id), config.id, server)

          this.proxys.set(hashKey, proxyValue)
          resolve(this.portMap.get(config.id))
        })
        .useAuth(socks.auth.None())
    })
  }

  // 检查端口是否被占用，并找到可用端口
  async getPort(browserId) {
    try {
      const isUsed = await isPortUsed(this.currentPort)

      if (isUsed) {
        this.currentPort++
        return this.getPort(browserId)
      }

      // 设置对应的port
      this.portMap.set(browserId, this.currentPort)

      return this.currentPort
    } catch (err) {
      sshLogs.error('current ssh port is used and get a nother port ==>>> ', this.currentPort)
    }
  }

  // 停止代理并删除信息
  destroy(config) {
    try {
      const sshConfig = { host: config.host, port: config.port, username: config.proxyUserName, password: config.proxyPassword }
      const hashKey = crypto.createHash('md5').update(JSON.stringify(sshConfig)).digest('hex')

      if (this.proxys.has(hashKey)) {
        const proxyValue = this.proxys.get(hashKey)
        proxyValue.delete(config.id)

        // 没有浏览器在使用的时候，则直接停掉端口
        if (proxyValue.isEmpty()) {
          this.proxys.delete(hashKey)

          proxyValue.server.close()
          proxyValue.conn.end()
        }
      }
    } catch (err) {
      sshLogs.error('destory ssh proxy error ==>>> ', err)
    }
  }
}

const sshProxy = new SSHProxy()

export { sshProxy }
