import Router from 'koa2-router'
import { ApiUtil } from '../interface/ApiUtil'
import browserTabs from '../interface/BrowserTabs'
import browserStatus from '../interface/browserStatus'
import { messages } from '../interface/Messages'
import { apiLog } from '../logs'

const tabsRouter = new Router()

// tabsRouter.use(async (ctx, next) => {
//   apiLog.info('tabs request url ==>>>> ', ctx.request.url, ctx.request.body)
//   await next()
// })

// 获取所有打开的tabs
tabsRouter.post('/tabs/list', async ctx => {
  const browserId = ctx.request.body.browserId
  if (!browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('Required', 'browserId')))
  const tabs = await browserTabs.getTabs(browserId)
  ctx.body = ApiUtil.success(tabs)
})

// 窗口内打开URL
tabsRouter.post('/tabs/openurl', async ctx => {
  const browserId = ctx.request.body.browserId
  const url = ctx.request.body.url
  const active = ctx.request.body.active
  if (!browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('NoBrowserID')))
  if (!url) return (ctx.body = ApiUtil.fail(messages.getMessage('NoOpenUrl')))
  if (typeof active !== 'boolean') return (ctx.body = ApiUtil.fail(messages.getMessage('BooleanType', 'active')))
  try {
    await browserStatus.openUrl(browserId, url, active)
  } catch (err) {
    apiLog.error('open url error ==>>> ', err)
    return (ctx.body = ApiUtil.fail(err.message))
  }
  ctx.body = ApiUtil.success()
})

// 打开多个url
tabsRouter.post('/tabs/openurls', async ctx => {
  const browserId = ctx.request.body.browserId
  const urls = ctx.request.body.urls
  const closeOthers = ctx.request.body.closeOthers
  if (!browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('NoBrowserID')))
  if (!urls || !Array.isArray(urls)) return (ctx.body = ApiUtil.fail(messages.getMessage('NoUrls')))
  if (closeOthers != null && typeof closeOthers !== 'boolean')
    return (ctx.body = ApiUtil.fail(messages.getMessage('BooleanType', 'closeOthers')))
  try {
    await browserStatus.openUrls(browserId, urls, closeOthers)
    ctx.body = ApiUtil.success()
  } catch (err) {
    apiLog.error('open urls error ==>>>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

// 关闭urls
tabsRouter.post('/tabs/close', async ctx => {
  const body = ctx.request.body
  if (!body.browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('NoBrowserID')))
  if (!body.urls) return (ctx.body = ApiUtil.fail(messages.getMessage('Required', 'urls')))
  if (!Array.isArray(body.urls)) return (ctx.body = ApiUtil.fail(messages.getMessage('ArrayType', 'urls')))
  try {
    await browserStatus.closeUrls(body.browserId, body.urls)
    ctx.body = ApiUtil.success(messages.getMessage('Success'))
  } catch (err) {
    apiLog.error('close browser urls error ==>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

// 除了指定url，其他都关闭
tabsRouter.post('/tabs/close/except', async ctx => {
  const body = ctx.request.body
  if (!body.url) return (ctx.body = ApiUtil.fail(messages.getMessage('Required', 'url')))
  if (!body.browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('NoBrowserID')))
  try {
    await browserStatus.closeTabsExcept(body.browserId, body.url)
    ctx.body = ApiUtil.success(messages.getMessage('Success'))
  } catch (err) {
    apiLog.error('close browser tabs except error ==>>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

// 关闭当前窗口
tabsRouter.post('/tabs/close/active', async ctx => {
  const body = ctx.request.body
  try {
    const browserIds = body.ids
    const keepSafe = body.keepSafe
    await browserStatus.closeActiveTabs(browserIds, keepSafe)
    ctx.body = ApiUtil.success()
  } catch (err) {
    apiLog.error('close browser tabs active error ==>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

// tabs去重
tabsRouter.post('/tabs/deduplication', async ctx => {
  const browserId = ctx.request.body.browserId
  if (!browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('NoBrowserID')))
  try {
    await browserStatus.pagesDeduplication(browserId)
    ctx.body = ApiUtil.success()
  } catch (err) {
    ctx.body = ApiUtil.fail(err.message)
  }
})

// 刷新
tabsRouter.post('/tabs/refresh', async ctx => {
  const body = ctx.request.body
  if (!body.browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('NoBrowserID')))
  if (!body.url) return (ctx.body = ApiUtil.fail(messages.getMessage('Required', 'url')))
  if (body.hasOwnProperty('ignoreCache') && typeof body.ignoreCache !== 'boolean')
    return (ctx.body = ApiUtil.fail(messages.getMessage('BooleanType', 'ignoreCache')))
  try {
    await browserStatus.pageReload(body.browserId, body.url, body.ignoreCache)
    ctx.body = ApiUtil.success()
  } catch (err) {
    apiLog.error('refresh url error ==>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

// 保存tabs
tabsRouter.post('/tabs/save', ctx => {
  const body = ctx.request.body
  browserTabs.setTabs(body.browserId, body.tabs)
  ctx.body = ApiUtil.success()
})

// 截图
tabsRouter.post('/screenshot', async ctx => {
  const browserId = ctx.request.body.browserId
  const path = ctx.request.body.path
  if (!browserId) return (ctx.body = ApiUtil.fail(messages.getMessage('NoBrowserID')))
  if (!path) return (ctx.body = ApiUtil.fail(messages.getMessage('ScreenshotPath')))
  try {
    await browserStatus.pageScreenshot(browserId, path)
    ctx.body = ApiUtil.success()
  } catch (err) {
    ctx.body = ApiUtil.fail(err.message)
  }
})

export default tabsRouter
