import { ipcMain } from 'electron'
import { sendSyncTask } from '../electron-main'
import { openOrClose, updateBrowserCookie } from './request'
import { apiLog, syncTaskLog } from '../logs'
import { uploadWebsiteCredentials } from './cacheSynchronization'

// taskID枚举
export const SyncTaskEnum = {
  uploadCookies: 'upload-cookies', // 上传cookie
  openBrowser: 'open-browser', // 打开窗口
  closeBrowser: 'close-browser', // 关闭窗口
  uploadWebsitesCredentials: 'websites-credentials' // 同步已保存的密码
}

class Task {
  constructor(seq, taskId, data, isApiUser) {
    this.seq = seq // 窗口序号
    this.taskId = taskId // 任务taskId
    this.data = data // 提交参数
    this.isApiUser = isApiUser // 是否api用户
  }
}

class SyncTasks {
  constructor() {
    this.tasks = [] // 正常的任务
    this.failTasks = [] // 运行失败的任务，正常任务运行完后，再将失败的任务放到正常任务里，用于下次执行
  }

  add(seq, taskId, data, isApiUser) {
    apiLog.info('add sync task ==>>> ', seq, taskId, data)
    const task = new Task(seq, taskId, data, isApiUser)
    this.tasks.push(task)

    sendSyncTask({ seq, taskId, type: 'add' })
  }

  allTasks() {
    return this.tasks
  }

  clearTasks() {
    this.tasks = []
    this.failTasks = []
  }

  // 接收到界面上的指令时，立即执行，不管重试了几次
  async run() {
    if (!this.tasks.length) return

    while (this.tasks.length) {
      const task = this.tasks.shift()

      try {
        // 同步cookie
        if (task.taskId === SyncTaskEnum.uploadCookies) {
          await updateBrowserCookie(task.data, task.isApiUser)
        }

        // 同步浏览器状态
        if (task.taskId === SyncTaskEnum.openBrowser || task.taskId === SyncTaskEnum.closeBrowser) {
          apiLog.info('close browser task ==>>>> ', task)
          await openOrClose(task.data, task.isApiUser)
        }

        // 用户名密码上传失败
        if (task.taskId === SyncTaskEnum.uploadWebsitesCredentials) {
          await uploadWebsiteCredentials(task.data.browserId, task.data.seq, task.data.randomKey)
        }

        // 发送任务到界面
        sendSyncTask({ seq: task.seq, taskId: task.taskId, type: 'delete' })
      } catch (err) {
        syncTaskLog.error('run sync task error ==>>>> ', err.message)
        this.failTasks.push(task)
      }
    }

    // 将失败的任务重新加回tasks
    this.tasks.push(...this.failTasks)
    this.failTasks = []
  }
}

const syncTasks = new SyncTasks()

export default syncTasks

ipcMain.handle('run-sync-tasks', () => syncTasks.run())
ipcMain.handle('get-all-sync-tasks', () => syncTasks.allTasks())
ipcMain.on('clear-all-sync-tasks', () => syncTasks.clearTasks())
