// 检查浏览器是否需要代理检测，需要的话，返回检测的url
userRouter.post('/browser/proxyCheck', async ctx => {
  const browserId = ctx.request.body.id
  const config = browserStatus.getBrowserConfig(browserId)
  try {
    if (config.proxyType === 'noproxy') {
      ctx.body = ApiUtil.success({
        needCheck: true,
        url: `${globalSetting.getServiceLine()}/v1/apis/ipgeoMethod`
      })
      return
    } else {
      const ipInfo = await checkAgentIpData(config)
      if (ipInfo.success) {
        const ipData = ipInfo.data
        // 代理页面获取IP信息成功后，同步此次的IP和Country
        syncLastIp(browserId, ipData.ip, ipData.countryName)
      }
    }
  } catch (err) {
    apiLog.error('browser proxy check error ==>>>> ', err)
  }
  ctx.body = ApiUtil.success({ needCheck: false })
})

