// 代理请求
userRouter.post('/proxy-request', async ctx => {
  const url = ctx.request.body.url
  const axiosConfig = {
    method: 'get',
    url: url
  }
  if (getNeedsSystemCertificates()) {
    axiosConfig.httpsAgent = https.globalAgent
  }
  const res = await axios(axiosConfig)
  if (res.status === 200) {
    ctx.body = ApiUtil.success(res.data)
  } else {
    ctx.body = ApiUtil.fail(`status: ${res.status}, data: ${JSON.stringify(res.data)}`)
  }
})

userRouter.post('/utils/readexcel', async ctx => {
  const filepath = path.resolve(ctx.request.body.filepath)
  const exists = await pathExists(filepath)
  if (!exists) {
    throw new Error('file not exist.')
  }

  // 检查是否在安装目录下
  const appPath = app.getAppPath()
  if (filepath.startsWith(appPath)) {
    throw new Error('Cannot read files from installation directory')
  }

  // 检查是否在userData目录下
  const userDataPath = app.getPath('userData')
  if (filepath.startsWith(userDataPath)) {
    throw new Error('Cannot read files from userData directory')
  }

  const sheets = xlsx.parse(filepath)
  ctx.body = ApiUtil.success(sheets)
})

userRouter.post('/utils/readfile', async ctx => {
  const filepath = path.resolve(ctx.request.body.filepath)
  const exists = await pathExists(filepath)
  if (!exists) {
    throw new Error('file not exist.')
  }

  // 检查是否在安装目录下
  const appPath = app.getAppPath()
  if (filepath.startsWith(appPath)) {
    throw new Error('Cannot read files from installation directory')
  }

  // 检查是否在userData目录下
  const userDataPath = app.getPath('userData')
  if (filepath.startsWith(userDataPath)) {
    throw new Error('Cannot read files from userData directory')
  }

  const content = await readFile(filepath)
  ctx.body = ApiUtil.success(content.toString())
})

