userRouter.post('/utils/sendCommand', ctx => {
  const reqBody = ctx.request.body

  const event = reqBody.event
  const payload = reqBody.payload
  const focus = reqBody.focusMainWindow

  if (focus) {
    focusMainWindow()
  }

  sendCustomCommand({ event, data: payload })

  ctx.body = ApiUtil.success()
})

userRouter.post('/utils/blockedCNDomains', async ctx => {
  const domains = await getBlockedCNDomains()
  ctx.body = ApiUtil.success(domains)
})

userRouter.get('/utils/thirdLogin', ctx => {
  const params = ctx.request.query

  apiLog.info('third login ==>>>> ', params)

  // 获取重定向地址
  const redirectParam = params.redirect || params.redirect_uri || params.return_url
  const redirectUrl = redirectParam && redirectParam.trim() ? decodeURIComponent(redirectParam) : null

  sendThirdLoginMsg(params)

  // 如果传入了重定向地址，则进行重定向
  if (redirectUrl) {
    // 给重定向地址添加 isRedirect=1 参数
    const separator = redirectUrl.includes('?') ? '&' : '?'
    const redirectWithParam = `${redirectUrl}${separator}isRedirect=1`
    ctx.redirect(redirectWithParam)
  } else {
    ctx.body = ApiUtil.success()
  }
})

