import EventEmitter from 'events'
import path from 'path'
import axios from 'axios'
import fs from 'fs-extra'
import throttle from 'lodash/throttle'
import { log } from '../logs'
import crypto from 'crypto'
import { sendDownloadFileProgress } from '../electron-main'
import { rimraf } from 'rimraf'
import { getNeedsSystemCertificates } from '../utils/systemCertificates'
import https from 'https'

// 保存正在下载的文件
const Pool = new Map()

export class DownloadService extends EventEmitter {
  constructor(url, dest) {
    super()

    log.info('download ==========>>>>>>>>>>>>> ', url, dest)

    this.url = url
    this.dest = path.resolve(dest)

    const hash = crypto.createHash('sha256')
    hash.update(url + dest)
    this.hashKey = hash.digest().toString('hex')
  }

  // 检查是否为HTTP URL
  isHttpUrl(url) {
    return url.startsWith('http://')
  }

  // 将HTTP URL转换为HTTPS
  convertToHttps(url) {
    return url.replace('http://', 'https://')
  }

  // 执行下载请求
  async performDownload(url) {
    return new Promise((resolve, reject) => {
      const axiosConfig = {
        method: 'get',
        url: url,
        responseType: 'stream',
        timeout: 0
      }

      // 如果存在证书问题标记，使用全局 agent（包含合并后的系统证书）
      if (getNeedsSystemCertificates()) {
        axiosConfig.httpsAgent = https.globalAgent
      }

      axios(axiosConfig)
        .then(res => {
          const writer = fs.createWriteStream(this.dest)
          res.data.pipe(writer)

          const _throttle = throttle(progress => {
            this.fireProgress(progress)
          }, 200)

          const totalLength = parseInt(res.headers['content-length'])
          let downloadedLength = 0

          writer.on('error', e => {
            log.error('download file writer errorr ==>>>>>>>> ', e)
            reject(e.message)
          })

          res.data.on('data', chunk => {
            downloadedLength += chunk.length

            const progress = (100 * downloadedLength) / totalLength

            // 100 由 finished发送
            if (progress < 100) {
              _throttle(progress)
            }
          })

          writer.on('finish', () => {
            if (totalLength === downloadedLength) {
              _throttle(100)

              Pool.delete(this.hashKey)
              resolve()
            } else {
              this.clearErrorFile()

              reject('chunk losed')
            }
          })

          res.data.on('error', e => {
            log.error('download file error => ', e)

            writer.end()

            this.clearErrorFile()

            reject(e.message)
          })
        })
        .catch(err => {
          log.error('download file request error ===>>>>>> ', err.message)
          reject(err)
        })
    })
  }

  async start() {
    if (!this.url || !this.dest) {
      throw new Error('url and dest required.')
    }

    const isDirectory = fs.pathExistsSync(this.dest) && fs.statSync(this.dest).isDirectory()

    if (isDirectory) {
      throw new Error('the dest must be a file path.')
    }

    if (Pool.has(this.url)) {
      return Pool.get(this.url)
    }

    // 缓存当前实例
    Pool.set(this.hashKey, this)

    try {
      // 首先尝试原始URL
      await this.performDownload(this.url)
      return
    } catch (error) {
      log.warn(`Download failed with original URL, trying fallback ==>>> ${this.url}`, error.message)

      // 如果原始URL是HTTP，尝试HTTPS
      if (this.isHttpUrl(this.url)) {
        const httpsUrl = this.convertToHttps(this.url)
        log.info(`HTTP download failed, trying HTTPS: ${httpsUrl}`)

        try {
          await this.performDownload(httpsUrl)
          return
        } catch (httpsError) {
          log.error('HTTPS download also failed ===>>>>>> ', httpsError.message)
          Pool.delete(this.hashKey)
          throw httpsError
        }
      }
      // 其他情况直接失败
      else {
        log.error('download failed ===>>>>>> ', error.message)
        Pool.delete(this.hashKey)
        throw error
      }
    }
  }

  // 进度提示
  fireProgress(rate) {
    log.info('download progress ==>>>>> ', rate, this.hashKey)
    this.emit(DownloadService.EventMap.progress, rate)
    sendDownloadFileProgress({ rate, url: this.url })
  }

  async clearErrorFile() {
    try {
      Pool.delete(this.hashKey)
      await rimraf(this.dest, { maxRetries: 5 })
    } catch (err) {
      log.error('clear download file error ==>>>>> ', err)
    }
  }

  static EventMap = {
    progress: 'progress',
    finished: 'finished'
  }
}
