import { getClient } from './client'
import { apiLog } from '../logs'
import { safeJsonParse } from '../utils/safeJsonParse'

const Table = 'browser_persistent_data'
export const BrowserPersistentDataType = {
  Bounds: 'BOUNDS'
}

export async function getBrowserPersistentData({ browserId, type } = {}) {
  if (!browserId || !type) return null

  try {
    const db = await getClient()
    const res = await db(Table).select('*').where({ browser_id: browserId, type })
    if (res.length) {
      const value = res[0].value
      const valueType = res[0].value_type
      return valueType === 'json' ? safeJsonParse(value, `getBrowserPersistentData:${type}`) : value
    }
    return null
  } catch (err) {
    apiLog.error('get browser persistent data error ==>>> ', err)
  }
  return null
}

export async function saveBrowserPersistentData({ browserId, type, value, valueType = 'json' } = {}) {
  if (!browserId || !type || !value) return false

  try {
    const db = await getClient()
    await db(Table)
      .insert({
        browser_id: browserId,
        type,
        value: valueType === 'json' ? JSON.stringify(value) : value,
        value_type: valueType,
        update_time: new Date()
      })
      .onConflict(['browser_id', 'type'])
      .merge()
    return true
  } catch (err) {
    apiLog.error('save browser persistent data error ==>>> ', err)
  }
  return false
}

export async function deleteBrowserPersistentData({ browserId, type } = {}) {
  if (!browserId || !type) return false

  try {
    const db = await getClient()
    await db(Table).delete().where({ browser_id: browserId, type })
    return true
  } catch (err) {
    apiLog.error('delete browser persistent data error ==>>> ', err)
  }
}
