import { getClient } from './client'
import { apiLog } from '../logs'

export async function updateChromeVersion(chrome, version) {
  try {
    const db = await getClient()
    await db('chrome_versions').insert({ chrome, version }).onConflict('chrome').merge()
  } catch (err) {
    apiLog.error('update chrome app version ==>>> ', err)
  }
}

export async function getChromeAppVersions() {
  try {
    const db = await getClient()
    const res = await db('chrome_versions').select('*')
    return res
  } catch (err) {
    apiLog.error('get chrome app versions error ==>>> ', err)
  }
  return []
}

export async function getChromeByCoreVersion(coreVersion) {
  try {
    const db = await getClient()
    const res = await db('chrome_versions').select('*').where('chrome', '=', coreVersion)
    if (res.length) return res[0]
  } catch (err) {
    apiLog.error('get chrome by core version error ==>>> ', err)
  }
  return null
}
