import { getClient } from './client'
import { apiLog } from '../logs'

// 添加本地扩展
export async function addLocalExtension(info) {
  try {
    apiLog.info('local extension info ==>>>> ', info)
    const db = await getClient()
    await db('local_extensions')
      .insert({
        name: info.name,
        version: info.version,
        desc: info.desc,
        icon: info.icon || '',
        extension_id: info.id,
        is_use: info.isUse,
        cloud_id: info.cloud_id,
        main_user_id: info.mainUserId
      })
      .onConflict('extension_id')
      .merge()
  } catch (err) {
    apiLog.error('save local extension to db error ==>>> ', err)
  }
}

// 启用/禁用本地扩展
export async function changeExtensionIsUse(extensionId, isUse) {
  apiLog.info('change local extension is use ==>>> ', extensionId, isUse)
  try {
    const db = await getClient()
    await db('local_extensions').insert({ extension_id: extensionId, is_use: isUse }).onConflict('extension_id').merge()
  } catch (err) {
    apiLog.error('change extension isUse error ==>>> ', isUse)
  }
}

// 更新clou_id
export async function updateCloudId(extensionId, cloudId, mainUserId) {
  try {
    const db = await getClient()
    await db('local_extensions')
      .insert({ extension_id: extensionId, cloud_id: cloudId, main_user_id: mainUserId })
      .onConflict('extension_id')
      .merge()
  } catch (err) {
    apiLog.error('update cloud id error ==>>>> ', err)
  }
}

// 删除本地扩展
export async function deleteLocalExtension(extensionId) {
  try {
    const db = await getClient()
    await db('local_extensions').delete('*').where('extension_id', '=', extensionId)
  } catch (err) {
    apiLog.error('delete local extension error ==>>> ', extensionId)
  }
}

// 获取本地扩展列表
export async function getLocalExtensionList() {
  try {
    const db = await getClient()
    const res = await db('local_extensions').select('*')
    return res
  } catch (err) {
    apiLog.info('get local extension list error  ===>>>> ', err)
  }
  return []
}

