// 检查是否已存在相同名字和版本的扩展
export async function ifExists(name, version, mainUserId) {
  try {
    const db = await getClient()
    const res = await db('local_extensions').select('*').where({
      name,
      version,
      main_user_id: mainUserId
    })
    return res.length > 0
  } catch (err) {
    apiLog.info('check extension exists error  ===>>>> ', err)
  }
  return false
}

// 通过extensionId检查是否存在，识别Google扩展时用到
export async function ifExistsById(extensionId) {
  try {
    const db = await getClient()
    const res = await db('local_extensions').select('*').where('extension_id', '=', extensionId)
    return res.length > 0
  } catch (err) {
    apiLog.info('check extension exists by id error  ===>>>> ', err)
  }
  return false
}

// 检查对应版本扩展是否存在
export async function ifVersionExists(extensionId, version) {
  try {
    const db = await getClient()
    const res = await db('local_extensions').select('*').where('extension_id', '=', extensionId).andWhere('version', '=', version)
    return res.length > 0
  } catch (err) {
    apiLog.info('check extension exists by id error  ===>>>> ', err)
  }
  return false
}

// 获取扩展信息
export async function getLocalExtensionInfo(extensionId) {
  try {
    const db = await getClient()
    const res = await db('local_extensions').select('*').where('extension_id', '=', extensionId)
    if (res.length) return res[0]
  } catch (err) {}
  return {}
}
