import { messages } from '../interface/Messages'
import { apiLog } from '../logs'
import { sleep } from '../utils'

// [{timeId, fn}, ...]
const stack = []
let running = false
let lastRunningTime = null

// browser/open 接口做队列处理，防止并发过高，挨个打开窗口，最多等待1秒，传入queue为true后，按照队列处理
export function openingQueue() {
  return async (ctx, next) => {
    if (ctx.request.url !== '/browser/open' || !ctx.request.body.queue) {
      await next()
    } else {
      if (stack.length > 200) {
        ctx.status = 429
        ctx.throw(ctx.status, messages.getMessage('outofQueue'))
        return
      }

      apiLog.info('browser open stack ===>>>>> ', ctx.request.body.id, stack.length)

      if (stack.length > 0) {
        const p = new Promise(resolve => {
          const obj = { timeId: null, resolve } // 构建对象，保持引用，则 setTimeout 可以重置此对象属性

          const timeout = 1000 * stack.length
          obj.timeId = setTimeout(() => {
            apiLog.info('resolve timeout ==>>>>>>>> ', timeout)
            resolve()

            obj.timeId = null
            obj.resolve = null
          }, timeout) // x秒钟后，自动resolve，每来一个请求，延迟一秒

          stack.push(obj)
        })
        await p
      } else {
        // 第一个排队的无需等待，直接跳过即可
        stack.push({ timeId: null, resolve: null })
      }

      await next()

      await handleResolve()
    }
  }
}

// 保持独立处理程序，保持队列
async function handleResolve() {
  if (!stack.length || running) return

  running = true

  let target

  // 清空已执行的
  while (stack.length) {
    target = stack.shift()

    if (!target.timeId || !target.resolve) continue

    // resolve掉等待的
    clearTimeout(target.timeId)

    // 上一次调用距离当前小于100毫秒时，等待200毫秒再执行，防止引起并发错误
    if (lastRunningTime && Date.now() - lastRunningTime < 100) {
      await sleep(0.5)
    }

    target.resolve?.()
    lastRunningTime = Date.now()

    apiLog.info('open browser finished ===========>>>>>>>>>>>> ', stack.length)
  }

  if (!stack.length) running = false
}
