import { scheduledJobs, cancelJob } from 'node-schedule'
import { wakeupAndReconnectToBrowser } from '../browser'
import { resumeLogs } from '../logs'
import browserStatus from './browserStatus'
import { registerSchedules } from '../tasks/schedule'
import { scanRpaTasks } from '../rpa/schedule'

// 进入睡眠
let sleeping = false

// 进入睡眠
export function goingToSleep() {
  sleeping = true
  resumeLogs.info('computer are going to sleep and suspend.')

  // 睡眠时取消掉所有的定时任务
  const JobIds = Object.keys(scheduledJobs)
  resumeLogs.info('cancel jobs ==>>> ', JobIds)
  JobIds.forEach(jobId => cancelJob(jobId))
}

// 计算机唤醒
export async function wakeup() {
  sleeping = false

  const configs = browserStatus.getOpenedBrowserConfigs().values()
  for (let config of configs) {
    wakeupAndReconnectToBrowser(browserStatus.getBrowser(config.id).wsEndpoint(), config)
  }

  // 连接手机
  // for (const cfg of phoneStatus.opened_browsers_configs.values()) {
  //   wakeupAndReconnectToPhone(phoneStatus.getBrowser(cfg.id).wsEndpoint(), cfg)
  // }

  // 重新注册一遍定时器
  registerSchedules()
  scanRpaTasks()
}

// 是否进入睡眠了
export function computerSleeping() {
  return sleeping
}
