import { app } from 'electron'
import { getTimeOfPinToTaskbar, saveTimeOfPinToTaskbar } from '../data/globalConfigs'
import { taskbarLog } from '../logs'
import path from 'path'
import { pathExists } from 'fs-extra'
import { execCmd } from '../utils'

// 固定到任务栏
export async function pinToTaskbar() {
  try {
    // Windows才设置
    if (process.platform !== 'win32') return

    // 上一次设置的时间还不到3天，不用设置
    const lastTime = await getTimeOfPinToTaskbar()
    if (lastTime && lastTime + 3 * 24 * 60 * 60 > Date.now() / 1000) return

    // 首先保存本次设置的时间
    await saveTimeOfPinToTaskbar(Date.now() / 1000)

    const linkOrExe = await getLnkOrExePath()
    taskbarLog.info('lnk or exe path ==>>> ', linkOrExe)

    const stdout = await execCmd(`MenuTask.exe "${linkOrExe}"`, {
      cwd: process.env.DEV ? path.resolve(__dirname, '../../utils') : path.resolve(process.resourcesPath, 'utils')
    })

    if (stdout) taskbarLog.info('stdout ==>>> ', stdout)
  } catch (err) {
    taskbarLog.error('pin to taskbar error ==>>> ', err)
  }
}

/**
 * @description 获取快捷方式或者exe路径，不存在快捷方式则返回exe路径
 * @return {Promise<String>} path 返回路径地址
 * */
async function getLnkOrExePath() {
  const exePath = app.getPath('exe')

  try {
    // 安装目录下存在快捷方式，则直接返回
    let linkPath = path.resolve(app.getPath('exe'), '../bitlink.lnk')
    let exist = await pathExists(linkPath)
    if (exist) return linkPath

    // 桌面存在快捷方式，则直接返回
    const desktopLink = path.join(app.getPath('desktop'), path.basename(exePath).split('.').shift() + '.lnk')
    const desktopExists = await pathExists(desktopLink)
    if (desktopExists) return desktopLink
  } catch (err) {
    taskbarLog.error('get link or exe path error ===>>> ', err)
  }
  return exePath
}
