// 打开手机检查绑定状态
async function checkBinding(id) {
  try {
    await request({ url: '/v1/cloudphone/cloudPhonesEvn/checkBinding/' + id, method: 'get' })
  } catch (error) {
    phoneLog.info(error, '--error')

    if (error && error.code === 16187) {
      await request({
        url: '/v1/cloudphone/cloudPhonesEvn/close',
        method: 'post',
        data: {
          id,
          isRelease: 0
        }
      })
      await request({ url: '/v1/cloudphone/cloudPhonesEvn/checkBinding/' + id, method: 'get' })
    } else {
      throw new Error(error.message)
    }
  }
}

phoneRouter.post('/phone/openphone', paramRequired('id'), async ctx => {
  let id = ctx.request.body.id

  if (phoneStatus.isOpening(id)) {
    throw new Error(messages.getMessage('phoneOpening'))
  }
  if (phoneStatus.isClosing(id)) {
    throw new Error(messages.getMessage('phoneClosing'))
  }

  let detailRes = await request({
    url: '/v1/cloudphone/cloudPhonesEvn/' + id,
    method: 'get'
  })

  const token = await getAppToken()
  const listeningPort = await getLocalServerPort()
  const locale = await getLocaleFromDB()
  let line = await getServiceLineFromDB()

  // 本地环境 测试环境 生产环境
  let phoneHost = ''
  if (process.env.DEV) {
    phoneHost = 'http://localhost:8081'
  } else if (process.env.DEBUGGING) {
    phoneHost = 'http://testphone.bitbrowser.cn/'
  } else {
    let clintLine = {
      line1: 'https://phone.bitbrowser.net/',
      line2: 'https://phone.bitbrowser.net/',
      line3: 'https://phone2.bitbrowser.net/',
      line4: 'https://phone2.bitbrowser.net/'
    }
    phoneHost = clintLine[line]
  }

  await checkBinding(id)

  let config = {
    id,
    seq: detailRes.seq,
    url: `${phoneHost}?token=${token}&id=${id}&lang=${locale}&port=${listeningPort}&type=${detailRes.channel}&isapi=1`
  }

  await openPhoneWindow(config)
  ctx.body = ApiUtil.success()
})

