phoneRouter.post('/phone/bounds', async ctx => {
  const options = ctx.request.body

  // 如果包含ids参数，则以ids参数为准，覆盖掉seqlist即可
  if (options.hasOwnProperty('ids')) {
    if (!Array.isArray(options.ids)) {
      return (ctx.body = ApiUtil.fail('ids is array type'))
    }
    options.seqlist = options.ids
      .map(id => {
        if (phoneStatus.opened_phone_configs.has(id)) {
          return phoneStatus.opened_phone_configs.get(id).seq
        }
      })
      .filter(item => !!item)
  } else {
    if (options.hasOwnProperty('seqlist') && !Array.isArray(options.seqlist))
      return (ctx.body = ApiUtil.fail(messages.getMessage('Seqlist')))
  }

  await windowBounds.setPhoneBounds(options)
  ctx.body = ApiUtil.success()
})

