phoneRouter.post('/phone/suspend', paramRequired('id'), async ctx => {
  let phoneId = ctx.request.body.id
  // 关闭手机窗口
  let openQunkongIds = phoneStatus.getKeepAliveIds()

  if (openQunkongIds.includes(phoneId)) {
    throw new Error(messages.getMessage('qunKongOpend'))
  }
  await closePhoneWindow(phoneId)

  // 挂起API
  await request({ url: 'v1/cloudphone/cloudPhonesEvn/close', method: 'post', data: { id: phoneId, isRelease: 0 } })

  ctx.body = ApiUtil.success()
})

/**
 * @description 关机手机
 * */
phoneRouter.post('/phone/shutdown', paramRequired('id'), async ctx => {
  let phoneId = ctx.request.body.id
  let openQunkongIds = phoneStatus.getKeepAliveIds()
  if (openQunkongIds.includes(phoneId)) {
    throw new Error(messages.getMessage('qunKongOpend'))
  }

  await Promise.all([
    closePhoneWindow(phoneId),
    request({ url: '/v1/cloudphone/cloudPhonesEvn/close', method: 'post', data: { id: phoneId, isRelease: 1 } })
  ])

  ctx.body = ApiUtil.success()
})

/**
 * @description 创建云手机环境
 * */
phoneRouter.post('/phone/profile/add', async ctx => {
  // 简单校验下请求参数，必填的，参数长度等
  let param = ctx.request.body
  if (!param.regionId) throw new Error(messages.getMessage('Required', 'regionId'))
  param = validatePhoneProfile(param)
  let res = await request({ url: 'v1/cloudphone/cloudPhonesEvn', method: 'post', data: param })
  ctx.body = ApiUtil.success(res)
})

function validatePhoneProfile(param) {
  if (param.name && param.name.length > 30) throw new Error(messages.getMessage('maxLength', 'name'))

  if (param.remark && param.remark.length > 500) throw new Error(messages.getMessage('RemarkExceed'))

  if (![0, 1, 2].includes(param.computeType)) throw new Error(messages.getMessage('Required', 'computeType'))

  if (!param.host) throw new Error(messages.getMessage('Required', 'host'))

  if (!param.port) throw new Error(messages.getMessage('Required', 'port'))

  if (!param.proxyUserName) throw new Error(messages.getMessage('Required', 'proxyUserName'))

  if (!param.proxyPassword) throw new Error(messages.getMessage('Required', 'proxyPassword'))

  if (![0, 1].includes(param.udp)) {
    param.udp = 1
  }
  if (param.cloudPhonesFingerPrint && Object.prototype.toString.call(param.cloudPhonesFingerPrint) !== '[object Object]') {
    throw new Error(messages.getMessage('ObjectType', 'cloudPhonesFingerPrint'))
  }

  param.proxyType = 'socks5'
  param.proxyMethod = 2
  return param
}
