// 确保云手机处于开机状态
async function ensurePhoneStartup(id, msg) {
  const status = await getPhoneStatus(id)
  if (status !== 1) {
    throw new Error(msg ? msg : id + messages.getMessage('phoneNoOpened'))
  }
}

async function getPhoneStatus(id) {
  let res = await request({ url: 'v1/cloudphone/cloudPhonesEvn/getCheckStatusPhone/' + id, method: 'get' })
  return +res.phoneStatus
}

