function generateUniqueFileName(originalFileName) {
  const random = uid()
  const extension = originalFileName.split('.').pop()
  return `${random}.${extension}`
}

function formatFileSize(bytes) {
  if (bytes === 0) return '0 Bytes'
  const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB']
  const i = Math.floor(Math.log2(bytes) / 10) // 计算文件大小所在的单位级别
  const formattedSize = parseFloat((bytes / Math.pow(1024, i)).toFixed(2)) // 计算文件大小
  return `${formattedSize} ${sizes[i]}` // 返回带有单位的文件大小
}

function getUploadFileType(type) {
  let img = new Set(['jpeg', 'png', 'svg', 'jpg', 'webp', 'ico'])
  let doc = new Set(['doc', 'docx', 'xls', 'xlsx', 'ppt', 'rtf', 'pptx', 'txt', 'js', 'html', 'php', 'java', 'py'])

  if (type === 'apk') return 'apk'
  if (img.has(type)) return 'img'
  if (doc.has(type)) return 'doc'
  return 'other'
}

async function uploadOss({ md5, filePath, fileSize, fileName }) {
  const userInfo = await getUserInfo()
  // 上传文件到OSS
  let client = await getOssClient({ bucket: 'bitphone-files', endpoint: 'oss-cn-hongkong.aliyuncs.com' })
  let apkres = await multipartUpload(client, `${userInfo.belongUserId}/${userInfo.id}/${generateUniqueFileName(fileName)}`, filePath)

  let param = {
    md5Sum: md5,
    fileName,
    filePath: apkres.requestUrls[0],
    fileType: getUploadFileType(fileName.split('.').pop()),
    status: 0,
    type: 3,
    fileSize: formatFileSize(fileSize),
    mainUserId: userInfo.belongUserId,
    appName: fileName,
    sizeNum: parseFloat(fileSize)
  }

  return request({
    url: '/v1/cloudphone/cloudPhonesFileUploads',
    method: 'post',
    data: param
  })
}

function validateFile(stats, fileName) {
  if (stats.size === 0) {
    throw new Error(messages.getMessage('emptyFile'))
  }
  if (fileName.length > 100) {
    throw new Error(messages.getMessage('ruleNameMsg'))
  }
  const fileSizeMB = stats.size / (1024 * 1024)
  const maxSize = 1024 * 1024 * 300 // 300MB 的大小限制
  if (fileSizeMB > maxSize) {
    throw new Error(messages.getMessage('uploadMaxSize'))
  }
}

// 缓存，
const cachePatch = new Cache()
/**
 * @description 上传文件
 * */
phoneRouter.post('/phone/uploadFile', async ctx => {
  const ids = ctx.request.body.ids
  if (!ids) {
    throw new Error(messages.getMessage('Required', 'ids'))
  }
  if (!Array.isArray(ids) || !ids.length) {
    throw new Error(messages.getMessage('ArrayType', 'ids'))
  }
  if (ids.length > 10) {
    throw new Error(messages.getMessage('uploadPhoneMaxLimit'))
  }

  const filePath = path.resolve(ctx.request.body.path)

  // 验证文件路径安全性
  const appPath = app.getAppPath()
  const userDataPath = app.getPath('userData')

  if (filePath.endsWith('.apk')) {
    throw new Error(messages.getMessage('DisableApkUploading'))
  }
  // 检查是否在安装目录下
  if (filePath.startsWith(appPath)) {
    throw new Error('Cannot upload files from installation directory')
  }

  // 检查是否在userData目录下
  if (filePath.startsWith(userDataPath)) {
    throw new Error('Cannot upload files from userData directory')
  }

  const exist = await fs.pathExists(filePath)
  if (!exist) {
    throw new Error(messages.getMessage('fileNotFound'))
  }

  if (cachePatch.has(filePath)) {
    throw new Error(messages.getMessage('uploading'))
  }

  const stats = await fs.stat(filePath)
  if (!stats.isFile()) {
    throw new Error(messages.getMessage('notFile'))
  }

  for (let i = 0; i < ids.length; i++) {
    await ensurePhoneStartup(ids[i], messages.getMessage('requestFaledPhoneOff'))
  }

  cachePatch.add(filePath, filePath, 0.16)
  const fileName = path.basename(filePath)

  validateFile(stats, fileName)

  const md5 = await getFileMd5(filePath)

  let uploadFileRes = {}

  const alreadyUploaded = await request({
    url: '/v1/cloudphone/cloudPhonesFileUploads/isFileMd5Exist',
    method: 'post',
    data: { fileName, md5Sum: md5, status: 1, sizeNum: stats.size }
  })

  uploadFileRes.id = alreadyUploaded

  if (!uploadFileRes.id) {
    try {
      uploadFileRes = await uploadOss({
        md5,
        filePath,
        fileName,
        fileSize: stats.size
      })
    } catch (error) {
      cachePatch.delete(filePath)
      throw new Error(messages.getMessage('uploadFileError'))
    }
  }
  if (uploadFileRes.id) {
    request({
      url: '/v1/cloudphone/cloudPhonesFileUploads/batchFiles',
      method: 'post',
      data: { classify: 1, type: 'distribute', fileIds: [uploadFileRes.id], phoneIds: ids }
    })
  }

  cachePatch.delete(filePath)

  ctx.body = ApiUtil.success()
})

