phoneRouter.post('/phone/group/list', async ctx => {
  // 分组list
  const param = ctx.request.body

  if (typeof param.page !== 'number' || typeof param.pageSize !== 'number') throw new Error(messages.getMessage('Page'))

  try {
    // 权限内的所有分组
    if (typeof param.all === 'boolean' && param.all) {
      param.searchParas = {
        conditions: [
          {
            name: 'isManage',
            op: 'eq',
            value: '1'
          },
          {
            name: 'isGroupUserRel',
            op: 'eq',
            value: '1'
          }
        ]
      }
    }
    const res = await request({ url: '/v1/cloudphone/cloudPhonesGroupInfo/list', method: 'post', data: param })
    ctx.body = ApiUtil.success(res)
  } catch (err) {
    phoneLog.error('get group list error ===>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

// 添加分组
phoneRouter.post('/phone/group/add', async ctx => {
  const param = ctx.request.body
  if (!param.groupName) throw new Error(messages.getMessage('Required', 'groupName'))
  if (typeof param.sortNum !== 'number') throw new Error(messages.getMessage('Required', 'sortNum'))
  if (typeof param.groupName.length > 20) throw new Error(messages.getMessage('GroupNameExceed'))
  try {
    const res = await request({ url: '/v1/cloudphone/cloudPhonesGroupInfo', method: 'post', data: param })
    ctx.body = ApiUtil.success(res)
  } catch (err) {
    phoneLog.error('group add error ==>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

