/**
 * @description 批量修改备注
 * */
phoneRouter.post('/phone/batchUpdate/remark', async ctx => {
  const param = ctx.request.body
  const phoneIds = param.phoneIds

  if (!phoneIds || !phoneIds.length || !Array.isArray(phoneIds)) throw new Error(messages.getMessage('ArrayRequired', 'phoneIds'))

  const remark = param.remark
  if (!remark) throw new Error(messages.getMessage('Required', 'remark'))
  if (![1, 2].includes(param.remarkType)) throw new Error(messages.getMessage('Required', 'remarkType'))
  let res = await request({
    url: '/v1/cloudphone/cloudPhonesEvn/batchUpdateRemark',
    method: 'post',
    data: { ids: phoneIds, remark, remarkType: param.remarkType }
  })

  ctx.body = ApiUtil.success(res)
})
/**
 * @description 批量代理
 * */
phoneRouter.post('/phone/batchUpdate/proxy', async ctx => {
  const param = ctx.request.body
  const phoneIds = param.phoneIds

  if (!phoneIds || !phoneIds.length || !Array.isArray(phoneIds)) throw new Error(messages.getMessage('ArrayRequired', 'phoneIds'))

  if (!param.host) throw new Error(messages.getMessage('Required', 'host'))
  if (!param.port) throw new Error(messages.getMessage('Required', 'port'))
  if (!param.proxyPassword) throw new Error(messages.getMessage('Required', 'proxyPassword'))
  if (!param.proxyUserName) throw new Error(messages.getMessage('Required', 'proxyUserName'))
  let data = {
    ids: phoneIds,
    proxyType: 'socks5',
    host: param.host,
    port: param.port,
    proxyMethod: 2,
    proxyPassword: param.proxyPassword,
    proxyUserName: param.proxyUserName,
    udp: ![0, 1].includes(param.udp) ? 1 : param.udp
  }
  if (param.ipCheckService) {
    data.ipCheckService = param.ipCheckService
  }
  let res = await request({
    url: '/v1/cloudphone/cloudPhonesEvn/batchUpdateProxy',
    method: 'post',
    data
  })

  ctx.body = ApiUtil.success(res)
})
