/**
 * @description 删除环境
 * */
phoneRouter.post('/phone/delete', async ctx => {
  const { ids } = ctx.request.body

  if (!ids || !ids.length || !Array.isArray(ids)) throw new Error(messages.getMessage('ArrayRequired', 'ids'))

  // 未关闭，打开中，关闭中，均不可删除
  for (let id of ids) {
    if (phoneStatus.isClosing(id) || phoneStatus.isOpening(id) || phoneStatus.opened_phone_configs.has(id)) {
      throw new Error(messages.getMessage('phoneDleteTip'))
    }
  }

  await request({
    url: `/v1/cloudphone/cloudPhonesEvn`,
    method: 'delete',
    data: {
      ids
    }
  })

  ctx.body = ApiUtil.success(messages.success())
})

