import Router from 'koa2-router'
import { deleteGlobalConfig, getGlobalConfigs, setGlobalConfigs } from '../data/globalConfigs'
import { ApiUtil } from '../interface/ApiUtil'
import { setProcessClear } from '../tasks/schedule'
import { apiLog } from '../logs'

const configsRouter = new Router()

// 获取全局配置
configsRouter.post('/configs/all', async ctx => {
  const res = await getGlobalConfigs()
  ctx.body = ApiUtil.success(res)
})

// 按字段保存全局配置
configsRouter.post('/configs/save', async ctx => {
  const body = ctx.request.body
  apiLog.info('save global configs ==>>>> ', body)
  await setGlobalConfigs(body)

  // 设置进程保护对应定时器
  if (Reflect.has(body, 'process_protect_period')) {
    setProcessClear(body.process_protect_period)
  }

  ctx.body = ApiUtil.success()
})

// 按字段删除全局配置
configsRouter.post('/configs/delete', async ctx => {
  const { name } = ctx.request.body
  apiLog.info('delete global configs ==>>>> ', name)
  await deleteGlobalConfig(name)

  ctx.body = ApiUtil.success()
})

configsRouter.post('/configs/autopaste/shortcutKey', async ctx => {
  const res = await getGlobalConfigs()
  const defaultKeys = process.platform === 'darwin' ? 'Command + Shift + E' : 'Ctrl + Shift + E'
  ctx.body = ApiUtil.success(res.autopaste_shortcut || defaultKeys)
})

export default configsRouter
