function getLinesArr(lineObj) {
  let arr = []
  for (let key in lineObj) {
    arr.push({ label: lineObj[key].label, value: key })
  }
  return arr
}

class GlobalSetting {
  // 默认line1
  constructor() {
    this.line = 'line1'
    this.lineObj = process.env.DEBUGGING ? DebugServiceLine[this.line] : AppServiceLine[this.line]
  }

  // 设置线路
  setLine(line) {
    this.line = line
    this.lineObj = process.env.DEBUGGING ? DebugServiceLine[line] : AppServiceLine[line]
    // 存储本地配置文件
    saveServiceLine(line)
  }

  getWebUrl(lang) {
    return this.lineObj.web + `?lang=${lang}`
  }

  // api打开，则走client接口
  getServiceLine(isApiUser = false) {
    if (isApiUser) return this.lineObj.client
    return this.lineObj.webapi
  }

  // 获取代理检测使用的baseUrl
  getProxyUrl() {
    return this.lineObj.proxyUrl
  }

  getLines() {
    return process.env.DEBUGGING ? getLinesArr(DebugServiceLine) : getLinesArr(AppServiceLine)
  }

  getActive() {
    return this.line
  }
}

const globalSetting = new GlobalSetting()

// 设置下默认线路
initial()
async function initial() {
  const line = await getServiceLineFromDB()
  globalSetting.setLine(line)
}

export default globalSetting
