export class ApiUtil {
  static success(data) {
    return {
      success: true,
      data
    }
  }
  static fail(msg) {
    const obj = { success: false }
    if (typeof msg === 'string') obj.msg = msg
    if (Object.prototype.toString.call(msg) === '[object Object]') Object.assign(obj, msg)
    return obj
  }
}
