import axios from 'axios'
import browserStatus from './browserStatus'
import { log } from '../logs'

// 使用 Map 存储 tabs，key 是 browserId，value 是 tabs 数组
const tabsCache = new Map()

class BrowserTabs {
  constructor() {}

  setTabs(browserId, tabs) {
    if (!tabs || !tabs.length) return
    if (browserStatus.isClosing(browserId)) return
    tabsCache.set(browserId, tabs)
  }

  deleteTabs(browserId) {
    tabsCache.delete(browserId)
  }

  async getTabs(browserId) {
    return tabsCache.get(browserId) || null
  }

  // 获取浏览器窗口活动的tab的url
  async getActiveUrl(browserId) {
    const tabs = tabsCache.get(browserId)
    if (!tabs || !tabs.length) return null
    const activeTab = tabs.find(item => item.active)
    return activeTab ? activeTab.url : null
  }

  // 获取浏览器窗口活动的page
  /**
   * @description 获取活动标签页 active tab
   * @param {Object} browser puppeteer browser 对象
   * @returns {Object} puppeteer page 对象
   * */
  async getActivePage(browser) {
    try {
      const httpAddress = browserStatus.getBrowserHttpAddress(browser)

      const { data } = await axios.get(httpAddress + '/json/list')
      const { id } = data.filter(item => item.type === 'page')[0] // 从active tab里获取到的targetId

      const targets = browser.targets()
      const target = targets.find(t => t._targetId === id)

      if (target) {
        return target.page()
      }
    } catch (err) {
      log.error('get active page error ==>>>> ', err)
    }

    return null
  }

  async getUrls(browserId, platform) {
    let tabs = tabsCache.get(browserId)
    if (!tabs || !tabs.length) return ''

    let urls = tabs.map(item => item.url || item.pendingUrl)

    urls = Array.from(new Set(urls)) // 去重

    // 如果设置的platform不是http或https开头的，那么补上再过滤
    let httpPlatform = platform
    let httpsPlatform = platform
    if (!platform.startsWith('http')) {
      httpPlatform = `http://${platform}`
      httpsPlatform = `https://${platform}`
    }
    // 过滤掉127.0.0.1和platform，以及非http开头的，比如 chrome:// 等，过滤掉有可能出现的空url
    urls = urls.filter(url => {
      // 去掉url尾部的'/'后再比较
      if (url && url.endsWith('/')) {
        url = url.substr(0, url.length - 1)
      }
      const isPlatform = url === httpsPlatform || url === httpPlatform
      return url && !url.includes('127.0.0.1') && !url.includes('console.bitbrowser.net') && !isPlatform
    })
    // 最多20个
    if (urls.length > 30) {
      urls = urls.slice(0, 30)
    }
    urls = urls.map(url => encodeURIComponent(url))
    return urls.toString()
  }
}

const browserTabs = new BrowserTabs()
export default browserTabs
