import { getClient } from './client'
import { apiLog } from '../logs'

export async function updateFirefoxVersion(firefox, version) {
  try {
    const db = await getClient()
    await db('firefox_versions').insert({ firefox, version }).onConflict('firefox').merge()
  } catch (err) {
    apiLog.error('update firefox app version ==>>> ', err)
  }
}

export async function getFirefoxVersions() {
  try {
    const db = await getClient()
    const res = await db('firefox_versions').select('*')
    return res
  } catch (err) {
    apiLog.error('get firefox app versions error ==>>> ', err)
  }
  return []
}

export async function getFirefoxByCoreVersion(coreVersion) {
  try {
    const db = await getClient()
    const res = await db('firefox_versions').select('*').where('firefox', '=', coreVersion)
    if (res.length) return res[0]
  } catch (err) {
    apiLog.error('get firefox by core version error ==>>> ', err)
  }
  return null
}
