import { getClient } from './client'
import { apiLog } from '../logs'
import { getGlobalConfigs, setGlobalConfigs } from './globalConfigs'
import { safeJsonParse } from '../utils/safeJsonParse'
import { getLatestFontNames, getFontNamesFileMd5, getFontFilesMapMd5, getLatestFontFilesMap } from '../fingerprint/font'
import { getLatestWebglparametersData, getParametersFileMd5 } from '../fingerprint/webgl'
import { getLangFileMd5, getLatestLangData } from '../fingerprint/lang'
import { streamJsonStringify } from '../utils/streamJson'

const Table = 'cache_data_for_server'

export async function getCacheDataFromDB({ dataKey = '', serverType = 'dict' }) {
  if (!dataKey) return null

  try {
    const db = await getClient()
    const res = await db(Table).select('*').where('data_key', '=', dataKey).andWhere('server_type', '=', serverType)
    const { data_type, data_value, data_version, id } = res[0]

    // 服务端版本存在，且与本地版本不一致时，删掉重新获取
    const serverDataVersion = await getDictDataVersoin()
    if (serverDataVersion && serverDataVersion !== data_version) {
      await db(Table).delete('*').where('id', '=', id)
      return null
    }

    if (data_type === 'string') {
      return data_value
    } else {
      return safeJsonParse(data_value, `getCacheDataFromDB:${dataKey}`)
    }
  } catch (err) {}

  return null
}

// 删除缓存数据
export async function deleteCacheDataFromDB({ dataKey = '', serverType = 'dict' }) {
  try {
    const db = await getClient()
    await db(Table).delete('*').where('data_key', '=', dataKey).andWhere('server_type', '=', serverType)
  } catch (err) {
    apiLog.error('delete cache data from DB error ===>>> ', err)
  }
}

/**
 * @description 保存缓存数据到DB，如果有md5，则使用md5作为版本号，否则使用服务端的版本号
 * */
export async function saveCacheDataToDB({ dataKey, dataValue, serverType = 'dict', md5 = '' }) {
  try {
    const dataVersion = md5 || (await getDictDataVersoin())

    const dataType = typeof dataValue === 'string' ? 'string' : 'json'

    apiLog.info('save cached data to DB ==>>> ', dataKey, dataValue, dataType, dataVersion, serverType)

    // streamJsonStringify 是异步函数，需要使用 await
    const dataValueString = dataType === 'string' ? dataValue : await streamJsonStringify(dataValue)

    const db = await getClient()
    await db(Table)
      .insert({
        data_key: dataKey,
        data_value: dataValueString,
        data_version: dataVersion,
        server_type: serverType,
        data_type: dataType
      })
      .onConflict('data_key')
      .merge()
    return true
  } catch (err) {
    apiLog.error('save cache data to DB error ===>>> ', err)
  }

  return false
}

async function getDictDataVersoin() {
  const res = await getGlobalConfigs()
  if (res.server_dict_version) {
    return res.server_dict_version
  }

  return null
}

// save server data version to global configs
export async function saveCacheDictVersion(server_version) {
  setGlobalConfigs({ server_dict_version: server_version })
}

/**
 * @description 获取字体Names，数据库不存在数据，或者版本不匹配，则获取一遍
 * @param {string} platform dataKey 与 指纹 platform一致
 * @param {number} retryTimes 重试次数
 * @returns {Promise<Array>} []
 * @example getCachedFontNames('Windows')
 * */
export async function getCachedFontNames(platform, retryTimes = 0) {
  if (!platform || retryTimes > 5) return null

  try {
    const db = await getClient()
    const res = await db(Table).select('*').where('data_key', '=', `FontNames_${platform}`).andWhere('server_type', '=', 'fontNames')

    if (!res.length) {
      await getLatestFontNames(platform)
      return getCachedFontNames(platform, retryTimes + 1)
    }

    const { data_value, data_version, id } = res[0]

    // data_version 使用ossMd5判定
    const md5 = await getFontNamesFileMd5(platform)
    if (md5 && md5 !== data_version) {
      await db(Table).delete('*').where('id', '=', id)
      // 下载字体Names
      await getLatestFontNames(platform)
      return getCachedFontNames(platform, retryTimes + 1)
    }

    return safeJsonParse(data_value, `getCachedFontNames:${platform}`)
  } catch (err) {}

  return null
}

/**
 * @description 保存字体Names到DB
 * */
export async function saveFontNamesToDB({ platform, dataValue }) {
  const md5 = await getFontNamesFileMd5(platform)

  await saveCacheDataToDB({
    dataKey: `FontNames_${platform}`,
    dataValue,
    serverType: 'fontNames',
    md5
  })
}

