// 删除缓存，保留扩展数据，force => 不检查freeTogo
export async function clearCacheWithoutExtensions(browserIds = [], force = false) {
  log.info('clear without extensions =======================>>>> ', browserIds)
  if (!browserIds.length) return

  for (const id of browserIds) {
    try {
      if (!force && !browserStatus.isFreeTogo(id)) continue

      const cacheDir = await getBrowserCacheDir(id)
      const exists = await fs.pathExists(cacheDir)
      if (!exists) continue

      // 先删掉除了Default目录的所有目录和文件
      const dirs = await fs.readdir(cacheDir)
      await Promise.all(dirs.filter(dir => dir !== 'Default').map(dir => rimraf(path.join(cacheDir, dir), { maxRetries: 5 })))

      // 再删除掉Default目录下，除了扩展外的所有
      const inDirs = await fs.readdir(path.join(cacheDir, 'Default'))
      await Promise.all(
        inDirs
          .filter(
            dir =>
              ![
                'Extensions',
                'Preferences',
                'Secure Preferences',
                'Local Extension Settings',
                'Sync Extension Settings',
                'Managed Extension Settings'
              ].includes(dir)
          )
          .map(dir => rimraf(path.join(cacheDir, 'Default', dir), { maxRetries: 5 }))
      )
    } catch (err) {
      log.error('clear cache without extensions error ==>>>> ', err)
    }
  }
}

// 删除残留的 .zip 文件
async function clearBrowserResidualZipFiles(browserId) {
  const cacheDir = await getBrowserCacheDir(browserId)
  const dirs = ['Local Storage', 'IndexedDB', 'Local Extension Settings', 'Sync Extension Settings', 'Managed Extension Settings']

  // 先清理Default目录下的 .zip 文件
  const defaultDir = path.join(cacheDir, 'Default')
  const defaultFiles = await fs.readdir(defaultDir)
  Promise.all(defaultFiles.filter(file => file.endsWith('.zip')).map(file => rimraf(path.join(defaultDir, file), { maxRetries: 5 })))

  // 再清理其他目录下的 .zip 文件
  for (const dir of dirs) {
    const dirPath = path.join(cacheDir, 'Default', dir)
    if (await fs.pathExists(dirPath)) {
      const dirFiles = await fs.readdir(dirPath)
      await Promise.all(dirFiles.filter(file => file.endsWith('.zip')).map(file => rimraf(path.join(dirPath, file), { maxRetries: 5 })))
    }
  }
}

// 刚打开浏览器时设置cookie以及去掉重复tab等
async function initialPages(pages, config) {
  const listeningPort = await getLocalServerPort()

  // 解析cookies，启动时不删除cookie，则parse一下
  let parseResult = { success: true, cookies: [] }
  if (!config.clearCacheFilesBeforeLaunch && !config.clearCacheWithoutExtensions && !config.clearCookiesBeforeLaunch) {
    parseResult = await parseCookies(config.cookie)
  }

  log.info('parseResult ==>>> ', parseResult.cookies.length)

  // bithelper 的cookies
  const initCookies = [
    { name: 'BrowserId', value: config.id, domain: '.bithelper.bitbrowser.cn', path: '/' },
    { name: 'LocalPort', value: listeningPort + '', domain: '.bithelper.bitbrowser.cn', path: '/' },
    { name: 'disableAutoplay', value: !!config.abortMedia + '', domain: '.bithelper.bitbrowser.cn', path: '/' }
  ]
  if (config.coreProduct === 'firefox' && config.abortImage) {
    parseResult.cookies.push({
      name: 'AbortImageMaxSize',
      value: config.abortImageMaxSize + '',
      domain: '.bithelper.bitbrowser.cn',
      path: '/'
    })
  }
  try {
    // 首先设置cookies 此时 page.url() 可能还没有值
    const client = await pages[0].target().createCDPSession()
    // 分开设置，防止设置失败导致全部设置失败
    await Promise.all([
      parseResult.cookies.length ? client.send('Network.setCookies', { cookies: parseResult.cookies }) : Promise.resolve(),
      client.send('Network.setCookies', { cookies: initCookies })
    ])
  } catch (err) {
    log.error('Set Cookies error ==>>> ', err)
    reporter.browser(config.id, err, JSON.stringify(parseResult.cookies))
  }

  pages.map(page => {
    const url = page.target().url()
    if (url && url !== 'about:blank') page.goto(url) // firefox 刚刚启动时，获取的url为空
  })
}

// 获取浏览器启动参数
async function getLaunchArgs(config, loadExtensions = '', ipResult, windowbounds = {}) {
  const fingureprint = config.browserFingerPrint
  const chromePath = await chromeVersion.getExePath(config.browserFingerPrint.coreVersion)
  const lang = (fingureprint.isIpCreateDisplayLanguage ? ipResult.data && ipResult.data.languages : fingureprint.displayLanguages) || ''

  const args = [
    `--file-url-path-alias=/gen=${path.resolve(path.dirname(chromePath), 'gen')}`,
    '--no-default-browser-check',
    '--disable-background-mode',
    '--disable-blink-features=AutomationControlled',
    '--fingerprint-config=' + path.resolve(app.getPath('userData'), 'LocalCache', config.id)
  ]

  // 重启窗口，或者默认位置打开，无需设置最大化最小化，设置最小化和最大化时，不能设置 --window-size，否则无法生效
  if (windowbounds.windowState && windowbounds.windowState !== 'minimized') {
    args.push(
      `--window-position=${windowbounds.left || 0},${windowbounds.top || 0}`,
      `--window-size=${windowbounds.width || fingureprint.openWidth || 1280},${windowbounds.height || fingureprint.openHeight || 720}`
    )
  } else {
    const positionStyle = await getBrowserStartPosition()
    if (positionStyle.maximized) args.push('--start-maximized')
    if (positionStyle.minimized) args.push('--start-minimized')
    if (positionStyle.lastPosition) {
      const bounds = (await getBrowserPersistentData({ browserId: config.id, type: BrowserPersistentDataType.Bounds })) || {}
      args.push(`--window-size=${bounds.width || fingureprint.openWidth || 1280},${bounds.height || fingureprint.openHeight || 720}`)
      args.push(`--window-position=${bounds.left || 0},${bounds.top || 0}`)
    }
    if (positionStyle.position)
      args.push(
        `--window-size=${fingureprint.openWidth || 1280},${fingureprint.openHeight || 720}`,
        `--window-position=${positionStyle.x || 0},${positionStyle.y || 0}`
      )
  }

  if (lang) args.push('--lang=' + lang)

  // 加载扩展
  let extensionStr = loadExtensions || ''
  // TODO: 先屏蔽掉，验证没问题后可以删除
  // if (config.browserFingerPrint.coreVersion && +config.browserFingerPrint.coreVersion < 130) {
  //   extensionStr += `,${path.resolve(__dirname, process.env.DEV ? '../' : process.resourcesPath, 'bitHelper')}`
  // }
  if (config.rpaRun) {
    const automaPath = await rpaContainer.getAutomaPath()
    extensionStr += `,${automaPath}`
  }
  args.push(`--load-extension=${extensionStr}`)

  if (config.platform && (config.userName || config.password)) {
    // 这里要再补上斜杠，浏览器自动填充记录的url尾部带斜杠
    args.push('--website-url=' + config.platform + '/')
    args.push('--website-username=' + config.userName)
    args.push('--website-password=' + config.password)
  }

  // 禁止图片显示，abortImageMaxSize为0时，直接禁止内核功能即可
  if (config.abortImage && !config.abortImageMaxSize) {
    args.push('--blink-settings=imagesEnabled=false')
  }

  if (config.muteAudio) {
    args.push('--mute-audio')
  }
  if (config.disableGpu) {
    args.push('--disable-gpu')
  }

  // 不显示桌面通知
  if (config.disableNotifications) {
    args.push('--x-block-notifications')
  }

  // 直连模式，或者设置了127代理，不使用系统代理
  const sysProxyConfig = await getSysProxyConfig()
  if (sysProxyConfig.type === 2 || config.proxyType === 'noproxy' || config.host === '127.0.0.1') {
    args.push('--x-dont-nest-system-proxy')
  }

  // 指纹里单独配置的参数
  if (fingureprint.launchArgs) {
    args.push(...fingureprint.launchArgs.split(','))
  }

  // 设置workbench 页面，允许不设置，运行rpa任务时，必须有本地工作台或者rpa页面
  const listeningPort = await getLocalServerPort()

  if (config.workbench === 'localserver') {
    args.push(getWorkbenchUrl(config, listeningPort))
  } else {
    if (config.rpaRun && config.workflowId) {
      const url = await getRpaHtml(config.id, config.workflowId)
      args.push(url)
    }
  }

  return args
}

