// 同步到本地浏览器缓存文件
async function syncBrowserCacheFiles(config) {
  sendToRenderer(config.id, '正在同步缓存配置...')

  // 删除整个浏览器缓存文件时，无需从服务端同步缓存
  if (config.clearCacheFilesBeforeLaunch) {
    await deleteBrowserCacheDir(config.id, true)
  } else if (config.clearCacheWithoutExtensions) {
    await clearCacheWithoutExtensions([config.id], true)
  } else {
    const asyncFns = []

    if (config.clearCookiesBeforeLaunch) {
      await deleteCookiesFile(config.id)
    }

    if (config.clearHistoriesBeforeLaunch) {
      await deleteHistoryFile(config.id)
    } else {
      if (config.syncHistory) asyncFns.push(syncHistory(config.id))
    }

    if (config.syncIndexedDb) asyncFns.push(syncIndexedDB(config.id, config.randomKey))
    if (config.syncBookmarks) asyncFns.push(syncBookmarks(config.id, config.coreProduct === 'firefox'))
    if (config.syncLocalStorage) asyncFns.push(syncLocalStorage(config.id, config.randomKey, config.coreProduct === 'firefox'))

    if (config.syncExtensions) {
      if (config.syncUserExtensions) {
        asyncFns.push(syncExtensionsFromOss(config.id, config.randomKeyUser, config.ossExtend || {}, true))
      } else {
        asyncFns.push(syncExtensionsFromOss(config.id, config.randomKey, config.ossExtend || {}))
      }
    }

    if (config.syncAuthorization) asyncFns.push(syncWebsiteCredentials(config.id, config.syncBrowserAccount, config.randomKey))
    // if (config.syncPaymentsAndAddress) asyncFns.push(syncPaymentsAndAddress(config.id, config.randomKey))

    await Promise.all(asyncFns)
  }

  await setPreferences(config)
  log.info('cache files download complete!!!!')
}

// disconnected处理事件，往服务端同步缓存文件等,开始同步时，等待1秒，此时浏览器可能还在写入缓存
async function handleDisconnected(config) {
  await sleep(0.1) // 等待100毫秒，触发sleep事件要比浏览器触发disconnect 要慢
  if (computerSleeping()) {
    return
  }

  // 手工关闭时，不会记录closingId，只有主动调用了 closeBrowser 才会记录 closing, 防止网络异常或其他意外导致的断开连接而直接杀掉进程
  if (browserStatus.isClosing(config.id)) {
    const pid = browserStatus.opened_browsers_pids.get(config.id)
    await ensureProcessGone(pid) // 确保进程退掉
  }

  // 如果是API close的，等待30秒，检查是否已经删掉了窗口，如果删掉了，则不用同步
  if (browserStatus.api_closing_ids.has(config.id)) {
    const timeout = await getApiCloseTimeout()
    let timeId = setTimeout(() => {
      timeId = null
      browserStatus.api_closing_ids.delete(config.id)

      if (browserStatus.removed_ids.has(config.id)) {
        log.info('browser has removed, no need to upload cache!!!')
        browserStatus.removed_ids.delete(config.id)
        return
      }

      if (browserStatus.isFreeTogo(config.id)) {
        uploadCacheFilesToOss(config)
      }
    }, timeout * 1000)
  } else {
    await uploadCacheFilesToOss(config)
  }

  // 不同步tabs的时候，原来是什么值，设置回去什么值
  const urls = await browserTabs.getUrls(config.id, config.platform)
  browserStatus.setBrowserClosed(config, config.syncTabs && !config.robotUrls && !config.ignoreDefaultUrls ? urls : config.url)

  // 删掉存储的tabs
  browserTabs.deleteTabs(config.id)

  deleteBrowserFingerprintFile(config.id)
  clearBrowserResidualZipFiles(config.id)
}

async function uploadCacheFilesToOss(config) {
  const asyncFns = []

  // 先开始同步历史记录，即使出错，后续的同步也赢得了时间，减小关键信息同步出错几率
  if (config.syncHistory) asyncFns.push(uploadHistory(config.id))

  if (config.syncCookies) asyncFns.push(uploadCookies(config))

  if (config.syncBookmarks) asyncFns.push(uploadBookmarks(config.id, config.coreProduct === 'firefox'))

  if (config.syncAuthorization) asyncFns.push(uploadWebsiteCredentials(config.id, config.seq, config.randomKey, true))

  // if (config.syncPaymentsAndAddress) asyncFns.push(uploadPaymentsAndAddress(config.id, config.randomKey))

  if (config.syncLocalStorage) asyncFns.push(uploadLocalStorage(config.id, config.randomKey, config.coreProduct === 'firefox'))

  if (config.syncIndexedDb) asyncFns.push(uploadIndexedDB(config.id, config.randomKey))

  // 同步扩展数据 config.syncUserExtensions, config.createdBy,
  if (config.syncExtensions) {
    asyncFns.push(uploadExtensions(config.id, config.id, config.randomKey))
    if (config.syncUserExtensions) asyncFns.push(uploadExtensions(config.id, config.createdBy, config.randomKeyUser))
  }

  await sleep(1)
  await Promise.all(asyncFns)
}

// 设置浏览器首选项，包含允许登录、显示书签栏
async function setPreferences(config) {
  try {
    const cacheDir = await getBrowserCacheDir(config.id)
    const preferences = path.join(cacheDir, 'Default/Preferences')
    const exist = await fs.pathExists(preferences)
    let json = {}
    const allowed = config.allowedSignin
    if (!exist) {
      if (!allowed) json = { signin: { allowed: false, allowed_on_next_startup: false } }
    } else {
      json = await fs.readJSON(preferences)

      if (!json.signin) json.signin = {}

      json.signin.allowed = allowed
      json.signin.allowed_on_next_startup = allowed
    }
    // 同步书签，则显示书签栏，不同步，则不管
    if (config.syncBookmarks) json.bookmark_bar = { show_on_all_tabs: true }

    // 屏蔽提示保存密码弹窗与自动登录
    json.credentials_enable_service = !config.credentialsEnableService
    // json.credentials_enable_autosignin = false

    if (config.disableTranslatePopup) {
      json.translate = { enabled: false }
      json.translate_ignored_count_for_language = { en: 2 }
    } else {
      delete json.translate
    }

    // 禁止网站读取剪贴板内容
    if (config.disableClipboard) {
      json.clipboard = {}
      setMultiObjectValue(json, ['profile', 'default_content_setting_values', 'clipboard'], 2)
      // 删掉已保存的指定网站
      try {
        delete json.profile.content_settings.exceptions.clipboard
      } catch (err) {}
    } else {
      if (Reflect.has(json, 'profile')) {
        setMultiObjectValue(json.profile, ['default_content_setting_values', 'clipboard'], 1)
      }
    }

    // 设置下载和保存文件目录
    const saveToSameDir = await getSaveToSameDir()
    const savefileDir = await getSaveFileDir()
    const selectfileDir = await getSelectFileDir()
    const promptForDownload = await getPromptForDownload()

    if (json.download) {
      json.download.default_directory = saveToSameDir ? path.resolve(savefileDir) : path.join(savefileDir, config.seq + '')
    } else {
      json.download = {
        default_directory: saveToSameDir ? path.resolve(savefileDir) : path.join(savefileDir, config.seq + '')
      }
    }
    json.download.prompt_for_download = promptForDownload

    json.savefile = {
      default_directory: saveToSameDir ? path.resolve(savefileDir) : path.join(savefileDir, config.seq + '')
    }
    json.selectfile = {
      last_directory: path.resolve(selectfileDir)
    }

    // 设置网页缩放
    const zoom = await getWebpageZoom()
    if (Reflect.has(json, 'partition')) {
      json.partition.default_zoom_level = { x: zoom }
    } else {
      json.partition = { default_zoom_level: { x: zoom } }
    }

    // 设置固定的扩展 preferences extensions pinned_extensions
    const pinnedExtensions = config.pinnedExtensions || []
    const removedPinnedExtensions = config.removedPinnedExtensions || []
    const existingPinnedExtensions = json.extensions?.pinned_extensions || []
    const newPinnedExtensions = Array.from(
      new Set(existingPinnedExtensions.filter(id => !removedPinnedExtensions.includes(id)).concat(pinnedExtensions))
    )
    json.extensions = json.extensions || {}
    json.extensions.pinned_extensions = newPinnedExtensions

    // json有设置内容，才写如配置文件
    if (Object.keys(json).length) await fs.outputJson(preferences, json)

    log.info('output preferences success!!!')
  } catch (err) {
    log.error('output preference json error ==>>> ', err)
  }
}

// 设置扩展同步 preferences bt_extensions
export async function setPreferencesExtensions(browserId, extensionIds = []) {
  try {
    if (!extensionIds || !extensionIds.length) return

    const cacheDir = await getBrowserCacheDir(browserId)
    const preferences = path.join(cacheDir, 'Default/Preferences')

    let json = { bt_extensions: Array.from(extensionIds) }

    const exist = await fs.pathExists(preferences)
    if (exist) {
      // 读取合并原有的 bt_extensions
      json = await fs.readJSON(preferences)
      json.bt_extensions = Array.from(new Set(extensionIds.concat(json.bt_extensions || [])))
    }

    await fs.outputJson(preferences, json)
  } catch (err) {
    log.error('set preferences extensions error ==>>> ', err)
  }
}

// 获取去重后的url，cookie robot则直接返回空数组
function getInitialUrls(urlString, platformUrl, skip = false) {
  if (skip) return []

  let urlArr = urlString.split(',').map(itemUrl => decodeURIComponent(itemUrl))

  // 首先去掉绝对重复的
  urlArr = Array.from(new Set(urlArr))

  // 再次去重，去掉urls里同时有 / 结尾和无 / 结尾的url，比如: https://baidu.com/ https://baidu.com
  const finalUrls = urlArr.filter(url => url.endsWith('/') || !urlArr.includes(url + '/'))

  // 设置了平台网址，且urls里所有网址均不包含平台网址，则添加平台网址到第一位
  if (platformUrl && finalUrls.every(url => !url.includes(platformUrl))) {
    finalUrls.unshift(platformUrl)
  }

  // 去掉空数据
  return finalUrls.filter(url => !!url)
}

function getWorkbenchUrl(config, listeningPort) {
  let hostname = 'https://console.bitbrowser.net' // 生产
  if (process.env.DEBUGGING) {
    hostname = 'https://testconsole.bitbrowser.net' // 测试
  }
  let url = `${hostname}?id=${config.id}&locale=${getLocale()}&port=${listeningPort}`
  if (config.rpaRun && config.workflowId) {
    url += `&workflowId=${config.workflowId}&sessionId=${uid()}`
  }
  return url
}

export async function getRpaHtml(browserId, workflowId) {
  const listeningPort = await getLocalServerPort()
  return `http://127.0.0.1:${listeningPort}/rpa.html?id=${browserId}&locale=${getLocale()}&workflowId=${workflowId}&sessionId=${uid()}`
}

// page close 会触发这个事件，防止全部page关闭后，浏览器没有自动退出，mac必须执行此操作，否则dock栏不退出，win延迟两秒执行，防止弹出 cmd.exe
async function handleTargetdestroyed(browser) {
  try {
    const pages = await browser.pages()
    if (pages.length === 0) {
      if (process.platform === 'win32') {
        await sleep(2)
      }
      browser && browser.close()
    }
  } catch (err) {
    log.error('targetdestroyed error => ' + err.message)
  }
}

// 确保内核存在
async function ensureCoreProductReady(browserFingerPrint, sendMsg = false) {
  if (browserFingerPrint.coreProduct === 'firefox') {
    const firefoxExists = await firefoxVersion.checkExeExists(browserFingerPrint.coreVersion)
    if (!firefoxExists) {
      if (sendMsg) sendToRenderer(browserFingerPrint.browserId, '正在更新浏览器内核，请稍后...')

      await firefoxVersion.ensureFirefoxBeReady(browserFingerPrint.coreVersion)
    }
  } else {
    const chromeExists = await chromeVersion.checkExeExists(browserFingerPrint.coreVersion)
    if (!chromeExists) {
      if (sendMsg) sendToRenderer(browserFingerPrint.browserId, '正在更新浏览器内核，请稍后...')

      await chromeVersion.ensureChromeBeReady(browserFingerPrint.coreVersion)
    }
  }
}

// 设置窗口windowState为normal，用来把最小化的窗口，拉起到桌面，如果打开了多个窗口，则把目标窗口设置为最上层
export async function resetWindowState2Normal(browser) {
  const pages = await browser.pages()
  const client = await pages[0].createCDPSession()
  const res = await client.send('Browser.getWindowForTarget', { targetId: pages[0].target()._targetId })
  await client.send('Browser.setWindowBounds', { windowId: res.windowId, bounds: { ...res.bounds, windowState: 'normal' } })
}

async function runCookiesRobot(browser, urls) {
  for (const url of urls) {
    try {
      const page = await browser.newPage()

      await page.goto(url)
      await page.evaluate(() => {
        return new Promise((resolve, reject) => {
          let totalHeight = 0
          const scrollHeight = document.body.scrollHeight
          let timer

          const _scroll = () => {
            clearTimeout(timer)

            let distance = Math.random() * 1000 + 500
            window.scrollBy({
              top: distance,
              left: 0,
              behavior: 'smooth'
            })
            totalHeight += distance

            if (totalHeight >= scrollHeight) {
              resolve()
            } else {
              timer = setTimeout(_scroll, Math.random() * 1000 + 500)
            }
          }

          timer = setTimeout(_scroll, Math.random() * 1000)
        })
      })

      await sleep(Math.abs(Math.random() * 10 - 5))
      await page.close()
      await sleep(Math.abs(Math.random() * 10 - 5))
    } catch (err) {
      apiLog.error('cookie robot error ==>>>> ', err)
    }
  }
}
