import { autoUpdater } from 'electron-updater'
import { updateAvailable, downloadProgress, updateError, updateApplying } from './electron-main'
import { ipcMain, app } from 'electron'
import { copy, ensureDir, pathExists } from 'fs-extra'
import path from 'path'
import { compareVersion } from './utils'
import { saveCacheDictVersion } from './data/cacheData'
import { spawn } from 'child_process'
import { rimraf } from 'rimraf'
import { log } from './logs'
import { DownloadService } from './interface/DownloadFile'

autoUpdater.logger = log
autoUpdater.autoDownload = false
let releaseName = '' // 存储升级了chrome的版本号，用于比对跳版本升级时或chrome浏览器升级时，是否需要下载完整包

autoUpdater.on('checking-for-update', res => {
  log.info('Checking for update...', res)
})
autoUpdater.on('update-available', info => {
  log.info('Update available ===>>> ', info.version)
  saveCacheDictVersion(info.dictVersion)
  releaseName = info.releaseName
  updateAvailable({
    version: info.version,
    releaseNotes: info.releaseNotes,
    releaseName: info.releaseName
  })
})
autoUpdater.on('update-not-available', info => {
  log.info('Update not available ===>>>', info.version)
  saveCacheDictVersion(info.dictVersion)
})
autoUpdater.on('error', err => {
  log.info('Error in auto-updater ==>>>>> ', err)
  updateError('更新遇到错误，请重新下载，或者重启软件后更新')
})
