// 下载
ipcMain.handle('update-download', () => {
  log.info('trigger download')
  return downloadAppZipFile()
})

// 检查更新
ipcMain.handle('check-for-updates', () => {
  log.info('trigger check-for-updates')
  return autoUpdater.checkForUpdates()
})

// 重启安装
ipcMain.handle('quit-and-install', () => {
  log.info('trigger quit and apply')
  return extractAllAndReload()
})

// 当前版本信息
ipcMain.handle('get-current-version', () => {
  return autoUpdater.currentVersion
})

// 获取用户数据目录下的临时目录路径
const getUserDataTmpPath = () => {
  return path.join(app.getPath('userData'), 'tmp')
}

// 获取升级包下载路径 - 下载到 process.resourcesPath
const getDownloadPath = () => {
  return path.join(process.resourcesPath, 'app.7z')
}

// 获取解压目录路径
const getExtractPath = () => {
  return path.join(getUserDataTmpPath(), 'update')
}

// 获取update-tool.exe路径
const getUpdateToolPath = () => {
  return process.env.DEV
    ? path.resolve(__dirname, '../utils/update-tool.exe')
    : path.resolve(process.resourcesPath, 'utils/update-tool.exe')
}

// 获取临时update-tool.exe路径（用于升级时避免文件占用）
const getTempUpdateToolPath = () => {
  return path.join(getUserDataTmpPath(), 'update-tool.exe')
}

// 确保update-tool.exe准备就绪，返回临时目录中的update-tool.exe路径
async function ensureUpdatetoolReady() {
  const originalUpdateToolPath = getUpdateToolPath()
  const tempUpdateToolPath = getTempUpdateToolPath()

  log.info('originalUpdateToolPath ==>>> ', originalUpdateToolPath)

  // 检查原始update-tool.exe是否存在
  if (!(await pathExists(originalUpdateToolPath))) {
    const error = new Error('升级工具未找到，请重新下载完整安装包')
    log.error('update-tool.exe not found at:', originalUpdateToolPath)
    throw error
  }

  // 确保临时目录存在
  await ensureDir(getUserDataTmpPath())

  // 复制update-tool.exe到临时目录，避免升级时替换utils目录导致文件占用
  try {
    // 如果临时文件已存在，先删除
    if (await pathExists(tempUpdateToolPath)) {
      await rimraf(tempUpdateToolPath, { maxRetries: 5 })
    }
    await copy(originalUpdateToolPath, tempUpdateToolPath)
    log.info('Copied update-tool.exe to temp directory:', tempUpdateToolPath)
  } catch (err) {
    log.error('Error copying update-tool.exe to temp directory:', err)
    throw new Error('复制升级工具失败，请重试')
  }

  return tempUpdateToolPath
}

// 清理升级产生的临时文件
export async function clearUpdaterFiles() {
  try {
    const downloadPath = getDownloadPath()
    const extractPath = getExtractPath()
    const tempUpdateToolPath = getTempUpdateToolPath()

    // 旧版不是asar版本时，需要清理的文件
    const oldApp7z = path.join(process.resourcesPath, 'app.7z')
    const oldTempPath = path.join(process.resourcesPath, 'temppath')
    const oldAppPath = path.join(process.resourcesPath, 'app')

    // 并发执行所有清理任务
    await Promise.all([
      // 清理下载文件
      (async () => {
        if (await pathExists(downloadPath)) {
          await rimraf(downloadPath, { maxRetries: 5 })
          log.info('Removed old download file:', downloadPath)
        }
      })(),
      // 清理解压目录
      (async () => {
        if (await pathExists(extractPath)) {
          await rimraf(extractPath, { maxRetries: 5 })
          log.info('Removed old extract directory:', extractPath)
        }
      })(),
      // 清理临时update-tool.exe
      (async () => {
        if (await pathExists(tempUpdateToolPath)) {
          await rimraf(tempUpdateToolPath, { maxRetries: 5 })
          log.info('Removed temp update-tool.exe:', tempUpdateToolPath)
        }
      })(),
      // 清理旧版app.7z文件（现在下载到resourcesPath，所以downloadPath就是oldApp7z）
      (async () => {
        if (await pathExists(oldApp7z)) {
          await rimraf(oldApp7z, { maxRetries: 5 })
          log.info('Removed old app.7z file:', oldApp7z)
        }
      })(),
      // 清理旧版临时路径
      (async () => {
        if (await pathExists(oldTempPath)) {
          await rimraf(oldTempPath, { maxRetries: 5 })
          log.info('Removed old temp path:', oldTempPath)
        }
      })(),
      // 清理旧版app路径
      (async () => {
        if (await pathExists(oldAppPath)) {
          await rimraf(oldAppPath, { maxRetries: 5 })
          log.info('Removed old app path:', oldAppPath)
        }
      })()
    ])
  } catch (err) {
    log.error('Error clearing updater files:', err)
  }
}

// 下载 app.7z 文件到 process.resourcesPath 目录
async function downloadAppZipFile() {
  const downloadPath = getDownloadPath()
  const url = `${process.env.PUBLISH_URL}/${needFullPack(releaseName) ? 'full/app.7z' : 'app.7z'}`

  // 清理之前下载失败的缓存文件
  try {
    if (await pathExists(downloadPath)) {
      await rimraf(downloadPath, { maxRetries: 5 })
    }
  } catch (err) {
    log.error(err)
  }

  const downloadService = new DownloadService(url, downloadPath)
  downloadService.on('progress', progress => {
    downloadProgress({ percent: progress })
  })
  downloadService.on('finish', () => {
    downloadProgress({ percent: 100 })
  })
  try {
    await downloadService.start()
  } catch (err) {
    updateError('更新出错，请重试')
  }
}

// 使用 update-tool.exe 直接从 7z 文件解压替换并重启
async function extractAllAndReload() {
  try {
    await updateApplying() // 正在升级事件
    log.info('start replace-from7z with update-tool')

    const downloadPath = getDownloadPath()
    const exePath = app.getPath('exe')

    // 检查下载文件是否存在
    const exists = await pathExists(downloadPath)
    log.info(`${downloadPath} exists ==>>>> `, exists)
    if (!exists) {
      updateError('下载文件丢失，请尝试重启客户端后再进行升级')
      return
    }

    // 确保update-tool.exe准备就绪
    let updateToolPath = await ensureUpdatetoolReady()

    log.info('downloadPath ==>>> ', downloadPath)

    // 构建 update-tool replace-from7z 命令参数
    const args = [
      'replace-from7z',
      '--source',
      downloadPath,
      '--target',
      process.resourcesPath,
      '--restart',
      '--exe-path',
      exePath,
      '--skip-backup',
      '--restart-delay',
      '1'
    ]

    log.info('Executing update-tool replace-from7z with args:', args)

    // 直接启动update-tool.exe
    try {
      const childProcess = spawn(updateToolPath, args, {
        detached: true,
        stdio: 'ignore',
        windowsHide: true,
        env: {
          ...process.env,
          LOG_DIR: app.getPath('logs')
        }
      })

      childProcess.unref()
      log.info('update-tool started, PID:', childProcess.pid)

      // 延迟退出主进程，确保update-tool已经启动
      setTimeout(() => {
        log.info('Exiting main process, update-tool will handle restart')
        app.exit(0)
      }, 1000) // 等待1秒确保update-tool已启动
    } catch (err) {
      log.error('Error executing update-tool:', err)
      updateError('升级工具执行失败，请重试')
    }
  } catch (err) {
    updateError('升级工具执行失败，请重试')
    log.info('extractAllAndReload error ==>>> ', err)
  }
}

// 是否需要全量包，全量包包含了浏览器等 remoteVersion => 远程浏览器的版本，存于 releaseName 字段
function needFullPack(remoteVersion) {
  if (!remoteVersion) return false // 远程字段没有值的时候，不需要升级
  const curr = autoUpdater.currentVersion.version
  const result = compareVersion(curr, remoteVersion)
  return result === 1
}
