import { app, ipcMain } from 'electron'
import { apiLog } from '../logs'
import path from 'path'
import { getClient } from './client'
import { isDirectoryEmpty } from '../utils'
import fs from 'fs-extra'
import { safeJsonParse } from '../utils/safeJsonParse'

const Table = 'global_configs'

/**
 * 保存全局配置，基础方法
 * @param {string} name 配置名称
 * @param {string} value 配置值
 */
export async function saveGlobalConfig(name, value) {
  if (!name || !value) throw new Error('name and value are required')

  try {
    const db = await getClient()
    await db(Table).insert({ config_name: name, config_value: value }).onConflict('config_name').merge()
  } catch (err) {
    apiLog.error('save global config error ==>>> ', name, value, err)
  }
}

/**
 * 获取全局配置，基础方法
 * @param {string} name 配置名称
 * @returns {Promise<string | null>} 配置值
 */
export async function getGlobalConfig(name) {
  if (!name) throw new Error('name is required')
  try {
    const db = await getClient()
    const res = await db(Table).select('config_value').where('config_name', '=', name).first()
    if (res) return res.config_value
  } catch (err) {
    apiLog.error('get global config error ==>>> ', name, err)
  }
  return null
}

/**
 * 删除全局配置，基础方法
 * @param {string} name 配置名称
 */
export async function deleteGlobalConfig(name) {
  if (!name) throw new Error('name is required')
  try {
    const db = await getClient()
    await db(Table).delete().where('config_name', '=', name)
  } catch (err) {
    apiLog.error('delete global config error ==>>> ', name, err)
  }
}

// 保存浏览器缓存目录，保存时，保存为所有浏览器的cache根目录
export async function saveBrowserCacheDir(dir) {
  try {
    // 验证缓存目录位置
    const normalizedDir = path.resolve(dir)
    const appPath = app.getAppPath()

    // 检查是否在磁盘根目录
    const driveRoot = path.parse(normalizedDir).root
    if (normalizedDir === driveRoot) {
      throw new Error('Cannot save cache directory to disk root')
    }

    // 检查是否在客户端安装目录下
    if (normalizedDir.startsWith(appPath)) {
      throw new Error('Cannot save cache directory under installation directory')
    }

    await saveGlobalConfig('browser_cache_dir', dir)
  } catch (err) {
    apiLog.error('save browser cache dir error ==>>> ', err)
    throw err // 重新抛出错误，让调用方知道保存失败
  }
}

// 获取浏览器缓存目录，获取时，直接取到具体浏览器，未保存则获取userData下的LocalCache
// browserId传空则获取到根目录
export async function getBrowserCacheDir(browserId = '') {
  // 默认目录
  let defaultPath = path.join(app.getPath('userData'), 'BrowserCache')

  try {
    const dir = await getGlobalConfig('browser_cache_dir')
    if (dir) {
      return path.join(dir, browserId)
    } else {
      // 只有默认目录是空的，并且安装目录不为C盘，并且win系统，则设置默认缓存目录到安装目录的根目录下
      const isEmpty = await isDirectoryEmpty(defaultPath)
      if (process.platform === 'win32' && isEmpty) {
        if (!app.getAppPath().startsWith('C')) {
          const drive = app.getAppPath().slice(0, 1)
          defaultPath = path.resolve(`${drive}:/bitbrowser-cache`)
        } else {
          // 默认目录为空时，有可能覆盖安装从D/E盘变更到了C盘，导致缓存目录变更，查找下D/E盘下是否存在bitbrowser-cache目录
          const dPath = path.resolve(`D:/bitbrowser-cache`)
          const ePath = path.resolve(`E:/bitbrowser-cache`)
          const dExists = await fs.pathExists(dPath)
          const eExists = await fs.pathExists(ePath)

          if (dExists) {
            defaultPath = dPath
          } else if (eExists) {
            defaultPath = ePath
          }
        }
      }
    }
  } catch (err) {
    apiLog.error('get browser cache dir error ==>>> ', err)
  }

  // 默认返回系统默认的目录，且保存下
  saveBrowserCacheDir(defaultPath)
  return path.join(defaultPath, browserId)
}

// 保存本地服务端口
export async function saveLocalServerPort(port) {
  try {
    await saveGlobalConfig('server_port', port)

    // 兼容旧版，保存本地文件
    saveConfigAddress(port)
  } catch (err) {
    apiLog.error('save local server port error ==>>> ', err)
  }
}

function saveConfigAddress(port) {
  const config = {
    localServerAddress: `http://127.0.0.1:${port}`
  }
  fs.outputJson(path.join(app.getPath('userData'), 'config.json'), config)
}

// 往config.json文件里设置auth token
export async function saveAuthToken(enable = false, token = '') {
  try {
    const configPath = path.join(app.getPath('userData'), 'config.json')
    const config = await fs.readJson(configPath)

    config.enableAuth = enable
    config.authToken = token
    await fs.outputJson(configPath, config)
  } catch (err) {
    apiLog.error('set auth token error ==>>>> ', err)
  }
}

// 获取本地服务端口，默认返回 54345
export async function getLocalServerPort() {
  try {
    const port = await getGlobalConfig('server_port')
    if (port) return +port
  } catch (err) {
    apiLog.error('get server port error ==>>> ', err)
  }
  return 54345
}

