// 获取所有全局配置
export async function getGlobalConfigs() {
  try {
    const db = await getClient()
    const res = await db(Table).select('*')
    return res.reduce((acc, cur) => {
      if (cur.config_name !== 'rpa_md5') {
        acc[cur.config_name] = cur.config_value
      }
      return acc
    }, {})
  } catch (err) {}
  return {}
}

// 分字段设置全局配置
export async function setGlobalConfigs(configs) {
  for (const [key, value] of Object.entries(configs)) {
    await saveGlobalConfig(key, value + '')
  }
}

