/**
 * @description 获取系统代理配置
 * @returns {Promise<{type: 1 | 2 | 3, port: Number}>} 代理配置 ,1 => 自动检测系统代理 2 => 不使用系统代理，3 => 自定义端口
 * */
export async function getSysProxyConfig() {
  const sysProxyConfig = await getGlobalConfig('sys_proxy_config')
  if (sysProxyConfig) return safeJsonParse(sysProxyConfig, 'getSysProxyConfig')
  return { type: 2, port: null }
}

