import { app } from 'electron'
import { apiLog } from '../logs'
import { knex } from 'knex'
import path from 'path'

let dbInstance = null
let initPromise = null
let isInitialized = false

// 数据库初始化超时时间（毫秒）
const DB_INIT_TIMEOUT = 30000

/**
 * 获取数据库客户端实例（懒加载）
 * 只在第一次调用时初始化数据库连接和表结构
 * @returns {Promise<import('knex').Knex>} 数据库客户端实例
 */
export async function getClient() {
  // 如果已经初始化完成，直接返回
  if (isInitialized && dbInstance) {
    return dbInstance
  }

  // 如果正在初始化，等待初始化完成
  if (initPromise) {
    await initPromise
    return dbInstance
  }

  // 开始初始化，添加超时控制
  initPromise = Promise.race([
    initializeDatabase(),
    new Promise((_, reject) =>
      setTimeout(() => reject(new Error(`Database initialization timeout (${DB_INIT_TIMEOUT}ms)`)), DB_INIT_TIMEOUT)
    )
  ])

  try {
    await initPromise
    return dbInstance
  } catch (err) {
    // 超时或失败时清理状态，允许重试
    // apiLog.error('Database initialization failed, will retry on next call:', err)
    initPromise = null
    throw err
  }
}

/**
 * 执行数据库初始化
 */
async function initializeDatabase() {
  try {
    apiLog.info('Initializing database connection...')

    dbInstance = knex({
      client: 'better-sqlite3',
      connection: {
        filename: path.join(app.getPath('userData'), 'db.sqlite')
      },
      useNullAsDefault: true,
      log: {
        warn: apiLog.warn,
        error: apiLog.error,
        deprecate: apiLog.info
      }
    })

    // 初始化所有表结构
    await initTables()

    isInitialized = true
    apiLog.info('Database initialized successfully')
  } catch (err) {
    apiLog.error('Failed to initialize database:', err)
    dbInstance = null
    throw new Error(`Database initialization failed: ${err.message}`)
  }
}

/**
 * 主动连接数据库
 * 在应用启动时调用，提前初始化数据库连接
 * @returns {Promise<{success: boolean, error?: string, duration?: number}>}
 */
export async function connect() {
  const startTime = Date.now()

  try {
    await getClient()
    const duration = Date.now() - startTime
    apiLog.info(`Database connected successfully in ${duration}ms`)

    return {
      success: true,
      duration
    }
  } catch (err) {
    const duration = Date.now() - startTime
    // apiLog.error(`Database connection failed after ${duration}ms:`, err)

    return {
      success: false,
      error: err.message,
      duration
    }
  }
}

/**
 * 检查数据库连接健康状态
 * @returns {Promise<{healthy: boolean, error?: string}>}
 */
export async function healthCheck() {
  try {
    const db = await getClient()
    await db.raw('SELECT 1')
    return { healthy: true }
  } catch (err) {
    apiLog.error('Database health check failed:', err)
    return {
      healthy: false,
      error: err.message
    }
  }
}

/**
 * 重置数据库连接
 * 用于重连或测试场景
 */
export async function reset() {
  try {
    if (dbInstance) {
      await dbInstance.destroy()
      apiLog.info('Database connection destroyed')
    }
  } catch (err) {
    apiLog.error('Failed to destroy database connection:', err)
  } finally {
    dbInstance = null
    initPromise = null
    isInitialized = false
    apiLog.info('Database connection reset complete')
  }
}

/**
 * 初始化所有数据库表结构
 */
async function initTables() {
  await createGlobalConfigsTable()
  await createLocalExtensionsTable()
  await createChromeVersionsTable()
  await createFirefoxVersionsTable()
  await createRpaLogsTable()
  await createSyncOssLogsTable()
  await createCacheFilesTable()
  await createLocalExtraLogsTable()
  await createCacheDataForServerTable()
  await createBrowserTempDataTable()
  await createBrowserPersistentDataTable()
}

/**
 * 创建全局配置表
 */
async function createGlobalConfigsTable() {
  const hasTable = await dbInstance.schema.hasTable('global_configs')
  if (!hasTable) {
    await dbInstance.schema.createTable('global_configs', table => {
      table.increments('id')
      table.string('config_name')
      table.string('config_value')
      table.unique('config_name')
    })
  }
}

/**
 * 创建本地扩展表
 */
async function createLocalExtensionsTable() {
  const hasTable = await dbInstance.schema.hasTable('local_extensions')
  if (!hasTable) {
    await dbInstance.schema.createTable('local_extensions', table => {
      table.increments('id')
      table.string('name')
      table.string('desc')
      table.string('extension_id')
      table.string('icon')
      table.string('version')
      table.boolean('is_use')
      table.unique('extension_id')
      table.string('cloud_id')
      table.string('main_user_id')
    })
  } else {
    // 处理字段迁移
    const cloudIdExists = await dbInstance.schema.hasColumn('local_extensions', 'cloud_id')
    const userColumnExists = await dbInstance.schema.hasColumn('local_extensions', 'main_user_id')

    if (!cloudIdExists) {
      await dbInstance.schema.alterTable('local_extensions', table => {
        table.string('main_user_id')
        table.string('cloud_id')
      })
    } else if (!userColumnExists) {
      await dbInstance.schema.alterTable('local_extensions', table => {
        table.string('main_user_id')
      })
    }
  }
}

