/**
 * 创建 RPA 日志表
 */
async function createRpaLogsTable() {
  const hasTable = await dbInstance.schema.hasTable('rpa_logs')
  if (!hasTable) {
    await dbInstance.schema.createTable('rpa_logs', table => {
      table.increments('id')
      table.string('browser_id')
      table.integer('browser_seq')
      table.string('task_id')
      table.integer('status') // 任务执行状态 1 开始执行 2 执行中 3 执行完成 4 任务未执行完，跳过
      table.integer('error_type') // 1 正常打开 2 已打开，跳过 3 打开失败 4 关闭窗口 5 已打开的窗口执行
      table.string('error_msg') // 错误信息
      table.dateTime('created_time').defaultTo(new Date())
      table.bigInteger('created_time_hr').defaultTo(process.hrtime.bigint())
    })
  }
}

