import schedule from 'node-schedule'
import { autoUpdater } from 'electron-updater'
import { heartBeat } from '../electron-main'
import debounce from 'lodash/debounce'
import syncTasks from '../interface/SyncTasks'
import browserCacheClear from './BrowserCacheClear'
import { processProtect } from './processMom'
import { memoryMonitor } from './memoryMonitor'
import { getGlobalConfigs } from '../data/globalConfigs'
import { log } from '../logs'

export function registerSchedules() {
  // 每小时执行一次
  schedule.scheduleJob('every-hour', { second: 0, minute: 0 }, () => {
    log.info('check for updates every hour')
    autoUpdater.checkForUpdates()
  })

  // 5分钟心跳，增加10秒防抖延迟，防止休眠后瞬间n次调用，从当前分钟数算起
  schedule.scheduleJob('heart-beat', `${new Date().getMinutes() % 5}/5 * * * *`, debounce(heartBeat, 10000))

  // schedule.scheduleJob('sync-task', { second: 0 }, () => {
  //   syncTasks.run()
  // })

  // 每天6点执行一次清理浏览器缓存任务
  schedule.scheduleJob('every-day-at-6', { hour: 6, minute: 0, second: 0 }, () => {
    log.info('clear browser cache files at 6 clock every day ===>>>>>>>> ', Date.now())
    browserCacheClear.clearByDays()
  })

  // 每5分钟执行一次内存监控
  schedule.scheduleJob('memory-monitor', '*/5 * * * *', debounce(memoryMonitor, 10000))

  setProcessClear()
}

export async function setProcessClear(period) {
  if (!period) {
    const configs = await getGlobalConfigs()
    period = configs.process_protect_period || '0'
  }

  schedule.cancelJob('process-clear') // 先取消定时器
  if (period === '0') return

  log.info('set process period ==>>>> ', period)
  // 每period分钟执行
  schedule.scheduleJob('process-clear', `*/${period} * * * *`, () => {
    log.info('process clear every ' + period + ' minute')
    processProtect()
  })
}
