import { autoUpdater } from 'electron-updater'
import { reportErrorLogs } from './request'
class Reporter {
  constructor() {
    this.defaultData = {
      platform: process.platform,
      arch: process.arch,
      version: autoUpdater.currentVersion.version
    }
  }

  browser(browserId, err, comments) {
    reportErrorLogs({
      errorContent: err.stack,
      logKey: browserId,
      logType: 'Browser',
      parameters: '',
      requestType: '',
      url: '',
      extraInfo: comments,
      ...this.defaultData
    })
  }

  extension(err, extensionId, extraInfo) {
    reportErrorLogs({
      errorContent: err.stack,
      logType: 'Extensions',
      logKey: extensionId,
      extraInfo,
      ...this.defaultData
    })
  }

  requester(config, resData) {
    reportErrorLogs({
      errorContent: JSON.stringify(resData),
      logKey: config.baseURL,
      logType: 'ApiRequest',
      parameters: config.data,
      requestType: config.method,
      url: config.url,
      extraInfo: 'Api请求报错',
      ...this.defaultData
    })
  }

  fingerprint(id, err, extraInfo) {
    reportErrorLogs({
      errorContent: err.stack,
      logType: 'Fingerprint',
      logKey: id,
      extraInfo,
      ...this.defaultData
    })
  }

  updater(err) {
    reportErrorLogs({
      errorContent: err.stack,
      logType: 'AutoUpdater',
      ...this.defaultData
    })
  }
}

const reporter = new Reporter()

export default reporter
