import Router from 'koa2-router'
import { clearExtraLogs, deleteExtraLogs, getExtraInfo, listExtraLogs, saveExtraLog, updateExtraLog } from '../data/extraLogs'
import { ApiUtil } from '../interface/ApiUtil'
import { apiAuth } from '../middleware/auth'

const extraLogRouter = new Router()

extraLogRouter.use(apiAuth())

extraLogRouter.post('/extralog/add', async ctx => {
  const data = ctx.request.body
  if (!data || !data.log_key || !data.log_value) {
    throw new Error('log_key and log_value field are required.')
  }

  const res = await saveExtraLog(data)
  ctx.body = ApiUtil.success(res)
})

extraLogRouter.post('/extralog/delete', async ctx => {
  const ids = ctx.request.body.ids
  if (!ids || !ids.length) {
    throw new Error('ids is array and required.')
  }

  await deleteExtraLogs(ids)
  ctx.body = ApiUtil.success()
})

extraLogRouter.post('/extralog/update', async ctx => {
  const data = ctx.request.body
  await updateExtraLog(data)
  ctx.body = ApiUtil.success()
})

extraLogRouter.post('/extralog/detail', async ctx => {
  const res = await getExtraInfo(ctx.request.body.id)
  ctx.body = ApiUtil.success(res)
})

extraLogRouter.post('/extralog/list', async ctx => {
  const body = ctx.request.body

  const res = await listExtraLogs(body)
  ctx.body = ApiUtil.success(res)
})

extraLogRouter.post('/extralog/clear', async ctx => {
  await clearExtraLogs()
  ctx.body = ApiUtil.success()
})

export default extraLogRouter
