import Router from 'koa2-router'
import { ApiUtil } from '../interface/ApiUtil'
import { saveBrowserPersistentData, BrowserPersistentDataType } from '../data/browserPersistentData'

const boundsRouter = new Router()

boundsRouter.post('/bounds/set', async ctx => {
  const body = ctx.request.body
  if (!body.browserId) return (ctx.body = ApiUtil.fail('browserId is required'))
  if (!body.bounds) return (ctx.body = ApiUtil.fail('bounds is required'))
  await saveBrowserPersistentData({ browserId: body.browserId, type: BrowserPersistentDataType.Bounds, value: body.bounds })
  ctx.body = ApiUtil.success()
})

export default boundsRouter
