import axios from 'axios'
import browserStatus from './browserStatus'
import { statusLog } from '../logs'

class BrowserExtensionStore {
  constructor() {
    this.store = new Map()
    this.status = new Set() // 正在处理的browser，不用重复处理
    this.regex = /chrome-extension:\/\/([^/]+)/
  }

  // 添加extensionId
  async add(browserId, browser) {
    if (this.status.has(browserId)) return

    try {
      this.status.add(browserId)
      const httpAddress = browserStatus.getBrowserHttpAddress(browser)
      // statusLog.info('extension store http address ==>>> ', httpAddress)

      const res = await axios.get(`${httpAddress}/json/list`)

      const extensions = res.data.filter(item => item.url && item.url.startsWith('chrome-extension://'))
      // statusLog.info('extension store extensions ==>>> ', extensions)

      const extensionIds = extensions.map(item => item.url.match(this.regex)[1])
      // statusLog.info('extension ids ==>>>>>>> ', extensionIds)

      this.store.set(browserId, new Set(extensionIds))
      // statusLog.info('extension store done !!!!!!!!!!!!!')
    } catch (err) {
      statusLog.error('set extension ids error ===>>>> ', err)
    }

    this.status.delete(browserId)
  }

  // 删除extensionId，暂时无须删除
  remove(browserId, url) {
    if (!url || !browserId) return

    const extensionId = getExtensionId(url)
    if (!extensionId) return

    if (this.store.has(browserId)) {
      this.store.get(browserId).delete(extensionId)
    }
  }

  // 获取窗口加载的扩展
  getIds(browserId) {
    if (!this.store.has(browserId)) return []

    return Array.from(this.store.get(browserId))
  }

  // 删除窗口存储Set
  removeBrowser(browserId) {
    if (!browserId) return
    this.store.delete(browserId)
    this.status.delete(browserId)
  }

  clear() {
    this.store.clear()
  }
}

const browserExtensionStore = new BrowserExtensionStore()
export default browserExtensionStore

/**
 * @description 匹配url中的extensionId，并返回
 * @param {string} [url=''] url
 * @returns {String | Null} 返回extensionId或者null
 * */
function getExtensionId(url) {
  if (!url.startsWith('chrome-extension://')) return null

  const regex = /chrome-extension:\/\/([^/]+)/
  const matches = url.match(regex)

  if (matches && matches.length >= 2) {
    return matches[1]
  }

  return null
}
