import { apiLog } from '../logs'
import { execCmd } from './index'

// 记录已经尝试过添加防火墙规则的版本
const attemptedVersions = new Set()

/**
 * 判断错误是否由防火墙引起，error是空对象，则有可能是
 */
export function isPossibleFirewallError(error) {
  return !error || (typeof error === 'object' && Object.keys(error).length === 0)
}

/**
 * 检查某个版本是否已经尝试过添加防火墙规则
 * @param {string} coreVersion - 内核版本号
 * @returns {boolean}
 */
export function hasAttemptedFirewallRule(coreVersion) {
  return attemptedVersions.has(coreVersion)
}

/**
 * 标记某个版本已尝试添加防火墙规则
 * @param {string} coreVersion - 内核版本号
 */
function markAsAttempted(coreVersion) {
  attemptedVersions.add(coreVersion)
  apiLog.info(`mark ${coreVersion} as attempted ===>>>>>> `)
}

/**
 * 为 BitBrowser.exe 添加防火墙入站规则
 * @param {string} chromePath - BitBrowser.exe 完整路径
 * @param {string} coreVersion - 内核版本号，如 '142', '140'
 */
export async function addFirewallRule(chromePath, coreVersion) {
  if (process.platform !== 'win32') {
    return { success: false, reason: 'not_windows' }
  }

  try {
    const ruleName = `BitBrowser-${coreVersion}`

    apiLog.info(`set firewall rule: ${ruleName}`)

    // 1. 检查规则是否已存在且路径匹配
    try {
      const result = await execCmd(`netsh advfirewall firewall show rule name="${ruleName}" verbose`, '', 5000)
      if (result.includes(chromePath)) {
        apiLog.info('firewall rule already exists')
        markAsAttempted(coreVersion)
        return { success: true, reason: 'already_exists' }
      }
    } catch {
      // 规则不存在，继续
    }

    // 2. 删除旧规则
    try {
      await execCmd(`netsh advfirewall firewall delete rule name="${ruleName}"`, '', 5000)
      apiLog.info(`delete old rule: ${ruleName}`)
    } catch {
      // 删除失败没关系
    }

    // 3. 添加新规则
    await execCmd(
      `netsh advfirewall firewall add rule name="${ruleName}" dir=in action=allow program="${chromePath}" enable=yes profile=any`,
      '',
      10000
    )

    apiLog.info(`set firewall rule success: ${ruleName}`)
    markAsAttempted(coreVersion)
    return { success: true }
  } catch (err) {
    apiLog.error('set firewall rule failed ==>>> ', err)
    // 无论成功失败，都标记为已尝试，避免重复尝试
    markAsAttempted(coreVersion)
    return { success: false }
  }
}
