const UserAgentPlatformVersionMap = {
  6.3: '0.3.0',
  6.2: '0.2.0',
  6.1: '0.1.0',
  '10.0': '10.0.0'
}

const BrandingInfo = {
  IDS_PRODUCT_NAME: 'BitBrowser',
  'IDS_PRODUCT_NAME@zh-CN': '比特浏览器',
  IDS_ABOUT_VERSION_COMPANY_NAME: 'BitBrowser',
  'IDS_ABOUT_VERSION_COMPANY_NAME@zh-CN': '比特浏览器',
  IDS_ABOUT_VERSION_COPYRIGHT: 'Copyright ©2018-2025 HongKong Bit-Internet Technology Limited. All rights reserved.',
  'IDS_ABOUT_VERSION_COPYRIGHT@zh-CN': '版权所有 2025 北京元宇蓝图科技有限公司，保留所有权利。'
}

class FingerPint {
  // 根据接口返回的 browserFingerPrint 先初始化一些固定值
  constructor(browserFingerPrint) {
    this.Resource = BrandingInfo

    this.isMobile = browserFingerPrint.ostype !== 'PC' // 移动端判断，非指纹值
    this.uiLang = browserFingerPrint.displayLanguages // 界面语言，跟随IP时重置

    // 随后匹配设置语言
    this.appLocale = '' // 环境语言，只能设置一个
    this.acceptLang = browserFingerPrint.languages // 用户偏好语言，可以设置多个，逗号分隔

    this.taskbarString = browserFingerPrint.seq + '' // seq
    this.toolbarString = browserFingerPrint.seq + '' // seq
    this.doNotTrack = +browserFingerPrint.doNotTrack === 1 //
    this.userAgent = browserFingerPrint.userAgent
    this.battery = this.isMobile ? genRandomNum(20, 100) : 100 // 移动端20-100随机
    this.navigator = {
      platform: browserFingerPrint.os || 'Win32',
      hardwareConcurrency: +browserFingerPrint.hardwareConcurrency || null, // cpu
      deviceMemory: +browserFingerPrint.deviceMemory,
      maxTouchPoints: this.isMobile ? 5 : 0, // PC 0, mobile 1
      vendor: browserFingerPrint.navigatorVendor || 'Google Inc.' // ios为："Apple Computer, Inc."
    }
    try {
      this.UserAgentArchitecture = browserFingerPrint.architecture
      this.UserAgentBitness = browserFingerPrint.bitness || 64
      this.UserAgentIsWow64 = browserFingerPrint.iswow64 || false
      this.UserAgentIsMobile = this.isMobile
      this.UserAgentModel = browserFingerPrint.uamodel || ''

      // 匹配userAgentVersion，如果是标准的 CriOS 或者 Chrome，则按照第一个规则匹配，匹配不到，可能是用户自定义的ua，按照第二种方式匹配
      let userAgentVersion = ''
      const matchs = browserFingerPrint.userAgent.match(/(CriOS\/|Chrome\/)([\d\.]+)/)
      if (matchs && matchs.length) {
        userAgentVersion = matchs[2]
      } else {
        const otherMatchs = browserFingerPrint.userAgent.match(/(\d+\.\d+\.\d+\.\d+)/)
        if (otherMatchs && otherMatchs.length) {
          userAgentVersion = otherMatchs[1]
        }
      }

      this.userAgentVersion = userAgentVersion

      this.UserAgentPlatform = getUserAgentPlatform(browserFingerPrint.ostype, browserFingerPrint.os) // navigator.userAgentData.platform [Windows | macOS | Linux | iOS | Android]

      this.UserAgentPlatformVersion =
        browserFingerPrint.platformVersion ||
        (browserFingerPrint.os.includes('Win')
          ? UserAgentPlatformVersionMap[browserFingerPrint.userAgent.match(/Windows NT (\d+.\d+)/)[1]]
          : null)

      if (browserFingerPrint.ostype !== 'IOS') {
        const mainVersion = userAgentVersion.split('.').shift()
        if (+mainVersion >= 102) {
          this.userAgent = this.userAgent.replace(userAgentVersion, `${mainVersion}.0.0.0`)
        }
      }
    } catch (err) {
      reporter.fingerprint(browserFingerPrint.id, err, 'browserFingerPrint.userAgent')
      log.error('initial fingerprint error ==>>> ', err)
    }

    this.maxImageBytes = browserFingerPrint.abortImageBytes || null

    this.PasswordManager = {
      RemoveAllBeforeImport: false, // 加载 ～LoginData
      CryptLoginData: true, // 加密 ～LoginData
      Lock: false, // 禁止自带的密码管理器
      ForceAutofillDomains: [],
      LockAutofillDomains: []
    }

    this.screen = {
      pixelDepth: browserFingerPrint.colorDepth || 24, // read config
      colorDepth: browserFingerPrint.colorDepth || 24, // read config
      devicePixelRatio: browserFingerPrint.devicePixelRatio || 1,
      width: 1920, // read electron|config
      height: 1200, // read electron|config
      availWidth: 1920, // read electron|config
      availHeight: 1200 // read electron|config
    }
    // allow|block|'' 为空时询问
    if (+browserFingerPrint.position === 0) {
      this.geoPositionMode = '' // 询问
    } else if (+browserFingerPrint.position === 1) {
      this.geoPositionMode = 'allow'
    } else {
      this.geoPositionMode = 'block'
    }
    // 跟随IP时随后重置
    this.geoPosition = {
      accuracy: browserFingerPrint.precisionData, // 精度
      latitude: +browserFingerPrint.lat,
      longitude: +browserFingerPrint.lng
    }
    this.timeZone = browserFingerPrint.timeZone || '' // 跟随IP时随后重置

    // 新版 WebRTC 配置
    this.WebRTC = {
      HostIP: null,
      PublicIP: null,
      IceServers: null,
      Disabled: +browserFingerPrint.webRTC === 2,
      IPHandlingPolicy: null
    }
    // 隐私模式
    if (+browserFingerPrint.webRTC === 3) {
      this.WebRTC.IPHandlingPolicy = 'disable_non_proxied_udp'
    }
    // 替换模式
    if (+browserFingerPrint.webRTC === 0) {
      this.WebRTC.HostIP = browserFingerPrint.hostIP
      // this.WebRTC.PublicIP = browserFingerPrint.publicIP
      // this.WebRTC.IceServers = [{ urls: ['stun:stun.l.google.com:19302'], username: '', password: '' }]
    }

    // TODO 几个大版本后删除，当前版本 709 默认隐私，如果替换，即跟随IP，则随后重置
    if (+browserFingerPrint.webRTC === 2) {
      this.disableWebRtc = true
    } else if (+browserFingerPrint.webRTC === 3) {
      this.webRtcRemoteIp = '-'
    }

    // agent 随后根据代理类型配置
    this.Proxy = {}
    this.WebGL = {
      webglRenderer: browserFingerPrint.webGLRender, // config
      webglVendor: browserFingerPrint.webGLManufacturer, // config
      enableWebGLRendererNoise: +browserFingerPrint.webGL === 0,
      // webGLRendererNoiseInterval: 1,
      webGLRendererNoiseValue: +browserFingerPrint.webGLValue
    }
    // 随机
    this.canvasContext = {
      enableCanvasContextNoise: +browserFingerPrint.canvas === 0,
      canvasContextNoiseValue: +browserFingerPrint.canvasValue
      // canvasContextNoiseInterval: 1
    }
    // 随机
    this.audioBuffer = {
      enableAudioBufferNoise: +browserFingerPrint.audioContext === 0,
      audioBufferNoiseValue: +browserFingerPrint.audioContextValue,
      audioBufferNoiseInterval: 10
    }

    // 开启则数组，否则null
    this.DisableSSLCipherSuites = browserFingerPrint.disableSslCipherSuitesFlag
      ? browserFingerPrint.disableSslCipherSuites.split(',')
      : null

    // null 为关闭，有值为数组
    this.mediaDevicesInfo = null
    if (+browserFingerPrint.mediaDevice === 0 && browserFingerPrint.mediaDeviceValue) {
      try {
        this.mediaDevicesInfo = safeJsonParse(browserFingerPrint.mediaDeviceValue, 'mediaDevicesInfo')
      } catch (err) {
        log.error('media deviece set error ==>>> ', browserFingerPrint.mediaDeviceValue, err)
      }
    }
    // null 为关闭，有值为数组
    this.voices = +browserFingerPrint.speechVoices === 0 ? browserFingerPrint.speechVoicesValue || null : null
    if (+browserFingerPrint.speechVoices === 0 && browserFingerPrint.speechVoicesValue) {
      try {
        this.voices = safeJsonParse(browserFingerPrint.speechVoicesValue, 'speechVoices')
      } catch (err) {
        log.error('speech voices set error ==>>> ', browserFingerPrint.speechVoicesValue, err)
      }
    }

    this.FontConfig = {
      BasePath: '#/BitBrowser/Fonts',
      Names: [],
      BlockFallbackList: [
        'Segoe UI Emoji', // Win 模拟 Mac 时, 不 Block 掉 CreepJS 能检测到.
        'Segoe Fluent Icons'
      ],
      Files: [] // 读取本地文件，相对 BitBrowser/Fonts
    }

    // 是否移动端 true时修改 user-agent
    this.enableDeviceEmulation = this.isMobile
    this.emulationPrefs = {
      customEmulatedDeviceList: [
        {
          capabilities: ['mobile', 'touch'],
          modes: [
            {
              orientation: 'vertical',
              title: ''
            },
            {
              orientation: 'horizontal',
              title: ''
            }
          ],
          screen: {
            'device-pixel-ratio': browserFingerPrint.devicePixelRatio || 3, // 移动端默认设置3
            horizontal: { height: 414, width: 736 },
            vertical: { height: 736, width: 414 }
          },
          show: 'Default',
          'show-by-default': true,
          title: 'Custom',
          type: 'phone',
          'user-agent': this.userAgent
        }
      ],
      'emulation.deviceModeValue': {
        device: 'Custom',
        mode: '',
        orientation: 'vertical'
      },
      'emulation.deviceScale': 1.0
    }

    // 设备信息
    this.DeviceInfo = {
      enabled: browserFingerPrint.deviceInfoEnabled || false,
      computerName: browserFingerPrint.computerName,
      modelName: browserFingerPrint.modelName || browserFingerPrint.computerName,
      macAddr: browserFingerPrint.macAddr,
      manufacturerName: browserFingerPrint.manufacturerName || null // 设备型号
    }

    this.ClientRectNoiseVal = browserFingerPrint.clientRectNoiseEnabled ? browserFingerPrint.clientRectNoiseValue : 0 // 0 关闭，大于0开启，随机 1 - 999999

    this.plugins = browserFingerPrint.enablePlugins ? getPlugins(browserFingerPrint.plugins) : null

    this.window = {
      max_width: null,
      max_height: null
    }

    this.WebGPU = browserFingerPrint.webgpu || null

    // null 保持原样，allow 允许通知，但不弹出权限，block 阻止通知，并不弹出权限
    this.notificationsMode = null
    this.StorageQuota = {
      TotalDiskSpaceKB: (browserFingerPrint.totalDiskSpace && +browserFingerPrint.totalDiskSpace) || null
    }

    // null 或者不设置，chrome默认行为，[] 屏蔽所有本地端口连接，[1,2,3] 除白名单外，屏蔽所有本地接口连接
    if (browserFingerPrint.portScanProtect !== '1') {
      this.AllowLocalWebSocketPorts = []
    }
    if (browserFingerPrint.portWhiteList) {
      try {
        this.AllowLocalWebSocketPorts = browserFingerPrint.portWhiteList.split(',').map(port => +port)
      } catch (err) {
        log.error('set websocket ports error ==>>>>> ', err.message)
      }
    }
  }

  // 设置 Proxy,要有默认字段名
  async setProxy({ type = '', host = '', port = null, username = '', password = '', enableSocks5Udp = false }) {
    this.Proxy = {
      type: type,
      host: host,
      port: port,
      username: username,
      password: password,
      enable_socks5_udp: enableSocks5Udp,
      bypass: [],
      bypass_rules: []
    }

    await this.setProxyBypass()
    await this.setProxyBypassRules()
  }

  async setProxyBypass() {
    try {
      const res = await getGlobalValueFromClient({ globalValueType: 'ipWhitelist' })
      if (res && res.globalValue && res.globalValue.length) {
        this.Proxy.bypass = safeJsonParse(res.globalValue, 'setProxyBypass')
      }

      this.Proxy.bypass.push('127.0.0.1') // 添加过滤 127
    } catch (err) {
      log.error('set proxy bypass error ==>>> ', err)
    }
  }

  // 设置全局的Bypass_rules
  async setProxyBypassRules() {
    const rules = await getProxyBypassRules()

    try {
      // 挑出需要覆盖掉 bypass 的值，从 bypass 中删掉
      const overwriteList = rules.filter(item => item.__overwriteBypass)
      const bypassSet = new Set(this.Proxy.bypass)
      overwriteList
        .reduce((acc, cur) => {
          acc = acc.concat(cur.domains)
          return acc
        }, [])
        .map(domain => {
          bypassSet.delete(domain)
        })

      this.Proxy.bypass = Array.from(bypassSet)
      this.Proxy.bypass_rules = rules
    } catch (err) {
      apiLog.error('set bypass rules error ==>>> ', err)
    }
  }

  // 设置screen size以及像素比，后三个参数只有PC有效
  setScreenSize(width, height, availWidth, availHeight, devicePixelRatio) {
    this.screen.width = width
    this.screen.height = height
    this.screen.availWidth = this.enableDeviceEmulation ? width : availWidth
    this.screen.availHeight = this.enableDeviceEmulation ? height : availHeight
    if (devicePixelRatio) this.screen.devicePixelRatio = devicePixelRatio
    // 移动端同时修改模拟的尺寸
    if (this.enableDeviceEmulation) {
      const screen = this.emulationPrefs.customEmulatedDeviceList[0].screen
      screen.vertical.width = width
      screen.vertical.height = height
      screen.horizontal.width = height
      screen.horizontal.height = width
    }
  }

  // 设置地理位置
  setGeoPosition(lat, lng, accuracy) {
    this.geoPosition.latitude = +lat
    this.geoPosition.longitude = +lng
    this.geoPosition.accuracy = accuracy
  }

  // 获取对象实例，并合并云端配置
  getInstanceString(extendOptions = {}) {
    let obj = {}
    for (let [key, value] of Object.entries(this)) {
      obj[key] = value
    }

    // 合并服务端的配置
    try {
      obj = merge(obj, extendOptions)
    } catch (err) {
      apiLog.error('merge cloud config error ==>>>> ', err)
    }
    return JSON.stringify(obj)
  }

  // 设置角标
  setBadgeString({ taskbarString, toolbarString }) {
    this.taskbarString = taskbarString
    this.toolbarString = toolbarString
  }

  setWebRtcRemoteIp(ip) {
    this.webRtcRemoteIp = ip
    this.WebRTC.PublicIP = ip

    log.info('set webRtc config ==>>> ', this.WebRTC, this.Proxy)
  }

  setNotificationMode(mode) {
    this.notificationsMode = mode
  }

  setVariations(Seed, Sign) {
    this.Variations = { Seed, Sign }
  }

  setFontConfig(fontConfig) {
    this.FontConfig = fontConfig
  }

  async setWebglParameters(code = '22') {
    if (!code) return
    try {
      const parameters = await getWebglParametersObj(code)
      this.WebGL = { ...this.WebGL, ...parameters }
    } catch (err) {
      log.error('set webgl parameters error ==>>> ', err)
    }
  }
}

/**
 * @description 生成指纹配置文件
 * @param {object} config 浏览器配置，包含browserFingerPrint
 * @param {object} ipData IP信息
 * @returns {Promise<void>}
 * */
export default async function genFingerprintFile(config, ipData) {
  // log.info('generate fingerprint file')
  // log.info(ipData)
  const browserFingerPrint = config.browserFingerPrint
  browserFingerPrint.seq = config.seq // 防止browserFingerPrint.taskbarString没有值
  browserFingerPrint.abortImageBytes = config.abortImage ? (+config.abortImageMaxSize || 0) * 1024 : null
  const fingerprint = new FingerPint(browserFingerPrint)

  // 设置角标
  const obj = await getBadgeObject(config)
  fingerprint.setBadgeString(obj)
  log.info('badge type object ==>>> ', obj)

  // 语言跟随IP
  if (browserFingerPrint.isIpCreateLanguage) {
    const lang = ipData && ipData.languages
    const langObj = await resolveLang(lang)
    fingerprint.appLocale = langObj?.lang
    fingerprint.acceptLang = langObj?.accept_languages
  } else {
    const langObj = await resolveLang(browserFingerPrint.languages)
    fingerprint.appLocale = langObj?.lang
    fingerprint.acceptLang = langObj?.accept_languages
  }

  // 界面语言跟随IP
  if (browserFingerPrint.isIpCreateDisplayLanguage) {
    fingerprint.uiLang = ipData && ipData.languages
  }

  // 时区跟随IP
  if (browserFingerPrint.isIpCreateTimeZone) {
    fingerprint.timeZone = ipData && ipData.timeZone
  }

  // 设置屏幕尺寸，自定义且设置了尺寸，则取自定义尺寸
  if (+browserFingerPrint.resolutionType === 1 && browserFingerPrint.resolution && browserFingerPrint.resolution.length) {
    const sizes = browserFingerPrint.resolution.split('x')
    if (browserFingerPrint.ostype === 'PC') {
      fingerprint.setScreenSize(+sizes[0], +sizes[1], +sizes[0], browserFingerPrint.os === 'Win32' ? +sizes[1] - 38 : +sizes[1] - 25)
    } else {
      fingerprint.setScreenSize(+sizes[0], +sizes[1], +sizes[0], sizes[1])
    }
  } else {
    const display = electron.screen.getPrimaryDisplay()
    fingerprint.setScreenSize(
      display.size.width,
      display.size.height,
      display.workAreaSize.width,
      display.workAreaSize.height,
      display.scaleFactor
    )
  }

  // webRtc  替换远程ip
  if (+browserFingerPrint.webRTC === 0 && ipData && ipData.ip) {
    fingerprint.setWebRtcRemoteIp(ipData.ip)
  }

  // 地理位置
  if (+browserFingerPrint.position !== 2 && browserFingerPrint.isIpCreatePosition) {
    fingerprint.setGeoPosition(ipData && ipData.latitude, ipData && ipData.longitude, browserFingerPrint.defaultAccuracy || 10)
  }

  if (config.proxyType === 'ssh') {
    const port = await sshProxy.getSocksPort(config)
    await fingerprint.setProxy({
      type: 'socks5',
      host: '127.0.0.1',
      port: port,
      username: '',
      password: '',
      enableSocks5Udp: false
    })
  } else if (config.proxyType !== 'noproxy') {
    await fingerprint.setProxy({
      type: config.proxyType,
      host: config.host,
      port: config.port,
      username: config.proxyUserName,
      password: config.proxyPassword,
      enableSocks5Udp: config.enableSocks5Udp
    })
  }

  // 限制了窗口大小
  if (browserFingerPrint.ostype === 'PC' && +browserFingerPrint.resolutionType === 1 && !!browserFingerPrint.windowSizeLimit) {
    const resolutionArr = browserFingerPrint.resolution.split('x')
    if (resolutionArr.length === 2) {
      fingerprint.window.max_width = +resolutionArr[0]
      fingerprint.window.max_height = +resolutionArr[1]
    }
  }

  if (config.disableNotifications) {
    fingerprint.setNotificationMode('allow')
  }

  const fontConfig = await getFontConfig({
    platform: fingerprint.UserAgentPlatform,
    platformVersion: fingerprint.UserAgentPlatformVersion,
    locale: fingerprint.appLocale,
    fontType: browserFingerPrint.fontType,
    font: browserFingerPrint.font
  })
  fingerprint.setFontConfig(fontConfig)
  // apiLog.info('font config ==>>> ', fontConfig)

  await fingerprint.setWebglParameters(browserFingerPrint.webglparameterscode)

  // mac 和 win设置变体
  const seedAndSign = await getChromeVariations(fingerprint.userAgentVersion)
  if (seedAndSign) {
    fingerprint.setVariations(seedAndSign.Seed, seedAndSign.Sign)
  }

  // 写入文件
  const filePath = path.resolve(appGetPath('userData'), 'LocalCache', config.id)
  try {
    await writeFile(filePath, fingerprint.getInstanceString(browserFingerPrint.extendOptions), browserFingerPrint.coreVersion)
  } catch (e) {
    throw e
  }
}

// 为rpa生成指纹文件，没有任何指纹信息
export async function genRpaFingerprintFile(config) {
  const filePath = path.resolve(appGetPath('userData'), 'LocalCache', config.id)
  try {
    await writeFile(
      filePath,
      JSON.stringify({
        Resource: BrandingInfo,
        taskbarString: 'RPA',
        toolbarString: 'RPA'
      }),
      140
    )
  } catch (e) {
    throw e
  }
}

async function writeFile(filePath, data, coreVersion) {
  // log.info('file data =>>>>>>>>>>>>>>>')
  // log.info(data)
  if (+coreVersion === 92) {
    await encryptFile(filePath, data, getFingerprintDectyptKey())
  } else {
    await writeEncryptFingerprintFile(filePath, data)
  }
}

// Windows | macOS | Linux | iOS | Android
function getUserAgentPlatform(ostype, os) {
  if (ostype !== 'PC') {
    return { IOS: 'iOS', Android: 'Android' }[ostype]
  }
  if (os.includes('Win32')) return 'Windows'
  if (os.includes('Linux')) return 'Linux'
  if (os.includes('Mac')) return 'macOS'
  return 'Windows'
}

// 转换指纹传入的plugins字符串为数组
function getPlugins(pluginStr) {
  let arr = []
  try {
    if (pluginStr) {
      let tempArr = safeJsonParse(pluginStr, 'getPlugins')
      for (let item of tempArr) {
        arr.push({
          name: item.name,
          filename: item.filename,
          description: item.description,
          mimes: [
            {
              type: item.mimeType,
              description: item.mimeDescription,
              suffixes: ['text_ext', item.suffixes]
            }
          ]
        })
      }
    }
  } catch (err) {
    log.error('parse plugins string error ==>>> ', pluginStr)
  }
  return arr
}
