import browserStatus from './browserStatus'
import { screen, ipcMain } from 'electron'
import phoneStatus from './phoneWindowStatus'
import { log } from '../logs'
import { Window as SystemWindow } from 'node-system-bridge'

// 自适应的宫格Map
const FlexableMap = {
  1: '1*1',
  2: '2*1',
  4: '2*2'
}

// 手机或者浏览器
export const BrowserType = {
  browser: 1,
  phone: 2
}

class WindowBounds {
  constructor() {
    this.options = {
      screenId: null,
      type: 'box',
      startX: 0,
      startY: 0,
      width: 500,
      height: 300,
      col: 4,
      spaceX: 0,
      spaceY: 0,
      offsetX: 50,
      offsetY: 50,
      seqlist: [], // 传入 seqlist，则只排列seqlist对应的窗口
      orderBy: 'asc' // 按序号排序
    }
    this.browserType = BrowserType.browser // 默认是浏览器
  }

  // 手机页面排列
  async setPhoneBounds(options) {
    this.browserType = BrowserType.phone
    this.options = { ...this.options, ...options }
    if (!options.seqlist || !options.seqlist.length) this.options.seqlist = [] // 没传 seqlist 时，重置为空，排列所有

    if (this.options.type === 'box') {
      await this.setByBox()
    } else {
      await this.setByDiagonal()
    }
  }

  async setBounds(options = {}) {
    this.browserType = BrowserType.browser
    // 合并参数
    this.options = { ...this.options, ...options }
    if (!options.seqlist || !options.seqlist.length) this.options.seqlist = [] // 没传 seqlist 时，重置为空，排列所有

    if (this.options.type === 'box') {
      await this.setByBox()
    } else {
      await this.setByDiagonal()
    }
  }

  // 自适应排列
  async setFlexableBounds(seqlist = [], screenId, type = BrowserType.browser, orderBy = 'asc') {
    this.browserType = type
    genFlexableMap()

    // 找出需要排列的窗口，这里的只是查下length，用来计算宫格
    let browsers = type === BrowserType.browser ? browserStatus.getOpenedBrowsersSeqs() : phoneStatus.getOpenedBrowsersSeqs()
    if (seqlist.length) {
      browsers = browsers.filter(item => seqlist.includes(item.seq))
    }

    if (!browsers.length) return

    // 找到对应的宫格，设置options
    const [x, y] = getFlexableCol(browsers.length)

    this.options.screenId = screenId
    const display = this.getTrargetDisplay()

    this.options = {
      screenId,
      type: 'box',
      startX: 0,
      // mac 从顶部菜单栏开始排列
      startY: display.workArea.y,

      // mac 下只有一个窗口排列的时候，width减少10，否则占满宽度会导致窗口变成最小
      width:
        process.platform === 'darwin' && browsers.length === 1
          ? display.workAreaSize.width - 12
          : Math.floor(display.workAreaSize.width / x),
      height: Math.floor(display.workAreaSize.height / y),
      col: x,
      spaceX: 0,
      spaceY: 0,
      offsetX: 50,
      offsetY: 50,
      seqlist,
      orderBy
    }

    await this.setByBox()
  }

  // 宫格排列
  async setByBox() {
    let browsers =
      this.browserType === BrowserType.browser
        ? browserStatus.getOpenedBrowsersSeqs(this.options.orderBy === 'desc')
        : phoneStatus.getOpenedBrowsersSeqs(this.options.orderBy === 'desc')
    if (this.options.seqlist && this.options.seqlist.length) {
      browsers = browsers.filter(item => this.options.seqlist.includes(item.seq))
    }

    const pids = this.browserType === BrowserType.browser ? browsers.map(item => item.pid) : []

    let currentRow = 0
    let currentCol = 0

    if (!browsers.length) return

    const display = this.getTrargetDisplay()

    while (browsers.length) {
      // 超过指定列数，则重置到第0列，并行数 +1
      if (currentCol >= this.options.col) {
        currentCol = 0
        currentRow++
      }

      const current = browsers.shift()

      if (browserStatus.isClosing(current.browserId) || phoneStatus.isClosing(current.phoneId)) {
        log.info('current browser is closing and continue ===>>>>>>> ', current.browserId)
        continue
      }
      this.setWindowBounds(current.browserId || current.phoneId, {
        width: this.options.width,
        height: this.options.height,
        left: this.options.startX + display.bounds.x + currentCol * (this.options.width + this.options.spaceX),
        top: this.options.startY + display.bounds.y + currentRow * (this.options.height + this.options.spaceY)
      })

      currentCol++
    }

    await this.resetTopMost(pids)
  }

  // 对角线排列
  async setByDiagonal() {
    let browsers =
      this.browserType === BrowserType.browser
        ? browserStatus.getOpenedBrowsersSeqs(this.options.orderBy === 'desc')
        : phoneStatus.getOpenedBrowsersSeqs(this.options.orderBy === 'desc')
    if (this.options.seqlist && this.options.seqlist.length) {
      browsers = browsers.filter(item => this.options.seqlist.includes(item.seq))
    }

    if (!browsers.length) return

    const display = this.getTrargetDisplay()

    const pids = this.browserType === BrowserType.browser ? browsers.map(item => item.pid) : []

    for (let i = 0; i < browsers.length; i++) {
      await this.setWindowBounds(browsers[i].browserId || browsers[i].phoneId, {
        width: this.options.width,
        height: this.options.height,
        left: this.options.startX + display.bounds.x + i * this.options.offsetX,
        top: this.options.startY + display.bounds.y + i * this.options.offsetY
      })
    }
    await this.resetTopMost(pids)
  }

  async setWindowBounds(browserId, bounds) {
    // 设置尺寸和位置
    if (this.browserType === BrowserType.phone) {
      await this.resetPhoneWindowBounds(browserId, bounds)
    } else {
      await this.resetSizeAndPos(browserId, bounds)
    }
  }

  // pids
  async resetTopMost(pids = []) {
    if (!pids || !pids.length) return

    try {
      const results = await SystemWindow.bringToFrontBatch(pids)

      results.forEach(({ pid, success, errorMessage }) => {
        if (success) {
          log.info(`✓ PID ${pid}: Success`)
        } else {
          // 关键：查看详细的错误信息
          log.error(`✗ PID ${pid}: Failed - ${errorMessage}`)
        }
      })
    } catch (err) {
      log.error('Batch error:', err)
    }
  }

  // 设置窗口的window bounds
  async resetSizeAndPos(browserId, bounds) {
    try {
      const browser = browserStatus.getBrowser(browserId)

      if (!browser) return

      const pages = await browser.pages()
      if (!pages.length) return
      const page = pages.find(item => !item.url().startsWith('about:blank') && !item.url().startsWith('chrome://')) || pages[0]
      const target = page.target() // 通过对一个page的target对象设置
      const client = await target.createCDPSession()
      // 获取windowId
      const res = await client.send('Browser.getWindowForTarget', { targetId: target._targetId })

      // 如果窗口处于最大化或者全屏，则需要执行两次设置
      const currentBounds = await client.send('Browser.getWindowBounds', { windowId: res.windowId })
      if (currentBounds.windowState !== 'normal') {
        await client.send('Browser.setWindowBounds', { windowId: res.windowId, bounds })
      }

      // 设置窗口大小和尺寸
      await client.send('Browser.setWindowBounds', { windowId: res.windowId, bounds })
    } catch (err) {
      log.error('set window bounds error ==>>> ', err)
    }
  }

  // 设置phone window bounds
  async resetPhoneWindowBounds(phoneId, bounds) {
    log.info('set phone bounds ==>>>> ', phoneId, bounds)
    const window = phoneStatus.getWindow(phoneId)
    window.setBounds({ ...bounds, x: bounds.left, y: bounds.top })
  }

  getTrargetDisplay() {
    const displays = screen.getAllDisplays()
    const target = displays.find(item => item.id === this.options.screenId)

    if (target) return target

    return screen.getPrimaryDisplay()
  }
}

// 生成完整的自适应宫格Map，宫格总数最多1024
function genFlexableMap() {
  if (FlexableMap[3]) return

  for (let i = 3; i <= 32; i++) {
    FlexableMap[i * i] = `${i}*${i}`
    FlexableMap[i * (i - 1)] = `${i}*${i - 1}`
    FlexableMap[i * (i - 2)] = `${i}*${i - 2}`
  }
}

// 找出自适应宫格对应的col，有对应的宫格直接返回，否则给 num + 1，直到找到为止
function getFlexableCol(num) {
  if (FlexableMap[num]) return FlexableMap[num].split('*').map(item => +item)

  return getFlexableCol(num + 1)
}

const windowBounds = new WindowBounds()

ipcMain.handle('reset-window-bounds-flexable', (e, seqlist, screenId, orderBy) => {
  return windowBounds.setFlexableBounds(seqlist, screenId, BrowserType.browser, orderBy)
})

export default windowBounds
