// Promise resolve 标准对象
class ResolveMsg {
  constructor(data) {
    this.success = true
    this.data = data
  }
}

// Promise reject 标准对象
class RejectMsg {
  constructor(message, stop) {
    this.success = false
    this.message = message
    this.stop = stop // 是否停止执行
  }
}

// 自定义代理策略，向窗口发送消息
const customAgentStrategy = {
  async socks5(config) {
    sendToRenderer(config.id, '正在加载代理IP...')
    const proxyOptions = { host: config.host, port: config.port, username: config.proxyUserName, password: config.proxyPassword }
    const agent = getSocksAgent(proxyOptions)
    const res = await getSocks5AgentIpData(config, agent)
    if (res.success) {
      return res
    }
    const agentWithLocalDNS = getSocksAgent({ ...proxyOptions, useLocalDNS: true })
    return getSocks5AgentIpData(config, agentWithLocalDNS)
  },
  http(config) {
    sendToRenderer(config.id, '正在加载代理IP...')
    const agent = getHttpAgent(config.host, config.port, config.proxyUserName, config.proxyPassword)
    return getHttpsAgentIpData(config, agent)
  },
  https(config) {
    return this.http(config)
  },
  // 转换为socks5代理
  async ssh(config) {
    try {
      sendToRenderer(config.id, '正在加载代理IP...')
      const port = await sshProxy.getSocksPort(config)
      apiLog.info('ssh proxy port from sshProxy ==>>> ', port)
      const agent = getSocksAgent({ host: '127.0.0.1', port: port })
      return getSocks5AgentIpData(config, agent)
    } catch (err) {
      apiLog.error('ssh proxy error ==>>> ', err)
      return new RejectMsg('SSH 代理失败，请重试')
    }
  },
  noproxy(config) {
    return getNoproxyAgentIpData(config)
  }
}

/**
 * @description 获取代理IP后的ip信息
 * @param {object} config 窗口参数，包含proxy信息 proxyMethod 代理方式: 1 平台代理, 2 自定义
 * @returns {Promise<{RejectMsg|ResolveMsg}>} 成功或失败均返回resolved Promise，通过success判断是否成功取得ip信息
 * */
export async function getAgentIpData(config) {
  // 非直连，且非127，且不是通过ip234in查一次IP的情况
  const sysProxy = await getSysProxy()
  const resObj = await getMiddleQueryHosts()
  const subDomain = getSubDomainFromHost(config.host)

  if (config.proxyType !== 'noproxy' && sysProxy && config.host && config.host !== '127.0.0.1' && !resObj[subDomain]) {
    return getSysTunnelIpData(sysProxy, config)
  }

  // 每次重新打开窗口获取代理IP信息的时候，删掉之前缓存的信息
  deleteCachedProxyIPData(config.id)
  return customAgentStrategy[config.proxyType](config)
}

/**
 * @description 检查代理后的IP信息
 * @param {object} config 窗口参数，包含proxy信息 proxyMethod 代理方式: 1 平台代理, 2 自定义
 * @returns {Promise<RejectMsg|ResolveMsg>} 成功或失败均返回resolved Promise，通过success判断是否成功取得ip信息
 * */
export async function checkAgentIpData(config) {
  if (hasCachedProxyIPData(config.id)) {
    apiLog.info('cached agent ip data ==>> ' + config.seq)
    const cachedIpData = getCachedProxyIPData(config.id)
    if (!cachedIpData) {
      apiLog.warn('no cached ip data ==>>> ' + config.seq)
    } else {
      apiLog.info(
        `cached ip data ==>>> ip: ${cachedIpData.ip}, countryName: ${cachedIpData.countryName}, city: ${cachedIpData.city}, languages: ${cachedIpData.languages}, timeZone: ${cachedIpData.timeZone}, longitude: ${cachedIpData.longitude}, latitude: ${cachedIpData.latitude}, zip: ${cachedIpData.zip}`
      )
    }
    return new ResolveMsg(cachedIpData)
  }
  apiLog.info('has no cached ip data =>>> ' + config.seq)

  return customAgentStrategy[config.proxyType](config)
}

// 提取IP可以再次代理
export async function changeProxyAndReopen(browserId) {
  try {
    const task = rpaTaskPool.findRunningTask(browserId)

    // close browser
    await closeBrowser(browserId)

    const listener = id => {
      if (browserId !== id) return
      if (!task) {
        reopenBrowser(browserId)
      } else {
        task.jumpToFirst(browserId)
      }
    }

    // 监听一次关闭事件
    browserStatus.once(BrowserStatusEvent.closed, listener)
  } catch (e) {
    apiLog.error(e.message)
  }
}

// socks5 agent
function getSocksAgent({ host, port, username = '', password = '', useLocalDNS = false }) {
  // 通过 URL 对象设置凭据，自动处理特殊字符编码
  // 如果 useLocalDNS 为 true，则使用 socks5:// 协议，否则使用 socks5h:// 协议，部分自建代理有可能不支持 socks5h:// 协议
  const proxyUrl = new URL(`${useLocalDNS ? 'socks5' : 'socks5h'}://${host}:${port}`)
  if (username) {
    proxyUrl.username = encodeURIComponent(username)
  }
  if (password) {
    proxyUrl.password = encodeURIComponent(password)
  }
  return new SocksProxyAgent(proxyUrl, { timeout: 20000 })
}

// 获取ssh 通道的端口
export function getSshPort(sshConfig) {
  return crypto.createHash('md5').update(JSON.stringify(sshConfig)).digest('hex')
}

// socks5 代理结果
async function getSocks5AgentIpData(config, agent) {
  try {
    const middleIp = await getMiddleIp(config, agent)

    const res = await getIpInfo({
      method: config.ipCheckService,
      isIpv6: config.isIpv6,
      isApiUser: browserStatus.ids_from_api.has(config.id),
      checkExists: config.checkExists || config.duplicateCheck || 0,
      middleIp,
      agent: !middleIp ? agent : null // 没有 middleIp 时，代理后查询，有则不需要代理，直接查询IP
    })

    if (res.ip) {
      saveProxyIPData(config.id, res)
      return new ResolveMsg(res)
    }
  } catch (err) {
    apiLog.error('get socks5 agent ip data error ==>>>> ', err.message)
  }
  return new RejectMsg('代理IP无法连接')
}

// http & https 代理结果，http代理时，分别以proxy对象和httpAgent方式检测一次代理
async function getHttpsAgentIpData(config, agent, useProxy = false) {
  apiLog.info('http & https agent ==>>> ')

  const middleIp = await getMiddleIp(config, agent, true)

  const options = {
    method: config.ipCheckService,
    isIpv6: !!config.isIpv6,
    isApiUser: browserStatus.ids_from_api.has(config.id),
    checkExists: config.checkExists || 0,
    middleIp,
    agent: !middleIp ? agent : null
  }

  try {
    const res = await getIpInfo(options, useProxy)
    if (res.ip) {
      saveProxyIPData(config.id, res)
      return new ResolveMsg(res)
    }
  } catch (err) {
    apiLog.error('get https agent ip data error ==>>>> ', err.message)

    // 检测失败且 useProxy = false(防止死循环) 时，重新以 proxy 方式再次检查一次，
    if (!useProxy) return getHttpsAgentIpData(config, agent, true)
  }
  return new RejectMsg('代理IP无法连接')
}

// noproxy ip结果
async function getNoproxyAgentIpData(config) {
  apiLog.info('noproxy ==>>> ')
  try {
    let res = {}
    // 直连模式，已经将IP信息带到config里了
    if (config.ipResult) {
      res = config.ipResult
    } else {
      res = await getIpInfo({
        method: config.ipCheckService,
        isIpv6: config.isIpv6,
        isApiUser: browserStatus.ids_from_api.has(config.id)
      })
    }

    if (res.ip) {
      saveProxyIPData(config.id, res)
      return new ResolveMsg(res)
    }
  } catch (err) {
    apiLog.error('get noproxy agent ip data error ==>>>> ', err.message)
  }
  return new RejectMsg('当前网络故障，请检查网络...')
}

// https & http agent
export function getHttpAgent(host, port, username, password) {
  const proxyUrl = new URL(`http://${host}:${port}`)
  if (username && password) {
    proxyUrl.username = encodeURIComponent(username)
    proxyUrl.password = encodeURIComponent(password)
  }
  return new HttpsProxyAgent(proxyUrl.toString(), {
    timeout: 20000
  })
}

// 获取经由系统代理的代理IP信息
async function getSysTunnelIpData(sysProxy, config) {
  const { port, closeTun } = await getTempBittun(sysProxy, config)
  await sleep(1) // 获取到通道代理后，等待1秒，防止不能立即生效

  apiLog.info('socks5 tunnel agent ==>>> ')
  try {
    const res = await getIpInfo({
      agent: getSocksAgent({ host: '127.0.0.1', port: port }),
      method: config.ipCheckService,
      isIpv6: config.isIpv6,
      isApiUser: browserStatus.ids_from_api.has(config.id),
      checkExists: config.checkExists || config.duplicateCheck || 0
    })
    if (res.ip) {
      saveProxyIPData(config.id, res)
      return new ResolveMsg(res)
    }
  } catch (err) {
    apiLog.error('get socks5 agent error ==>>>> ', err.message)
  } finally {
    closeTun()
  }
  return new RejectMsg('代理IP无法连接')
}

// 提取动态IP
export async function extractDymanicIp(config, duplicateCheck = false) {
  try {
    // 需要检查现有代理的有效性
    if (!config.isDynamicIpChangeIp && config.host && config.port) {
      const ipResult = await getAgentIpData(config)
      if (ipResult.success && ipResult.data.ip) {
        // 如果IP还有效，直接返回原始对象即可
        return config
      }
    }

    if (!config.dynamicIpUrl) {
      return Promise.reject(new Error(messages.getMessage('extractIpError3')))
    }

    // 获取提取链接结果
    const options = { url: encodeURI(decodeURI(config.dynamicIpUrl)), method: 'get' }
    const sysProxy = await getSysProxy()
    const sysPort = await getSysProxyPort()
    if (sysProxy && sysPort) {
      options.httpAgent = options.httpsAgent = getHttpAgent('127.0.0.1', sysPort, '', '')
    } else if (getNeedsSystemCertificates()) {
      options.httpsAgent = https.globalAgent
    }
    let res = await axios(options)
    apiLog.info('extract request data ==>>> ', res.data)

    if (typeof res.data === 'string') {
      if (res.data.includes('未加入白名单') && config.dynamicIpChannel === 'rola') {
        const ip = res.data.split(' ')[0]
        const result = await rolaAddWhitelist(config.dynamicIpUrl, ip)
        if (typeof result !== 'string') return Promise.reject(new Error(JSON.stringify(result)))
        res.data = result
      }
    } else {
      // 重写res.data 为字符串的ip信息
      if (config.dynamicIpChannel !== 'rola') {
        return Promise.reject(new Error(messages.getMessage('extractIpError2', JSON.stringify(res.data))))
      }
      if (res.data.code === 0) {
        res.data = res.data.data[0]
      } else if (res.data.msg.includes('未加入白名单')) {
        const ip = res.data.msg.split(' ')[0]
        const result = await rolaAddWhitelist(config.dynamicIpUrl, ip)
        if (result.code !== 0) return Promise.reject(new Error(JSON.stringify(result)))
        res.data = result.data[0]
      } else {
        return Promise.reject(new Error(JSON.stringify(res.data)))
      }
    }

    if (typeof res.data !== 'string') {
      return Promise.reject(new Error(`解析不成功：${JSON.stringify(res)}`))
    }

    // 解析结果
    let ipstr = res.data.split(/[\n\r\t]/)[0] // 换行｜制表符分隔后取第一个

    apiLog.info('extract ip string ==>>>> ', ipstr)

    // 如果结果中包含 @ 符号，认为是 user:pass@host:port格式，尝试解析为 host:port:user:pass 格式
    if (ipstr.includes('@')) {
      try {
        ipstr = ipstr.split('@').reverse().join(':')
      } catch (err) {
        apiLog.error('parse extract ip error ====>>>> ', ipstr, err.message)
      }
    }

    // 解析为数组，肯定会有host和port前两项，没有的默认为空
    const ipItems = ipstr.split(':')

    if (ipItems.length > 4) return Promise.reject(new Error(messages.getMessage('extractIpError1', ipstr)))

    config.host = ipItems[0]
    config.port = +ipItems[1]
    config.proxyUserName = ipItems[2] || ''
    config.proxyPassword = ipItems[3] || ''

    // 检查重复
    if (config.duplicateCheck === 1 && duplicateCheck) {
      for (let i = 0; i < 5; i++) {
        const result = await getAgentIpData(config)

        // 代理检测失败则继续下一轮，检测到未使用过，则跳出循环，使用过，则再次提取一次
        if (!result.success) continue
        if (!result.data.used) break

        apiLog.info('检测到重复 ==>>> ', result)
        config = await extractDymanicIp(config, false) // 递归检测时，不需要检测重复，防止死循环
      }
    }

    return config
  } catch (err) {
    return Promise.reject(new Error(messages.getMessage('extractIpError', err.message)))
  }
}

// rola加白名单
async function rolaAddWhitelist(dynamicIpUrl, ip) {
  apiLog.info('add white list ==>>> ', ip)
  const url = new URL(dynamicIpUrl)
  const result = await axios.get(
    `http://api.rola-ip.co/user_add_whitelist?token=${url.searchParams.get('token')}&remark=bitbrowser&ip=${ip}`
  )
  if (result.data.code !== 0) return result.data // 添加白名单失败，返回失败内容
  const res = await axios.get(dynamicIpUrl)
  return res.data
}

// 检测系统代理状态
export async function checkSysProxyStatus(payload) {
  try {
    const config = safeJsonParse(payload, 'checkSysProxyStatus')
    let port = null

    if (config.type === 3) {
      port = config.port
    } else {
      const agentUrl = await getSysProxy()
      if (agentUrl) port = agentUrl.split(':').pop()
    }

    return getHttpsAgentIpData({}, getHttpAgent('127.0.0.1', port))
  } catch (err) {
    return new RejectMsg('系统代理检测失败')
  }
}

// 获取ip234的ip，从ip234in获取一次IP，再用，http代理时，使用proxy的代理方式
async function getMiddleIp(config, agent, useProxy = false) {
  try {
    const objRes = await getMiddleQueryHosts()
    const subDomain = getSubDomainFromHost(config.host)

    if (!objRes[subDomain]) return ''

    const options = {}
    if (useProxy) {
      options.proxy = getHttpProxyObj(agent.proxy)
    } else {
      options.httpAgent = options.httpsAgent = agent
    }
    const res = await axios.get(objRes[subDomain], options)

    apiLog.info('middle ip res ==>>> ', subDomain, res.data.ip)

    return res.data.ip || ''
  } catch (err) {
    apiLog.error('get ip234ip error ==>>>> ', err.message)
  }

  return ''
}
