import { log } from '../logs'
import { execCmd, sleep } from '../utils'
import os from 'os'
import { getBrowserCacheDir, getPerformanceConfig } from '../data/globalConfigs'

class PerformanceMonitor {
  constructor() {
    this.open = true // 是否开启了性能监控
    this.cpu = 95 // cpu使用率
    this.mem = 95 // 内存使用率
    this.freeCacheSpace = 1 // 缓存所在目录剩余空间 GB
    // 添加缓存机制
    this.spaceCache = {
      data: null,
      timestamp: 0,
      cacheTime: 30000 // 30秒缓存
    }
  }

  async initial() {
    const config = await getPerformanceConfig()
    if (config) {
      this.open = config.open
      this.cpu = config.cpu
      this.mem = config.mem
      this.freeCacheSpace = config.freeCacheSpace
    }
  }

  isOpen() {
    return this.open
  }

  getCPUInfo() {
    const cpus = os.cpus()
    let user = 0,
      nice = 0,
      sys = 0,
      idle = 0,
      irq = 0,
      total = 0

    cpus.forEach(cpu => {
      const { times } = cpu
      user += times.user
      nice += times.nice
      sys += times.sys
      idle += times.idle
      irq += times.irq
    })

    total = user + nice + sys + idle + irq

    return {
      total,
      idle
    }
  }

  // 计算500毫秒内的cpu使用率
  async getCPUUsage() {
    const startInfo = this.getCPUInfo()
    await sleep(0.5)
    const endInfo = this.getCPUInfo()
    const idleDiff = startInfo.idle - endInfo.idle
    const totalDiff = startInfo.total - endInfo.total
    return (1 - Math.abs(idleDiff / totalDiff)) * 100
  }

  async isCpuMax() {
    const percentCPUUsage = await this.getCPUUsage()
    log.info('================= cpu percent usage ======>>>>> ', percentCPUUsage)
    return percentCPUUsage > this.cpu
  }

  async isMemMax() {
    if (os.platform() !== 'win32') return false
    const { free, total } = process.getSystemMemoryInfo()
    log.info('mem info ===>>>> ', total, free, (1 - free / total) * 100)
    return (1 - free / total) * 100 > this.mem
  }

  async isFreeCacheSpaceMax() {
    if (os.platform() === 'win32') return this.isWin32SpaceMax()
    return this.isUnixSpaceMax()
  }

  async isUnixSpaceMax() {
    const stdout = await execCmd('df -P -k -- /')
    const space = getFreeFromStdout(stdout, false)
    return space / 1024 / 1024 < this.freeCacheSpace
  }

  // 使用 wmic 获取磁盘空间（推荐，兼容性最好）
  async getSpaceWithWmic(driveLetter) {
    const cmd = `wmic logicaldisk where "DeviceID='${driveLetter}:'" get FreeSpace /value`
    try {
      const stdout = await execCmd(cmd, null, 5000) // 5秒超时
      if (stdout) {
        // 解析输出格式：FreeSpace=1234567890
        const match = stdout.match(/FreeSpace=(\d+)/)
        if (match) {
          const space = parseInt(match[1])
          return isNaN(space) ? null : space
        }
      }
    } catch (error) {
      log.error('wmic command failed or timeout ==>>> ', error.message)
    }
    throw new Error('wmic command failed')
  }

  // 测试检测指定磁盘空间（用于调试）
  async testDriveSpace(driveLetter = 'D') {
    try {
      log.info(`Testing drive ${driveLetter} space...`)
      const space = await this.getSpaceWithWmic(driveLetter)
      if (space !== null) {
        const spaceGB = space / 1024 / 1024 / 1024
        log.info(`Drive ${driveLetter} free space: ${spaceGB.toFixed(2)} GB`)
        return space
      }
    } catch (error) {
      log.error(`Test drive ${driveLetter} space failed ==>>> `, error.message)
    }
    return null
  }

  async isWin32SpaceMax() {
    try {
      // 检查缓存是否有效
      const now = Date.now()
      if (this.spaceCache.data && now - this.spaceCache.timestamp < this.spaceCache.cacheTime) {
        log.info('using cached space data ==>>>>>>> ', this.spaceCache.data)
        return this.spaceCache.data / 1024 / 1024 < this.freeCacheSpace
      }

      const cachePath = await getBrowserCacheDir()
      const driveLetter = cachePath[0].toUpperCase()

      // 直接使用 wmic 命令
      let space = null
      try {
        space = await this.getSpaceWithWmic(driveLetter)
      } catch (err) {
        log.info('wmic command failed ==>>> ', err.message)
      }

      if (space !== null) {
        // 更新缓存
        this.spaceCache.data = space
        this.spaceCache.timestamp = now
        log.info('free space ==>>>>>>> ', space)
        return space / 1024 / 1024 < this.freeCacheSpace
      }
    } catch (err) {
      log.error('check win32 space error ==>>> ', err)
    }
    // 默认一律视为空间充足
    return false
  }

  async check(seq) {
    try {
      await this.initial()
      if (!this.isOpen()) return Promise.resolve()
      // CPU 指标暂时屏蔽
      // if (await this.isCpuMax()) return Promise.reject(new Error(`窗口 ${seq} 启动失败，CPU使用率超出 ${this.cpu}%`))
      if (await this.isMemMax()) return Promise.reject(new Error(`窗口 ${seq} 启动失败，内存使用率超出 ${this.mem}%`))
      if (await this.isFreeCacheSpaceMax())
        return Promise.reject(new Error(`窗口 ${seq} 启动失败，缓存所在目录剩余空间小于 ${this.freeCacheSpace}GB`))
    } catch (err) {
      log.error('performance monitor check error ==>>>> ', err)
    }
  }
}

// 获取parse后的free空间，unix在第四位，win32在第二位，统一返回位KB， driveName 盘符 eg: C|D|E
function getFreeFromStdout(stdout, isWin32 = true, driveName) {
  let parsed = stdout
    .trim()
    .split('\n')
    .slice(1)
    .map(line => {
      return line.trim().split(/\s+(?=[\d/])/)
    })

  let driveData = []

  if (isWin32) {
    driveData = parsed.filter(driveArr => driveArr[0].startsWith(driveName))[0]
  } else {
    driveData = parsed[0]
  }

  log.info('driveData info ==>>>>>>>>>>>> ', driveData)

  return isWin32 ? parseInt(driveData[1]) / 1024 : parseInt(driveData[3])
}

const performanceMonitor = new PerformanceMonitor()

export default performanceMonitor
