import Router from 'koa2-router'
import { ApiUtil } from '../interface/ApiUtil'
import { getCacheDataFromDB } from '../data/cacheData'
import { apiLog } from '../logs'

const cacheDataRouter = new Router()

// 获取全局配置
cacheDataRouter.post('/cacheData/getData', async ctx => {
  const body = ctx.request.body
  const res = await getCacheDataFromDB(body)
  ctx.body = ApiUtil.success(res)
})

export default cacheDataRouter
