import { getClient } from './client'
import { rpaLogs } from '../logs'
import { ipcMain } from 'electron'

export async function saveRpaLog(browser_id = '', browser_seq = '', task_id = '', status, error_type, error_msg) {
  try {
    const db = await getClient()
    await db('rpa_logs').insert({
      browser_id,
      task_id,
      status,
      error_type,
      error_msg,
      browser_seq,
      created_time: Date.now(),
      created_time_hr: process.hrtime.bigint()
    })
  } catch (err) {
    rpaLogs.error('save rpa log error ==>>>> ', err)
  }
}

export async function clearRpaLogs(task_id) {
  try {
    const db = await getClient()
    await db('rpa_logs').where('task_id', '=', task_id).del()
  } catch (err) {
    rpaLogs.error('delete rpa logs error ==>>>> ', err)
  }
}

// 分页获取日志，page从0开始
export async function getRpaLogs({ task_id, page, pageSize }) {
  try {
    const db = await getClient()
    const res = await db('rpa_logs').select('*').where('task_id', '=', task_id).limit(pageSize).offset(page).orderBy('id', 'desc')
    const countRes = await db('rpa_logs').count().where('task_id', '=', task_id)
    return {
      total: countRes[0]['count(*)'],
      list: res
    }
  } catch (err) {
    rpaLogs.error('get rpa logs error ==>>>> ', task_id, err)
    throw new Error(err.message)
  }
}

// 获取rpa automa 数据的 md5 值
export async function getRpaFilesMd5() {
  try {
    const db = await getClient()
    const res = await db('global_configs').select('config_value').where('config_name', '=', 'rpa_md5')
    if (res.length) {
      return res[0].config_value
    }
  } catch (err) {}
  return null
}

// 保存rpa automa 数据的 md5 值
export async function saveRpaFilesMd5(md5) {
  try {
    const db = await getClient()
    await db('global_configs').insert({ config_name: 'rpa_md5', config_value: md5 }).onConflict('config_name').merge()
  } catch (err) {}
}

ipcMain.handle('get-rpa-logs', async (e, params) => getRpaLogs(params))
