const noPermittedIds = new Set() // 同步扩展时，出现权限问题的扩展，不再进行下载

/**
 * @description 确保扩展都已经同步好了
 * @param {Array} extensionList 传入的扩展list
 */

export async function ensureExtensionsBeReady(extensionList = []) {
  log.info('ensure extensions be ready ==>>> ', extensionList)
  const resolver = await tempPromise()
  try {
    if (extensionList.length > 0) {
      // 需要下载的list，有需要下载的，则等待全部下载，无需要下载的则直接返回
      const downloadList = await getDownloadExtensionList(extensionList)
      log.info('download extension list ==>>> ', downloadList)

      if (downloadList.length > 0) {
        // const resolver = await tempPromise()
        for (let item of downloadList) {
          await downloadExtension(item.url, item.extensionId, item.md5)
        }
      }
    }

    await ensureCloudExtensionsDone()
    resolver && resolver()
  } catch (err) {
    log.info('check extensions error ==>>> ', err)
    throw err
  }
}

/**
 * @description 下载扩展到根目录
 * @param {string} url 下载地址
 * @param {string} extensionId 扩展id
 * @param {string} fileMd5 扩展md5
 */
export function downloadExtension(url, extensionId, fileMd5) {
  return new Promise(async (resolve, reject) => {
    try {
      // 先确保扩展根目录存在
      const rootPath = await getExtensionRootPath()
      await fs.ensureDir(rootPath)

      await clearUselessExtensions(extensionId) // 清理掉之前残留的zip文件和扩展目录
      const zipFile = path.resolve(rootPath, `${extensionId}.zip`)

      const downloadService = new DownloadService(url, zipFile)
      await downloadService.start()

      const md5 = await getFileMd5(zipFile)

      log.info('extension download and uncompress completed. md5 ==>>> ', md5)

      // TODO 7.0.4 版本添加，过几个版本后，强制验证md5
      if (fileMd5 && md5 !== fileMd5) {
        log.error('download extension md5 not match ==>>> ', md5, fileMd5)
        await rimraf(zipFile, { maxRetries: 5 })
        reject('download extension md5 not match')
        return
      }

      await compressing.zip.uncompress(zipFile, rootPath)
      log.info('extension download and uncompress completed.')
      rimraf(zipFile, { maxRetries: 5 })
      resolve()
    } catch (err) {
      log.error('download or uncompress error ==>>> ', err)
      reporter.extension(err, extensionId, '下载扩展: ' + url)
      reject('同步出错，请重试')
    }
  })
}

export async function copyBuildInExtension() {
  try {
    const buildInExtensionPath = path.resolve(__dirname, process.env.DEV ? '../' : process.resourcesPath, 'build-in-extension')
    const exist = await fs.pathExists(buildInExtensionPath)

    if (!exist) {
      log.info('build-in-extension directory does not exist, skip.')
      return
    }

    // 获取扩展根目录
    const rootPath = await getExtensionRootPath()
    await fs.ensureDir(rootPath)

    // 读取 build-in-extension 目录下的所有文件
    const files = await fs.readdir(buildInExtensionPath)
    const zipFiles = files.filter(file => file.endsWith('.zip'))

    log.info(`Found ${zipFiles.length} extension(s) in build-in-extension directory`)

    for (const zipFile of zipFiles) {
      try {
        // 提取扩展ID（zip文件名去掉.zip后缀）
        const extensionId = path.basename(zipFile, '.zip')
        const extensionPath = path.join(rootPath, extensionId)

        // 检查扩展是否已存在
        const extensionExists = await fs.pathExists(extensionPath)

        if (extensionExists) {
          log.info(`Extension ${extensionId} already exists, skip.`)
          continue
        }

        // 解压扩展到 BitExtensions 目录
        const zipFilePath = path.join(buildInExtensionPath, zipFile)
        log.info(`Extracting extension ${extensionId} from ${zipFile}`)
        await compressing.zip.uncompress(zipFilePath, rootPath)
        log.info(`Extension ${extensionId} extracted successfully.`)
      } catch (err) {
        log.error(`Failed to process extension ${zipFile} ==>>> `, err)
      }
    }

    // 删除 build-in-extension 目录（生产环境）
    if (!process.env.DEV) {
      log.info('Removing build-in-extension directory...')
      await rimraf(buildInExtensionPath, { maxRetries: 5 })
      log.info('build-in-extension directory removed successfully.')
    } else {
      log.info('Development environment, keeping build-in-extension directory.')
    }
  } catch (err) {
    log.error('copy build in extension error ==>>> ', err)
  }
}

/**
 * @description 删除下载的扩展
 * @param {string} extensionId 扩展id
 */
export async function removeExtension(extensionId) {
  try {
    log.info('remove extension ==>>> ', extensionId)
    const extensionPath = await getExtensionPath(extensionId)
    const exist = await fs.pathExists(extensionPath)
    if (exist) {
      await rimraf(extensionPath, { maxRetries: 5 })
      log.info('remove extension success')
    } else {
      log.info('extension does not exist, no need to delete')
    }
    return Promise.resolve()
  } catch (err) {
    return err
  }
}

// 同步之前先清理掉有可能之前没同步成功的扩展，或者升级扩展时可以重新下载，不清理旧版本，防止正在使用的浏览器窗口失效
async function clearUselessExtensions(extensionId) {
  const rootPath = await getExtensionRootPath()
  const zipFile = path.join(rootPath, `${extensionId}.zip`)
  try {
    // await removeExtension(extensionId)
    log.info('remove zip file ==>>> ')
    const exist = await fs.pathExists(zipFile)
    if (exist) {
      await rimraf(zipFile, { maxRetries: 5 })
      log.info('remove zip file success ==>>> ', zipFile)
    } else {
      log.info('zip file does not exist, no need to delete.')
    }
    return Promise.resolve()
  } catch (err) {
    log.error(err)
    return err
  }
}

/**
 * @description 获取需要load的扩展拼接字符串
 * @param {array} extensionList
 * @returns {Promise<String>} args
 */
export async function getExtensionArgString(config, extensionList = []) {
  try {
    const args = await getUsedLocalExtensionsPaths(config)

    const rootPath = await getExtensionRootPath()
    // 只加载存在的，防止有意外找不到的，导致浏览器出错
    for (let item of extensionList) {
      const extensionPath = path.join(rootPath, item.extensionId, `${item.version}_0`)
      const exist = await fs.pathExists(extensionPath)
      if (exist) {
        args.push(extensionPath)
      }
    }
    return args.join()
  } catch (err) {
    log.error('getExtensionArgString error ==>>> ', err)
  }
  return ''
}

// 选择文件夹，并获取扩展信息
export async function getExtensionInfo() {
  try {
    const result = await dialog.showOpenDialog({
      message: '选择浏览器扩展目录',
      properties: ['openDirectory', 'showHiddenFiles']
    })
    if (result.canceled) {
      return null
    } else {
      const filePath = result.filePaths[0]
      const manifestPath = path.join(filePath, 'manifest.json')
      const exists = await fs.pathExists(manifestPath)

      if (!exists) return Promise.reject('目录中不存在 manifest.json 文件，请重新选择目录')

      const manifest = await fs.readJson(manifestPath, { encoding: 'utf-8' })

      if (manifest.name.startsWith('__MSG_')) {
        const nameKey = manifest.name.match(/^(__MSG_)(.*)(__)$/)[2]
        const descKey = manifest.description.match(/^(__MSG_)(.*)(__)$/)[2]
        const messageJson = await fs.readJson(path.join(filePath, '_locales', manifest.default_locale, 'messages.json'))
        if (nameKey) {
          manifest.name = messageJson[nameKey].message
        }
        if (descKey) {
          manifest.description = messageJson[descKey].message
        }
      }

      let icon = ''
      const iconKeys = Object.keys(manifest.icons || manifest.images || {})
      if (iconKeys && iconKeys.length) {
        const maxKey = Math.max(...iconKeys) // 取最大的
        const file = await fs.readFile(path.join(filePath, manifest.icons[maxKey]))
        const buffer = Buffer.from(file)
        icon = 'data:image/png;base64,' + buffer.toString('base64')
      }

      return {
        path: filePath,
        manifest,
        icon
      }
    }
  } catch (err) {
    log.error('get local extension info error ==>>> ', err)
    return Promise.reject(err)
  }
}

// 保存本地扩展 {name, version, desc, path, logo}
export async function saveLocalExtension(info) {
  try {
    const exists = await ifExists(info.name, info.version, info.mainUserId)
    if (exists) return Promise.reject('扩展已存在')
    const id = uid()
    const rootPath = await getExtensionRootPath()
    await fs.copy(info.path, path.join(rootPath, id), { recursive: true })
    await addLocalExtension({ ...info, id })
  } catch (err) {
    log.error('save local extension error ==>>> ', err)
  }
}

// 删除本地扩展，同时删除文件与记录，同时删除oss文件
export async function deleteLocalExtensionById(extensionId, deleteOss) {
  try {
    await deleteLocalExtension(extensionId)
    await removeExtension(extensionId)
    if (deleteOss) {
      await deleteExtensionFromOss(extensionId)
    }
  } catch (err) {
    log.error('delete local extension error ==>>> ', err)
  }
}

// 获取已启用的本地扩展地址list
export async function getUsedLocalExtensionsPaths(config) {
  const paths = []
  try {
    let list = await getUsedLocalExtensions()
    // 如果有main_user_id 必须和当前主账户一致，如果没用mian_user_id 是老数据，正常加载
    // list = list.filter(item => {
    //   return !item.main_user_id || item.main_user_id === config.mainUserId
    // })
    // 找到已启用的 或者没启用的 但是config里面有的
    let unopenedList = await getUnopenedExtensiosn()
    if (config.extendIds && config.extendIds.length) {
      unopenedList = unopenedList.filter(item => config.extendIds.includes(item.cloud_id))
      list = list.concat(unopenedList)
    }
    for (let item of list) {
      const extensionPath = await getExtensionPath(item.extension_id)
      const exist = await fs.pathExists(extensionPath)
      if (exist) paths.push(extensionPath)
    }
  } catch (err) {}
  log.info('used local extension paths =>>> ', paths)
  return paths
}

// 获取扩展的文件目录
async function getExtensionPath(extensionId) {
  const rootPath = await getExtensionRootPath()
  return path.join(rootPath, extensionId)
}

// 获取扩展根目录，在用户目录下的 BitExtensions 文件夹
export async function getExtensionRootPath() {
  const extensionDir = path.join(app.getPath('userData'), 'BitExtensions')
  const exists = await fs.pathExists(extensionDir)
  if (!exists) {
    await ensureDir(extensionDir)

    // 如果旧的目录存在，拷贝到新的目录下，然后删除旧的目录
    const oldDir = path.join(await getBrowserCacheDir(), 'BitExtensions')
    if (await fs.pathExists(oldDir)) {
      await fs.copy(oldDir, extensionDir, { recursive: true })
      await rimraf(oldDir, { maxRetries: 5 })
    }
  }

  return extensionDir
}

// 获取需要下载的扩展list
async function getDownloadExtensionList(extensionList = []) {
  let downloadList = []
  const rootPath = await getExtensionRootPath()
  for (let item of extensionList) {
    // 判断是否存在扩展 + 版本_0，比如：aapbdbdomjkkjkaonfhkkikfgjllcleb/2.0.12_0，不存在则要下载
    const exist = await fs.pathExists(path.join(rootPath, item.extensionId, `${item.version}_0`))
    if (!exist) downloadList.push(item)
  }
  return downloadList
}

export async function addFromGoogleStore(info) {
  try {
    const exists = await ifExistsById(info.id)
    if (exists) {
      return Promise.reject('扩展已存在')
    }

    // 先确保扩展根目录存在
    const rootPath = await getExtensionRootPath()
    await fs.ensureDir(rootPath)

    await downloadFromGoogleStore(info, path.join(rootPath, info.id))

    await addLocalExtension(info)
  } catch (err) {
    log.error('add from google store error ==>>> ', err)
    return Promise.reject('获取扩展失败')
  }
}

// 从Google Store下载扩展
async function downloadFromGoogleStore(info, localPath) {
  const options = {
    method: 'get',
    url: info.downUrl,
    responseType: 'arraybuffer',
    timeout: 0
  }

  // 如果需要使用系统证书，则使用全局 agent，防止证书问题导致下载失败
  if (getNeedsSystemCertificates()) {
    options.httpsAgent = https.globalAgent
  }

  // 如果需要使用系统代理，则使用系统代理，覆盖系统证书
  const sysPort = await getSysProxyPort()
  if (sysPort) {
    options.httpAgent = options.httpsAgent = getHttpAgent('127.0.0.1', sysPort, '', '')
  }

  const res = await axios(options)
  await compressing.zip.uncompress(crxToZip(res.data), localPath)

  // 读取本地文件中的ICON，存储为base64格式的
  const manifest = await fs.readJson(path.join(localPath, 'manifest.json'), { encoding: 'utf-8' })
  let iconKeys = []
  if (manifest.icons) {
    iconKeys = Object.keys(manifest.icons)
  } else if (manifest.images) {
    iconKeys = Object.keys(manifest.images)
  } else if (manifest.action?.default_icon) {
    iconKeys = Object.keys(manifest.action.default_icon)
  }
  if (iconKeys && iconKeys.length) {
    const maxKey = Math.max(...iconKeys) // 取最大的
    let iconUrl = ''
    if (manifest.icons) {
      iconUrl = manifest.icons[maxKey]
    } else if (manifest.images) {
      iconUrl = manifest.images[maxKey]
    } else if (manifest.action?.default_icon) {
      iconUrl = manifest.action.default_icon[maxKey]
    }
    const file = await fs.readFile(path.join(localPath, iconUrl))
    const buffer = Buffer.from(file)
    info.icon = 'data:image/png;base64,' + buffer.toString('base64')
  }

  // 如果没有key的话，设置一个key，用id中的6位替换掉publicKey中的6位，保证同一个id的key相同
  if (!manifest.key) {
    const pubKey = await getPublicKeyFromCrxStream(Buffer.from(res.data))
    manifest.key =
      pubKey ||
      `MIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8AMIIBCgKCAQEAv9MwekU64GFSXIteFgB9laQHgn7J4dFGwI4j8c4V${info.id.substr(
        0,
        6
      )}`
  }
  await fs.outputJSON(path.join(localPath, 'manifest.json'), manifest)
}

// Credits for the original function go to Rob--W
// https://github.com/Rob--W/crxviewer/blob/master/src/lib/crx-to-zip.js
function crxToZip(buf) {
  function calcLength(a, b, c, d) {
    let length = 0

    length += a << 0
    length += b << 8
    length += c << 16
    length += (d << 24) >>> 0
    return length
  }

  // 50 4b 03 04
  // This is actually a zip file
  if (buf[0] === 80 && buf[1] === 75 && buf[2] === 3 && buf[3] === 4) {
    return buf
  }

  // 43 72 32 34 (Cr24)
  if (buf[0] !== 67 || buf[1] !== 114 || buf[2] !== 50 || buf[3] !== 52) {
    throw new Error('Invalid header: Does not start with Cr24')
  }

  // 02 00 00 00
  // or
  // 03 00 00 00
  const isV3 = buf[4] === 3
  const isV2 = buf[4] === 2

  if ((!isV2 && !isV3) || buf[5] || buf[6] || buf[7]) {
    throw new Error('Unexpected crx format version number.')
  }

  if (isV2) {
    const publicKeyLength = calcLength(buf[8], buf[9], buf[10], buf[11])
    const signatureLength = calcLength(buf[12], buf[13], buf[14], buf[15])

    // 16 = Magic number (4), CRX format version (4), lengths (2x4)
    const zipStartOffset = 16 + publicKeyLength + signatureLength

    return buf.slice(zipStartOffset, buf.length)
  }
  // v3 format has header size and then header
  const headerSize = calcLength(buf[8], buf[9], buf[10], buf[11])
  const zipStartOffset = 12 + headerSize

  return buf.slice(zipStartOffset, buf.length)
}

// 获取oss存储的本地扩展路径
async function getOssPathOfLocalExtension(extensionId) {
  const userInfo = await getUserInfo()
  return `user-extensions/${userInfo.belongUserId}/${extensionId}.zip`
}

// 打包上传本地扩展到oss
async function uploadLocalExtensionToOSS(extensionId) {
  try {
    const ossClient = await getOssClient({ bucket: OssExtensionBucket })

    const rootPath = await getExtensionRootPath()
    const zipFile = path.join(rootPath, `${extensionId}.zip`)

    await compressing.zip.compressDir(path.join(rootPath, extensionId), zipFile)
    const ossPath = await getOssPathOfLocalExtension(extensionId)
    await putObject(ossClient, ossPath, zipFile, extensionId)

    rimraf(zipFile, { maxRetries: 5 })
    // 有icon的话，上传到oss
    const info = await getLocalExtensionInfo(extensionId)

    if (info.icon && info.icon.split(',')[1]) {
      await ossClient.put(ossPath.replace('.zip', '.png'), Buffer.from(info.icon.split(',')[1], 'base64'))
    }
  } catch (err) {
    ossLog.error('upload extension to oss error ==>>>> ', err)
    throw err
  }
}

// 上传完成后，修改cloud_id
async function updateExtensionCloudId(extensionId, cloudId, mainUserId) {
  await updateCloudId(extensionId, cloudId, mainUserId)
}

// 是否需要下载自定义扩展，报错则直接返回true，重新下载
async function ifNeedDownload(extensionId, version) {
  try {
    // 先判断本地文件是否存在，不存在则直接下载
    const extensionPath = await getExtensionPath(extensionId)
    const exists = await fs.pathExists(extensionPath)
    if (!exists) return true

    // 扩展存在，则判断对应版本是否存在
    const versionExists = await ifVersionExists(extensionId, version)
    return !versionExists
  } catch (err) {
    ossLog.error('check if need download extension error ==>>> ', err)
  }
  return true
}

// 从oss下载自定义扩展
async function downloadLocalExtensionsFromOss(list = []) {
  for (const item of list) {
    try {
      // 有权限问题，直接跳过
      if (noPermittedIds.has(item.id)) continue

      // 不需要下载则直接跳过
      const needDownload = await ifNeedDownload(item.id, item.version)
      ossLog.info('if need to download extension ==>>>> ', item.id, item.version, needDownload)
      if (!needDownload) continue

      const rootPath = await getExtensionRootPath()
      await fs.ensureDir(rootPath)

      const client = await getOssClient({ bucket: OssExtensionBucket })
      const zipFile = path.join(rootPath, `${item.id}.zip`)
      const ossPath = await getOssPathOfLocalExtension(item.id)

      await downloadObject(client, ossPath, zipFile)
      await rimraf(path.join(rootPath, item.id), { maxRetries: 5 })
      await compressing.zip.uncompress(zipFile, rootPath)
      await addLocalExtension(item)
      await rimraf(zipFile, { maxRetries: 5 })
    } catch (err) {
      ossLog.error('download extension from oss error ==>>>>> ', err.message)

      reporter.extension(err, item.id, '下载自定义扩展')

      // 文件已经不存在，则删掉服务端记录
      if (err.message === 'Object not exists') {
        deleteExtensionNotExistsAnymore(item.cloud_id)
      } else {
        // 除了扩展文件不存在，其他情况都添加到本地扩展列表，如果是有问题的扩展，用户可以自己删除
        await addLocalExtension(item)
      }
      if (err.message.includes('EPERM: operation not permitted')) {
        noPermittedIds.add(item.id)
      }
    }
  }
}

// 从oss删除自定义扩展，删除扩展和图片
async function deleteExtensionFromOss(extensionId) {
  try {
    const ossClient = await getOssClient({ bucket: OssExtensionBucket })
    const ossPath = await getOssPathOfLocalExtension(extensionId)
    await deleteOssObject(ossClient, ossPath)
    await deleteOssObject(ossClient, ossPath.replace('.zip', '.png'))
  } catch (err) {
    ossLog.error('delete oss extension error ==>>> ', err)
  }
}

// 确保需要同步的云端扩展已下载到本地
async function ensureCloudExtensionsDone() {
  try {
    const cloudList = await getCustomExtensions()
    const localList = await getLocalExtensionList()
    ossLog.info('cloud and local extension list ==>>>> ', cloudList, localList.length)
    const userInfo = await getUserInfo()

    // 找出本地需要删掉的list，有cloud_id且云端list不包含此id
    const cloudIds = new Set(cloudList.map(item => item.id))
    const deleteList = localList.filter(
      item => item.cloud_id && item.main_user_id === userInfo.belongUserId && !cloudIds.has(item.cloud_id)
    )
    ossLog.info('delete extension list ==>>>> ', deleteList.length)
    if (deleteList.length) {
      deleteList.forEach(item => {
        deleteLocalExtensionById(item.extension_id)
      })
    }
    // 找出本地当前在云端list中的数据，取交集，更新 is_use
    const localCloudIds = new Set(localList.map(item => item.cloud_id))
    const updateList = cloudList.filter(item => localCloudIds.has(item.id))
    updateList.forEach(item => {
      changeExtensionIsUse(item.extendKey, item.isUse)
    })

    // 找出需要下载的list，本地数据库不存在的，以及本地库存在，但扩展文件不存在的
    let downList = []
    for (let item of cloudList) {
      if (localList.findIndex(cItem => item.extendKey === cItem.extension_id && item.version === cItem.version) === -1) {
        downList.push(item)
        continue
      }

      if (await ifNeedDownload(item.extendKey, item.version)) {
        downList.push(item)
      }
    }
    ossLog.info('sync extension list ==>>>> ', downList.length)

    if (downList.length) {
      downList = downList.map(item => {
        return {
          desc: item.extendDescribe,
          id: item.extendKey,
          icon: item.extendLogo,
          isUse: item.isUse,
          name: item.extendName,
          version: item.version,
          cloud_id: item.id,
          mainUserId: item.mainUserId
        }
      })

      await downloadLocalExtensionsFromOss(downList)
    }
  } catch (err) {
    ossLog.error('ensure cloud extensions done error ==>>>> ', err)
  }
}

// 更新Chrome扩展
async function updateGoogleExtension(info) {
  ossLog.info('update chrome extension ==>>>> ', info)

  const rootPath = await getExtensionRootPath()
  await fs.ensureDir(rootPath)
  const tempId = uid()

  // 下载到临时目录里
  await downloadFromGoogleStore(info, path.join(rootPath, tempId))
  // 删掉旧的
  await removeExtension(info.id)
  // 临时目录改回真正的目录
  await fs.rename(path.join(rootPath, tempId), path.join(rootPath, info.id))

  await addLocalExtension(info)

  ossLog.info('update chrome extension success.')
}

function pubKeyToHexId(pubKey) {
  return crypto.createHash('sha256').update(pubKey).digest('hex').slice(0, 32)
}

/**
 * @param {Buffer} crxData
 * */
async function getPublicKeyFromCrxStream(crxData) {
  try {
    // 加载 protobuf 定义
    const root = await protobuf.load(path.resolve(__dirname, process.env.QUASAR_PUBLIC_FOLDER, 'crx3.proto'))
    const CrxFileHeader = root.lookupType('crx_file.CrxFileHeader')
    const SignedData = root.lookupType('crx_file.SignedData')

    const magic = crxData.subarray(0, 4).toString()
    if (magic !== 'Cr24') {
      return null
    }

    const version = crxData.readUInt32LE(4)
    if (version !== 3) {
      return null
    }

    const headerSize = crxData.readUInt32LE(8)
    const crxFileHeader = CrxFileHeader.decode(crxData.subarray(12, 12 + headerSize))
    const signedHeaderData = SignedData.decode(crxFileHeader.signedHeaderData)
    const hexId = signedHeaderData.crxId.toString('hex')

    for (const proof of [...crxFileHeader.sha256WithRsa, ...crxFileHeader.sha256WithEcdsa]) {
      if (pubKeyToHexId(proof.publicKey) === hexId) {
        return proof.publicKey.toString('base64')
      }
    }
  } catch (err) {
    log.error('get public key from crx stream error ==>>> ', err)
  }

  return null // 如果没有找到公钥，返回 null
}

