export function getRandomLocalIp() {
  const genFns = [gen10Ip, gen172Ip, gen192Ip]
  return genFns[genRandomNum(0, 2)]()
}

function gen10Ip() {
  return `10.${genRandomNum(0, 255)}.${genRandomNum(0, 255)}.${genRandomNum(0, 255)}`
}
function gen172Ip() {
  return `172.${genRandomNum(16, 31)}.${genRandomNum(0, 255)}.${genRandomNum(0, 255)}`
}
function gen192Ip() {
  return `192.168.${genRandomNum(0, 255)}.${genRandomNum(0, 255)}`
}

