function encrypt(text, key) {
  const iv = crypto.randomBytes(16)
  const cipher = crypto.createCipheriv('aes-256-cbc', key, iv)
  let encrypted = cipher.update(text)
  encrypted = Buffer.concat([encrypted, cipher.final()])
  return iv.toString('hex') + ':' + encrypted.toString('hex')
}

export function decryptText(text, key) {
  if (!text) return ''
  const parts = text.split(':')
  const iv = Buffer.from(parts.shift(), 'hex')
  const encryptedText = Buffer.from(parts.pop(), 'hex')
  const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv)
  let decrypted = decipher.update(encryptedText)
  decrypted = Buffer.concat([decrypted, decipher.final()])
  return decrypted.toString()
}

// 写入加密文件，指纹文件与 ~LoginData
export async function encryptFile(filePath, data, key) {
  try {
    const hash = crypto.createHash('sha256')
    hash.update(key)
    const hashKey = hash.digest()
    const ivStr = crypto.randomBytes(16)

    let cipher = crypto.createCipheriv('aes-256-cbc', hashKey, ivStr)
    let crypted = cipher.update(data, 'utf8', 'binary')
    crypted += cipher.final('binary')
    crypted = Buffer.from(crypted, 'binary')

    let encrypted = Buffer.concat([ivStr, crypted])

    await fs.outputFile(filePath, encrypted)

    log.info('write file success')
  } catch (e) {
    throw e
  }
}

// 读取文件，加密并返回
export async function getFileEncrypedData(filePath, key) {
  try {
    const hash = crypto.createHash('sha256')
    hash.update(key)
    const hashKey = hash.digest()
    const ivStr = crypto.randomBytes(16)

    let cipher = crypto.createCipheriv('aes-256-cbc', hashKey, ivStr)
    const data = await fs.readFile(filePath)
    let crypted = cipher.update(data, 'utf8', 'binary')
    crypted += cipher.final('binary')
    crypted = Buffer.from(crypted, 'binary')

    let encrypted = Buffer.concat([ivStr, crypted])

    return encrypted
  } catch (err) {
    log.error('get file encrypted data error ======>>>>>>>', err)
  }
  return null
}

// 写入指纹加密文件
// #BT@ + 4字节保留（全0x00）+ 签名 + vi + 密文
export async function writeEncryptFingerprintFile(filePath, data) {
  // log.info('fingerprint file path ===>>>>>>>>> ', filePath, data)
  try {
    const { signature, encrypted } = await getSingature(data)

    const start = Buffer.from('#BT@')
    const signBuffer = Buffer.from(signature, 'hex')

    await fs.outputFile(filePath, Buffer.concat([start, Buffer.alloc(4), signBuffer, encrypted]))
  } catch (err) {
    throw err
  }
}

// 签名 = RSA 私钥加密 { sha256 ( vi + 密文 ) }
async function getSingature(data) {
  // 密文
  const encryptKey = getFingerprintDectyptKey()
  const hash = crypto.createHash('sha256')
  hash.update(encryptKey)
  const hashKey = hash.digest()
  const ivStr = crypto.randomBytes(16)

  let cipher = crypto.createCipheriv('aes-256-cbc', hashKey, ivStr)
  let crypted = cipher.update(data, 'utf8', 'binary')
  crypted += cipher.final('binary')
  crypted = Buffer.from(crypted, 'binary')

  const encrypted = Buffer.concat([ivStr, crypted])

  const signHash = crypto.createHash('sha256')
  signHash.update(encrypted)

  const signData = signHash.digest().toString('hex')

  const signature = await getRsaSign(signData)

  return {
    signature,
    encrypted
  }
}

// 多次调用，等第一次结束以后才可以执行后面的调用
export function hasCanUse() {
  let resolver
  let promise
  let tempPromise = () => {
    if (!promise) {
      promise = new Promise(resolve => {
        resolver = resolve
      })
      return Promise.resolve(resolver)
    }

    return promise
  }

  return tempPromise
}

// 获取解密文件内容
export async function decryptFile(filePath, key) {
  const bufferContent = await fs.readFile(filePath)

  const iv = bufferContent.subarray(0, 16) // 提取前 16 字节作为 IV
  const encryptedData = bufferContent.subarray(16) // 剩余部分是加密后的数据

  const hash = crypto.createHash('sha256')
  hash.update(key)

  const decipher = crypto.createDecipheriv('aes-256-cbc', hash.digest(), iv)
  let decrypted = decipher.update(Buffer.from(encryptedData), 'binary', 'utf-8')
  decrypted += decipher.final()

  return decrypted
}

