export function encryptZipFile(inputPath, outPath, key) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256')
    hash.update(key)
    const hashKey = hash.digest()

    const ivStr = crypto.randomBytes(16)

    const cipher = crypto.createCipheriv('aes-256-cbc', hashKey, ivStr)

    const input = fs.createReadStream(inputPath)
    const output = fs.createWriteStream(outPath)

    // 将IV附加到加密文件的开头
    output.write(ivStr)

    input.pipe(cipher).pipe(output)

    output.on('finish', resolve)

    output.on('error', e => {
      reject(e)
    })
  })
}

/**
 * @returns {Promise<Boolean>} 解密是否成功
 * */
export function decryptZipFile(inputFilePath, outputFilePath, key) {
  try {
    // log.info('decrypt zip file ========>>>>>>>>>>> ', inputFilePath, outputFilePath)
    const encryptedData = fs.readFileSync(inputFilePath)

    const hash = crypto.createHash('sha256')
    hash.update(key)
    const hashKey = hash.digest()

    // 从输入数据中读取前16个字节作为IV
    const readIV = encryptedData.subarray(0, 16)

    const decipher = crypto.createDecipheriv('aes-256-cbc', hashKey, readIV)

    const decryptedData = Buffer.concat([decipher.update(encryptedData.subarray(16)), decipher.final()])

    fs.writeFileSync(outputFilePath, decryptedData)
    return Promise.resolve(true)
  } catch (err) {
    log.error('decrypt zip file error ==>>>>> ', err)
    return Promise.resolve(false)
  }
}

export function decryptHexData(hexData, key) {
  try {
    const encryptedData = Buffer.from(hexData, 'hex')

    const hash = crypto.createHash('sha256')
    hash.update(key)
    const hashKey = hash.digest()

    // 从输入数据中读取前16个字节作为IV
    const readIV = encryptedData.subarray(0, 16)

    const decipher = crypto.createDecipheriv('aes-256-cbc', hashKey, readIV)

    const decryptedData = Buffer.concat([decipher.update(encryptedData.subarray(16)), decipher.final()])

    return decryptedData
  } catch (err) {
    ossLog.error('decrypt hex data error ==>>>> ', err)
  }
  return null
}

// 执行命令
export async function execCmd(cmd, cwd, timeout = 10000) {
  const exec = util.promisify(child_process.exec)
  try {
    const { stdout, stderr } = await Promise.race([
      exec(cmd, { cwd }),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Command timeout')), timeout))
    ])
    if (stderr) {
      log.info('exec cmd error ==>>> ', stderr)
      throw stderr
    } else {
      return stdout
    }
  } catch (error) {
    if (error.message === 'Command timeout') {
      log.error(`Command timeout after ${timeout}ms: ${cmd}`)
    }
    throw error
  }
}

// spawn执行命令
export function spawnCmd(bin, args) {
  return new Promise((resolve, reject) => {
    const proc = spawn(bin, args, { windowsHide: true })
    let output = ''
    proc.on('error', function (err) {
      reject(err)
    })
    proc.on('exit', function (code) {
      if (code) {
        reject(new Error(`spawn cmd failed with code ${code}\n${output}`))
      } else {
        resolve(output)
      }
    })
    proc.stdout.on('data', chunk => {
      output += chunk.toString()
    })
    proc.stderr.on('data', chunk => {
      output += chunk.toString()
    })
  })
}

/**
 * @description 获取系统代理
 * @returns {Promise<String>} eg: http://127.0.0.1:1090
 * */
export async function getSysProxy() {
  // 不使用系统代理，直接返回
  const { type, port } = await getSysProxyConfig()
  if (type === 2) return null

  // 自定义端口
  if (type === 3) return `http://127.0.0.1:${port}`

  if (process.platform === 'win32') {
    return getWindowsProxy()
  } else {
    return getDarwinProxy()
  }
}

/**
 * @description 获取系统代理port
 * @returns {Promise<Number>} port
 */
export async function getSysProxyPort() {
  const sysProxy = await getSysProxy()
  if (sysProxy) {
    const port = new URL(sysProxy).port

    return +port
  }
  return null
}

// 自动检测win系统代理配置
async function getWindowsProxy() {
  try {
    if (noNeedToCheckSysProxyAgain) return null

    let proxy = await execCmd('reg query "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings" /v ProxyServer')
    let enabled = await execCmd('reg query "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings" /v ProxyEnable')

    enabled = enabled.includes('0x1')
    proxy = proxy.split('REG_SZ')[1].trim()

    if (enabled && proxy) {
      return `http://${proxy}`
    }
  } catch (error) {
    log.error('Error fetching proxy settings:', error)
    noNeedToCheckSysProxyAgain = true
  }
  return null
}

// mac系统代理配置，遍历寻找Enable的网络
async function getDarwinProxy() {
  const netList = await getDarwinNetList()

  // 如果有Wi-Fi的网络，先判断有没有代理，没有的话，再遍历判断
  if (netList.includes('Wi-Fi')) {
    const wifiInfo = await getNetInfo('Wi-Fi')
    if (wifiInfo.Enabled === 'Yes') return `http://${wifiInfo.Server}:${wifiInfo.Port}`
  } else {
    for (const name of netList) {
      const info = await getNetInfo(name)
      if (info.Enabled === 'Yes') return `http://${info.Server}:${info.Port}`
    }
  }

  return null
}

// 获取mac系统内的netlist
async function getDarwinNetList() {
  try {
    const res = await execCmd('networksetup -listallnetworkservices', '')

    // 移除第一条，第一条无用：An asterisk (*) denotes that a network service is disabled.
    const list = res.split('\n').filter(item => !!item)
    list.shift()

    return list
  } catch (err) {}

  return []
}

// 获取Net对象 {Enabled: 'Yes|No', Server: '127.0.0.1', Port: 1087}
async function getNetInfo(netName) {
  const info = await execCmd(`networksetup -getwebproxy "${netName}"`, '')
  const arr = info.split('\n').filter(item => !!item)

  const obj = {}
  arr.forEach(item => {
    const tempArr = item.split(':')
    obj[tempArr[0]] = tempArr[1].trim()
  })

  return obj
}

// 从代理的host中，获取子域名, 如 zproxy.lum-superproxy.io，获取 lum-superproxy.io 部分
export function getSubDomainFromHost(host = '') {
  if (!host) return ''

  const parts = host.split('.')
  if (parts.length >= 2) {
    return parts[parts.length - 2] + '.' + parts[parts.length - 1]
  }

  return host // 不符合的话原样返回
}

// 设置多级Object的值
export function setMultiObjectValue(obj, keys = [], value) {
  while (keys.length) {
    const key = keys.shift()
    if (!keys.length) {
      obj[key] = value
    } else {
      if (!Reflect.has(obj, key)) {
        obj[key] = {}
      }

      setMultiObjectValue(obj[key], keys, value)
    }
  }
}

// 处理返回值为 key-value 键值对
function getWmicStdoutObj(stdout) {
  if (!stdout) return {}

  return stdout
    .trim()
    .split('\r\n')
    .map(item => item.trim())
    .reduce((acc, cur) => {
      const [key, value] = cur.split('=')
      acc[key] = value
      return acc
    }, {})
}

async function getWin7Model() {
  try {
    const obj = {}

    const sysRes = await execCmd('wmic computersystem get model,manufacturer /format:list')
    const sysData = getWmicStdoutObj(sysRes)

    const cpuRes = await execCmd('wmic cpu get Manufacturer,Name /format:list')
    const cpuData = getWmicStdoutObj(cpuRes)
    const cpuNameArr = cpuData.Name.split(' ')

    const osRes = await execCmd('wmic os get Caption,SerialNumber /format:list')
    const osData = getWmicStdoutObj(osRes)

    obj.model = sysData.Model
    obj.manufacturer = sysData.Manufacturer
    obj.cpuManufacturer = cpuNameArr.shift()
    obj.cpuBrand = cpuNameArr.join(' ')
    obj.cpuVendor = cpuData.Manufacturer
    obj.distro = osData.Caption
    obj.serial = osData.SerialNumber

    return obj
  } catch (err) {
    apiLog.error('get win7 model error ==>>> ', err)
  }

  return {}
}

