// Windows 系统进程获取备用方法
export async function getProcessListFallback() {
  try {
    if (process.platform !== 'win32') {
      apiLog.warn('getProcessListFallback is only supported on Windows')
      return []
    }

    let processes = []

    // 方法1: 尝试使用 wmic (最直接的备用方案，与 Get-CimInstance 类似)
    try {
      apiLog.info('Trying wmic process...')
      const stdout = await execCmd('wmic process get Name,ProcessId,ParentProcessId /format:csv', '', 10000)
      const lines = stdout.split('\n').slice(1) // 跳过标题行

      for (const line of lines) {
        if (line.trim()) {
          try {
            // 解析 CSV 格式的输出 (Node,Name,ParentProcessId,ProcessId)
            const parts = line.split(',').map(part => part.replace(/"/g, '').trim())
            if (parts.length >= 4) {
              const name = parts[1]
              const parentProcessId = parseInt(parts[2], 10)
              const pid = parseInt(parts[3], 10)

              if (!isNaN(pid) && name) {
                processes.push({
                  pid: pid,
                  parentPid: isNaN(parentProcessId) ? 0 : parentProcessId,
                  name: name,
                  path: ''
                })
              }
            }
          } catch (parseErr) {
            continue
          }
        }
      }

      if (processes.length > 0) {
        apiLog.info(`wmic method found ${processes.length} processes`)
        return processes
      }
    } catch (wmicErr) {
      apiLog.warn('wmic method failed:', wmicErr.message)
    }

    // 方法2: 尝试使用 Get-WmiObject (PowerShell WMI 备用方案)
    try {
      apiLog.info('Trying Get-WmiObject Win32_Process...')
      const stdout = await execCmd(
        'powershell "Get-WmiObject Win32_Process | Select-Object ProcessId,Name,ParentProcessId | ConvertTo-Csv -NoTypeInformation"',
        '',
        10000
      )
      const lines = stdout.split('\n').slice(1) // 跳过标题行

      for (const line of lines) {
        if (line.trim()) {
          try {
            // 解析 CSV 格式的输出 ("ProcessId","Name","ParentProcessId")
            const parts = line.split(',').map(part => part.replace(/"/g, '').trim())
            if (parts.length >= 2) {
              const pid = parseInt(parts[0], 10)
              const name = parts[1]
              const parentPid = parts[2] ? parseInt(parts[2], 10) : 0

              if (!isNaN(pid) && name) {
                processes.push({
                  pid: pid,
                  parentPid: isNaN(parentPid) ? 0 : parentPid,
                  name: name,
                  path: ''
                })
              }
            }
          } catch (parseErr) {
            continue
          }
        }
      }

      if (processes.length > 0) {
        apiLog.info(`Get-WmiObject method found ${processes.length} processes`)
        return processes
      }
    } catch (wmiErr) {
      apiLog.warn('Get-WmiObject method failed:', wmiErr.message)
    }

    // 方法3: 尝试使用 Get-Process
    try {
      apiLog.info('Trying Get-Process...')
      const stdout = await execCmd('powershell "Get-Process | Select-Object Id,ProcessName | ConvertTo-Csv -NoTypeInformation"', '', 8000)
      const lines = stdout.split('\n').slice(1) // 跳过标题行

      for (const line of lines) {
        if (line.trim()) {
          try {
            // 解析 CSV 格式的输出 ("Id","ProcessName")
            const parts = line.split(',').map(part => part.replace(/"/g, '').trim())
            if (parts.length >= 2) {
              const pid = parseInt(parts[0], 10)
              const name = parts[1]

              if (!isNaN(pid) && name) {
                processes.push({
                  pid: pid,
                  parentPid: 0, // Get-Process 无法直接获取父进程ID
                  name: name,
                  path: ''
                })
              }
            }
          } catch (parseErr) {
            continue
          }
        }
      }

      if (processes.length > 0) {
        apiLog.info(`Get-Process method found ${processes.length} processes`)
        return processes
      }
    } catch (getProcessErr) {
      apiLog.warn('Get-Process method failed:', getProcessErr.message)
    }

    // 方法4: 最后尝试使用 tasklist（最基础的方法）
    try {
      apiLog.info('Trying tasklist as final fallback...')
      const stdout = await execCmd('tasklist /fo csv /nh', '', 5000)
      const lines = stdout.split('\n')

      for (const line of lines) {
        if (line.trim()) {
          try {
            const parts = line.split(',').map(part => part.replace(/"/g, '').trim())
            if (parts.length >= 2) {
              const name = parts[0]
              const pid = parseInt(parts[1], 10)

              if (!isNaN(pid) && name) {
                processes.push({
                  pid: pid,
                  parentPid: 0, // tasklist 无法获取父进程ID
                  name: name,
                  path: ''
                })
              }
            }
          } catch (parseErr) {
            continue
          }
        }
      }

      if (processes.length > 0) {
        apiLog.info(`tasklist method found ${processes.length} processes`)
        return processes
      }
    } catch (tasklistErr) {
      apiLog.error('All fallback methods failed. tasklist error:', tasklistErr.message)
    }

    apiLog.warn('No fallback method succeeded, returning empty process list')
    return processes
  } catch (err) {
    apiLog.error('getProcessListFallback error ==>>> ', err)
    return []
  }
}

