/**
 * @description 杀掉还存在的 BitBrowser.exe 或者 BitBrowser.app，是内核程序，不是客户端主程序
 */
export async function killExistBrowsers() {
  try {
    const browsers = await getBitBrowserOrBitfoxProcesses()

    while (browsers.length) {
      const item = browsers.shift()
      Process.killProcess(item.pid)
    }
  } catch (e) {
    log.error('kill exist browsers error ==>>> ', e.message)
  }
}

export async function getFileMd5(filePath = '') {
  return new Promise((resolve, reject) => {
    const readStream = fs.createReadStream(filePath)
    const hash = crypto.createHash('md5')

    readStream.on('data', chunk => {
      hash.update(chunk)
    })

    readStream.on('end', () => {
      resolve(hash.digest('hex'))
    })

    readStream.on('error', reject)
  })
}

/**
 * @description 计算文件的哈希值并写入文件
 * @param {Stream} inputStream 输入流
 * @param {string} outputPath 输出文件路径
 * @returns {Promise<string>} 文件的哈希值
 */
export async function calculateHashAndWriteFile(inputStream, outputPath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('md5')
    const outputStream = fs.createWriteStream(outputPath)

    inputStream.on('data', chunk => {
      hash.update(chunk)
      outputStream.write(chunk)
    })

    inputStream.on('end', () => {
      outputStream.end()
      resolve({ md5: hash.digest('hex') })
    })

    inputStream.on('error', err => {
      outputStream.end()
      reject(err)
    })

    outputStream.on('error', err => {
      reject(err)
    })
  })
}

/**
 * @description 打包并加密
 * @param {Object} params
 * @param {string} params.targetDir 需要打包的目录
 * @param {string} params.key 密钥
 * @returns {Promise<string>} 打包并加密后的文件路径
 * */
export async function packAndEncrypt({ targetDir, key }) {
  const dirname = path.dirname(targetDir) // 上级目录
  const temp = path.join(dirname, uid() + '.zip')
  const encryptFile = path.join(dirname, uid() + '.zip')

  await compressing.zip.compressDir(targetDir, temp)
  await encryptZipFile(temp, encryptFile, key)
  rimraf(temp, { maxRetries: 5 })

  return encryptFile
}

/**
 * @description 解密并解包，根据 7z 和 zip 分别处理，过几个大版本后，可以删除7z判断
 * @param {Object} params
 * @param {string} params.sourceFile 加密文件路径
 * @param {string} params.targetDir 解包目录
 * @param {string} params.key 密钥
 * @returns {Promise<string>} 解包后的目录
 * */
export async function decryptAndUnpack({ sourceFile, targetDir, key }) {
  const temp = path.join(targetDir, uid())

  await decryptZipFile(sourceFile, temp, key)

  if (path.extname(sourceFile) === '.7z') {
    await unpack(temp, targetDir)
  } else {
    await compressing.zip.uncompress(temp, targetDir)
  }

  rimraf(sourceFile, { maxRetries: 5 })
  rimraf(temp, { maxRetries: 5 })
}

// 设置 Sentry 用户信息
export async function setSentryUser() {
  try {
    const userInfo = await getUserInfo()
    if (userInfo && userInfo.userName && userInfo.id) {
      const userData = {
        id: userInfo.id.toString(),
        username: userInfo.userName
      }

      // Sentry Electron 使用 setUser 设置用户信息
      Sentry.setUser(userData)
    } else {
      log.warn('User info incomplete, cannot set Sentry user:', {
        hasUserName: !!userInfo?.userName,
        hasId: !!userInfo?.id,
        userInfo: userInfo ? { id: userInfo.id, userName: userInfo.userName } : null
      })
    }
  } catch (err) {
    log.error('Failed to set Sentry user info:', err.message, err.stack)
  }
}

