import { ipcMain } from 'electron'
import { deleteCachedProxyIPData } from '../data/proxyIP'
import { sendBrowserOpened, sendBrowserClosed, sendBrowserStop } from '../electron-main'
import browserTabs from './BrowserTabs'
import { messages } from './Messages'
import { openOrClose } from './request'
import { sshProxy } from './SSHProxy'
import syncTasks, { SyncTaskEnum } from './SyncTasks'
import EventEmitter from 'events'
import { getBitBrowserOrBitfoxProcesses } from '../utils'
import { statusLog } from '../logs'

// 注册到相关事件
const BrowserStatusEvent = {
  closed: 'browser-close'
}

class BrowserStatus extends EventEmitter {
  constructor() {
    super()

    this.opening_ids = new Set() // 正在打开的浏览器ids
    this.opened_browsers = new Map() // 已打开的浏览器 puppeteer browser 对象
    this.opened_browsers_configs = new Map() // 已打开的浏览器 config 对象
    this.opened_browsers_pids = new Map() // 已打开的浏览器对应的pid
    this.closing_ids = new Set() // 正在关闭的窗口ids
    this.api_closing_ids = new Set() // api正在关闭的窗口
    this.ids_from_api = new Set() // api 打开的窗口
    this.firefox_ids = new Set() // 火狐内核的集合
    this.removed_ids = new Set() // API删除的id集合，如果API删除，则无须继续往服务端发送同步信息及接口等
  }

  /**
   * @description 设置正在打开的浏览器，删除有可能冗余下的已打开项，与配置项
   * @param {String} browserId 浏览器id
   * @param {Boolean} isApiUser 是否是API用户
   * */
  setBrowserOpening(browserId, isApiUser) {
    statusLog.info('set browser opening ==>>> ', browserId)
    this.opening_ids.add(browserId)
    this.opened_browsers.delete(browserId)
    this.opened_browsers_configs.delete(browserId)
    if (isApiUser) {
      this.ids_from_api.add(browserId)
    } else {
      this.ids_from_api.delete(browserId)
    }
  }

  /**
   * @description 设置正在关闭的窗口，正在关闭时，不进行tab标签的同步，防止出错
   * @param {String} browserId 浏览器id
   * */
  setBrowserClosing(browserId, fromApi) {
    statusLog.info('set browser closing ==>>> ', browserId)
    this.closing_ids.add(browserId)
    if (fromApi) {
      this.api_closing_ids.add(browserId)
    }
  }

  /**
   * @description 关闭进度窗口时，发送事件，停止继续打开浏览器
   * @param {String} browserId 浏览器id
   * */
  stopOpening(browserId) {
    statusLog.info('stop opening ==>>> ', browserId)
    this.opening_ids.delete(browserId)
  }

  /**
   * @description 设置已打开的浏览器数据
   * @param {String} browserId 浏览器id
   * @param {Object} browser puppeteer browser 对象
   * @param {Object} config 浏览器指纹配置
   * @param {Boolean} sendApi 是否需要发送请求，默认发送，从睡眠唤醒时，无需发送
   * */
  setBrowserOpened(browserId, browser, config, sendApi = true) {
    const isApiUser = this.ids_from_api.has(browserId)
    statusLog.info('set browser opened ==>>> ', config.seq, isApiUser)

    this.opening_ids.delete(browserId)
    this.closing_ids.delete(browserId)
    this.opened_browsers.set(browserId, browser)
    this.opened_browsers_configs.set(browserId, config)
    if (config.coreProduct === 'firefox') {
      this.firefox_ids.add(browserId)
    }

    sendBrowserOpened(config)

    // 唤醒重连时，有可能获取不到pid
    if (browser.process() && browser.process().pid) {
      this.opened_browsers_pids.set(browserId, browser.process().pid)
    }

    if (sendApi) {
      const reqData = { ids: [browserId], status: 1 }
      openOrClose(reqData, isApiUser)
    }
  }

  /**
   * @description 设置已关闭的浏览器状态数据，清除对应的缓存
   * @param {Object} config 浏览器配置
   * @param {String} urls 同步回服务端的tab urls，默认无需传入，如果需要同步tabs，则为传入的urls
   * */
  async setBrowserClosed(config, urls) {
    statusLog.info('set browser closed ==>>> ', config.seq, urls)
    this.firefox_ids.delete(config.id) // 不管是不是firefox，直接删除即可

    const data = { ids: [config.id], status: 0, url: urls === undefined ? config.url : urls }
    const isApiUser = this.ids_from_api.has(config.id)
    // 同步服务端状态，不阻塞流程
    openOrClose(data, isApiUser).catch(err => {
      syncTasks.add(config.seq, SyncTaskEnum.closeBrowser, data, isApiUser)
      statusLog.error('open or close error ==>>> ', err.message)
    })

    // 发送关闭消息到web
    sendBrowserClosed(config.id, urls === undefined ? config.url : urls)

    this.opening_ids.delete(config.id)
    this.opened_browsers.delete(config.id)
    this.opened_browsers_configs.delete(config.id)
    this.opened_browsers_pids.delete(config.id)
    this.closing_ids.delete(config.id)
    this.ids_from_api.delete(config.id)

    deleteCachedProxyIPData(config.id) // 删除缓存的代理IP信息
    if (config.proxyType === 'ssh') {
      sshProxy.destroy(config)
    }

    // 触发rpa中的关闭事件
    if (config.rpaRun) {
      ipcMain.emit('rpa-browser-close', config.id)
    }
    this.emit(BrowserStatusEvent.closed, config.id)
  }

  /**
   * @description 是否正在打开
   * @param {String} browserId 窗口ID
   * @returns {Boolean}
   * */
  isOpening(browserId) {
    return this.opening_ids.has(browserId)
  }

  /**
   * @description 是否正在关闭
   * @param {String} browserId 窗口ID
   * @returns {Boolean}
   * */
  isClosing(browserId) {
    return this.closing_ids.has(browserId)
  }

  /**
   * @description 是否已打开
   * @param {String} browserId 窗口ID
   * @returns {Boolean}
   * */
  hasOpened(browserId) {
    return this.opened_browsers.has(browserId)
  }

  // 是否时火狐
  isFirefox(browserId) {
    return this.firefox_ids.has(browserId)
  }

  /**
   * @description 获取已打开的窗口的puppeteer browser对象
   * @param {String} browserId
   * @returns {Object} 返回 puppeteer browser 对象
   * */
  getBrowser(browserId) {
    return this.opened_browsers.get(browserId)
  }

  /**
   * @description 获取已打开的窗口的 port
   * @param {Object} browser
   * @returns {Number} 返回浏览器debug port
   * */
  getBrowserPort(browser) {
    const wsEndpoint = browser.wsEndpoint()
    const url = new URL(wsEndpoint)
    return url.port
  }

  /**
   * @description 获取已打开的窗口的http调试地址
   * @param {Object} browser
   * @returns {String} 返回浏览器http调试地址 http://127.0.0.1:${port}
   * */
  getBrowserHttpAddress(browser) {
    const port = this.getBrowserPort(browser)
    return `http://127.0.0.1:${port}`
  }

  /**
   * @description 获取已打开的窗口config集合
   * @returns {Map<browserId, config>} 返回config数组
   */
  getOpenedBrowserConfigs() {
    return this.opened_browsers_configs
  }

  /**
   * @description 获取已打开的窗口config
   * @param {String} browserId
   * @returns {Object} config 返回config
   */
  getBrowserConfig(browserId) {
    return this.opened_browsers_configs.get(browserId)
  }

  /**
   * @description 获取已打开的窗口ID集合
   * @returns {Array<String>} 返回ids
   */
  getOpenedBrowserIds() {
    return Array.from(this.opened_browsers_configs.keys())
  }

  /**
   * @description 获取给定已打开的窗口的PID集合对象，有可能获取到的pid已经死掉了
   * @returns {Object}
   * @param {Array} browserIds
   */
  getOpenedBrowsersPids(browserIds = []) {
    const obj = {}
    for (let id of browserIds) {
      if (this.opened_browsers_pids.has(id)) obj[id] = this.opened_browsers_pids.get(id)
    }
    return obj
  }

  /**
   * @description 获取给定已打开的窗口的PID集合对象，检查下PID是否还活着，死掉的话，设置浏览器为关闭状态
   * @returns {Object}
   * @param {Array} browserIds
   */
  async getAliveBrowsersPids(browserIds = []) {
    const obj = {}
    try {
      // 所有缓存的窗口ids
      const allIds = Array.from(this.opened_browsers_pids.keys())

      statusLog.info('allIds ==>>>> ', allIds)

      // 取 allInds 和 browserIds 的并集，取到目标ids
      const targetIds = browserIds.filter(id => allIds.includes(id))

      statusLog.info('targetIds ==>>>> ', targetIds)

      // 没有要处理的数据，则直接返回 obj
      if (!targetIds.length) return obj

      const list = await getBitBrowserOrBitfoxProcesses()

      // 获取到现有的所有浏览器进程pid集合
      const browserPids = list.map(item => item.pid)

      statusLog.info('browser pids ==>>> ', browserPids)

      for (let id of targetIds) {
        const pid = this.opened_browsers_pids.get(id)

        // 进程id还存在，则说明活着，否则说明窗口被关闭了，清理一次关闭状态即可
        if (browserPids.includes(pid)) {
          obj[id] = pid
        } else {
          this.reset(id)
        }
      }
    } catch (err) {
      statusLog.error('get browser pids error ==>>> ', err)
    }
    return obj
  }

  // 获取已打开的窗口，只包含序号和id
  getOpenedBrowsersSeqs(desc = false) {
    let browsers = []
    for (let [key, value] of this.opened_browsers_configs) {
      browsers.push({ seq: value.seq, browserId: key, pid: this.opened_browsers_pids.get(key) })
    }
    return browsers.sort((a, b) => (desc ? b.seq - a.seq : a.seq - b.seq))
  }

  // 获取指定seq的窗口ids
  getBrowserIdsBySeqs(seqs = []) {
    const list = Array.from(this.opened_browsers_configs.values())
    return list.filter(config => seqs.includes(config.seq)).map(item => item.id)
  }

  /**
   * @description 打开URL
   * @param {String} browserId 窗口id
   * @param {String} url 要打开的url
   * @param {Boolean} active 是否当前活动标签打开
   */
  async openUrl(browserId, url, active) {
    const browser = this.getBrowser(browserId)
    if (!browser || !url) return

    if (url.startsWith('bitbrowser://')) {
      url = url.replace('bitbrowser://', 'chrome://')
    }

    if (active) {
      // 找到active page
      let page = await browserTabs.getActivePage(browser)

      page &&
        page.goto(url, {
          waitUntil: 'domcontentloaded'
        })
    } else {
      const newPage = await browser.newPage()
      newPage.goto(url)
    }
  }

  /**
   * @description 打开多个url
   * @param {String} browserId 窗口id
   * @param {Array} urls 要打开的urls
   * @param {Boolean} closeOthers 是否关闭其他标签
   */
  async openUrls(browserId, urls, closeOthers = false) {
    const browser = this.getBrowser(browserId)
    if (!browser) throw new Error(messages.getMessage('notOpened'))

    // 关闭其他tab，只保留现有的最后一个，防止浏览器被关闭
    let stashPage = null

    if (closeOthers) {
      const pages = await browser.pages()
      stashPage = pages.pop()
      if (pages.length) {
        pages.map(page => page.close())
      }
    }

    // 打开新tab
    for (let url of urls) {
      const newPage = await browser.newPage()
      newPage.goto(url, {
        waitUntil: 'domcontentloaded'
      })
    }
    // 关掉保留的最后一个page
    if (stashPage) stashPage.close()
  }

  /**
   * @description 关闭urls
   * @param {String} browserId 窗口id
   * @param {Array} urls 要关闭的url
   */
  async closeUrls(browserId, urls) {
    const browser = this.getBrowser(browserId)
    if (!browser) return Promise.reject(new Error(messages.getMessage('notOpened')))
    const pages = await browser.pages()

    // 移除所有的空白页面
    if (urls.includes('about:blank')) urls.push('chrome://newtab/')

    const closePages = pages.filter(page => {
      return urls.includes(page.target().url())
    })
    for (let page of closePages) {
      await page.close()
    }
  }

  /**
   * @description 除了指定url，关闭其他所有tab
   * @param {String} browserId 窗口id
   * @param {String} url 指定保留的url
   */
  async closeTabsExcept(browserId, url) {
    const browser = this.getBrowser(browserId)
    if (!browser) return Promise.reject(new Error(messages.getMessage('notOpened')))
    const pages = await browser.pages()

    // 过滤出需要排除的url页面，把其他的关闭即可，如果没有指定的url，则新打开一个空白页面，关掉其他
    const targetPages = pages.filter(page => page.target().url() !== url)

    if (targetPages.length < pages.length) {
      await Promise.all(targetPages.map(page => page.close()))
    } else {
      await browser.newPage()
      await Promise.all(pages.map(page => page.close()))
    }
  }

  /**
   * @description 关闭活动标签
   * @param {any[]} [browserIds=[]] 为空，则控制所有窗口
   * @param {boolean} [keepSafe=false] 是否保留最后一个标签页不关闭
   * @returns {Promise}
   * */
  async closeActiveTabs(browserIds = [], keepSafe = false) {
    try {
      if (!browserIds.length) {
        browserIds = this.getOpenedBrowserIds()
      }

      for (const id of browserIds) {
        const browser = await this.getBrowser(id)
        if (!browser) continue

        // 保留最后一个标签
        if (keepSafe) {
          const pages = await browser.pages()

          // 过滤掉打开的开发者工具
          const finalPages = pages.filter(page => !page.url().startsWith('devtools://'))

          if (finalPages.length === 1) continue
        }

        const activePage = await browserTabs.getActivePage(browser)
        if (!activePage) continue

        activePage.close()
      }
    } catch (err) {
      statusLog.error('close active tabs error ==>>>> ', err)
    }
  }

  // 检查是否停止继续打开窗口，直接跑出异常
  checkIfStopOpen(config, msg) {
    if (!this.opening_ids.has(config.id)) {
      sendBrowserStop(config.id)
      this.setBrowserClosed(config)

      statusLog.info('opening has been stoped ==>>>> ', msg)
      throw new Error('stop opening')
    }
  }

  async pageScreenshot(browserId, path) {
    const browser = this.getBrowser(browserId)
    if (!browser) return Promise.reject(new Error(messages.getMessage('screenShotErr')))
    const pages = await browser.pages()
    const page = pages.find(item => item.url() === browserTabs.getActiveUrl(browserId))
    await page.screenshot({ path, quality: 60, type: 'jpeg' })
  }

  /**
   * @description tabs去重，随机留一个tab
   * @param {String} browserId 窗口id
   */
  async pagesDeduplication(browserId) {
    const browser = this.getBrowser(browserId)
    if (!browser) return Promise.reject(new Error(messages.getMessage('notOpened')))
    let pages = await browser.pages()

    while (pages.length) {
      const page = pages.shift()
      const urls = pages.map(item => item.url())

      if (urls.includes(page.url())) {
        statusLog.info('page url ==>>> ', page.url())
        await page.close()
      }
    }
  }

  /**
   * @description 刷新url
   * @param {String} browserId 窗口id
   * @param {String} url 要刷新的url
   * @param {Boolean} ignoreCache 是否忽略缓存，默认false
   */
  async pageReload(browserId, url, ignoreCache = false) {
    const browser = this.getBrowser(browserId)
    if (!browser) return Promise.reject(new Error(messages.getMessage('notOpened')))
    const targets = browser.targets().filter(t => t.type() === 'page' && t.url() === url)
    for (let target of targets) {
      const client = await target.createCDPSession()
      await client.send('Page.reload', { ignoreCache })
    }
  }

  /**
   * @description 检查浏览器是否闲置，非已打开，正在打开，正在关闭
   * @param {String} browserId
   * @return {Boolean}
   * */
  isFreeTogo(browserId) {
    return !this.opened_browsers.has(browserId) && !this.opening_ids.has(browserId) && !this.closing_ids.has(browserId)
  }

  /**
   * @description 获取已打开窗口的port集合，已关闭的窗口，pid还残留的，设置为关闭
   * @return {Object} 返回已打开窗口的端口集合 {id: port, ...}
   * */
  async getOpenedPorts() {
    const map = {}
    const psList = await getBitBrowserOrBitfoxProcesses()

    // 获取到现有的所有浏览器进程pid集合
    const browserPids = psList.map(item => item.pid)

    for (const [id, browser] of this.opened_browsers) {
      const pid = this.opened_browsers_pids.get(id)
      if (browserPids.includes(pid)) {
        const url = new URL(browser.wsEndpoint())
        map[id] = url.port
      } else {
        const config = this.opened_browsers_configs.get(id)
        if (config) {
          this.setBrowserClosed(config)
        }
      }
    }
    return map
  }

  // 重置状态为未打开
  reset(browserId = '') {
    this.opening_ids.delete(browserId)
    this.opened_browsers.delete(browserId)
    this.opened_browsers_configs.delete(browserId)
    this.opened_browsers_pids.delete(browserId)
    this.closing_ids.delete(browserId)
    this.api_closing_ids.delete(browserId)
  }
}

const browserStatus = new BrowserStatus()

export default browserStatus
export { BrowserStatusEvent }
