const proxyIPInfo = new Map() // 缓存已代理上的IP信息

export function saveProxyIPData(browserId, ipData) {
  if (browserId) {
    proxyIPInfo.set(browserId, ipData)
  }
}

export function getCachedProxyIPData(browserId) {
  return proxyIPInfo.get(browserId)
}

export function deleteCachedProxyIPData(browserId) {
  proxyIPInfo.delete(browserId)
}

export function hasCachedProxyIPData(browserId) {
  return proxyIPInfo.has(browserId)
}
