import { app, ipcMain } from 'electron'
import { emptyDir, ensureDir, pathExists, createWriteStream } from 'fs-extra'
import path from 'path'
import { log } from '../logs'
import axios from 'axios'
import { exec } from 'child_process'
import compressing from 'compressing'
import { rimraf } from 'rimraf'
import { getNeedsSystemCertificates } from '../utils/systemCertificates'
import https from 'https'

export class Qunkong {
  constructor() {
    this.downloadUrl = ''
    this.rootPath = path.join(app.getPath('userData'), 'qunkong') // qunkong根目录 ${userData}/qunkong
    this.zipFile = path.join(this.rootPath, 'qunkong.zip') // 下载的文件
  }

  /**
   * @description 获取exe可执行文件路径
   * @return {Promise<String>} 返回exe path，不存在则返回null
   * */
  async getExePath() {
    try {
      // 在群控根目录 qunkong/Start.exe
      let startPath = path.join(this.rootPath, 'Start.exe')
      let exists = await pathExists(startPath)
      if (!exists) {
        // 不存在的话，往下继续找一层，防止打包了外层 qunkong 文件夹，结构变成 qunkong/qunkong/Start.exe
        startPath = path.join(this.rootPath, 'qunkong', 'Start.exe')
        exists = await pathExists(startPath) // 再次检测一次
      }
      if (exists) return startPath
    } catch (err) {}
    return null
  }

  // 下载到 rootPath/qunkong.zip
  download() {
    return new Promise(async (resolve, reject) => {
      try {
        const axiosConfig = {
          method: 'get',
          url: this.downloadUrl,
          responseType: 'stream',
          timeout: 0,
          httpsAgent: getNeedsSystemCertificates() ? https.globalAgent : false
        }

        const res = await axios(axiosConfig)

        const req = res.data
        const stream = createWriteStream(this.zipFile)

        stream.on('error', reject)

        let len = parseInt(res.headers['content-length'])
        let cur = 0
        req.pipe(stream)
        req.on('data', chunk => {
          cur += chunk.length
        })
        req.on('end', async () => {
          if (res.status === 200) {
            if (len === cur) {
              resolve()
            } else {
              stream.end()
              reject()
            }
          } else {
            stream.end()
            reject()
          }
        })
        req.on('error', e => {
          log.error('download qunkong.zip error ==>>> ', e)
          stream.end()
          reject()
        })
      } catch (err) {
        log.error('download qunkong.zip error ==>>> ', err)
        reject()
      }
    })
  }

  // 解压到userData/qunkong 目录
  async unzip() {
    await compressing.zip.uncompress(this.zipFile, this.rootPath)
    rimraf(this.zipFile, { maxRetries: 5 })
  }

  // 启动 Start.exe，传入url，需要下载时，从url下载zip
  async start(url) {
    try {
      this.downloadUrl = url
      await ensureDir(this.rootPath)
      let exePath = await this.getExePath()
      log.info('qunkong start.exe path ==>>>> ', exePath)
      if (exePath) {
        await this.exec(exePath)
      } else {
        // 清理掉有可能存在的损坏的文件
        await this.clear()
        await this.download()
        await this.unzip()
        // 下载完再次获取一遍exePath
        exePath = await this.getExePath()
        await this.exec(exePath)
      }
    } catch (err) {
      return Promise.reject(err)
    }
  }

  exec(exePath) {
    return new Promise((resolve, reject) => {
      const cp = exec(
        'Start.exe',
        {
          cwd: path.dirname(exePath)
        },
        err => {
          if (err) {
            reject(err)
          } else {
            log.info('relaunch start.exe ===>>>> ')
            resolve()
          }
        }
      )
      cp.on('error', err => {
        reject(err)
      })
      cp.stdout.once('data', data => {
        log.info('stdout data ==>>>> ', data)
        resolve()
      })
      cp.stdout.once('error', err => {
        log.info('stderr data ==>>> ', err)
        resolve()
      })
    })
  }

  // 清理掉损坏的文件
  async clear() {
    await emptyDir(this.rootPath)
  }
}

export function qunkongInitial() {
  const qunkong = new Qunkong()
  ipcMain.handle('start-qunkong', (e, url) => qunkong.start(url))
}
