import browserStatus, { BrowserStatusEvent } from './browserStatus'
import { log } from '../logs'
import { closeBrowser, openBrowserByApi } from '../browser'
import { getBrowserDetailForApi } from './request'
import { sleep } from '../utils'
import { getBatchOpenInterval } from '../data/globalConfigs'

const PosMap = new Map() // browserId => windowbounds = {left, top, width, height}
const reopenErrors = []
let isReopening = false // 正在重启，同时只能有一个重启任务执行

// 当前位置，重新打开浏览器
export async function reopenBrowsersAtCurrentPos(all = false, browserIds = []) {
  let ids = all ? browserStatus.getOpenedBrowserIds() : browserIds
  log.info('reopen ids ==>>>> ', ids)

  if (!ids.length || isReopening) return

  // 过滤掉未打开的窗口
  ids = ids.filter(id => browserStatus.hasOpened(id))

  reopenErrors.length = 0 // 每次重启窗口时，清空error
  isReopening = true

  // 等待全部关闭
  await waitForAllClosed(ids)

  log.info('reopen browsers closed ==>>>> ', ids)

  await sleep(2)

  // 依次打开
  for (const browserId of ids) {
    await reopenNow(browserId)
    const timeout = await getBatchOpenInterval()
    await sleep((timeout && timeout / 1000) || 2)
  }

  isReopening = false

  return reopenErrors
}

async function setCurPos(browserId) {
  const browser = browserStatus.getBrowser(browserId)
  const pages = await browser.pages()
  const target = (pages.find(item => !item.url().startsWith('about:blank') && !item.url().startsWith('chrome://')) || pages[0]).target() // 通过对一个page的target对象设置
  const client = await target.createCDPSession()
  // 获取windowId
  const res = await client.send('Browser.getWindowForTarget', { targetId: target._targetId })
  const currentBounds = await client.send('Browser.getWindowBounds', { windowId: res.windowId })
  PosMap.set(browserId, currentBounds.bounds)
}

async function reopenNow(browserId) {
  let res = {}
  try {
    res = await getBrowserDetailForApi(browserId)

    await openBrowserByApi(res, [], true, PosMap.get(browserId))
    PosMap.delete(browserId)
  } catch (err) {
    log.error('reopen now error ==>>> ', err)
    reopenErrors.push({ seq: res.seq, msg: err.message, id: browserId })
  }
}

// 等待所有窗口都关闭
function waitForAllClosed(ids = []) {
  return new Promise(async resolve => {
    const stackSet = new Set(ids)

    const handler = async browserId => {
      log.info('reopen and triggered closed ==>>>>> ', browserId)
      if (!stackSet.has(browserId)) return

      stackSet.delete(browserId)

      if (stackSet.size === 0) {
        browserStatus.off(BrowserStatusEvent.closed, handler)
        resolve()
      }
    }

    browserStatus.on(BrowserStatusEvent.closed, handler)

    // 依次关闭，跳过正在关闭的，和未打开的
    for (const browserId of ids) {
      const config = browserStatus.getBrowserConfig(browserId)
      try {
        await setCurPos(browserId)
        await closeBrowser(browserId)
      } catch (err) {
        log.error('reopen browser and close error ==>>>> ', err)
        PosMap.delete(browserId)
        reopenErrors.push({ seq: config.seq, msg: err.message, id: browserId })
      }
    }
  })
}
