import path from 'path'
import { app, BrowserWindow, session, screen } from 'electron'
import phoneStatus from './interface/phoneWindowStatus'
import { phoneLog } from './logs'

app.commandLine.appendSwitch('disable-accelerated-video-decode')
app.commandLine.appendSwitch('disable-accelerated-video-encode')
export async function openPhoneWindow(config) {
  if (phoneStatus.isOpening(config.id)) return

  if (phoneStatus.hasOpened(config.id)) {
    await reconnecPhonetWindow(config)
    return
  }

  phoneStatus.setBrowserOpening(config.id)
  let iconUrl = 'icons/phone-badge.ico'
  if (config.id === 'qunkong') {
    iconUrl = 'icons/qunkong-badge.ico'
  }
  const phoneWindow = new BrowserWindow({
    icon: path.resolve(__dirname, process.env.QUASAR_PUBLIC_FOLDER, iconUrl), // tray icon
    width: config.width || 357,
    height: config.height || 631,
    // minWidth: 357,
    // minHeight: 631,
    frame: false,
    backgroundColor: '#fff',
    resizable: false,
    webPreferences: {
      session: session.fromPartition(config.id),
      contextIsolation: true,
      sandbox: false,
      preload: path.resolve(__dirname, process.env.QUASAR_ELECTRON_PRELOAD)
    }
  })

  phoneWindow.on('close', e => {
    e.preventDefault()
    phoneWindow.webContents.send('mainwindow-close')
  })

  phoneWindow.on('closed', () => {
    phoneStatus.setBrowserClosed(config)
  })

  // windows设置不同的appId，以便每个窗口都有独立的任务栏图标
  if (process.platform === 'win32') {
    phoneWindow.setAppDetails({ appId: 'com.bitbrowser.com.' + config.id })
  }

  loadPhoneUrl(phoneWindow, config.url)

  phoneStatus.setBrowserOpened(config, phoneWindow)
}

// 加载手机页面
export async function loadPhoneUrl(window, url) {
  try {
    await window.webContents.loadURL(url)
  } catch (err) {
    window.loadFile(path.resolve(__dirname, process.env.QUASAR_PUBLIC_FOLDER, 'phoneError.html?' + url))
    phoneLog.error('load phone url error ==>>> ', err)
  }
}

// 唤起窗口
export async function reconnecPhonetWindow(config) {
  const window = phoneStatus.getWindow(config.id)
  if (!window) return

  window.restore()
  window.setAlwaysOnTop(true)
  setTimeout(() => {
    window.setAlwaysOnTop(false)
  }, 1000)
}

export async function closePhoneWindow(phoneId) {
  const window = phoneStatus.getWindow(phoneId)
  if (window) {
    window.destroy()
  }
}

export function setAlwaysOnTop(phoneId, onTop = false) {
  const window = phoneStatus.getWindow(phoneId)
  if (window) {
    window.setAlwaysOnTop(onTop)
  }
}

export function isAlwaysOnTop(phoneId) {
  const window = phoneStatus.getWindow(phoneId)
  if (window) {
    return window.isAlwaysOnTop()
  }
  throw new Error('Not found the window target, please check your phone profile ID.')
}

export async function closeAllPhoneWindows() {
  const ids = phoneStatus.getOpenedphoneIds()
  for (let id of ids) {
    await closePhoneWindow(id)
  }
}

export function minimizePhoneWindow(id) {
  const window = phoneStatus.getWindow(id)
  if (window) {
    window.minimize()
  }
}

let defaultBounds
export function toggleMaxiMizePhoneWindow(id) {
  const window = phoneStatus.getWindow(id)
  if (!window) return
  if (process.platform === 'darwin') {
    if (window.isMaximized()) {
      window.setBounds(defaultBounds)
    } else {
      defaultBounds = window.getBounds()

      const display = screen.getDisplayMatching(defaultBounds)
      const bounds = display.workArea
      window.setBounds(bounds)
    }
    return
  }
  if (window.isMaximized()) {
    window.restore()
  } else {
    window.maximize()
  }
}
