import Koa from 'koa'
import serve from 'koa-static'
import bodyParser from 'koa-bodyparser'
import path from 'node:path'
import { getLocalServerPort, saveLocalServerPort } from '../data/globalConfigs'
import tabsRouter from './tabs'
import userRouter from './user'
import developerRouter from './developer'
import { ipcMain } from 'electron'
import { messages } from '../interface/Messages'
import phoneRouter from './phone'
import sseRouter from './sse'
import configsRouter from './configs'
import { cors } from '../middleware/cors'
import { errorHandler } from '../middleware/error'
import extraLogRouter from './extraLog'
import cacheDataRouter from './cacheData'
import { apiLog } from '../logs'
import os from 'node:os'
import { execCmd } from '../utils'
import boundsRouter from './bounds'

const app = new Koa()
let server = null

// 允许跨域
app.use(cors())

// 错误处理
app.use(errorHandler())

app.use(
  serve(
    process.env.DEV
      ? path.resolve(__dirname, process.env.QUASAR_PUBLIC_FOLDER, 'agentHtml')
      : path.resolve(process.resourcesPath, 'agentHtml')
  )
)

app.use(
  bodyParser({
    enableTypes: ['json', 'form', 'text']
  })
)

// 注意先后注册的顺序，洋葱模型，要把只有并发限制的developerRouter放在最后
app.use(sseRouter)
app.use(configsRouter)
app.use(tabsRouter)
app.use(boundsRouter)
app.use(userRouter)
app.use(extraLogRouter)
app.use(cacheDataRouter)
app.use(developerRouter)
app.use(phoneRouter)

export async function initServer() {
  try {
    let port = await getLocalServerPort()
    const isUsed = await isPortUsed(port)
    apiLog.info('port is used ==>>> ', port, isUsed)

    // if (isUsed) port = 0
    server = app.listen(port)

    server.on('listening', () => {
      const listeningPort = server.address().port

      apiLog.info('loacal server listening port ==>>> ', listeningPort)
      saveLocalServerPort(listeningPort)
    })

    // 出错的时候，给本地端口加1，继续往上尝试
    server.on('error', async err => {
      apiLog.error('init server error ==>>>> ', err)
      let port = await getLocalServerPort()
      if (port < 65535) {
        port += 1
        await saveLocalServerPort(port)
        initServer()
      }
    })
  } catch (err) {
    apiLog.error('init local server error ==>>> ', err)
  }
}

// 关闭Server，防止升级或者其他退出情况时，Server还继续占用着端口
export function closeLocalServer() {
  return new Promise(resolve => {
    if (server && typeof server.close === 'function') {
      server.close(err => {
        if (err) {
          apiLog.error('close server error ==>>>>> ', err)
        }
        server = null
        resolve()
      })
    } else {
      resolve()
    }

    // 防止close一直无响应，2秒后自动resolve
    setTimeout(resolve, 2000)
  })
}

// 更换Server port
export async function changeServer(port) {
  const isUsed = await isPortUsed(port)
  apiLog.info('change server port ==>>> ', port, isUsed)
  if (isUsed) return Promise.reject(messages.getMessage('PortUsed'))
  await closeLocalServer()
  server = app.listen(port)
  saveLocalServerPort(port)
}

/**
 * @description 检测端口是否被占用，只要有输出，即可视为被占用，也可以用来检测PID是否在启用
 * @param {boolean} port
 * @return {Promise<Boolean>}
 *  */
export async function isPortUsed(port) {
  try {
    // 有任何返回，都认为被占用
    const stdout = await execCmd(os.platform() === 'win32' ? `netstat -ano|findstr ${port}` : `netstat -an|grep ${port}`)
    apiLog.info('check if port used stdout or stderr ==>>> ')
    apiLog.info(stdout)
    if (stdout) return true
  } catch (err) {
    // 没被占用的时候，会直接报错，则最终返回false即可
    apiLog.error('exec netstat error ===>>> ', err)
  }
  return false
}

ipcMain.handle('save-local-server-port', (e, port) => changeServer(port))
