export class TimeoutStack {
  constructor(list = [], timeout = 1000) {
    this.stack = list
    this.timeout = timeout
  }

  [Symbol.asyncIterator]() {
    let i = 0
    return {
      next: () => {
        const promise = new Promise(resolve => {
          setTimeout(() => {
            let done = i === this.stack.length
            resolve({ done, value: done ? undefined : this.stack[i++] })
          }, this.timeout)
        })
        return promise
      }
    }
  }
}
