import { log } from '../logs'
import browserStatus from '../interface/browserStatus'
import rpaContainer from '../rpa'
import { getBitBrowserOrBitfoxProcesses } from '../utils'

export async function processProtect() {
  const browsers = await getBitBrowserOrBitfoxProcesses()

  killResidualProcesses(browsers)
}

// 获取残留的进程
function killResidualProcesses(allList = []) {
  // 默认取已打开的窗口进程id，循环中加入正常的子进程，最终过滤出不在已打开的进程pid集合中，则为残留进程，获取到的进程中，父进程一定在子进程前面，所以循环一次即可
  const savedPids = new Set([...browserStatus.opened_browsers_pids.values()])

  // RPA的进程ID
  if (rpaContainer.pid) savedPids.add(rpaContainer.pid)

  // 先扫描所有直接子进程
  const result = []
  for (let item of allList) {
    if (savedPids.has(item.pid) || savedPids.has(item.parentPid)) {
      savedPids.add(item.pid)
    } else {
      result.push(item)
    }
  }

  log.info(
    'residual process ==>>>> ',
    result.map(item => `${item.pid}_${item.name}`)
  )
  while (result.length) {
    try {
      const item = result.shift()
      process.kill(item.pid)
    } catch (err) {
      log.error('kill residual process error ==>>>> ', err)
    }
  }
}
