export function cors() {
  return async (ctx, next) => {
    ctx.set('Access-Control-Allow-Origin', '*')
    ctx.set('Access-Control-Allow-Methods', '*')
    ctx.set('Access-Control-Allow-Headers', '*')

    if (ctx.request.method === 'OPTIONS') {
      ctx.status = 204
      ctx.body = ''
    } else {
      await next()
    }
  }
}
