import { getClient } from './client'
import { ossLog } from '../logs'

export async function saveSyncLogs(browser_id, path_md5, file_md5) {
  try {
    const db = await getClient()
    await db('sync_oss_logs').insert({ browser_id, path_md5, file_md5 }).onConflict('path_md5').merge()
  } catch (err) {
    ossLog.error('save oss sync logs error ==>>>> ', err)
  }
}

export async function findLocalOssMd5(path_md5) {
  try {
    const db = await getClient()
    const res = await db('sync_oss_logs').select('file_md5').where('path_md5', '=', path_md5)
    if (res.length) {
      return res[0].file_md5
    }
  } catch (err) {
    ossLog.error('find local oss file md5 error ==>>>> ', err)
  }
  return null
}

export async function clearSyncLogs(clearAll = false, browserIds = []) {
  try {
    const db = await getClient()
    if (clearAll) {
      await db('sync_oss_logs').del('*')
    } else {
      await db('sync_oss_logs').whereIn('browser_id', browserIds).del()
    }
  } catch (err) {
    ossLog.error('clear sync logs error ==>>>> ', err)
  }
}
