import { log } from '../logs'

// expired 实际过期时间，默认24小时
class CacheValue {
  constructor(value, hours = 24) {
    this.value = value
    this.expired = Date.now() + hours * 60 * 60 * 1000
  }
}

export class Cache {
  constructor() {
    this.valueMap = new Map()
  }

  // 过期时间按照小时算
  add(name, value, hours = 24) {
    this.valueMap.set(name, new CacheValue(value, hours))
  }

  get(name) {
    return this.valueMap.get(name).value
  }

  // 同时判断是否失效，失效则删除
  has(name) {
    if (!this.valueMap.has(name)) return false

    const cacheValue = this.valueMap.get(name)
    const expired = cacheValue.expired

    // 没有过期
    if (Date.now() < expired) return true

    this.delete(name)
    return false
  }

  delete(name) {
    log.info('delete cache value ==>>> ', name)
    this.valueMap.delete(name)
  }

  // 切换账号时，要清理掉所有缓存项
  clear() {
    this.valueMap.clear()
  }
}
