const developerRouter = new Router()

developerRouter.use(apiAuth(), async (ctx, next) => {
  apiLog.info('developer request url ==>>>> ', ctx.request.url)
  const url = ctx.request.url
  if (url.startsWith('/browser/') || url.startsWith('/group/') || url.startsWith('/cache/') || url.startsWith('/rpa/')) {
    ctx.isDeveloper = true
  }
  await next()
})
developerRouter.use('/browser/open', openingQueue())
developerRouter.use(rateLimit())

// 打开浏览器
developerRouter.post('/browser/open', paramRequired('id'), async ctx => {
  const id = ctx.request.body.id
  const args = ctx.request.body.args
  const queue = ctx.request.body.queue
  const ignoreDefaultUrls = ctx.request.body.ignoreDefaultUrls
  const newPageUrl = ctx.request.body.newPageUrl

  if (args != null && !Array.isArray(args)) return (ctx.body = ApiUtil.fail(messages.getMessage('ArrayType', 'args')))
  if (queue && typeof queue !== 'boolean') return (ctx.body = ApiUtil.fail(messages.getMessage('BooleanType', 'queue')))

  try {
    // 检查单个窗口状态
    if (isBrowserOpenApiCalling(id) || browserStatus.isOpening(id)) {
      throw new Error(messages.getMessage('browserOpening'))
    }

    if (browserStatus.isClosing(id)) {
      throw new Error(messages.getMessage('browserClosing'))
    }

    startBrowserOpenApiCall(id)

    let res = {}
    if (browserStatus.hasOpened(id)) {
      res = browserStatus.opened_browsers_configs.get(id)
      apiLog.info('browser has opened ==>>>> ', id)
    } else {
      res = await getBrowserDetailForApi(id)
      // 提取IP
      if (+res.proxyMethod === 3) res = await extractDymanicIp(res, true)
    }

    // 旧版本windows，不能打开109以上的内核
    if (res.browserFingerPrint.coreVersion && +res.browserFingerPrint.coreVersion > 109 && isOldWin()) {
      throw new Error(messages.getMessage('oldWin'))
    }

    // 是否忽略窗口原本的默认URL
    if (ignoreDefaultUrls) {
      res.ignoreDefaultUrls = ignoreDefaultUrls
      if (newPageUrl) res.newPageUrl = newPageUrl
    }

    const driverPath = res.coreProduct === 'firefox' ? '' : await chromeVersion.getChromedriverPath(res.browserFingerPrint.coreVersion)
    const wsEndpoint = await openBrowserByApi(res, args, true)

    apiLog.info('wsEndpoint ==>>>> ', wsEndpoint)
    const url = new URL(wsEndpoint)

    const result = {
      ws: wsEndpoint,
      http: `127.0.0.1:${url.port}`,
      coreVersion: res.browserFingerPrint.coreVersion,
      driver: driverPath,
      seq: res.seq,
      name: res.name,
      remark: res.remark,
      groupId: res.groupId,
      pid: browserStatus.opened_browsers_pids.get(id)
    }

    ctx.body = ApiUtil.success(result)
  } catch (err) {
    apiLog.error('get browser detail open ==>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  } finally {
    endBrowserOpenApiCall(id)
  }
})

// 关闭浏览器
developerRouter.post('/browser/close', paramRequired('id'), async ctx => {
  const id = ctx.request.body.id

  if (isBrowserOpenApiCalling(id)) {
    throw new Error(messages.getMessage('browserOpening'))
  }

  await closeBrowser(id, true)
  await sleep(1) // 等待1秒用于同步信息，防止API调用立即删除时，同步还未完成，导致竞速，接口报错

  ctx.body = ApiUtil.success(messages.getMessage('Success'))
})

