// 添加/修改浏览器，不能使用单独的 paramRequired('id') 中间件，因为 id 可能为空
developerRouter.post('/browser/update', async ctx => {
  try {
    const param = ctx.request.body
    if (param.id && param.id.length !== 32) return (ctx.body = ApiUtil.fail(messages.getMessage('InvalidID')))
    if (!param.browserFingerPrint) return (ctx.body = ApiUtil.fail(messages.getMessage('Required', 'browserFingerPrint')))
    if (Object.prototype.toString.call(param.browserFingerPrint) !== '[object Object]')
      return (ctx.body = ApiUtil.fail(messages.getMessage('ObjectType', 'browserFingerPrint')))
    if (param.name && param.name.length > 50) return (ctx.body = ApiUtil.fail(messages.getMessage('NameExceed')))
    if (param.userName && param.userName.length > 100) return (ctx.body = ApiUtil.fail(messages.getMessage('UsernameExceed')))
    if (param.password && param.password.length > 100) return (ctx.body = ApiUtil.fail(messages.getMessage('PassExceed')))
    if (param.remark && param.remark.length > 500) return (ctx.body = ApiUtil.fail(messages.getMessage('RemarkExceed')))
    if (![1, 2, 3].includes(param.proxyMethod)) return (ctx.body = ApiUtil.fail(messages.getMessage('ProxyMethod')))
    if (!param.proxyType) return (ctx.body = ApiUtil.fail(messages.getMessage('Required', 'proxyType')))

    // 数组类型的cookie，给序列化为字符串
    if (Array.isArray(param.cookie)) {
      param.cookie = JSON.stringify(param.cookie)
    }

    // 修改时，获取下detail，合并相关字段到参数里，否则会导致错误
    let detailConfig = {}
    if (param.id) {
      detailConfig = await getBrowserDetail(param.id)
    }

    // 远程请求的实际配置，由默认配置合并传入配置得到
    const reqParam = { ...BROWSER_CONFIG, ...detailConfig, ...param }
    // 添加时，设置下默认指纹对象
    if (!param.id) reqParam.browserFingerPrint = { ...BROWSER_CONFIG.browserFingerPrint, ...param.browserFingerPrint }

    const res = await updateBrowserInfo(reqParam)
    ctx.body = ApiUtil.success(res)
  } catch (err) {
    apiLog.error('browser update error ===>>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

