// 删除浏览器，彻底删除
developerRouter.post('/browser/delete', paramRequired('id'), async ctx => {
  const id = ctx.request.body.id

  if (isBrowserOpenApiCalling(id) || browserStatus.isOpening(id)) {
    throw new Error(messages.getMessage('browserOpening'))
  }

  // 正在打开或者关闭，等待5秒再执行
  if (browserStatus.isClosing(id)) {
    await sleep(5)
  }

  browserStatus.removed_ids.add(id)

  await closeBrowser(id, true)
  await deleteBrowserForever([id])
  clearBrowserCacheDirs([id])
  ctx.body = ApiUtil.success(messages.success())
})

// 批量删除浏览器
developerRouter.post('/browser/delete/ids', async ctx => {
  const ids = ctx.request.body.ids
  if (!ids || !Array.isArray(ids)) throw new Error(messages.getMessage('ArrayRequired', 'ids'))
  if (ids.length > 100) throw new Error(messages.getMessage('maxLength', 'ids'))

  if (ids.some(id => isBrowserOpenApiCalling(id) || browserStatus.isOpening(id))) {
    throw new Error(messages.getMessage('browserOpening'))
  }

  if (ids.some(id => browserStatus.isClosing(id))) {
    await sleep(5)
  }

  for (let id of ids) {
    if (typeof id !== 'string' || id.length !== 32) continue

    browserStatus.removed_ids.add(id)
    await closeBrowser(id, true)
  }

  await deleteBrowserForever(ids)
  clearBrowserCacheDirs(ids)

  ctx.body = ApiUtil.success(messages.success())
})

