developerRouter.post('/browser/list', async ctx => {
  const reqParam = ctx.request.body
  if (typeof reqParam.page !== 'number' || typeof reqParam.pageSize !== 'number') {
    return (ctx.body = ApiUtil.fail(messages.getMessage('Page')))
  }
  try {
    const conditions = [
      {
        name: 'isDelete',
        value: 0,
        op: 'eq'
      }
    ]
    if (reqParam.groupId) {
      conditions.push({ name: 'groupId', op: 'eq', value: reqParam.groupId })
    }
    if (reqParam.name) {
      conditions.push({ name: 'name', op: 'like', value: reqParam.name })
    }
    if (reqParam.remark) {
      conditions.push({ name: 'remark', op: 'like', value: reqParam.remark })
    }
    if (reqParam.seq && typeof reqParam.seq === 'number') {
      conditions.push({ name: 'seq', op: 'eq', value: reqParam.seq })
    }
    if (reqParam.minSeq && typeof reqParam.minSeq === 'number') {
      conditions.push({ name: 'seq', op: 'ge', value: reqParam.minSeq })
    }
    if (reqParam.maxSeq && typeof reqParam.maxSeq === 'number') {
      conditions.push({ name: 'seq', op: 'le', value: reqParam.maxSeq })
    }

    const res = await getBrowserList({
      searchParas: { conditions },
      sortProperties: 'seq',
      sortDirection: ['desc', 'asc'].includes(reqParam.sort) ? reqParam.sort : 'desc',
      ...reqParam
    })
    ctx.body = ApiUtil.success(res)
  } catch (err) {
    apiLog.error('get browser list error ===>>> ', err)
    ctx.body = ApiUtil.fail(err.message)
  }
})

