developerRouter.post('/browser/cookies/set', async ctx => {
  try {
    const browserId = ctx.request.body.browserId
    if (!browserId) throw new Error(messages.getMessage('Required', 'browserId'))

    const reqCookie = ctx.request.body.cookies
    if (!reqCookie || !reqCookie.length) throw new Error(messages.getMessage('Required', 'cookies'))

    let cookieStr = reqCookie
    if (Array.isArray(reqCookie)) {
      cookieStr = JSON.stringify(reqCookie)
    }
    const { success, cookies } = await parseCookies(cookieStr)
    if (!success) {
      throw new Error(messages.getMessage('invalidCookies'))
    }

    await setBrowserCookies(browserId, cookies)

    ctx.body = ApiUtil.success()
  } catch (err) {
    ctx.body = ApiUtil.fail(err.message)
  }
})

