import { deleteCookiesFile } from '../browser'
import browserStatus from './browserStatus'
import { log } from '../logs'
import throttle from 'lodash/throttle'

// 使用 Map 存储 cookies，key 是 browserId，value 是 cookies 数组
const cookiesCache = new Map()

// 存储每个 browserId 对应的 throttled 函数
const throttledSaveCookiesMap = new Map()

/**
 * @description 获取 CDP Client，每次都创建新的，避免缓存失效问题
 * @param {string} browserId 窗口ID
 * @returns {Promise<CDPSession|undefined>} CDP Session
 */
async function getCDPClient(browserId) {
  const browser = browserStatus.getBrowser(browserId)
  if (!browser) return

  const pages = await browser.pages()
  if (!pages.length) return

  // 优先选择非 about:blank 的 page（更可能长期存在）
  const targetPage = pages.find(p => !p.url().startsWith('about:blank') && !p.url().startsWith('chrome://')) || pages[0]
  log.info('targetPage ==>>> ', targetPage.url())

  const client = await targetPage.target().createCDPSession()
  return client
}

// 实际执行保存 cookies 的方法
async function doSaveBrowserCookies(browserId) {
  log.info('saveBrowserCookiesByApi ==>>> ', browserId)
  try {
    const client = await getCDPClient(browserId)
    if (!client) return

    const { cookies } = await client.send('Network.getAllCookies') // 获取所有域名包括第三方cookies
    cookiesCache.set(browserId, cookies)
  } catch (err) {
    // 关闭时，可能会导致无法获取到 CDP Session，不理即可
    log.error('save browser cookies by api error ==>>>> ', err.message)
  }
}

// 获取指定 browserId 的 throttled 函数
function getThrottledSaveCookies(browserId) {
  if (!throttledSaveCookiesMap.has(browserId)) {
    const throttledFn = throttle(
      () => {
        doSaveBrowserCookies(browserId)
      },
      1000,
      { leading: false, trailing: true }
    )
    throttledSaveCookiesMap.set(browserId, throttledFn)
  }
  return throttledSaveCookiesMap.get(browserId)
}

// 监听接口触发的保存cookies（带 throttle，1秒内最多执行一次，最后一次调用总是执行）
export function saveBrowserCookiesByApi(browserId) {
  getThrottledSaveCookies(browserId)()
}

// get browser cookies，获取关闭浏览器时还存在的page的cookie，platform无论是否关闭，都获取
export async function getBrowserCookies(browserId) {
  let cookies = cookiesCache.get(browserId) || []
  if (cookies && cookies.length) {
    // 过滤掉自定义的bitHelper cookie，这个域名只用于给扩展设置 BrowserId 和 LocalPort
    cookies = cookies.filter(item => item.domain !== '.bithelper.bitbrowser.cn')

    cookies = cookies.map(item => {
      delete item.priority
      delete item.sourceScheme
      delete item.sourcePort
      delete item.size
      delete item.partitionKey
      delete item.partitionKeyOpaque
      item.expires = Math.floor((Date.now() + 365 * 24 * 60 * 60 * 1000) / 1000)
      return item
    })
  }
  return cookies || []
}

/**
 * @description 设置打开窗口的cookie，不调用接口设置服务端数据
 * @param {any[]} [cookies=[]] cookies
 * @param {string} [browserId=''] 窗口ID
 * */
export async function setBrowserCookies(browserId = '', cookies = []) {
  const client = await getCDPClient(browserId)
  if (!client) return

  await client.send('Network.setCookies', { cookies })
  cookiesCache.set(browserId, cookies)
}

/**
 * @description 清空窗口cookie，如果已打开，调用cdp Network.clearBrowserCookies设置，如果未打开，则直接删除本地Cookies文件
 * @param {string} browserId  窗口ID
 * */
export async function clearBrowserCookies(browserId = '') {
  cookiesCache.delete(browserId)

  const browser = browserStatus.getBrowser(browserId)
  if (!browser) {
    log.info('delete cookies file')
    await deleteCookiesFile(browserId)
  } else {
    const client = await getCDPClient(browserId)
    if (client) {
      await client.send('Network.clearBrowserCookies')
    }
  }
}

/**
 * @description 窗口关闭且cookie已经上传到服务端，清空cookie缓存，注意此方法只用于关闭窗口时，清除缓存，不要在其他地方调用
 * @param {string} browserId  窗口ID
 * */
export async function clearBorwserCookieCache(browserId) {
  cookiesCache.delete(browserId)
}
