import { sleep } from './index'
import { apiLog } from '../logs'

// 正在处理的唯一因子集合
const processingKeys = new Set()

/**
 * 检查并记录重复请求
 * @param {string} key 唯一标识键
 * @returns {boolean} 是否正在处理中
 */
export function isProcessing(key) {
  apiLog.info(`isProcessing: ${key}`, processingKeys.has(key))
  return processingKeys.has(key)
}

/**
 * 开始处理请求
 * @param {string} key 唯一标识键
 */
export function startProcessing(key) {
  apiLog.info(`startProcessing: ${key}`)
  processingKeys.add(key)
}

/**
 * 结束处理请求
 * @param {string} key 唯一标识键
 */
export async function endProcessing(key, isImmediate = false) {
  apiLog.info(`endProcessing: ${key}`)
  if (!isImmediate) {
    await sleep(1)
  }
  processingKeys.delete(key)
}

/**
 * 检查浏览器打开接口是否正在调用
 * @param {string} browserId 浏览器ID
 * @returns {boolean} 是否正在调用
 */
export function isBrowserOpenApiCalling(browserId) {
  const key = `browser-open:${browserId}`
  return isProcessing(key)
}

/**
 * 开始浏览器打开接口调用
 * @param {string} browserId 浏览器ID
 */
export function startBrowserOpenApiCall(browserId) {
  const key = `browser-open:${browserId}`
  startProcessing(key)
}

/**
 * 结束浏览器打开接口调用
 * @param {string} browserId 浏览器ID
 * @param {boolean} isImmediate 是否立即结束，默认false，延迟1秒结束
 */
export async function endBrowserOpenApiCall(browserId, isImmediate = false) {
  const key = `browser-open:${browserId}`
  await endProcessing(key, isImmediate)
}
