import EventEmitter from 'events'
import Router from 'koa2-router'
import { Transform } from 'stream'

class SSEStream extends Transform {
  constructor() {
    super({
      writableObjectMode: true
    })
  }

  _transform(data, _encoding, done) {
    if (data.event === 'retry') {
      this.push(`retry: 1000\ndata: connected\n\n`)
    } else {
      this.push(`event: ${data.event}\ndata: ${JSON.stringify(data.data)}\n\n`)
    }

    done()
  }
}

const sseRouter = new Router()

const events = new EventEmitter()
events.setMaxListeners(0)

sseRouter.get('/sse', (ctx, next) => {
  ctx.status = 200
  ctx.set({
    'Content-Type': 'text/event-stream; charset=utf-8',
    'Cache-Control': 'no-cache',
    Connection: 'keep-alive',
    'Transfer-Encoding': 'chunked'
  })

  const stream = new SSEStream()
  ctx.body = stream
  stream.write({ event: 'retry' }) //设定retry

  const listener = data => {
    stream.write(data)
  }

  events.on('data', listener)

  stream.on('close', () => {
    events.off('data', listener)
  })
})

// 手机窗口关闭
export function setPhoneBrowserClosed(id) {
  events.emit('data', { event: 'phone-closed', data: { id } })
}

// 手机窗口打开
export function setPhoneBrowserOpened(id) {
  events.emit('data', { event: 'phone-opened', data: { id } })
}

