/**
 * @description 发送自定义消息
 * @param {Object} param0
 * @param {String} param0.event event
 * @param {*} param0.data data
 * */
export function sendCustomCommand({ event, data }) {
  if (!event) return

  events.emit('data', { event, data })
}

export default sseRouter
