import { spawnCmd } from '.'
import { log } from '../logs'
import path from 'path'

let SevenBinPath = ''

const SevenBinName = {
  win32: '7za.exe',
  darwin: '7za',
  linux: '7za'
}

const SevenBinDirname = {
  win32: 'win',
  darwin: 'mac',
  linux: 'linux'
}

/**
 * @description 获取7z可执行文件路径，dev环境的路径为 /rootpath/node_modules/7zip-bin/[process.platform]/[process.arch]/[SevenBinName[process.platform]]
 * @description 生产环境的路径为 appPath/resourcesPath/7zip-bin/[SevenBinName[process.platform]]
 * @returns {string} 7z可执行文件路径
 * */
function get7zExecutablePath() {
  if (SevenBinPath) return SevenBinPath

  // require.resolve('7zip-bin') // /Users/xxx/xxx/node_modules/7zip-bin/index.js
  const BasePath = process.env.DEV ? path.dirname(require.resolve('7zip-bin')) : process.resourcesPath

  if (process.env.DEV) {
    SevenBinPath = path.join(BasePath, SevenBinDirname[process.platform], process.arch, SevenBinName[process.platform])
  } else {
    SevenBinPath = path.join(BasePath, '7zip-bin', SevenBinName[process.platform])
  }

  log.info('7z path ==>>> ', SevenBinPath)

  return SevenBinPath
}

/**
 * @description 7z压缩
 * @param sourcePath 源文件路径
 * @param dest 目标文件路径
 * @returns {Promise<void>}
 * */
export async function pack(sourcePath, dest) {
  const binPath = get7zExecutablePath()
  log.info('sourcePath ==>>> ', sourcePath, dest)
  await spawnCmd(binPath, ['a', dest, sourcePath])
}

/**
 * @description 7z解压
 * @param sourcePath 源文件路径
 * @param dest 目标文件路径
 * @returns {Promise<void>}
 * */
export async function unpack(sourcePath, dest) {
  log.info('sourcePath ==>>> ', sourcePath, dest)
  const binPath = get7zExecutablePath()
  await spawnCmd(binPath, ['x', sourcePath, '-y', '-o' + dest])
}

/**
 * @description 7z删除文件，升级时可能用到
 * @param sourcePath 源文件路径
 * @param targetDir 目标文件路径
 * @returns {Promise<void>}
 * */
export async function deleteDirFrom7z(sourcePath, targetDir) {
  const binPath = get7zExecutablePath()
  // 7z d .\app.7z 7zip-bin
  await spawnCmd(binPath, ['d', sourcePath, targetDir])
}
