import { saveWebGLParametersToDB } from '../data/cacheData'
import { getOssClient, getOssFileMd5, getOssObject } from '../interface/OssUtils'
import { apiLog } from '../logs'
import { safeJsonParse } from '../utils/safeJsonParse'

let parametersFileMd5 = ''
const OSSBucket = 'browser-fingerprint-assets'

/**
 * @description 获取oss存储的webgl文件的md5
 * */
export async function getParametersFileMd5() {
  if (parametersFileMd5) {
    return parametersFileMd5
  }

  const client = await getOssClient({ bucket: OSSBucket })
  const md5 = await getOssFileMd5(client, `webgl/webGLparameters.json`)
  if (md5) {
    parametersFileMd5 = md5
  }
  return md5
}

export async function getLatestWebglparametersData() {
  try {
    const client = await getOssClient({ bucket: OSSBucket })
    const result = await getOssObject(client, `webgl/webGLparameters.json`)
    if (result) {
      await saveWebGLParametersToDB({ dataValue: safeJsonParse(result, 'getLatestWebglparametersData') })
    }
  } catch (err) {
    apiLog.error('getLatestWebglparameters error ==>>> ', err)
  }
}
