import { app } from 'electron'
import path from 'path'
import { getChromeAppVersions, getChromeByCoreVersion, updateChromeVersion } from '../data/chrome'
import { chromeLog } from '../logs'
import { getChildrenListByName } from './request'
import fs from 'fs-extra'
import EventEmitter from 'events'
import { sleep } from '../utils'
import { DownloadService } from './DownloadFile'
import { unpack } from '../utils/7zip'
import { rimraf } from 'rimraf'
import { deleteCacheDataFromDB } from '../data/cacheData'

const UpdateStatus = {
  default: 0,
  checking: 1,
  downloading: 2,
  updating: 3,
  error: 4,
  copying: 5, // 正在复制resources里的chrome
  noPermitted: 6 // 权限问题，不再进行下载
}

class Chrome extends EventEmitter {
  constructor() {
    super()
    this.status = UpdateStatus.default
  }

  /**
   * @description 检测版本，先从本地resourcePath取配置文件，初次安装或者升级前本地没有浏览器时，先从本地resourcePath中取，随后从网络取
   * @returns {Promise<Array>} [] 返回需要升级的版本list，而不是全部的服务端list
   */
  async checkVersion() {
    try {
      await this.copyToUserData()

      // 正在升级时，直接返回
      // if (this.status > UpdateStatus.default && this.status < UpdateStatus.error) return
      this.status = UpdateStatus.checking
      const localList = await getChromeAppVersions()
      const latestVersions = await getChildrenListByName(process.platform === 'darwin' ? 'MacChromiumVersions' : 'ChromiumVersions')
      // 需要升级的list
      const updateList = latestVersions.filter(
        item => !localList.find(lItem => lItem.chrome === item.dicName && lItem.version === item.dicCode)
      )
      chromeLog.info(
        'update list ==>>> ',
        updateList.map(item => item.dicCode)
      )
      // if (!updateList.length) {
      //   this.status = UpdateStatus.default
      // } else {
      //   await Promise.all(updateList.map(item => this.downloadChrome({ chrome: item.dicName, version: item.dicCode })))
      // }

      return updateList
    } catch (err) {
      chromeLog.error('check chrome update error ==>>> ', err)
      this.status = UpdateStatus.error
    }
    return []
  }

  // 确保chrome下载完成，如果本地文件已删除，则直接下载最新版
  async ensureChromeBeReady(coreVersion = '132', tryTimes = 0) {
    // 权限问题，直接抛异常即可
    if (this.status === UpdateStatus.noPermitted) throw new Error('EPERM: operation not permitted')

    const list = await this.checkVersion()

    try {
      // 检查完版本，再次确认下下载的文件是否存在，不存在则重新下载
      const versionObj = await getChromeByCoreVersion(coreVersion)
      chromeLog.info('ensure chrome be ready ==>>>>> ', versionObj)

      // 如果target为null，则代表versionObj就是最新的版本，直接下载即可，否则下载target
      const target = list.find(item => item.dicName === coreVersion)
      if (!target) {
        // 缓存list中没有数据，本地库中也没有 versionObj，则删除缓存，重新获取一次，有可能是内核刚发布，而本地缓存了旧数据，获取不到数据导致的
        if (!versionObj && tryTimes < 1) {
          await deleteCacheDataFromDB({ dataKey: process.platform === 'darwin' ? 'MacChromiumVersions' : 'ChromiumVersions' })
          return this.ensureChromeBeReady(coreVersion, tryTimes + 1)
        }
        await this.downloadChrome(versionObj)
      } else {
        await this.downloadChrome(target)
      }
    } catch (err) {
      chromeLog.error('download chrome core version error ==>>>> ', err)
      if (err.message.includes('EPERM: operation not permitted')) {
        this.status = UpdateStatus.noPermitted
      } else {
        this.status = UpdateStatus.error
      }

      throw new Error(err)
    }
  }

  // 确保chromedriver 下载
  async getChromedriverPath(coreVersion) {
    try {
      const driverDir = path.resolve(app.getPath('userData'), 'chromedriver')
      const driverPath = path.join(
        driverDir,
        process.platform === 'darwin' && process.arch === 'arm64' ? `${coreVersion}-arm` : coreVersion,
        process.platform === 'darwin' ? 'chromedriver' : 'chromedriver.exe'
      )

      const exists = await fs.pathExists(driverPath)
      if (!exists) {
        await fs.ensureDir(driverDir)
        const zipFile = path.join(driverDir, `${coreVersion}.7z`)

        const downloadService = new DownloadService(getOssDriverPath(coreVersion), zipFile)
        await downloadService.start()

        await unpack(zipFile, driverDir)
        rimraf(zipFile, { maxRetries: 5 })
      }
      return driverPath
    } catch (err) {
      chromeLog.error('get chromedriver path error ====>>>>>> ', err)
    }
    return ''
  }

  // 取本地文件，copy到用户目录下
  async copyToUserData() {
    try {
      // 正在复制，则等待复制完成即可
      if (this.status === UpdateStatus.copying) {
        chromeLog.info('chrome files copying!!!')
        await this.onCopyComplete()
        return
      }

      const configPath = path.join(process.resourcesPath, 'chrome/config.json')
      const configExists = await fs.pathExists(configPath)

      chromeLog.info('resources chrome config exists ==>>>> ', configExists)

      // 文件不存在，则直接返回即可
      if (!configExists) return

      this.status = UpdateStatus.copying
      const config = await fs.readJSON(configPath)

      // 确保 Chrome-bin 存在
      const chromeBinPath = path.join(app.getPath('userData'), 'Chrome-bin')
      await fs.ensureDir(chromeBinPath)

      // 复制所有文件到用户目录
      for (let [chrome, version] of Object.entries(config)) {
        // 如果对应内核已经存在了一个版本，则直接跳过，不进行复制，防止安装包里的chrome无法删除，导致每次启动都复制chrome到用户目录下，导致出错
        const skip = await this.checkExeExists(chrome)
        if (skip) continue

        chromeLog.info('copy resources chrome version ==>>> ', chrome, version)
        await fs.copy(path.join(process.resourcesPath, `chrome/${chrome}`), path.join(chromeBinPath, chrome), { recursive: true })
        await updateChromeVersion(chrome, version) // 更新数据库
      }

      this.status = UpdateStatus.default
      this.emit('copy-complete')
    } catch (err) {
      chromeLog.error('copy chrome to user data error ==>>>> ', err)
      this.status = UpdateStatus.error
    }
  }

  // 下载对应版本的chrome
  async downloadChrome(versionObj) {
    // 将字典转化为chrome和version
    if (!versionObj.chrome && !versionObj.version) {
      versionObj.chrome = versionObj.dicName
      versionObj.version = versionObj.dicCode
    }
    this.status = UpdateStatus.downloading

    const url = getDownloadUrl(versionObj)
    const chromeDir = path.join(app.getPath('userData'), 'Chrome-bin', versionObj.chrome)
    const zipFile = path.join(chromeDir, versionObj.version + '.7z')

    await fs.ensureDir(chromeDir)

    // 文件不存在才下载，防止重复下载
    if (!(await fs.pathExists(zipFile))) {
      chromeLog.info('chrome not exists , start download ==>>> ', url, zipFile)
      const downloadService = new DownloadService(url, zipFile)
      await downloadService.start()
    }

    await this.updateChrome(zipFile, path.join(chromeDir, versionObj.version), versionObj)
  }

  // 升级解压缩
  async updateChrome(zipFile, dest, versionObj) {
    this.status = UpdateStatus.updating

    chromeLog.info('updateChrome begin ==>>> ', zipFile, dest)

    try {
      await unpack(zipFile, dest)
      await updateChromeVersion(versionObj.chrome, versionObj.version)

      this.status = UpdateStatus.default
      this.emit('complete')
    } catch (err) {
      chromeLog.error('update chrome error ==>>>> ', err)
      if (err.message.includes('EPERM: operation not permitted')) {
        this.status = UpdateStatus.noPermitted
      } else {
        this.status = UpdateStatus.error
      }
    } finally {
      // 无论是成功还是失败，都删除，防止zip文件损坏导致下次无法下载，或者下载的文件不完整
      if (await fs.pathExists(zipFile)) {
        await rimraf(zipFile, { maxRetries: 5 })
      }
    }
  }

  // 更新完成
  onUpdateComplete() {
    return new Promise(resolve => {
      this.on('complete', resolve)
    })
  }

  // 文件复制完成
  onCopyComplete() {
    return new Promise(resolve => {
      this.on('copy-complete', resolve)
    })
  }

  // 检测本地exe文件是否存在，默认104
  async checkExeExists(coreVersion = '122') {
    try {
      const versionObj = await getChromeByCoreVersion(coreVersion)
      if (!versionObj) return false

      const exeFile = path.join(
        app.getPath('userData'),
        'Chrome-bin',
        versionObj.chrome,
        versionObj.version,
        process.platform === 'darwin' ? 'BitBrowser.app' : 'BitBrowser.exe'
      )
      const exists = await fs.pathExists(exeFile)
      return exists
    } catch (err) {
      chromeLog.error('check chrome secure error ==>>> ', err)
    }
    return false
  }

  // 获取执行文件路径，默认104
  async getExePath(coreVersion = '122', retryTimes = 0) {
    const platform = process.platform

    const versionObj = await getChromeByCoreVersion(coreVersion)

    chromeLog.info('versionObj ==>>> ', versionObj, retryTimes)

    // 获取不到的话，等待2秒再试试，重试10次
    if (!versionObj && retryTimes < 10) {
      chromeLog.info('retry get BitBrowser path')
      await sleep(2)
      return this.getExePath(coreVersion, retryTimes + 1)
    }

    if (platform === 'win32') {
      return path.resolve(app.getPath('userData'), 'Chrome-bin', versionObj.chrome, versionObj.version, 'BitBrowser.exe')
    } else {
      return path.resolve(
        app.getPath('userData'),
        'Chrome-bin',
        versionObj.chrome,
        versionObj.version,
        'BitBrowser.app/Contents/MacOS/BitBrowser'
      )
    }
  }

  // 删掉非当前版本的chrome文件，以及resource path 里的chrome，有残留的zip文件会一起被删除
  async clearOldChromes() {
    try {
      const versions = await getChromeAppVersions()

      if (!versions.length) return

      for (let ver of versions) {
        const chromeDir = path.join(app.getPath('userData'), 'Chrome-bin', ver.chrome)
        const dirs = await fs.readdir(chromeDir)
        const deleteDirs = dirs.filter(item => item !== ver.version)
        chromeLog.info('clear old chromes ==>>>> ', deleteDirs)
        deleteDirs.map(dir => rimraf(path.join(chromeDir, dir), { maxRetries: 5 }))
      }

      await rimraf(path.join(process.resourcesPath, 'chrome'), { maxRetries: 5 })
    } catch (err) {
      chromeLog.info('clear old chromes error ==>>> ', err)
    }
  }

  async repair(coreVersion) {
    try {
      const latestVersions = await getChildrenListByName(process.platform === 'darwin' ? 'MacChromiumVersions' : 'ChromiumVersions')
      const target = latestVersions.find(item => item.dicName === coreVersion)

      const versionPath = path.join(app.getPath('userData'), 'Chrome-bin', coreVersion)
      await fs.emptyDir(versionPath)

      await this.downloadChrome(target)
    } catch (err) {
      chromeLog.error('repair chrome error ==>>>> ', err)
      return Promise.reject(err.message)
    }
  }
}

// 获取内核oss url
function getDownloadUrl(versionObj) {
  let url = `${process.env.PUBLISH_URL}/chrome-${versionObj.chrome}/${versionObj.version}`
  if (process.platform === 'darwin') {
    url += process.arch === 'arm64' ? '_mac_arm64.7z' : '_mac.7z'
  } else {
    url += process.arch === 'ia32' ? '_x86.7z' : '.7z'
  }
  return url
}

function getOssDriverPath(coreVersion) {
  const publishUrl = process.env.PUBLISH_URL
  const urlObj = new URL(publishUrl)
  let url = `${urlObj.protocol}//${urlObj.hostname}/chromedriver` // 去掉publishUrl里的 /bit-update
  if (process.platform === 'darwin') {
    url += process.arch === 'arm64' ? `/mac/${coreVersion}-arm.7z` : `/mac/${coreVersion}.7z`
  } else {
    url += `/win/${coreVersion}.7z`
  }

  return url
}

export default new Chrome()
