import path from 'path'
import { log } from '../logs'
import { spawn } from 'child_process'
import { safeJsonParse } from './safeJsonParse'

/**
 * @description 获取系统代理临时隧道的端口
 * @param {String} sysProxy 系统代理地址 eg: http://127.0.0.1:10809
 * @param {Object} config 窗口配置
 * @returns {Promise<{port: Number, closeTun: Function}>}
 * */
export function getTempBittun(sysProxy, config) {
  return new Promise(resolve => {
    const exePath = getBittunPath()

    const targetProxy = getProxyScheme(config)
    log.info('target proxy info ===>>>>> ', sysProxy)

    const args = ['-L', 'socks5://:0', '-F', sysProxy, '-F', targetProxy]
    const tunnel = spawn(exePath, args, {
      // detached: true,
      // shell: true,
      windowsHide: true
    })

    // 判断 stderr 信息里的msg，是否包含 listening on [::]:57329/tcp 文本
    tunnel.stderr.on('data', data => {
      data = data.toString()
      log.info('tunnel data ==>>> ', data)
      if (data.includes('listening on')) {
        const res = safeJsonParse(data, 'getTempBittun')
        resolve({
          port: +res.msg.match(/\d+/)[0],
          closeTun() {
            log.info('close bit tunnel ==>>>> ')
            tunnel.kill('SIGTERM')
          }
        })
      } else {
        // tunnel.kill('SIGTERM')
        resolve({ port: null, closeTun() {} })
      }
    })

    tunnel.on('close', code => {
      log.info(`bittun 进程退出，退出码 ${code}`)
      resolve({ port: null, closeTun() {} })
    })
  })
}

// 获取scheme 代理配置
function getProxyScheme(config) {
  const username = config.proxyUserName
  const password = config.proxyPassword
  const host = config.host
  const port = config.port

  if (username && password) {
    const info = `${username}:${password}@${host}:${port}`
    if (config.proxyType === 'ssh') return `sshd://${info}`
    return `${config.proxyType}://${info}`
  } else {
    if (config.proxyType === 'ssh') return `sshd://${host}:${port}`
    return `${config.proxyType}://${host}:${port}`
  }
}

function getBittunPath() {
  if (process.platform === 'win32') {
    return process.env.DEV ? path.resolve(__dirname, '../../utils/bittun.exe') : path.join(process.resourcesPath, 'utils/bittun.exe')
  } else {
    return process.env.DEV ? path.resolve(__dirname, '../../utils/bittun') : path.join(process.resourcesPath, 'utils/bittun')
  }
}
