import { getPerformanceConfig, savePerformanceConfig } from '../data/globalConfigs'
import crypto from 'crypto'
import { v4 as uid } from 'uuid'
import path from 'path'
import fs from 'fs-extra'
import os from 'os'
import { log } from '../logs'

export async function ensureXCF() {
  const res = await getPerformanceConfig()
  if (!res) {
    const xcfValue = (await getXCF()) || (await generateAndSetXCF())
    savePerformanceConfig({ open: true, cpu: 95, mem: 95, freeCacheSpace: 1, xcf: xcfValue })
    return
  }

  const trimmedXcf = getTrimmedXCF(res.xcf) // 数据库中可能也存入了全空字符，这里进行修剪

  if (!trimmedXcf) {
    // performanceConfig 中不存在 xcf，先检查本地文件
    const localXcf = (await getXCF()) || (await generateAndSetXCF())
    savePerformanceConfig({ ...res, xcf: localXcf })
  } else {
    // performanceConfig 中存在 xcf，校验是否和本地文件一致
    const localXcf = await getXCF()
    if (!localXcf) {
      // 本地的 xcf 不存在，则设置到本地文件
      setXCF(res.xcf)
    } else if (res.xcf !== localXcf) {
      // 本地文件存在且 xcf 不一致，则设置 db
      savePerformanceConfig({ ...res, xcf: localXcf })
    }
  }
}

/**
 * 获取本地 XCF 文件内容，如果文件不存在则返回 null
 * @returns {Promise<string|null>} XCF 字符串或 null
 */
async function getXCF() {
  // 获取持久化存储目录
  const persistentDir = getPersistentDataDir()
  const xcfFile = path.join(persistentDir, '.xcf')

  try {
    // 检查文件是否存在
    const exists = await fs.pathExists(xcfFile)
    if (exists) {
      // 读取文件内容
      const content = await fs.readFile(xcfFile, 'utf8')
      const trimmedContent = getTrimmedXCF(content)
      return trimmedContent
    }
  } catch (error) {
    log.error('read xcf file error', error)
  }

  return null
}

/**
 * 获取修剪后的 XCF 字符串，部分win系統下可能存在写入异常导致 .xcf 文件内容为全空字符，这里进行修剪
 * @param {string} xcf - 原始 XCF 字符串
 * @returns {string} 修剪后的 XCF 字符串，如果 xcf 为空则返回空字符串
 */
function getTrimmedXCF(xcf) {
  if (!xcf) return ''
  return xcf.replace(/\u0000/g, '').trim()
}

/**
 * 设置本地 XCF 文件内容，如果文件不存在则创建
 * @param {string} xcfValue - 要设置的 XCF 值
 * @returns {Promise<void>}
 */
async function setXCF(xcfValue) {
  // 获取持久化存储目录
  const persistentDir = getPersistentDataDir()
  const xcfFile = path.join(persistentDir, '.xcf')

  try {
    await fs.outputFile(xcfFile, xcfValue)
  } catch (error) {
    log.error('output xcf file error', error)
  }
}

/**
 * 生成新的 XCF 字符串并设置到本地文件
 * @returns {Promise<string>} 生成的 XCF 字符串
 */
async function generateAndSetXCF(xcfValue) {
  if (xcfValue) {
    await setXCF(xcfValue)
    return xcfValue
  }

  // 生成新的 XCF 字符串
  const randomUid = uid()
  const timestamp = Date.now()
  const newXcf = crypto
    .createHash('sha256')
    .update(randomUid + timestamp)
    .digest('hex')

  // 设置到本地文件
  await setXCF(newXcf)

  return newXcf
}

/**
 * 获取持久化数据目录，跨平台兼容
 * @returns {string} 持久化数据目录路径
 */
function getPersistentDataDir() {
  const platform = process.platform
  const dirName = process.env.DEBUGGING ? '.bitdata-debugging' : '.bitdata'

  switch (platform) {
    case 'win32':
      // Windows: ProgramData\.bitdata
      return path.join(process.env.PROGRAMDATA || 'C:\\ProgramData', dirName)
    case 'darwin':
      // macOS: 使用用户目录 ~/Library/Application Support\.bitdata
      return path.join(os.homedir(), 'Library/Application Support', dirName)
    case 'linux':
      // Linux: /var/lib/.bitdata 或 /opt/.bitdata 或 /home/user/.bitdata
      return path.join(os.homedir(), dirName)
    default:
      // 默认使用用户主目录
      return path.join(os.homedir(), dirName)
  }
}
