import { log } from '../logs'
import browserStatus from '../interface/browserStatus'

/**
 * @description 内存监控，检测主进程内存使用情况
 */
export function memoryMonitor() {
  try {
    const openedCount = browserStatus.getOpenedBrowserIds().length
    const memUsage = process.memoryUsage()
    const heapUsedMB = (memUsage.heapUsed / 1024 / 1024).toFixed(2)
    const heapTotalMB = (memUsage.heapTotal / 1024 / 1024).toFixed(2)
    const externalMB = (memUsage.external / 1024 / 1024).toFixed(2)
    const rssMB = (memUsage.rss / 1024 / 1024).toFixed(2)
    const heapUsedPercent = ((memUsage.heapUsed / memUsage.heapTotal) * 100).toFixed(2)

    log.info('[Memory Monitor]', {
      openedBrowsers: openedCount,
      heap: `${heapUsedMB}MB / ${heapTotalMB}MB (${heapUsedPercent}%)`,
      external: `${externalMB}MB`,
      rss: `${rssMB}MB`,
      uptime: `${(process.uptime() / 3600).toFixed(1)}h`
    })

    // 总堆使用超过 500MB 时报警
    if (heapTotalMB > 500) {
      log.warn('[High Memory] Heap usage warning:', {
        heapUsedPercent: `${heapUsedPercent}%`,
        heapUsed: `${heapUsedMB}MB`,
        heapTotal: `${heapTotalMB}MB`,
        openedBrowsers: openedCount
      })
    }
  } catch (err) {
    log.error('Memory monitor error:', err.message)
  }
}
