import { apiLog } from '../logs'

/**
 * 安全的 JSON.parse 包装函数，带有日志记录
 * @param {string} jsonString - 要解析的 JSON 字符串
 * @param {string} source - 调用来源标识（用于日志追踪）
 * @returns {any} 解析后的对象
 */
export function safeJsonParse(jsonString, source = 'unknown') {
  if (!jsonString) {
    return null
  }

  const sizeKB = Math.round(jsonString.length / 1024)

  // 记录日志：数据大小
  if (sizeKB >= 100) {
    // 大于 100KB 的数据记录 warn 级别日志
    apiLog.warn(`[JSON.parse] source: ${source}, size: ${sizeKB}KB (large data warning)`)
  } else if (sizeKB >= 10) {
    // 10KB-100KB 记录 info 级别日志
    apiLog.info(`[JSON.parse] source: ${source}, size: ${sizeKB}KB`)
  }
  // 小于 10KB 的数据不记录日志，避免日志过多

  try {
    return JSON.parse(jsonString)
  } catch (err) {
    apiLog.error(`[JSON.parse] Failed! source: ${source}, size: ${sizeKB}KB, error: ${err.message}`)
    throw err
  }
}

/**
 * 安全的 JSON.parse，失败时返回默认值而不是抛出异常
 * @param {string} jsonString - 要解析的 JSON 字符串
 * @param {any} defaultValue - 解析失败时的默认值
 * @param {string} source - 调用来源标识
 * @returns {any} 解析后的对象或默认值
 */
export function safeJsonParseWithDefault(jsonString, defaultValue = null, source = 'unknown') {
  try {
    return safeJsonParse(jsonString, source)
  } catch (err) {
    return defaultValue
  }
}
