import { date } from 'quasar'
import { getUserInfo } from '../interface/request'
import { extraLog } from '../logs'
import { getClient } from './client'

export async function saveExtraLog(data) {
  try {
    const userInfo = await getUserInfo()
    data.log_username = userInfo.userName
    data.log_userid = userInfo.id
    data.created_time = date.formatDate(new Date(), 'YYYY-MM-DD HH:mm:ss')
    const db = await getClient()
    const res = await db('local_extra_logs')
      .insert({ ...data })
      .returning('*')
    return res[0]
  } catch (err) {
    extraLog.error('save extra log error ==>>>> ', err)
  }
}

export async function getExtraInfo(id) {
  const db = await getClient()
  const res = await db('local_extra_logs').select('*').where('id', '=', id)
  if (!res || !res.length) {
    throw new Error('not found.')
  }

  return res[0]
}

export async function updateExtraLog(data) {
  const id = data.id
  delete data.id
  delete data.log_username
  delete data.log_userid
  const db = await getClient()
  await db('local_extra_logs').where({ id }).update(data)
}

export async function deleteExtraLogs(ids = []) {
  const db = await getClient()
  await db('local_extra_logs').delete('*').whereIn('id', ids)
}

export async function listExtraLogs({
  page = 0,
  page_size = 10,
  search_key = '',
  search_value = '',
  order_by = 'desc',
  from = '',
  to = ''
}) {
  const db = await getClient()
  let query = db('local_extra_logs').select('*')
  let countQuery = db('local_extra_logs').count('* as total')

  if (search_key && search_value) {
    query = query.whereLike(search_key, `%${search_value}%`)
    countQuery = countQuery.whereLike(search_key, `%${search_value}%`)
  }

  if (from && to) {
    query = query.whereBetween('created_time', [from, to])
    countQuery = countQuery.whereBetween('created_time', [from, to])
  }

  if (order_by) query = query.orderBy('id', order_by)

  query = query.offset(page * page_size).limit(page_size)

  extraLog.info('list sql ==>>>> ', query.toString())

  const res = await query
  const [{ total }] = await countQuery

  return { total, list: res }
}

export async function clearExtraLogs() {
  const db = await getClient()
  await db('local_extra_logs').delete('*')
}
