// 缓存请求promise，并发请求时，只等待第一次结果即可
const cacheRequestPromise = new Map()

// 解决证书问题
// process.env['NODE_TLS_REJECT_UNAUTHORIZED'] = 0

const request = axios.create({
  baseURL: process.env.VUE_APP_API,
  timeout: 30000,
  proxy: false,
  httpAgent: false,
  httpsAgent: false,
  agent: false,
  headers: {
    'Content-Type': 'application/json;charset=UTF-8'
  }
})

request.interceptors.request.use(
  async config => {
    // 如果存在证书问题标记，且请求级别没有传入 agent，则使用全局 agent（包含合并后的系统证书）
    if (getNeedsSystemCertificates()) {
      // 检查请求级别是否已经指定了 agent
      const hasCustomAgent = config.httpsAgent || config.httpAgent || config.agent

      if (!hasCustomAgent) {
        // 没有自定义 agent，使用全局 agent（包含系统证书）
        config.httpsAgent = https.globalAgent
      }
      // 如果有自定义 agent（比如代理检测时传入的代理 agent），则跳过，使用传入的配置
    }

    const token = await getAppToken()
    if (!token) {
      apiLog.info('token is invalid, please check ==>>>>> ')
      ipcMain.emit('user-logout') // 触发一次用户退出事件，清理掉rpa任务
      return Promise.reject(new Error('token 失效，请检查登录状态'))
    }
    config.headers['Authorization'] = `Bearer ${token}`
    config.headers.Language = getLocale()

    if (config.isIpv6) {
      config.baseURL = 'https://ipv6.bitbrowser.cn/bitbrowser'
    } else if (config.isProxy) {
      config.baseURL = globalSetting.getProxyUrl()
    } else {
      const serviceLine = globalSetting.getServiceLine(!!config.isApiUser)
      config.baseURL = serviceLine
    }

    if (config.isApiUser) {
      config.headers['x-api-auth'] = 1
    }

    // 针对老版本axios请求体直接传string的情况，新版本需要手动转换，兼容老版本
    if (typeof config.data === 'string') {
      config.transformRequest = [data => data]
    }

    apiLog.info('request api url ==>>> ', config.baseURL + config.url, config.isApiUser)

    return config
  },
  error => {
    apiLog.error('request api error ==>>> ', error.message)
    return Promise.reject(error)
  }
)

request.interceptors.response.use(
  response => {
    // apiLog.info('tcp client response header ==>>> ', response.request._header)
    if (response.status === 200) {
      if (response.data.code === 20000) {
        return response.data.result
      } else {
        return Promise.reject(response.data)
      }
    } else {
      return Promise.reject(`服务端状态出错, status: ${response.status}, text: ${response.statusText}`)
    }
  },
  error => {
    // const { response } = error
    return Promise.reject(error)
  }
)

export { request }

/**
 * @description 获取IP信息
 * @param {object} options
 * @param {object} options.agent
 * @param {string} options.method
 * @param {boolean} options.isIpv6
 * @param {number} options.timeout
 * @param {boolean} options.isApiUser
 * @param {boolean} options.isProxy 是否是代理检测接口
 * @param {1|0} options.checkExists 检查Ip是否使用过
 * @param {string} options.middleIp 如果是rola的ip，无法直接查询到的，则先通过ip234查询IP，再直接查询此IP的信息
 * @param {boolean} useProxy 是否使用proxy对象的代理方式替代httpAgent代理方式
 *  */
export async function getIpInfo(options, useProxy = false) {
  // 合并参数
  const opts = {
    url: '/v1/apis/ipgeoMethod',
    method: 'post',
    data: { ip: options.middleIp || '', method: options.method || 'ip123in', checkExists: options.checkExists || 0 },
    timeout: options.timeout || 20000,
    isIpv6: !!options.isIpv6,
    isApiUser: options.isApiUser,
    isProxy: true
  }
  if (options.agent) {
    if (useProxy) {
      opts.proxy = getHttpProxyObj(options.agent.proxy)
    } else {
      opts.httpAgent = opts.httpsAgent = options.agent
    }
  }

  return request(opts)
}

// 获取字典子值
export async function getChildrenListByName(dicCode) {
  const cacheData = await getCacheDataFromDB({ dataKey: dicCode })
  if (cacheData) {
    return cacheData
  } else {
    const res = await request({ url: '/v1/sysDictionarys/getChildrenListByName', method: 'post', data: { dicCode } })
    saveCacheDataToDB({ dataKey: dicCode, dataValue: res })
    return res
  }
}

// 获取字典值
export async function getDicListByName(name) {
  const cacheData = await getCacheDataFromDB({ dataKey: name })
  if (cacheData) {
    return cacheData
  } else {
    const data = {
      searchParas: {
        conditions: [
          {
            name: 'dicName',
            op: 'eq',
            value: name
          }
        ]
      }
    }
    const res = await request({
      url: '/v1/sysDictionarys/list',
      method: 'post',
      data: data
    })

    saveCacheDataToDB({ dataKey: name, dataValue: res })

    return res
  }
}

// 根据code获取字典值
export async function getDictByCode(code) {
  const cacheData = await getCacheDataFromDB({ dataKey: code })
  if (cacheData) {
    return cacheData
  } else {
    const data = {
      searchParas: {
        conditions: [
          {
            name: 'dicCode',
            op: 'eq',
            value: code
          }
        ]
      }
    }
    const res = await request({
      url: '/v1/sysDictionarys/list',
      method: 'post',
      data: data
    })

    // 字典真正有数据，才缓存
    if (res.list && res.list.length) {
      saveCacheDataToDB({ dataKey: code, dataValue: res })
    }

    return res
  }
}

