// 当前登录用户信息
export async function getUserInfo() {
  const cacheName = 'UserInfo'
  if (cacheData.has(cacheName)) return cacheData.get(cacheName)

  if (!cacheRequestPromise.has(cacheName)) {
    cacheRequestPromise.set(cacheName, request({ url: '/users/currentUser', method: 'get' }))
  }

  try {
    const res = await cacheRequestPromise.get(cacheName)

    cacheData.add(cacheName, res)

    saveAuthToken(res.isLocalToken === 1, res.localToken)

    return res
  } catch (err) {
    return Promise.reject(err)
  } finally {
    cacheRequestPromise.delete(cacheName)
  }
}

