// 获取工作台广告图片
export async function getWorkbenchAds() {
  try {
    const key = getLocale() === 'zh' ? 'DashboardAds' : 'DashboardAdsEn'

    if (cacheData.has(key)) {
      const list = cacheData.get(key)
      for (let item of list) {
        if (!item.dicName.startsWith('data:')) {
          item.dicName = await getCacheFileData(item.dicName)
        }
      }

      return list
    }
    const res = await getChildrenListByName(key)

    for (let item of res) {
      item.dicName = await getCacheFileData(item.dicName)
    }

    cacheData.add(key, res)
    return res
  } catch (err) {
    apiLog.error('get DashboardAds error ==>>>> ', err.message)
  }
  return []
}

