// 根据key获取基础配置
async function getBrowserBaseSetting() {
  let settings = {
    startBrowserStyle: 'position',
    needGoogleTranslate: 0,
    positionObject: { x: 0, y: 0 } // 默认打开位置
  }
  try {
    const res = await getGlobalValueFromClient({ globalValueType: 'browserBaseSetting' })
    if (res && res.globalValue && res.globalValue.length) {
      const sourceObj = safeJsonParse(res.globalValue, 'getBrowserBaseSetting')

      // 合并对象，防止默认值被覆盖
      Object.assign(settings, sourceObj)
    }
  } catch (error) {
    apiLog.error('getOpenBrowserStart ==>>> ', err)
  }
  return settings
}

// 获取窗口启动位置，默认位置
export async function getBrowserStartPosition() {
  const settings = await getBrowserBaseSetting()

  // return { lastPosition: true }

  switch (settings.startBrowserStyle) {
    case 'minimized':
      return { minimized: true }
    case 'maximized':
      return { maximized: true }
    case 'lastPosition':
      return { lastPosition: true }
    default:
      return { x: +settings.positionObject.x, y: +settings.positionObject.y, position: true }
  }
}

// 获取谷歌翻译的bypass_rule
async function getSysProxyBypassRules() {
  const settings = await getBrowserBaseSetting()
  if (!settings.needGoogleTranslate) return null

  if (cacheData.has('ProxyBypassRules')) return cacheData.get('ProxyBypassRules')

  try {
    const res = await request({ url: '/v1/sysUsers/getSysProxyList', method: 'post' })

    if (Array.isArray(res)) {
      const rules = res.map(item => {
        item.proxy = decryptText(item.proxy, getBypassrulesKey())
        return item
      })
      cacheData.add('ProxyBypassRules', rules)
      return rules
    }
  } catch (err) {
    apiLog.error('get sys proxy list error ==>>>> ', err.message)
  }

  return null
}

// 获取Proxy Bypass
export async function getProxyBypassRules() {
  const rules = []
  // 获取字典BypassRules
  try {
    const res = await getDictByCode('BypassRules')

    const data = safeJsonParse(res.list[0].comments, 'getProxyBypassRules')

    rules.push(...data)
  } catch (err) {
    apiLog.error('get bypassrules error ==>>>> ', err.message)
    rules.push({
      domains: [
        'safebrowsing.googleapis.com',
        'optimizationguide-pa.googleapis.com',
        '*gvt2.com',
        '*gvt1.com',
        '*gvt1-cn.com',
        '*gvt2-cn.com'
      ],
      proxy: 'http://127.0.0.1:6',
      overwriteBypass: true
    })
  }

  // 获取系统的bypass_rules，其中包含谷歌翻译
  const sysProxyBypassRules = await getSysProxyBypassRules()
  if (sysProxyBypassRules && sysProxyBypassRules.length) {
    rules.push(...sysProxyBypassRules)
  }

  return rules
}

