import { app } from 'electron'
import compressing from 'compressing'
import fs from 'fs-extra'
import path from 'path'
import { rimraf } from 'rimraf'
import { getOssClient, multipartUpload } from '../interface/OssUtils'
import { getUserInfo } from '../interface/request'
import { ossLog } from '../logs'
import dayjs from 'dayjs'

/**
 * @description 打包日志目录下的所有日志，压缩为zip，上传到OSS，然后删除临时文件
 * @returns {Promise<String>} 返回OSS路径
 * */
export async function uploadLogsToOss() {
  ossLog.info('upload logs to oss ==>>> ')

  // 1. 获取日志目录路径（Windows: userData/logs, Mac: Logs/BitBrowser）
  const logsPath = app.getPath('logs')

  // 2. 获取用户信息，用于构建OSS路径
  const userInfo = await getUserInfo()
  if (!userInfo || !userInfo.userName) {
    throw new Error('get user info failed or username is empty')
  }

  // 3. 创建临时zip文件路径（用户目录下的临时文件夹）
  const tempDir = app.getPath('temp')
  await fs.ensureDir(tempDir)
  const zipFileName = `${dayjs().format('YYYY-MM-DD_HH-mm-ss')}.zip`
  const zipFilePath = path.join(tempDir, zipFileName)

  // 4. 打包日志目录下的所有文件
  ossLog.info('compressing logs ==>>> ', logsPath, 'to', zipFilePath)
  await compressing.zip.compressDir(logsPath, zipFilePath)

  // 5. 检查压缩文件大小，如果超过100MB则报错
  const fileStats = await fs.stat(zipFilePath)
  const fileSizeInMB = fileStats.size / (1024 * 1024)
  const maxSizeInMB = 100

  if (fileSizeInMB > maxSizeInMB) {
    await rimraf(zipFilePath, { maxRetries: 5 })
    throw new Error(`zip file size ${fileSizeInMB.toFixed(2)}MB exceeds the limit ${maxSizeInMB}MB`)
  }

  // 6. 获取指定bucket的OSS client并上传
  const client = await getOssClient({ bucket: 'bitbrowser-report-logs' })
  const ossPath = `${process.env.DEBUGGING ? 'test' : 'prod'}/${userInfo.userName}/${zipFileName}`
  ossLog.info('uploading logs to oss ==>>> ', ossPath)
  await multipartUpload(client, ossPath, zipFilePath, userInfo.userName)

  // 7. 删除临时文件
  await rimraf(zipFilePath, { maxRetries: 5 })
  ossLog.info('upload logs to oss success and delete temp file ==>>> ', zipFilePath)
}
