import { ipcMain } from 'electron'
import { rpaLogs } from '../logs'
import { RpaTask } from './task'
import { sendWebRpaTaskChange } from '../electron-main'

class RpaTaskPool {
  constructor() {
    this.pool = [] // running list
    this.concurrent = 5 // 并发，默认5
    this.waittingList = [] // waitting task list
    this.failList = [] // 获取browserIds失败的任务，在下次执行任务的时候，优先从失败list中取出添加

    ipcMain.on('run-rpa-task', (e, taskItem) => {
      this.unshiftTask(taskItem)
    })

    ipcMain.on('stop-rpa-task', (e, taskId) => {
      this.destroyTask(taskId)
    })

    ipcMain.handle('get-running-rpa-tasks', () => this.pool)

    // 更新并发
    ipcMain.on('set-rpa-concurrent', (e, concurrent) => {
      rpaLogs.info('set rpa concurrent ========>>>>>>>> ', concurrent)

      if (typeof concurrent === 'number' && concurrent > 0 && this.concurrent !== concurrent) {
        this.concurrent = concurrent
        this.collect()
      }
    })

    // 找出执行完的浏览器所在的任务，触发hanleFinish
    ipcMain.on('rpa-browser-close', browserId => {
      rpaLogs.info('browser closed listener ===>>>>>> ', browserId)

      try {
        const task = this.pool.find(task => task.pool.includes(browserId))
        task && task.hanleFinish(browserId)
      } catch (err) {
        rpaLogs.error('find task which browser has closed error ==>>>> ', err)
      }
    })
  }

  // 最前插入任务
  unshiftTask(taskItem) {
    const task = new RpaTask(taskItem)

    this.waittingList.unshift(task) // 手工触发的任务，插入到队列最前面
    this.collect()
  }

  /**
   * @description 添加任务
   * @param {RpaTask} task
   */
  addTask(task) {
    rpaLogs.info('add rpa task ==>>> ', task)

    const index = this.waittingList.findIndex(item => item.taskId === task.taskId)
    if (index > -1) {
      this.waittingList.splice(index, 1, task) // 替换掉在排队的
    } else {
      this.waittingList.push(task) // 添加到watting list
    }

    this.collect()
  }

  // 收集需要执行的任务，每次添加任务，或者删除完任务，都需要收集一次
  collect() {
    while (this.waittingList.length && this.pool.length < this.concurrent) {
      const task = this.waittingList.shift()

      if (this.pool.findIndex(item => item.taskId === task.taskId) > -1) {
        task.isRuningAndSkip()
        rpaLogs.info('task is running and skip ==>>>> ', task)
      } else {
        this.pool.push(task)
        task.collectAndRun()
        rpaLogs.info('add task to pool ==>>>>> ', task)
      }
    }
  }

  setConcurrent(concurrent) {
    this.concurrent = concurrent
  }

  destroyTask(taskId) {
    // 先去掉wait list 里的任务
    const waitIndex = this.waittingList.findIndex(item => item.taskId === taskId)
    if (waitIndex > -1) this.waittingList.splice(waitIndex, 1)

    // 如果是正在执行，则停掉任务
    const index = this.pool.findIndex(item => item.taskId === taskId)
    if (index > -1) {
      const task = this.pool.splice(index, 1).pop()
      task.destroy()
    }

    sendWebRpaTaskChange()
    this.collect()
  }

  // 通过browserId查找正在运行的任务
  findRunningTask(browserId) {
    if (!this.pool.length) return null

    return this.pool.find(task => task.pool.includes(browserId))
  }
}

const rpaTaskPool = new RpaTaskPool()

export default rpaTaskPool
