class Messages {
  constructor() {
    this.locale = 'zh' // 默认中文
  }

  setLocale(locale = 'zh') {
    this.locale = locale
  }

  getLocale() {
    return this.locale || 'zh'
  }

  // 如果语言配置不存在，则返回英文的，如果有参数，则自动匹配替换
  getMessage(key, param) {
    try {
      if (!LocaleMessages[this.locale]) {
        return param ? LocaleMessages.en[key].replace('{arg}', param) : LocaleMessages.en[key]
      }
      return param ? LocaleMessages[this.locale][key].replace('{arg}', param) : LocaleMessages[this.locale][key]
    } catch (err) {
      apiLog.error('get locale message error ==>>> ', err)
    }
    return ''
  }

  success() {
    return this.locale === 'zh' ? '操作成功' : 'Success'
  }
}

const messages = new Messages()

export { messages }

// 加载完html后，无需从数据库读语言配置
export function getLocale() {
  return messages.getLocale()
}

ipcMain.on('set-locale', (e, locale) => {
  apiLog.info('set locale ==>>>>>>>', locale)
  messages.setLocale(locale)
  saveLocaleToDB(locale)
})
