import { setPhoneBrowserClosed, setPhoneBrowserOpened } from '../server/sse'
import { phoneBrowserOpenOrClose } from './request'
import { BrowserWindow } from 'electron'
import { phoneLog } from '../logs'

class PhoneWindowStatus {
  constructor() {
    this.opening_ids = new Set() // 正在打开的手机IDs
    this.opened_windows = new Map()
    this.opened_phone_configs = new Map() // 已打开的浏览器 config 对象
    this.closing_ids = new Set() // 正在关闭的手机IDs
    this.keep_alive_configs = new Map() // 关闭窗口不改状态
  }

  /**
   * @description 设置正在打开的浏览器，删除有可能冗余下的已打开项，与配置项
   * @param {String} phoneId 手机ID
   * */
  setBrowserOpening(phoneId) {
    phoneLog.info('set phone opening ==>>> ', phoneId)
    this.opening_ids.add(phoneId)
    this.opened_windows.delete(phoneId)
    this.opened_phone_configs.delete(phoneId)
  }

  /**
   * @description 设置正在关闭的窗口
   * @param {String} phoneId 手机ID
   * */
  setBrowserClosing(phoneId) {
    phoneLog.info('set phone closing ==>>> ', phoneId)
    this.closing_ids.add(phoneId)
  }

  /**
   * @description 设置已打开的浏览器数据
   * @param {Object} config 浏览器指纹配置
   * @param {BrowserWindow} widnow BrowserWindow 对象
   * */
  setBrowserOpened(config, widnow) {
    phoneLog.info('set phone opened ==>>> ', config.seq)

    this.opening_ids.delete(config.id)
    this.closing_ids.delete(config.id)
    this.opened_windows.set(config.id, widnow)
    this.opened_phone_configs.set(config.id, config)

    setPhoneBrowserOpened(config.id)
    phoneBrowserOpenOrClose({ id: config.id, openStatus: 1 })
  }

  /**
   * @description 设置已关闭的浏览器状态数据
   * @param {Object} config 浏览器配置
   * */
  async setBrowserClosed(config) {
    phoneLog.info('set phone closed ==>>> ')

    this.opening_ids.delete(config.id)
    this.opened_windows.delete(config.id)
    this.opened_phone_configs.delete(config.id)
    this.closing_ids.delete(config.id)

    if (this.keep_alive_configs.has(config.id)) {
      return
    }

    try {
      await phoneBrowserOpenOrClose({ id: config.id, openStatus: 0 })
    } catch (error) {
      phoneLog.info('set phone closed error==>>>  ', error)
    }
    setPhoneBrowserClosed(config.id)
  }

  /**
   * @description 是否正在打开
   * @param {String} phoneId 手机ID
   * @returns {Boolean}
   * */
  isOpening(phoneId) {
    return this.opening_ids.has(phoneId)
  }

  /**
   * @description 是否正在关闭
   * @param {String} phoneId 手机ID
   * @returns {Boolean}
   * */
  isClosing(phoneId) {
    return this.closing_ids.has(phoneId)
  }

  /**
   * @description 是否已打开
   * @param {String} phoneId 手机ID
   * @returns {Boolean}
   * */
  hasOpened(phoneId) {
    return this.opened_windows.has(phoneId)
  }

  /**
   * @description 获取已打开手机窗口对象
   * @param {String} phoneId
   * @returns {BrowserWindow} 返回 BrowserWindow 对象
   * */
  getWindow(phoneId) {
    return this.opened_windows.get(phoneId)
  }

  /**
   * @description 获取已打开的手机ID集合
   * @returns {Array<String>} 返回ids
   */
  getOpenedphoneIds() {
    return [...this.opened_phone_configs.keys(), ...this.keep_alive_configs.keys()]
  }

  getOpenedphoneConfigs() {
    return [...this.opened_phone_configs.values(), ...this.keep_alive_configs.values()]
  }

  // 获取已打开的窗口，只包含序号和id
  getOpenedBrowsersSeqs(desc = false) {
    let browsers = []
    for (let [key, value] of this.opened_phone_configs) {
      browsers.push({ seq: value.seq, phoneId: key })
    }
    return browsers.sort((a, b) => (desc ? b.seq - a.seq : a.seq - b.seq))
  }

  setQunkongPhoneConfig(phoneId, config) {
    this.keep_alive_configs.set(phoneId, config)
  }

  deleteQunkongPhoneId(phoneId) {
    this.keep_alive_configs.delete(phoneId)
  }

  getKeepAliveIds() {
    return [...this.keep_alive_configs.keys()]
  }
}

const phoneStatus = new PhoneWindowStatus()

export default phoneStatus
