import { ApiUtil } from '../interface/ApiUtil'
import { apiLog } from '../logs'

export function errorHandler() {
  return async (ctx, next) => {
    try {
      await next()
    } catch (err) {
      apiLog.error('api error ==>>> ', ctx.request.url, err.message, JSON.stringify(ctx.request.body))
      ctx.body = ApiUtil.fail(err.message)
    }
  }
}
