import { rimraf } from 'rimraf'
import log from 'electron-log/main'
import fs from 'fs-extra'
import { app } from 'electron'
import path from 'node:path'

log.transports.file.level = 'silly' // 最低级别，即所有日志都记录
log.transports.file.maxSize = 1048576 * 10 // 默认日志文件大小，10MB
const today = new Date()
log.transports.file.resolvePathFn = () =>
  path.join(app.getPath('logs'), `${today.getFullYear()}-${today.getMonth() + 1}-${today.getDate()}.log`)

// 删除多余的log文件，保留最近5条
async function clearHistoryLogs() {
  const logsPath = app.getPath('logs')
  try {
    const files = await fs.readdir(logsPath)
    const logs = files.filter(item => item.endsWith('.log'))
    logs.sort((a, b) => {
      return fs.statSync(path.join(logsPath, a)).mtime - fs.statSync(path.join(logsPath, b)).mtime
    })
    while (logs.length > 5) {
      const file = logs.shift()
      await rimraf(path.join(logsPath, file), { maxRetries: 5 })
    }
  } catch (err) {
    // log.info('logs error error ==>>> ')
    log.error(err)
  }
}

const apiLog = log.scope('local api')
const ossLog = log.scope('ali oss')
const statusLog = log.scope('browser status')
const chromeLog = log.scope('chrome exe')
const taskbarLog = log.scope('pin to task')
const syncTaskLog = log.scope('sync task')
const sshLogs = log.scope('ssh proxy logs')
const rpaLogs = log.scope('rpa')
const resumeLogs = log.scope('resume')
const firefoxLog = log.scope('firefox')
const phoneLog = log.scope('phone')
const extraLog = log.scope('extra logs')

export {
  log,
  apiLog,
  ossLog,
  statusLog,
  chromeLog,
  taskbarLog,
  syncTaskLog,
  sshLogs,
  rpaLogs,
  resumeLogs,
  clearHistoryLogs,
  firefoxLog,
  phoneLog,
  extraLog
}
