import fs from 'fs/promises'
import path from 'path'
import { getBrowserCacheDir, getCacheClearDays } from '../data/globalConfigs'
import { apiLog } from '../logs'
import { date } from 'quasar'

class BrowserCacheClear {
  constructor() {}

  // 按天数删除
  async clearByDays() {
    const days = await getCacheClearDays()
    apiLog.info('browser cache clear days ==>>> ', days)
    // 0天，不删除
    if (!days) return false
    try {
      const rootCachePath = await getBrowserCacheDir()
      let dirs = await fs.readdir(rootCachePath)
      dirs = dirs.filter(item => item.length === 32) // 找出文件名在32位的
      // 目标日期，这一天之前的全删除
      const targetDate = date.subtractFromDate(Date.now(), { days })
      while (dirs.length) {
        const pathName = path.join(rootCachePath, dirs.shift())
        const res = await fs.stat(pathName)
        if (Date.parse(res.mtime) > Date.parse(date.formatDate(targetDate, 'YYYY-MM-DD 00:00:00'))) continue
        apiLog.info('remove cache dir ==>>> ', pathName, date.formatDate(res.mtime, 'YYYY-MM-DD'))
        await fs.rm(pathName, { recursive: true, force: true })
      }
      return true
    } catch (err) {
      apiLog.error('cache dirs error ==>>> ', err)
      return false
    }
  }
}

const browserCacheClear = new BrowserCacheClear()

export default browserCacheClear
