import { getBrowserCacheDir, getLocalServerPort } from '../data/globalConfigs'
import genFingerprintFile, { genRpaFingerprintFile } from '../fingerprint'
import fs from 'fs-extra'
import path from 'path'
import { app, ipcMain } from 'electron'
import puppeteer from 'puppeteer-core'
import { getIpInfo, getUserInfo } from '../interface/request'
import { rpaLogs } from '../logs'
import chromeVersion from '../interface/Chrome'
import compressing from 'compressing'
import { setPreferencesExtensions } from '../browser'
import { getLocale } from '../interface/Messages'
import { getRpaFilesMd5, saveRpaFilesMd5 } from '../data/rpa'
import { sleep } from '../utils'
import { v4 as uid } from 'uuid'
import { getOssClient } from '../interface/OssUtils'
import { getExtensionRootPath } from '../extensions'
import { rimraf } from 'rimraf'
import { safeJsonParse } from '../utils/safeJsonParse'

const isMac = process.platform === 'darwin'

class RPAContainer {
  constructor() {
    this.versionInfo = {}
    this.automaPath = ''
    this.ossClient = null
    this.extensionId = ''
    this.browser = null
    this.pid = null
  }

  // 每次切换登录用户，都需要重新设置下id，扩展ID直接设置为用户ID
  async setExtensionId() {
    try {
      const userInfo = await getUserInfo()
      // rpaLogs.info('get userInfo ====>>>>>>>>> ', userInfo)
      this.extensionId = userInfo.id
    } catch (err) {
      rpaLogs.error('get userInfo error ==>>>> ', err)
      throw new Error('获取用户信息出错')
    }
  }

  async getAutomaPath() {
    if (this.automaPath) return this.automaPath

    try {
      await this.initOssClient()
      const { res, content } = await this.ossClient.get(process.env.DEBUGGING ? 'automa-test/version.json' : 'automa/version.json')
      if (res.status === 200) {
        this.versionInfo = safeJsonParse(content.toString(), 'getAutomaPath')
        rpaLogs.info('automa version info ==>>> ', this.versionInfo)

        const extensionRootPath = await getExtensionRootPath()
        this.automaPath = path.resolve(extensionRootPath, `${this.versionInfo.id}/${this.versionInfo.version}`)
      }
    } catch (err) {
      rpaLogs.error('get automa path error ==>>> ', err)
    }
    return this.automaPath
  }

  async initOssClient() {
    this.ossClient = await getOssClient({ bucket: 'browser-extend-hk' })
  }

  // 确保automa已ready
  async ensureAutomaBeReady() {
    await this.setExtensionId()
    await this.ensureAutomaExist()
    await this.ensureAutomaData()
  }

  // 确保扩展下载
  async ensureAutomaExist() {
    await this.getAutomaPath()
    if (!this.automaPath) throw new Error('RPA扩展下载失败')

    try {
      const exist = await fs.pathExists(this.automaPath)
      if (!exist) {
        await this.initOssClient()

        const rootPath = await getExtensionRootPath()

        const tempId = uid()
        const zipFile = `${rootPath}/${tempId}.zip`
        const { res } = await this.ossClient.get(`${process.env.DEBUGGING ? 'automa-test' : 'automa'}/${this.versionInfo.id}.zip`, zipFile)

        if (res.status !== 200) {
          throw new Error('oss downlaod automa error')
        }

        // 解压扩展文件
        await compressing.zip.uncompress(zipFile, rootPath)
        rimraf(zipFile, { maxRetries: 5 })
      }
    } catch (err) {
      rpaLogs.error('ensure automa extension error ==>>> ', err)
      throw new Error('RPA扩展同步失败')
    }
  }

  // 确保automa扩展数据存在，数据不存在，则直接同步服务端数据，数据存在，则判断是否要与服务端同步
  async ensureAutomaData() {
    try {
      const cacheDir = await getBrowserCacheDir(this.extensionId)
      const localESettings = path.join(cacheDir, 'Default/Local Extension Settings')
      const exists = await fs.pathExists(path.join(localESettings, this.versionInfo.id))

      rpaLogs.info('automa extension exists ===>>>>>> ', path.join(localESettings, this.versionInfo.id), exists)

      // 不存在则直接下载
      if (!exists) {
        await fs.ensureDir(localESettings)
        await this.syncDataFromOss()
      } else {
        const ossMd5 = await this.getRpaMd5OnOss()

        if (!ossMd5) return // 服务端不存在文件，则不同步

        // 本地的md5值与oss的不同，则下载oss文件
        const localMd5 = await getRpaFilesMd5()

        rpaLogs.info('ossMd5 ====>>>>>>> ', ossMd5, ' local md5 ==>>>>>>>> ', localMd5)

        if (ossMd5 !== localMd5) await this.syncDataFromOss(true)
      }
    } catch (err) {
      rpaLogs.error('ensure automa extension data error ==>>>> ', err)
      // 如果是因为压缩文件解压失败，则不抛出错误
      if (err.message.includes('ZipUncompressStreamError')) {
        return
      }
      throw new Error('RPA扩展数据同步失败')
    }
  }

  // 获取OSS存储的当前数据的MD5值，不存在则返回null
  async getRpaMd5OnOss() {
    try {
      await this.initOssClient()
      const { res } = await this.ossClient.head(`automa-data/${this.extensionId}/${this.versionInfo.id}.zip`)
      if (res.status === 200) {
        return res.headers['content-md5']
      }
    } catch (err) {
      rpaLogs.error('get automa-data oss md5 error ==>>> ', err.message)
    }
    return null
  }

  // 判断oss是否存在当前扩展数据，有md5值，则证明存在
  async isOssHas() {
    try {
      const md5 = await this.getRpaMd5OnOss()
      return !!md5
    } catch (err) {}
    return false
  }

  // 从oss下载automa数据，默认不存在oss文件，直接下载oss文件时，传入true
  async syncDataFromOss(hasOwn = false) {
    if (!hasOwn) {
      hasOwn = await this.isOssHas()
    }

    const cacheDir = await getBrowserCacheDir(this.extensionId)
    const localESettings = path.join(cacheDir, 'Default/Local Extension Settings')
    const targetDir = path.join(localESettings, this.versionInfo.id)
    const tempDir = path.join(localESettings, `${this.versionInfo.id}_temp_${uid()}`)
    const zipFile = `${localESettings}/${uid()}.zip`

    let sourceZip = hasOwn
      ? `automa-data/${this.extensionId}/${this.versionInfo.id}.zip`
      : `automa/Local Extension Settings/${this.versionInfo.id}.zip`

    try {
      // 下载zip文件
      const { res } = await this.ossClient.get(sourceZip, zipFile)
      if (res.status !== 200) {
        throw new Error('同步rpa扩展数据出错')
      }

      // 如果目标目录存在，先重命名为临时目录
      const targetExists = await fs.pathExists(targetDir)
      if (targetExists) {
        await fs.move(targetDir, tempDir)
      }

      // 解压zip文件
      await compressing.zip.uncompress(zipFile, localESettings)
      // 解压成功后，删除临时目录和zip文件
      if (targetExists) {
        await rimraf(tempDir, { maxRetries: 5 })
      }
    } catch (error) {
      // 如果解压失败，恢复原来的目录
      if (await fs.pathExists(tempDir)) {
        if (await fs.pathExists(targetDir)) {
          await rimraf(targetDir, { maxRetries: 5 })
        }
        await fs.move(tempDir, targetDir)
      }

      throw error
    } finally {
      // 清理zip文件
      if (await fs.pathExists(zipFile)) {
        await rimraf(zipFile, { maxRetries: 5 })
      }
    }
  }

  // 上传automa数据到oss
  async uploadDataToOss() {
    const ossPath = `automa-data/${this.extensionId}/${this.versionInfo.id}.zip`
    const cacheDir = await getBrowserCacheDir(this.extensionId)
    const automaPath = path.resolve(cacheDir, 'Default/Local Extension Settings', this.versionInfo.id)
    const zipFile = path.resolve(cacheDir, `Default/Local Extension Settings/${this.versionInfo.id}.zip`)

    try {
      await compressing.zip.compressDir(automaPath, zipFile) // 先压缩zip
      await this.initOssClient()
      const { res } = await this.ossClient.put(ossPath, zipFile)
      if (res.status === 200) {
        const md5 = res.headers['content-md5']
        saveRpaFilesMd5(md5)
        rimraf(zipFile, { maxRetries: 5 })
      }
    } catch (err) {
      rpaLogs.error('upload error ==>>>> ', err)
    }
  }

  // 复制rpa扩展数据到目标浏览器窗口里
  async copyAutomaData(targetId) {
    try {
      await this.ensureAutomaBeReady()

      const rpaBrowserPath = await getBrowserCacheDir(this.extensionId)
      const targetPath = await getBrowserCacheDir(targetId)

      // 删掉已有的，防止冲突
      await fs.ensureDir(path.resolve(targetPath, 'Default/Local Extension Settings', this.versionInfo.id))
      await fs.emptyDir(path.resolve(targetPath, 'Default/Local Extension Settings', this.versionInfo.id))

      await fs.copy(
        path.resolve(rpaBrowserPath, 'Default/Local Extension Settings', this.versionInfo.id),
        path.resolve(targetPath, 'Default/Local Extension Settings', this.versionInfo.id)
      )

      await setPreferencesExtensions(targetId, [this.versionInfo.id])

      rpaLogs.info('copy automa success and continue ==>>>> ')
    } catch (err) {
      rpaLogs.error('copy automa data error ==>>>> ', err)
    }
  }

  // 打开automa dashboard
  async openDashboard(coreVersion) {
    await this.ensureAutomaBeReady()

    const config = {
      id: this.extensionId
    }

    const browserCacheDir = await getBrowserCacheDir(config.id)
    rpaLogs.info('browserCacheDir ==>>> ', browserCacheDir)
    try {
      await fs.ensureDir(browserCacheDir) // 确保缓存文件夹创建
      await genRpaFingerprintFile(config)
      await setPreferencesExtensions(config.id, [this.versionInfo.id])
    } catch (e) {
      throw new Error(e.message)
    }

    const port = await getLocalServerPort()
    const locale = getLocale()

    // 组合指纹信息生成浏览器args，合并传入的参数
    let args = [
      '--no-default-browser-check',
      '--window-position=0,0',
      '--disable-background-mode',
      `--window-size=1280,760`,
      '--fingerprint-config=' + path.resolve(app.getPath('userData'), 'LocalCache', config.id),
      `--load-extension=` + this.automaPath,
      '--disable-blink-features=AutomationControlled',
      '--ignore-certificate-errors',
      `http://127.0.0.1:${port}/rpa.html?locale=${locale}`
    ]

    try {
      try {
        // 确保exe文件存在
        const chromeExists = await chromeVersion.checkExeExists(coreVersion)
        if (!chromeExists) {
          await chromeVersion.ensureChromeBeReady(coreVersion)
        }
      } catch (err) {
        throw new Error('内核更新失败，请重新启动客户端再打开')
      }
      const chromePath = await chromeVersion.getExePath(coreVersion)

      const browser = await puppeteer.launch({
        executablePath: chromePath,
        userDataDir: browserCacheDir,
        headless: false,
        defaultViewport: null,
        timeout: 50000,
        args,
        waitForInitialPage: true,
        ignoreDefaultArgs: [
          '--disable-background-networking',
          '--enable-features=NetworkService,NetworkServiceInProcess',
          '--disable-background-timer-throttling',
          '--disable-backgrounding-occluded-windows',
          '--disable-breakpad',
          '--disable-client-side-phishing-detection',
          '--disable-component-extensions-with-background-pages',
          '--disable-default-apps',
          '--disable-dev-shm-usage',
          '--disable-extensions',
          '--disable-features=Translate,BackForwardCache,AvoidUnnecessaryBeforeUnloadCheckSync',
          '--disable-hang-monitor',
          '--disable-ipc-flooding-protection',
          '--disable-renderer-backgrounding',
          '--disable-sync',
          '--enable-automation'
        ],
        devtools: false
      })

      this.browser = browser
      this.pid = browser.process().pid

      browser.on('targetdestroyed', async target => {
        try {
          const pages = await browser.pages()
          if (pages.length === 0) {
            if (process.platform === 'win32') {
              await sleep(1)
            }
            await browser.close()
            this.browser = null
            this.pid = null

            await sleep(1)
            this.uploadDataToOss()
          }
        } catch (err) {
          rpaLogs.error('targetdestroyed error => ' + err.message)
        }
      })

      // 初次打开时，需要借助popup.html来打开rpa
      try {
        const targets = browser.targets()

        targets.forEach(t => {
          rpaLogs.info('target t ==>>> ', t.url(), t.type())
        })
        const target = targets.find(t => t.url() && t.url().includes(this.versionInfo.id))

        let page
        if (!target) {
          page = await browser.newPage()
          await page.goto(`chrome-extension://${this.versionInfo.id}/popup.html#/`, { waitUntil: 'domcontentloaded' })
        } else {
          page = await target.page()
          // 等待页面主框架就绪
          if (page) {
            let retries = 10
            while (retries > 0) {
              try {
                page.mainFrame()
                break // 主框架已就绪
              } catch (e) {
                retries--
                if (retries === 0) {
                  throw new Error('Page main frame not ready after waiting')
                }
                await sleep(200) // 等待100ms后重试
              }
            }
          }
        }

        const settings = await evaluateWithTimeout(
          page.evaluate(`() => {
            return new Promise(resolve => {
              chrome.storage.local.get('settings', result => resolve(result))
            })
          }`),
          1000
        )

        let newSettings = settings.settings || {}
        newSettings.locale = getLocale()
        if (newSettings.locale === 'ru') {
          newSettings.locale = 'en'
        }

        // 设置automa语言配置
        await evaluateWithTimeout(page.evaluate(`chrome.storage.local.set({settings: ${JSON.stringify(newSettings)}})`), 1000)

        await evaluateWithTimeout(
          page.evaluate(
            `chrome.windows.create({"url": "chrome-extension://${this.versionInfo.id}/newtab.html#", "width": 1300, "height": 800, "type": "popup"})`
          ),
          1000
        )

        if (page.url().includes('popup.html')) {
          page.close()
        }
      } catch (err) {
        rpaLogs.error('open automa dashboard error ==>>>> ', err)
      }
    } catch (err) {
      rpaLogs.error('launch rpa browser error ===>>>> ', err)
      throw new Error('打开浏览器失败')
    }
  }

  async closeDashboard() {
    try {
      rpaLogs.info('close rpa dashboard ==>>>> ', this.browser)
      if (!this.browser) return
      const pages = await this.browser.pages()
      await Promise.all(pages.map(page => page.close()))
    } catch (err) {
      rpaLogs.error('close automa dashboard error ==>>>> ', err)
    }
  }
}

// 用于超时处理，page.evaluate 可能一直pending
function evaluateWithTimeout(evaluateFn, timeout, defaultValue = {}) {
  return Promise.race([evaluateFn, new Promise(resolve => setTimeout(() => resolve(defaultValue), timeout))])
}

const rpaContainer = new RPAContainer()

ipcMain.on('save-browser-cache-dir', () => {
  rpaContainer.automaPath = ''
  rpaContainer.getAutomaPath()
})

export default rpaContainer
