import { getChromeLangs, saveLangToDB } from '../data/cacheData'
import { getOssClient, getOssFileMd5, getOssObject } from '../interface/OssUtils'
import { apiLog } from '../logs'
import { safeJsonParse } from '../utils/safeJsonParse'

let langFileMd5 = ''
const OSSBucket = 'browser-fingerprint-assets'

/**
@description
参照 Chrome 的语言映射规则. 成功匹配返回 Chrome 支持的语言及 accept_languages.
否则返回 undefined, 使用自定义值或按 en-US 处理.
 */
export async function resolveLang(langTag) {
  if (!langTag) return { lang: 'en-US', accept_languages: 'en-US' }

  const chromeLangs = await getChromeLangs()

  // 如果chromeLangs为空，则使用自定义值
  if (!chromeLangs.length) return { lang: langTag?.split(',')[0]?.trim(), accept_languages: langTag }

  // 如果langTag包含多个语言，则使用第一个语言匹配
  let targetLang = langTag
  if (langTag.includes(',')) {
    const langs = langTag.split(',')
    targetLang = langs[0]
  }

  // 先使用完整语言找出匹配项目，如果找到，则返回
  const targetItem = chromeLangs.find(item => item.lang.toLowerCase() == targetLang.toLowerCase())
  if (targetItem) return targetItem

  // 如果没找到，则使用语言和地区匹配
  const [lang, region] = targetLang.split('-').map(item => item.toLowerCase())
  let tmp_lang = lang

  if (lang == 'es' && region != 'es') {
    tmp_lang = 'es-419' // es-MX
  } else if (lang == 'pt' && region != 'br') {
    tmp_lang = 'pt-PT'
  } else if (lang == 'zh') {
    if (region == 'hk' || region == 'mo') {
      tmp_lang = 'zh-TW'
    } else {
      tmp_lang = 'zh-CN'
    }
  } else if (lang == 'en') {
    if (region == 'lr' || region == 'ph') {
      tmp_lang = 'en-US'
    } else {
      tmp_lang = 'en-GB'
    }
  }

  // 找出匹配项目，如果找到，则返回
  const item = chromeLangs.find(item => item.lang.toLowerCase() == tmp_lang)
  if (item) return item

  // 如果都没匹配到，那么返回自定义值，lang只能有一个，accept_languages保持不变，可以为多个值，逗号分隔
  return { lang: targetLang, accept_languages: langTag }
}

/**
 * @description 获取oss存储的webgl文件的md5
 * */
export async function getLangFileMd5() {
  if (langFileMd5) {
    return langFileMd5
  }

  const client = await getOssClient({ bucket: OSSBucket })
  const md5 = await getOssFileMd5(client, `lang/chromeLangs.json`)
  if (md5) {
    langFileMd5 = md5
  }
  return md5
}

export async function getLatestLangData() {
  try {
    const client = await getOssClient({ bucket: OSSBucket })
    const result = await getOssObject(client, `lang/chromeLangs.json`)
    if (result) {
      await saveLangToDB({ dataValue: safeJsonParse(result, 'getLatestLangData') })
    }
  } catch (err) {
    apiLog.error('getLatestLang error ==>>> ', err)
  }
}
