import OSS from 'ali-oss'
import crypto from 'crypto'
import { saveSyncLogs, findLocalOssMd5 } from '../data/syncOssLogs'
import { getOssAccessInfo, getOssEndpoint } from './request'
import { sleep } from '../utils'
import { ossLog } from '../logs'
import dayjs from 'dayjs'

// 为每个bucket单独创建client，并缓存起来
const ClientMap = new Map()

// 正在实例化的bucket
const PendingBucket = new Set()

// 缓存的oss accessInfo
let accessInfo = { accessKeyId: null, accessKeySecret: null, stsToken: null, expiration: null }

// 重试次数
class RetryTimes {
  constructor() {
    this.store = new Map()
    this.maxTimes = 5

    this.Names = {
      PutObject: 'put-object',
      DownloadObject: 'download-object',
      HeadObject: 'head-object',
      DelObject: 'del-object',
      CopyObject: 'copy-object',
      MultipartUpload: 'multipartUpload',
      GetObject: 'get-object'
    }
  }

  increase(name) {
    if (!this.store.has(name)) {
      this.store.set(name, 0)
    } else {
      this.store.set(name, this.store.get(name) + 1)
    }
  }

  valid(name) {
    return !this.store.has(name) || this.store.get(name) < this.maxTimes
  }

  reset(name) {
    this.store.delete(name)
  }
}

const retryTimes = new RetryTimes()

/**
 * @description 获取指定bucket的oss client，有则直接返回，无则创建后返回
 * @param {object} param
 * @param {string} param.bucket oss bucket
 * @param {string} endpoint oss 连接endpoint，不传时，默认取 userInfo 的 endpoint
 * @param {string} region oss region，默认 oss-cn-hongkong
 * @returns {Promise<OSS>} 返回 new OSS({...options})
 */
export async function getOssClient({ bucket = '', endpoint = '', region = 'oss-cn-hongkong' }) {
  if (PendingBucket.has(bucket)) {
    ossLog.info('bucket is pending, wait 1 second >>>>> ', bucket)
    await sleep(1) // 如果bucket正在创建，等待1秒即可
    return getOssClient({ bucket, endpoint, region })
  }
  // 添加到Pending里
  PendingBucket.add(bucket)

  // 如果已经有该 bucket 的 OSS client，并且 stsTokenExpiration（STS临时凭证的过期时间）存在，
  // 并且当前时间距离过期时间还有超过1分钟，则直接复用已存在的 client。
  // 之所以加1分钟，是为了避免 token 即将过期时刚好被使用，导致后续请求因 token 失效而失败。
  // 预留1分钟的缓冲时间，可以减少 token 过期带来的异常。
  // 这么修改，是因为 ali-oss 的 refreshSTSToken 方法，可能存在异步问题，导致获取到过期的缓存token
  if (ClientMap.has(bucket) && accessInfo.expiration && dayjs(accessInfo.expiration).isAfter(dayjs().add(1, 'minute'))) {
    PendingBucket.delete(bucket)
    return ClientMap.get(bucket)
  }

  // 如果 accessInfo 有效期不足1分钟，则重新获取
  // eg: 比如长时间未使用，或者token过期了
  if (!accessInfo.expiration || dayjs(accessInfo.expiration).isBefore(dayjs().add(1, 'minute'))) {
    accessInfo = await getOssAccessInfo()
  }

  if (!endpoint) {
    endpoint = await getOssEndpoint()
  }

  const client = new OSS({
    region,
    accessKeyId: accessInfo.accessKeyId,
    accessKeySecret: accessInfo.accessKeySecret,
    bucket,
    endpoint,
    secure: false,
    stsToken: accessInfo.stsToken,
    refreshSTSToken: async () => {
      accessInfo = await getOssAccessInfo()
      return accessInfo
    },
    refreshSTSTokenInterval: 1000 * 60 * 13 // 13分钟刷新一次
  })

  ClientMap.set(bucket, client)

  PendingBucket.delete(bucket)

  return client
}

// 上传文件到oss，logId一般为 browserId，删除日志时，可以直接删除browserId对应的所有日志
export async function putObject(client, ossPath, filename, logId) {
  try {
    const { res } = await client.put(ossPath, filename)

    if (res.status !== 200) {
      throw new Error('上传服务器失败')
    }

    // 存上传日志
    if (!logId) return

    const pathMd5 = crypto.createHash('md5').update(ossPath).digest('hex')
    saveSyncLogs(logId, pathMd5, res.headers['content-md5'])

    retryTimes.reset(retryTimes.Names.PutObject)
  } catch (err) {
    if (err.message.includes('403') && retryTimes.valid(retryTimes.Names.PutObject)) {
      ossLog.info('403 error ==>>>> ', err.message)
      await sleep(1)
      retryTimes.increase(retryTimes.Names.PutObject)
      await putObject(client, ossPath, filename, logId)
    }
    throw err
  }
}

/**
 * @description 切片上传oss file，切片的文件不存在content-md5，使用etag
 * @param {OSS} client oss client
 * @param {string} ossPath oss file path
 * @param {string} filename filename
 * @param {string} logId 记录本地的logId
 */
export async function multipartUpload(client, ossPath, filename, logId) {
  try {
    const { res } = await client.multipartUpload(ossPath, filename, {
      checkpoint: true
    })
    if (res.status !== 200) {
      throw new Error('上传服务器失败')
    }

    // 存上传日志
    if (!logId) return res

    const pathMd5 = crypto.createHash('md5').update(ossPath).digest('hex')
    let ossMd5 = res.headers['content-md5'] || res.headers['etag']
    saveSyncLogs(logId, pathMd5, ossMd5)
    retryTimes.reset(retryTimes.Names.MultipartUpload)

    return res
  } catch (err) {
    if (err.message.includes('403') && retryTimes.valid(retryTimes.Names.MultipartUpload)) {
      ossLog.info('403 error ==>>>> ', err.message)
      await sleep(1)
      retryTimes.increase(retryTimes.Names.MultipartUpload)
      await multipartUpload(client, ossPath, filename, logId)
    }
    throw err
  }
}

// 从oss下载文件
export async function downloadObject(client, ossPath, filename) {
  try {
    const { res } = await client.get(ossPath, filename)
    if (res.status !== 200) {
      throw new Error('download file from oss error')
    }

    retryTimes.reset(retryTimes.Names.DownloadObject)
  } catch (err) {
    if (err.message.includes('403') && retryTimes.valid(retryTimes.Names.DownloadObject)) {
      ossLog.info('403 error ==>>>> ', err.message)
      await sleep(1)

      retryTimes.increase(retryTimes.Names.DownloadObject)
      await downloadObject(client, ossPath, filename)
    }
    throw err
  }
}

/**
 * @description 获取oss对象的内容
 * @param {OSS} client oss client
 * @param {string} ossPath oss file path
 * */
export async function getOssObject(client, ossPath) {
  try {
    const { res, content } = await client.get(ossPath)
    if (res.status !== 200) {
      throw new Error('get oss object error')
    }

    retryTimes.reset(retryTimes.Names.GetObject)

    return content.toString()
  } catch (err) {
    if (err.message.includes('403') && retryTimes.valid(retryTimes.Names.GetObject)) {
      ossLog.info('403 error ==>>>> ', err.message)
      await sleep(1)

      retryTimes.increase(retryTimes.Names.GetObject)
      return getOssObject(client, ossPath)
    }
  }

  return null
}

/**
 * @description 获取oss云端文件的MD5或者etag，分片上传的文件，不存在md5，只有etag
 * @param {OSS} client oss client
 * @param {String} ossPath oss文件路径
 * @returns {Promise<String>} md5 | etag | null
 * */
export async function getOssFileMd5(client, ossPath) {
  try {
    const { res } = await client.head(ossPath)
    if (res.status === 200) {
      retryTimes.reset(retryTimes.Names.HeadObject)

      // ossLog.info('res.headers ==>>> ', res.headers)

      return res.headers['content-md5'] || res.headers['etag']
    }
  } catch (err) {
    if (err.message.includes('403') && retryTimes.valid(retryTimes.Names.HeadObject)) {
      ossLog.info('403 error ==>>>> ', err.message)
      await sleep(1)

      retryTimes.increase(retryTimes.Names.HeadObject)
      return getOssFileMd5(client, ossPath)
    }
    ossLog.error('get oss file md5 error ==>>> ', err.message, ossPath)
  }
  return null
}

/**
 * @description 判断是否需要同步oss文件，出错时，默认返回true，需要同步
 * @returns {Promise<Boolean>} true | false
 * @param {OSS} client oss client
 * @param {String} ossPath oss文件路径
 * */
export async function isNeedSync(client, ossPath) {
  try {
    const ossMd5 = await getOssFileMd5(client, ossPath)
    const localMd5 = await findLocalOssMd5(crypto.createHash('md5').update(ossPath).digest('hex'))

    return ossMd5 !== null && ossMd5 !== localMd5
  } catch (err) {
    ossLog.error('check if need sync from oss error ==>>>> ', err)
  }
  return true
}

/**
 * @description 判断传入的md5与本地存储的md5是否相同
 * @returns {Promise<Boolean>} true | false
 * @param {String} md5 oss文件md5
 * @param {String} pathname oss文件路径
 * */
export async function diffMd5FromLocal(md5, pathname) {
  try {
    const localMd5 = await findLocalOssMd5(crypto.createHash('md5').update(pathname).digest('hex'))

    return md5 !== localMd5
  } catch (err) {
    ossLog.error('check if need sync from oss error ==>>>> ', err)
  }
  return true
}

// 从oss删除文件
export async function deleteOssObject(client, ossPath) {
  try {
    await client.delete(ossPath)

    retryTimes.reset(retryTimes.Names.DelObject)
  } catch (error) {
    if (err.message.includes('403') && retryTimes.valid(retryTimes.Names.DelObject)) {
      ossLog.info('403 error ==>>>> ', err.message)
      await sleep(1)

      retryTimes.increase(retryTimes.Names.DelObject)
      await deleteOssObject(client, ossPath)
    }
    throw error
  }
}

// 复制Object
export async function copyOssObject(client, toPath, fromPath) {
  try {
    const { res } = await client.copy(toPath, fromPath)
    if (res.status !== 200) {
      throw new Error('跨窗口上传失败')
    }

    retryTimes.reset(retryTimes.Names.CopyObject)
  } catch (err) {
    if (err.message.includes('403') && retryTimes.valid(retryTimes.Names.CopyObject)) {
      ossLog.info('403 error ==>>>> ', err.message)
      await sleep(1)

      retryTimes.increase(retryTimes.Names.CopyObject)
      await copyOssObject(client, toPath, fromPath)
    }
    throw err
  }
}
