import { messages } from '../interface/Messages'
import { getLocalApiConcurrent, getPhoneApiConcurrent } from '../interface/request'
import { apiLog } from '../logs'
import { hrtime } from 'node:process'

const whiteList = [
  '/browser/close',
  '/utils/blockedCNDomains',
  '/phone/close',
  '/phone/open',
  '/phone/reconnect',
  '/phone/close/all',
  '/phone/setAlwaysOnTop',
  '/phone/isAlwaysOnTop',
  '/phone/opened/ids',
  '/phone/bounds',
  '/phone/minimize',
  '/phone/reloadurl',
  '/phone/close/keep/state',
  '/phone/qunkong/close'
]

const Duration = 1e9 // 1秒 = 1_000_000_000 纳秒

// 请求限流，云手机限流1秒一次
export function rateLimit() {
  let concurrent = 11 // 一秒最大并发，从字典请求，客户端内默认11秒，如果每次请求字典值都是11，说明是字典没有请求到，取了默认值
  let count = 0 // 请求次数

  let start = hrtime.bigint()

  return async (ctx, next) => {
    apiLog.info('request url ==>>>> ', ctx.request.url, 'isDeveloper:', ctx.isDeveloper, 'isPhone:', ctx.isPhone)
    if (!ctx.isDeveloper || whiteList.includes(ctx.request.url) || ctx.request.method === 'GET') {
      await next()
    } else {
      if (concurrent === 11) {
        concurrent = await getLocalApiConcurrent(concurrent)
      }

      const end = hrtime.bigint()
      // 间隔大于1秒，直接放行
      if (end - start >= Duration) {
        start = end
        count = 1
        await next()
      } else {
        count++
        // 小于并发数，记录请求次数，放行
        if (count <= concurrent) {
          await next()
        } else {
          ctx.status = 429
          const msg = messages.getMessage('tooFrequent', concurrent)
          apiLog.error(ctx.request.url, msg)
          ctx.throw(ctx.status, msg, { total: concurrent })
        }
      }
    }
  }
}

// 云手机，限制并发1次
export function phoneApiRateLimit() {
  let concurrent = 2 // 一秒最大并发，从字典请求，客户端内默认11秒，如果每次请求字典值都是11，说明是字典没有请求到，取了默认值
  let count = 0 // 请求次数

  let start = hrtime.bigint()

  return async (ctx, next) => {
    apiLog.info('phone request url ==>>>> ', ctx.request.url, 'isDeveloper:', ctx.isDeveloper, 'isPhone:', ctx.isPhone)

    // 云手机并发限制
    if (!ctx.isPhone || whiteList.includes(ctx.request.url) || ctx.request.method === 'GET') {
      await next()
    } else {
      if (concurrent === 2) {
        concurrent = await getPhoneApiConcurrent(1)
      }

      const end = hrtime.bigint()
      // 间隔大于1秒，直接放行
      if (end - start >= Duration) {
        start = end
        count = 1
        await next()
      } else {
        count++
        // 小于并发数，记录请求次数，放行
        if (count <= concurrent) {
          await next()
        } else {
          ctx.status = 429
          const msg = messages.getMessage('tooFrequentForPhone', concurrent)
          apiLog.error('phone api concurrent error ==>>> ', msg)
          ctx.throw(ctx.status, msg, { total: concurrent })
        }
      }
    }
  }
}
