import { messages } from '../interface/Messages'

// 必传参数中间件
export function paramRequired(param) {
  return async (ctx, next) => {
    const body = ctx.request.body
    if (!body[param] || body[param].length !== 32) {
      throw new Error(messages.getMessage('InvalidID'))
    } else {
      await next()
    }
  }
}
