// 创建一个辅助窗口，用于loading以及打开外部链接等，一直缓存，供下一次使用
async function createAssistantWindow(isLoading, externalUrl) {
  log.info('isLoading ==>> ' + isLoading)
  log.info(externalUrl)
  assistantWindow = new BrowserWindow({
    icon: process.env.DEV ? path.resolve(__dirname, '../configs/bitbrowser/icon.ico') : path.resolve(app.getPath('exe'), './icon.ico'), // tray icon
    width: isLoading ? 400 : 1220,
    height: isLoading ? 300 : 840,
    show: false,
    autoHideMenuBar: true,
    useContentSize: true,
    maximizable: false,
    resizable: !isLoading,
    frame: !isLoading,
    title: '',
    webPreferences: {
      contextIsolation: true,
      sandbox: false,
      preload: path.resolve(__dirname, process.env.QUASAR_ELECTRON_PRELOAD)
    }
  })

  // 关闭时删掉缓存
  assistantWindow.on('close', () => {
    // 如果是loading界面一直加载，且未加载完主窗口时，直接退出软件
    if (isLoading && !mainWindowLoaded) {
      app.exit()
    }
    if (externalUrl) {
      cachedAssistantWindow.delete(externalUrl)
      openingExternalUrls.delete(externalUrl)
    }
  })
  assistantWindow.once('ready-to-show', async () => {
    const toTrayAtLaunch = await isToTrayAtLaunch()
    if (!toTrayAtLaunch) {
      assistantWindow.show()
    }
    openingExternalUrls.delete(externalUrl)
  })

  if (isLoading) {
    assistantWindow.setSize(400, 300)
    assistantWindow.center()
    const loadingHtml = await getLoadingHtml()
    await assistantWindow.loadFile(path.resolve(__dirname, process.env.QUASAR_PUBLIC_FOLDER, loadingHtml))
  } else {
    // 有已打开的外部链接窗口，直接显示
    if (cachedAssistantWindow.has(externalUrl)) {
      cachedAssistantWindow.get(externalUrl).focus()
      cachedAssistantWindow.get(externalUrl).restore()
      openingExternalUrls.delete(externalUrl)
    } else {
      cachedAssistantWindow.set(externalUrl, assistantWindow)
      await assistantWindow.loadURL(externalUrl)
      assistantWindow.show()
    }
  }
}

// 创建主窗口，首先隐藏，待页面内容渲染出来的时候，再显示
async function createMainWindow() {
  mainWindow = new BrowserWindow({
    icon: process.env.DEV ? path.resolve(__dirname, '../configs/bitbrowser/icon.ico') : path.resolve(app.getPath('exe'), './icon.ico'), // tray icon
    width: 1280,
    height: 770,
    minWidth: 700,
    minHeight: 400,
    useContentSize: true,
    show: false,
    frame: false,
    backgroundColor: '#fff',
    webPreferences: {
      contextIsolation: true,
      sandbox: false,
      // More info: /quasar-cli/developing-electron-apps/electron-preload-script
      preload: path.resolve(__dirname, process.env.QUASAR_ELECTRON_PRELOAD),
      minimumFontSize: 12
    }
  })

  mainWindow.on('session-end', () => {
    log.info('main window session end')
  })

  const webUrl = getMainwindowUrl()
  log.info('loading web url ===>>> ' + webUrl)
  mainWindow
    .loadURL(webUrl)
    .then(async () => {
      // 如果已是登录状态，获取一次用户信息，防止使用群控时并且开启了API鉴权，无法获取token
      if (process.env.DEV) return
      const token = await getAppToken()
      if (!token) return

      getUserInfo()
      // 设置 Sentry 用户信息
      await setSentryUser()
    })
    .catch(err => {
      log.info('load url error ==>>> ', err.message)
    })

  // if (process.env.DEBUGGING) {
  //   // if on DEV or Production with debug enabled
  //   mainWindow.webContents.openDevTools()
  // } else {
  //   // we're on production; no access to devtools pls
  //   mainWindow.webContents.on('devtools-opened', () => {
  //     mainWindow.webContents.closeDevTools()
  //   })
  // }

  mainWindow.on('close', e => {
    log.info('stop window close')
    e.preventDefault()
    if (mainWindow) {
      mainWindow.webContents.send('mainwindow-close')
      mainWindow.show()
    }
  })

  mainWindow.on('closed', () => {
    mainWindow = null
  })

  mainWindow.once('ready-to-show', () => {
    log.info('ready to show main window')
    // mainWindow.show()
  })
}

export function focusMainWindow() {
  try {
    if (!mainWindow) return

    if (mainWindow.isMinimized()) mainWindow.restore()

    mainWindow.show()
    mainWindow.focus()
  } catch (err) {
    log.error('focus main window error ===>>> ', err)
  }
}

