// 退出软件时，关掉所有浏览器
app.on('before-quit', async e => {
  log.info('before app quit ===>>>>> ', process.pid)
  // mac 自动退出node主进程有bug，直接kill掉
  if (process.env.DEV && process.platform === 'darwin') {
    process.kill(process.pid)
  }
  e.preventDefault()
  await closeAllBrowsers()
  await closeLocalServer()
  app.exit()
})

