// 从睡眠唤起
powerMonitor.on('resume', async () => {
  wakeup()

  // 检查数据库连接健康状态
  try {
    const { healthy } = await healthCheck()
    if (!healthy) {
      log.warn('Database unhealthy after system resume, resetting connection...')
      await reset()
      await connectDatabase()
      log.info('Database connection restored after reset')
    } else {
      log.info('Database health check passed after system resume')
    }
  } catch (err) {
    log.error('Failed to check database health after resume:', err)
  }
})

