ipcMain.handle('proxy-request', async (e, options) => {
  try {
    // 根据系统代理配置使用
    const sysPort = await getSysProxyPort()
    if (sysPort) {
      options.httpAgent = options.httpsAgent = getHttpAgent('127.0.0.1', sysPort, '', '')
    } else if (getNeedsSystemCertificates()) {
      options.httpsAgent = https.globalAgent
    }

    const res = await axios(options)
    if (res.status === 200) {
      return res.data
    } else {
      return null
    }
  } catch (err) {
    log.error('proxy request error ==>>> ', err)
    return Promise.reject(err.message)
  }
})

