// 先去本地库里的token，没有则获取cookie里的TOKEN，几个版本后，可以删掉从cookie里取token的逻辑
export async function getAppToken() {
  const appToken = await getAppTokenFromDB()
  if (appToken) return appToken

  // TODO 几个版本后删掉，当前 7.0.9
  const url = new URL(getMainwindowUrl())
  const tokens = await session.defaultSession.cookies.get({ name: 'BITBROWSER_TOKEN', domain: url.hostname })
  if (!tokens.length) return null
  return tokens[0].value
}

