// 切换线路时，重新加载主框架url
function reloadMainwindow() {
  if (!mainWindow) return
  const webUrl = globalSetting.getWebUrl(messages.getLocale())
  mainWindow
    .loadURL(webUrl)
    .then(async () => {
      log.info('web url loaded ===>>> ' + webUrl)
      await killExistBrowsers()
    })
    .catch(err => {
      log.info('load web url error ==>>> ', err.message)
    })
}

