function showMainWindow() {
  if (!mainWindowLoaded) {
    assistantWindow.show()
  } else {
    mainWindow.show()
  }
}

function initialTray() {
  if (process.platform !== 'win32') return // 只给windows设置

  tray = new Tray(
    process.env.DEV ? path.resolve(__dirname, '../configs/bitbrowser/icon.png') : path.resolve(app.getPath('exe'), '../icon.ico')
  )

  const contextMenu = Menu.buildFromTemplate([
    {
      label: messages.getMessage('ShowMainWindow'),
      type: 'normal',
      click: () => {
        showMainWindow()
      }
    },
    {
      label: messages.getMessage('Exit'),
      type: 'normal',
      click: () => {
        app.exit()
      }
    }
  ])

  tray.setContextMenu(contextMenu)
  tray.setToolTip('BitBrowser')

  tray.on('click', e => {
    showMainWindow()
  })
}

async function getLoadingHtml() {
  const locale = await getLocaleFromDB()
  let obj = {
    en: 'bitLoadingEn.html',
    zh: 'bitLoading.html',
    ru: 'bitLoadingRu.html'
  }

  return obj[locale] || obj.en
}

// 处理英文版，如果是英文版的，没打开过，则直接设置本地语言为en
async function dealwithEnLocale() {
  try {
    const hasLocale = await hasLocaleConfig()
    if (hasLocale) return

    const sysLocale = app.getLocale()
    let appLocale = 'en'

    if (sysLocale.startsWith('zh')) {
      appLocale = 'zh'
    } else if (sysLocale.startsWith('ru')) {
      appLocale = 'ru'
    }

    await saveLocaleToDB(appLocale)
    messages.setLocale(appLocale)
  } catch (err) {
    log.error('set en locale first run error ==>> ', err)
  }
}

function getMainwindowUrl() {
  return process.env.DEV ? process.env.DEV_URL || process.env.APP_URL : globalSetting.getWebUrl(messages.getLocale())
}
