import { getCACertificates } from 'node:tls'
import { globalAgent } from 'https'
import { log } from '../logs'
import https from 'https'

// 标记是否存在证书问题（需要使用系统证书）
let needsSystemCertificates = false

// 导出 getter 函数，确保每次调用都获取最新值
export function getNeedsSystemCertificates() {
  return needsSystemCertificates
}

/**
 * 测试单个 URL 的 HTTPS 证书
 * @param {string} testUrl - 要测试的 URL
 * @returns {Promise<{url: string, hasCertError: boolean, error?: string}>}
 */
async function testSingleUrl(testUrl) {
  return new Promise(resolve => {
    const req = https.request(testUrl, { method: 'HEAD', timeout: 5000 }, res => {
      // 连接成功，没有证书问题
      resolve({ url: testUrl, hasCertError: false })
      req.destroy()
    })

    req.on('error', err => {
      // 检查是否是证书相关错误
      const certErrors = [
        'unable to verify the first certificate',
        'self signed certificate',
        'unable to get local issuer certificate',
        'UNABLE_TO_VERIFY_LEAF_SIGNATURE',
        'CERT_HAS_EXPIRED',
        'DEPTH_ZERO_SELF_SIGNED_CERT'
      ]

      const isCertError = certErrors.some(errMsg => err.message?.includes(errMsg) || err.code?.includes(errMsg))

      resolve({
        url: testUrl,
        hasCertError: isCertError,
        error: err.message
      })
    })

    req.on('timeout', () => {
      req.destroy()
      resolve({ url: testUrl, hasCertError: false, error: 'timeout' })
    })

    req.end()
  })
}

/**
 * 测试多个 HTTPS 连接是否存在证书问题
 * @returns {Promise<boolean>} true 表示有证书错误，需要加载系统证书
 */
async function testHttpsConnection() {
  // 测试多个域名：公共域名 + 自己的服务域名
  const testUrls = [
    'https://www.google.com',
    'https://www.baidu.com',
    'https://serviceapi.bitbrowser.cn',
    'https://apiservice.bitbrowser.cn',
    'https://update.bitbrowser.cn',
    'https://apiservice4.bitbrowser.net'
  ]

  log.info(`Testing ${testUrls.length} URLs for certificate issues...`)

  // 并行测试所有 URL
  const results = await Promise.allSettled(testUrls.map(url => testSingleUrl(url)))

  // 提取成功的结果
  const successfulResults = results.filter(r => r.status === 'fulfilled').map(r => r.value)

  // 记录失败的测试
  const failedTests = results.filter(r => r.status === 'rejected')
  if (failedTests.length > 0) {
    log.warn(
      `${failedTests.length} test(s) failed unexpectedly:`,
      failedTests.map(r => r.reason?.message)
    )
  }

  // 分析结果
  const certErrorUrls = successfulResults.filter(r => r.hasCertError)

  if (certErrorUrls.length > 0) {
    log.warn(`Certificate errors detected on ${certErrorUrls.length}/${successfulResults.length} URL(s):`)
    for (const result of certErrorUrls) {
      log.warn(`  - ${result.url}: ${result.error}`)
    }
    return true // 有至少一个 URL 存在证书错误
  } else {
    log.info(`All ${successfulResults.length} URLs tested successfully, no certificate issues`)
    return false
  }
}

/**
 * 加载并合并系统证书到全局 HTTPS Agent
 */
function applySystemCertificates() {
  try {
    const startTime = Date.now()
    const nodeCerts = getCACertificates() // Node.js 内置证书
    const systemCerts = getCACertificates('system') // 系统证书
    const loadTime = Date.now() - startTime

    log.info(`Node.js built-in certificates: ${nodeCerts?.length || 0}`)
    log.info(`System certificates: ${systemCerts?.length || 0}`)

    // 合并 Node.js 内置证书和系统证书
    const combinedCerts = nodeCerts.concat(systemCerts)

    if (!Array.isArray(combinedCerts) || combinedCerts.length === 0) {
      log.error('No certificates available!')
      return false
    }

    // 计算证书总大小
    let totalSize = 0
    for (const cert of combinedCerts) {
      if (typeof cert === 'string') {
        totalSize += cert.length
      }
    }

    const certCount = combinedCerts.length
    const sizeMB = (totalSize / 1024 / 1024).toFixed(2)

    // 异常检测：证书数据过大可能表示证书存储损坏
    if (totalSize > 50 * 1024 * 1024) {
      log.error(`Certificates abnormally large: ${sizeMB}MB, skipping`)
      return false
    }

    if (certCount > 2000) {
      log.warn(`Unusually high number of certificates: ${certCount}`)
    }

    globalAgent.options.ca = combinedCerts
    log.info(
      `Applied ${certCount} certificates (${nodeCerts.length} built-in + ${systemCerts.length} system, ${sizeMB}MB) in ${loadTime}ms`
    )

    return true
  } catch (err) {
    log.error('Failed to apply system certificates:', err.message)

    if (err.message.includes('out of memory') || err.message.includes('Cannot allocate memory')) {
      log.error('Out of Memory error while loading certificates')
    }

    return false
  }
}

/**
 * 智能加载系统证书：先测试是否需要，只在必要时加载
 * 这样可以减少对正常用户的影响，只在检测到证书问题时才修改全局配置
 */
export async function loadSystemCertificates() {
  try {
    log.info('Testing HTTPS connection for certificate issues...')

    const hasCertError = await testHttpsConnection()

    if (hasCertError) {
      log.info('Certificate issue detected, loading system certificates...')
      const success = applySystemCertificates()
      if (success) {
        // 标记需要系统证书，axios 请求时会使用 globalAgent
        needsSystemCertificates = true
        log.info('System certificates loaded, axios will use globalAgent')
      }
      return success
    } else {
      log.info('No certificate issues detected, using default certificates')
      needsSystemCertificates = false
      return true
    }
  } catch (err) {
    log.error('Failed to test HTTPS connection:', err.message)
    // 测试失败时，保守起见，加载系统证书
    log.info('Loading system certificates as fallback...')
    const success = applySystemCertificates()
    if (success) {
      needsSystemCertificates = true
      log.info('System certificates loaded as fallback, axios will use globalAgent')
    }
    return success
  }
}
