import { app } from 'electron'
import { getCachedFontTTFs, getCachedFontNames, saveFontNamesToDB, saveFontFilesMapToDB } from '../data/cacheData'
import { downloadObject, getOssClient, getOssFileMd5, getOssObject } from '../interface/OssUtils'
import { apiLog } from '../logs'
import path from 'path'
import { ensureDir, pathExists } from 'fs-extra'
import { safeJsonParse } from '../utils/safeJsonParse'

const OSSBucket = 'browser-fingerprint-assets'
const fontNamesMd5 = new Map()
let fontFilesMapMd5 = ''

/**
 * @description getFontConfig
 * @param {Object} param
 * @param {number} fontType 0: 不使用字体, 1: 使用字体
 * @param {string} font 字体名
 * @param {string} platform Windows | macOS | Linux | iOS | Android
 * @param {string} platformVersion mac > 15.x.x, android > 14.x, 13.x, ignore for others
 * @param {string} locale en-US | zh-CN | zh-TW
 * @returns {Promise<Object>} { BasePath: '#/BitBrowser/Fonts', Names: [], BlockFallbackList: [], Files
  : [] }
 * */
export async function getFontConfig({ fontType, font = '', platform, platformVersion, locale }) {
  if (+fontType === 0) return null

  try {
    await ensureFontFilesReady(platform)

    // 设置字体
    const fontNames = await getFontNames({ platform, platformVersion, locale })
    return {
      BasePath: '#/BitBrowser/Fonts',
      Names: fontNames.concat(font.split(',')),
      // Win 模拟 Mac 时, 不 Block 掉 CreepJS 能检测到.
      BlockFallbackList: process.platform === 'win32' && platform === 'macOS' ? ['Segoe UI Emoji', 'Segoe Fluent Icons'] : [],
      Files: await getTTFFiles(platform) // 读取本地文件，相对 BitBrowser/Fonts
    }
  } catch (err) {
    apiLog.error('getFontConfig ensureFontFilesReady error ==>>> ', err)
  }

  return null
}

/**
 * @description getFontNames
 * @param {string} platform Windows | macOS | Linux | iOS | Android
 * @param {string} platformVersion mac > 15.x.x, android > 14.x, 13.x, ignore for others
 * @returns {Promise<Array>} []
 * */
export async function getFontNames({ platform, platformVersion, locale = '' }) {
  const fontNames = await getCachedFontNames(platform)

  if (!fontNames) {
    await getLatestFontNames(platform)
  }

  const strategy = {
    Windows: ({ locale }) => {
      // win 字体Names格式 {en-US: [], zh-CN: [], ... zh-TW: []}
      const names = fontNames['en-US']
      Reflect.deleteProperty(fontNames, 'en-US')

      const keys = Object.keys(fontNames)
      keys.map(key => {
        if (locale.toLowerCase().includes(key.toLowerCase())) {
          names.push(...fontNames[key])
        }
      })
      return names
    },
    macOS: ({ platformVersion }) => {
      // mac 字体Names格式 {15: [], 14: []}
      const version = +platformVersion.split('.')[0]
      if (version >= 15) {
        return fontNames['15']
      }
      if (version <= 14) {
        return fontNames['14']
      }
      return []
    },
    Linux: () => {
      // linux 字体Names格式 []
      return fontNames
    },
    iOS: () => {
      // ios 字体Names格式 {18: []}
      return fontNames['18']
    },
    Android: ({ platformVersion }) => {
      // Android 字体Names格式 {14: [], 13: []}
      const version = +platformVersion.split('.')[0]
      if (version >= 14) {
        return fontNames['14']
      }
      if (version <= 13) {
        return fontNames['13']
      }
      return []
    }
  }

  return strategy[platform]({ platformVersion, locale })
}

/**
 * @description 获取oss存储的对应platform的md5，获取到后存入map中，整个进程只会请求一次，每次启动客户端才会请求
 * */
export async function getFontNamesFileMd5(platform) {
  if (!platform) return null

  if (fontNamesMd5.has(platform)) {
    return fontNamesMd5.get(platform)
  }

  const client = await getOssClient({ bucket: OSSBucket })
  const md5 = await getOssFileMd5(client, `fonts/names/${platform}.json`)

  if (md5) {
    fontNamesMd5.set(platform, md5)
  }

  return md5
}

/**
 * @description 获取oss存储的字体files map的md5
 * */
export async function getFontFilesMapMd5() {
  if (fontFilesMapMd5) {
    return fontFilesMapMd5
  }

  const client = await getOssClient({ bucket: OSSBucket })
  const md5 = await getOssFileMd5(client, `fonts/files/map.json`)
  if (md5) {
    fontFilesMapMd5 = md5
  }
  return md5
}

/**
 * @description 获取最新的字体Names
 * */
export async function getLatestFontNames(platform) {
  try {
    const client = await getOssClient({ bucket: OSSBucket })
    // apiLog.info('getLatestFontNames client ==>>> ', client)
    const result = await getOssObject(client, `fonts/names/${platform}.json`)
    if (result) {
      await saveFontNamesToDB({ platform, dataValue: safeJsonParse(result, 'getLatestFontNames') })
    }
  } catch (err) {
    apiLog.error('getLatestFontNames error ==>>> ', err)
  }
}

/**
 * @description 获取最新的字体Names
 * */
export async function getLatestFontFilesMap() {
  try {
    const client = await getOssClient({ bucket: OSSBucket })
    const result = await getOssObject(client, `fonts/files/map.json`)
    if (result) {
      await saveFontFilesMapToDB({ dataValue: safeJsonParse(result, 'getLatestFontFilesMap') })
    }
  } catch (err) {
    apiLog.error('getLatestFontNames error ==>>> ', err)
  }
}

/**
 * @description 下载字体文件，如果是win模拟其他平台，或者mac模拟其他平台，需要下载字体文件
 * */
export async function ensureFontFilesReady(platform) {
  // apiLog.info('ensureFontFilesReady platform ==>>> ', platform)
  if (!platform) return
  if (process.platform === 'darwin' && platform === 'macOS') return
  if (process.platform === 'win32' && platform === 'Windows') return

  // 下载字体文件
  const ttfFiles = await getCachedFontTTFs(platform)
  // apiLog.info('ensureFontFilesReady ttfFiles ==>>> ', ttfFiles)

  const downList = await Promise.all(
    ttfFiles.map(async ttf => {
      const filepath = path.join(app.getPath('userData'), `Fonts/${platform}/${ttf}`)
      const exist = await pathExists(filepath)
      return { ttf, exist }
    })
  ).then(results => results.filter(result => !result.exist).map(result => result.ttf))

  // apiLog.info('ensureFontFilesReady downList ==>>> ', downList)

  if (!downList.length) return

  const client = await getOssClient({ bucket: OSSBucket })
  await Promise.all(
    downList.map(async ttf => {
      const filepath = path.join(app.getPath('userData'), `Fonts/${platform}/${ttf}`)
      await ensureDir(path.join(app.getPath('userData'), `Fonts/${platform}`))
      return downloadObject(client, `fonts/files/${platform}/${ttf}`, filepath)
    })
  )
}

async function getTTFFiles(platform) {
  if (!platform) return []
  if (process.platform === 'darwin' && platform === 'macOS') return []
  if (process.platform === 'win32' && platform === 'Windows') return []

  const files = await getCachedFontTTFs(platform)
  return files.map(file => `${platform}/${file}`)
}
