import { app } from 'electron'
import path from 'path'
import { firefoxLog } from '../logs'
import { getChildrenListByName } from './request'
import fs from 'fs-extra'
import EventEmitter from 'events'
import { sleep } from '../utils'
import { DownloadService } from './DownloadFile'
import { getFirefoxByCoreVersion, getFirefoxVersions, updateFirefoxVersion } from '../data/firefox'
import compressing from 'compressing'
import { rimraf } from 'rimraf'
import { getOssClient } from './OssUtils'

const UpdateStatus = {
  default: 0,
  checking: 1,
  downloading: 2,
  updating: 3,
  error: 4,
  copying: 5 // 正在复制resources里的 firefox
}

class Firefox extends EventEmitter {
  constructor() {
    super()
    this.status = UpdateStatus.default
    this.ossClient = null
  }

  async ensureOSSReady() {
    this.ossClient = await getOssClient({ bucket: 'bit-update', endpoint: 'oss-cn-shenzhen.aliyuncs.com', region: 'oss-cn-shenzhen' })
  }

  // 检测版本，先从本地resourcePath取配置文件，初次安装或者升级前本地没有浏览器时，先从本地resourcePath中取，随后从网络取
  async checkVersion() {
    try {
      // await this.copyToUserData()

      // 正在升级时，直接返回
      this.status = UpdateStatus.checking
      const localList = await getFirefoxVersions()
      const latestVersions = await getChildrenListByName(process.platform === 'darwin' ? 'MacFirefoxVersions' : 'FirefoxVersions')
      // 需要升级的list
      const updateList = latestVersions.filter(
        item => !localList.find(lItem => lItem.firefox === item.dicName && lItem.version === item.dicCode)
      )
      firefoxLog.info(
        'firefox update list ==>>> ',
        updateList.map(item => item.dicCode)
      )

      return updateList
    } catch (err) {
      firefoxLog.error('check firefox update error ==>>> ', err)
      this.status = UpdateStatus.error
    }
    return []
  }

  // 确保 firefox 下载完成
  async ensureFirefoxBeReady(coreVersion = '120') {
    const list = await this.checkVersion()

    try {
      // 检查完版本，再次确认下下载的文件是否存在，不存在则重新下载
      const versionObj = await getFirefoxByCoreVersion(coreVersion)
      firefoxLog.info('ensure firefox be ready ==>>>>> ', versionObj)

      if (!versionObj || !versionObj.firefox || !versionObj.version) {
        const target = list.find(item => item.dicName === coreVersion)
        await this.downloadFirefox(target)
      } else {
        await this.downloadFirefox(versionObj)
      }
    } catch (err) {
      firefoxLog.error('download firefox core version error ==>>>> ', err)
      this.status = UpdateStatus.error
      throw new Error(err)
    }
  }

  // 确保firefoxdriver 下载
  async getFirefoxDriverPath(coreVersion) {
    try {
      const driverDir = path.resolve(app.getPath('userData'), 'firefoxdriver')
      const driverPath = path.join(driverDir, coreVersion, process.platform === 'darwin' ? 'firefoxdriver' : 'firefoxdriver.exe')

      const exists = await fs.pathExists(driverPath)
      if (!exists) {
        await fs.ensureDir(driverDir)
        await this.ensureOSSReady()
        const zipFile = path.join(driverDir, `${coreVersion}.zip`)
        await this.ossClient.get(`firefoxdriver/${process.platform === 'darwin' ? 'mac' : 'win'}/${coreVersion}.zip`, zipFile)

        await compressing.zip.uncompress(zipFile, driverDir)
        rimraf(zipFile, { maxRetries: 5 })
      }
      return driverPath
    } catch (err) {
      firefoxLog.error('get firefoxdriver path error ====>>>>>> ', err)
    }
    return ''
  }

  // 取本地文件，copy到用户目录下
  async copyToUserData() {
    try {
      // 正在复制，则等待复制完成即可
      if (this.status === UpdateStatus.copying) {
        await this.onCopyComplete()
        return
      }

      const configPath = path.join(process.resourcesPath, 'firefox/config.json')
      const configExists = await fs.pathExists(configPath)

      // 文件不存在，则直接返回即可
      if (!configExists) return

      this.status = UpdateStatus.copying
      const config = await fs.readJSON(configPath)

      // 确保 Firefox-bin 存在
      const firefoxBinPath = path.join(app.getPath('userData'), 'Firefox-bin')
      await fs.ensureDir(firefoxBinPath)

      // 复制所有文件到用户目录
      for (let [firefox, version] of Object.entries(config)) {
        const skip = await this.checkExeExists(firefox)
        if (skip) continue

        await fs.copy(path.join(process.resourcesPath, `firefox/${firefox}`), path.join(firefoxBinPath, firefox), { recursive: true })
        await updateFirefoxVersion(firefox, version) // 更新数据库
      }

      this.status = UpdateStatus.default
      this.emit('copy-complete')
    } catch (err) {
      firefoxLog.error('copy firefox to user data error ==>>>> ', err)
      this.status = UpdateStatus.error
    }
  }

  // 下载对应版本的 firefox
  async downloadFirefox(versionObj) {
    // 将字典转化为firefox和version
    if (!versionObj.firefox && !versionObj.version) {
      versionObj.firefox = versionObj.dicName
      versionObj.version = versionObj.dicCode
    }
    this.status = UpdateStatus.downloading

    const url = getDownloadUrl(versionObj)
    const firefoxDir = path.join(app.getPath('userData'), 'Firefox-bin', versionObj.firefox)
    const zipFile = path.join(firefoxDir, versionObj.version + '.zip')

    await fs.ensureDir(firefoxDir)
    const downloadService = new DownloadService(url, zipFile)
    await downloadService.start()

    await this.updateFirefox(zipFile, path.join(firefoxDir, versionObj.version), versionObj)
  }

  // 升级解压缩
  async updateFirefox(zipFile, dest, versionObj) {
    this.status = UpdateStatus.updating

    firefoxLog.info('download complete ==>>> ', zipFile, dest)

    try {
      await compressing.zip.uncompress(zipFile, dest)
      await updateFirefoxVersion(versionObj.firefox, versionObj.version)
      rimraf(zipFile, { maxRetries: 5 })
      this.status = UpdateStatus.default
      this.emit('complete')
    } catch (err) {
      this.status = UpdateStatus.error
    }
  }

  // 更新完成
  onUpdateComplete() {
    return new Promise(resolve => {
      this.on('complete', resolve)
    })
  }

  // 文件复制完成
  onCopyComplete() {
    return new Promise(resolve => {
      this.on('copy-complete', resolve)
    })
  }

  // 检测本地exe文件是否存在，默认104
  async checkExeExists(coreVersion = '120') {
    try {
      const versionObj = await getFirefoxByCoreVersion(coreVersion)
      firefoxLog.info('check firefox exist ==>>>> ', versionObj)
      if (!versionObj) return false

      const exeFile = path.join(
        app.getPath('userData'),
        'Firefox-bin',
        versionObj.firefox,
        versionObj.version,
        process.platform === 'darwin' ? 'BitFox.app' : 'bitfox.exe'
      )
      const exists = await fs.pathExists(exeFile)
      return exists
    } catch (err) {
      firefoxLog.error('check firefox secure error ==>>> ', err)
    }
    return false
  }

  // 获取执行文件路径，默认104
  async getExePath(coreVersion = '120', retryTimes = 0) {
    const platform = process.platform

    let versionObj = await getFirefoxByCoreVersion(coreVersion)

    firefoxLog.info('versionObj ==>>> ', versionObj)

    // 获取不到的话，等待2秒再试试，重试10次
    if (!versionObj && retryTimes < 10) {
      firefoxLog.info('retry get firefox path')
      await sleep(2)
      return this.getExePath(coreVersion, retryTimes + 1)
    }

    if (platform === 'win32') {
      return path.resolve(app.getPath('userData'), 'Firefox-bin', versionObj.firefox, versionObj.version, 'bitfox.exe')
    } else {
      return path.resolve(
        app.getPath('userData'),
        'Firefox-bin',
        versionObj.firefox,
        versionObj.version,
        'BitFox.app/Contents/MacOS/BitFox'
      )
    }
  }

  // 删掉非当前版本的 firefox 文件，以及resource path 里的 firefox
  async clearOldFirefoxs() {
    try {
      const versions = await getFirefoxByCoreVersion()

      if (!versions.length) return

      for (let ver of versions) {
        const firefoxDir = path.join(app.getPath('userData'), 'Firefox-bin', ver.firefox)
        const dirs = await fs.readdir(firefoxDir)
        const deleteDirs = dirs.filter(item => item !== ver.version)
        firefoxLog.info('clear old firefoxs ==>>>> ', deleteDirs)
        deleteDirs.map(dir => rimraf(path.join(firefoxDir, dir), { maxRetries: 5 }))
      }

      await rimraf(path.join(process.resourcesPath, 'firefox'), { maxRetries: 5 })
    } catch (err) {
      firefoxLog.info('clear old firefoxs error ==>>> ', err)
    }
  }

  async repair(coreVersion) {
    try {
      const latestVersions = await getChildrenListByName(process.platform === 'darwin' ? 'MacFirefoxVersions' : 'FirefoxVersions')
      const target = latestVersions.find(item => item.dicName === coreVersion)
      const versionPath = path.join(app.getPath('userData'), 'Firefox-bin', coreVersion)
      await fs.emptyDir(versionPath)

      await this.downloadFirefox(target)
    } catch (err) {
      firefoxLog.error('check firefox update error ==>>> ', err)
      return Promise.reject(err.message)
    }
  }
}

// 获取内核oss url
function getDownloadUrl(versionObj) {
  let url = `${process.env.PUBLISH_URL}/bitfox/${versionObj.firefox}/${versionObj.version}`
  if (process.platform === 'darwin') {
    url += process.arch === 'arm64' ? '_mac_arm64.zip' : '_mac.zip'
  } else {
    url += process.arch === 'ia32' ? '_x86.zip' : '.zip'
  }
  return url
}

export default new Firefox()
