const firefoxBookmarksCache = new Cache()

// 获取access key 和初始化client
export async function initialClient() {
  const client = await getOssClient({ bucket: 'browser-cache-hk' })
  return client
}

/**
 * @description 判断是否需要同步oss文件，出错时，默认返回true，需要同步
 * @returns {Promise<Boolean>} true | false
 * @param {String} ossPath oss文件路径
 * */
async function needSyncNow(ossPath) {
  const client = await initialClient()
  return isNeedSync(client, ossPath)
}

/**
 * @description 上传文件到oss
 * @param {string} ossPath oss的完整文件路径，包含文件名
 * @param {string} filename 本地要上传的文件，绝对路径
 * @returns {Promise<{success: Boolean, data: String}>} 返回结果，成功或失败
 * */
async function uploadFileToOss(ossPath, filename, browserId) {
  const client = await initialClient()
  await multipartUpload(client, ossPath, filename, browserId)
}

// 从oss下载文件
async function downloadFileFromOss(ossPath, filename) {
  const client = await initialClient()
  await downloadObject(client, ossPath, filename)
}

/**
 * @description 从oss删除文件，用来删除7z文件
 * @param {String} ossPath oss文件路径
 * @returns {Promise<void>}
 * */
async function removeFileFromOss(ossPath) {
  const client = await initialClient()
  await deleteOssObject(client, ossPath)
}

// 上传Cookies数据 新版的Cookies 位于 /Default/Network/Cookies
export async function uploadCookies(config) {
  ossLog.info('upload cookies ==>>> ', config.seq)

  // 同步cookies 值到服务端
  const cookies = await getBrowserCookies(config.id)

  if (cookies && cookies.length) {
    const data = { id: config.id, randomKey: config.randomKey, cookie: JSON.stringify(cookies) }
    const isApiUser = browserStatus.ids_from_api.has(config.id)
    // 采用非阻塞方式，不等待接口返回结果
    updateBrowserCookie(data, isApiUser)
      .then(() => {
        clearBorwserCookieCache(config.id)
      })
      .catch(err => {
        syncTasks.add(config.seq, SyncTaskEnum.uploadCookies, data, isApiUser)
        ossLog.error('upload cookies error ===>>>> ', err.message)
      })
  }
}

// 上传indexedDB数据
export async function uploadIndexedDB(browserId, randomKey, retry = true) {
  ossLog.info('upload indexedDB ==>>> ', browserId)
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const targetDir = path.join(cacheDir, 'Default/IndexedDB')
    const exist = await fs.pathExists(targetDir)

    if (exist) {
      const encryptFilePath = await packAndEncrypt({ targetDir, key: randomKey })

      await uploadFileToOss(`${browserId}/IndexedDB.zip`, encryptFilePath, browserId)
      rimraf(encryptFilePath, { maxRetries: 5 })

      ossLog.info('upload indexedDB success and then delete zip file')
    }
  } catch (err) {
    ossLog.error('upload indexedDB error ==>>> ', retry, err.message)
    if (retry) {
      await sleep(1)
      await uploadIndexedDB(browserId, randomKey, false)
    }
  }
}

// 同步indexedDB
export async function syncIndexedDB(browserId, randomKey) {
  ossLog.info('sync indexedDB from oss!')
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const indexedDBPath = path.join(cacheDir, 'Default/IndexedDB')
    const exist = await fs.pathExists(indexedDBPath)
    const { md5, pathWithExt, is7z } = await getOssFilename(`${browserId}/IndexedDB`)

    if (!pathWithExt) return

    const needSync = await diffMd5FromLocal(md5, pathWithExt)

    if (exist && !needSync) {
      ossLog.info('no need to sync indexedDB.')
      return
    }

    if (exist) {
      await rimraf(indexedDBPath, { maxRetries: 5 })
    } else {
      // 确保存在缓存 Default 文件夹
      await fs.ensureDir(path.join(cacheDir, 'Default'))
    }

    const tempFile = path.join(cacheDir, `Default/IndexedDB.${path.extname(pathWithExt)}`)
    await downloadFileFromOss(pathWithExt, tempFile)

    await decryptAndUnpack({ sourceFile: tempFile, targetDir: path.join(cacheDir, 'Default'), key: randomKey })

    // TODO : 7z文件解压后，删除原来的7z文件，几个大版本后，删除判断代码
    if (is7z) {
      removeFileFromOss(pathWithExt)
    }

    ossLog.info('sync indexedDB success!!!')
  } catch (err) {
    ossLog.error(err.message)
    if (err.message !== 'Object not exists') sendToRenderer(browserId, '同步IndexedDB失败', 'error')
  }
}

// 上传 Local Storage
export async function uploadLocalStorage(browserId, randomKey, isFirefox = false, retry = true) {
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const targetDir = path.join(cacheDir, isFirefox ? 'storage/default' : 'Default/Local Storage')
    const exist = await fs.pathExists(targetDir)
    if (exist) {
      const encryptFilePath = await packAndEncrypt({ targetDir, key: randomKey })

      await uploadFileToOss(`${browserId}/LocalStorage.zip`, encryptFilePath, browserId)
      rimraf(encryptFilePath, { maxRetries: 5 })

      ossLog.info('upload local storage success and then delete zip file')
    }
  } catch (err) {
    ossLog.error('upload local storage error ==>>>> ', err.message)
    if (retry) {
      await sleep(1)
      await uploadLocalStorage(browserId, randomKey, isFirefox, false)
    }
  }
}

// 同步 Local Storage
export async function syncLocalStorage(browserId, randomKey, isFirefox = false) {
  ossLog.info('sync local storage from oss!')
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const storagePath = path.join(cacheDir, isFirefox ? 'storage/default' : 'Default/Local Storage')
    const exist = await fs.pathExists(storagePath)
    const ossPath = `${browserId}/LocalStorage`

    const { pathWithExt, md5, is7z } = await getOssFilename(ossPath)

    if (!pathWithExt) return

    const needSync = await diffMd5FromLocal(md5, pathWithExt)

    if (exist && !needSync) {
      ossLog.info('no need to sync local storage.')
      return
    }

    const targetPath = isFirefox ? 'storage' : 'Default'
    if (exist) {
      await rimraf(storagePath, { maxRetries: 5 })
    }

    // 确保存在缓存 Default 文件夹
    const defaultPath = path.join(cacheDir, targetPath)
    await fs.ensureDir(defaultPath)

    const tempFile = path.join(cacheDir, targetPath, `LocalStorage${path.extname(pathWithExt)}`)
    await downloadFileFromOss(pathWithExt, tempFile)

    await decryptAndUnpack({ sourceFile: tempFile, targetDir: defaultPath, key: randomKey })

    if (is7z) {
      removeFileFromOss(pathWithExt)
    }

    ossLog.info('sync local storage success!!!')
  } catch (err) {
    ossLog.error(err.message)
    if (err.message !== 'Object not exists') sendToRenderer(browserId, '同步Local Storage失败', 'error')
  }
}

// 上传书签，包括 Bookmarks
export async function uploadBookmarks(browserId, isFirefox = false, retry = true) {
  ossLog.info('upload bookmarks to oss ==>>> ')
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const bookmarks = path.join(cacheDir, 'Default/Bookmarks')

    // firefox 则需要先从缓存里取出再保存下bookmarks，保存完清理掉缓存即可
    if (isFirefox && firefoxBookmarksCache.has(browserId)) {
      const fireBookmarks = firefoxBookmarksCache.get(browserId)
      await fs.outputJson(bookmarks, fireBookmarks)
      firefoxBookmarksCache.delete(browserId)
    }

    const exist = await fs.pathExists(bookmarks)
    if (exist) {
      await uploadFileToOss(`${browserId}/Bookmarks`, bookmarks, browserId)
      ossLog.info('bookmarks upload success ==>>> ')
    }
  } catch (err) {
    ossLog.error('upload bookmarks error ==>>> ', retry, err.message)
    if (retry) {
      await sleep(1)
      await uploadBookmarks(browserId, isFirefox, false)
    }
  }
}

// 同步书签, firefox 的同步放在扩展里
export async function syncBookmarks(browserId, isFirefox = false) {
  ossLog.info('sync bookmarks from oss!')

  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const defaultPath = path.join(cacheDir, 'Default')
    const ossPath = `${browserId}/Bookmarks`
    const bookmarksPath = path.join(defaultPath, 'Bookmarks')

    const exists = await fs.pathExists(bookmarksPath)
    const needSync = await needSyncNow(ossPath)

    if (exists && !needSync && !isFirefox) {
      ossLog.info('no need to sync oss bookmarks, sync global bookmarks.')
      await syncGlobalBookmarks(browserId)

      return
    }

    await fs.ensureDir(defaultPath) // 确保Default目录存在
    await downloadFileFromOss(ossPath, bookmarksPath)

    ossLog.info('sync bookmarks from oss succeess!!!')
  } catch (err) {
    ossLog.error(err.message)
    if (err.message !== 'Object not exists') sendToRenderer(browserId, '同步书签失败', 'error')
  }

  if (!isFirefox) {
    await syncGlobalBookmarks(browserId)
  }
}

