// 上传已保存的密码 websites_credentials
export async function uploadWebsiteCredentials(browserId, seq, randomKey, addSyncTask = false) {
  ossLog.info('upload website credentials!!!')
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const websites_credentials = path.join(cacheDir, 'Default/~LoginData')
    if (await fs.pathExists(websites_credentials)) {
      const encryptedData = await getFileEncrypedData(websites_credentials, randomKey)

      if (!encryptedData) return

      const hexData = encryptedData.toString('hex')

      await uploadBrowserLoginData({ browserId, syncBrowserAccount: hexData })
    }
    ossLog.info('upload website credentials succees!!!')
  } catch (err) {
    ossLog.error('upload website credentials error ==>>> ', err.message)

    // 初次关闭窗口时，从此处添加同步任务，同步任务中出错，则直接抛出异常
    if (addSyncTask) {
      syncTasks.add(seq, SyncTaskEnum.uploadWebsitesCredentials, { browserId, seq, randomKey })
    }
  }
}

// 同步已保存的密码到本地
export async function syncWebsiteCredentials(browserId, hexData, randomKey) {
  ossLog.info('sync  websites credentials ==>>> ', browserId)

  const cacheDir = await getBrowserCacheDir(browserId)
  const websitesCredentials = path.join(cacheDir, 'Default/~LoginData')

  // 下载oss 文件
  try {
    await fs.ensureDir(path.join(cacheDir, 'Default')) // 确保Default目录存在

    // 获取解密内容，并写入到文件里
    if (hexData) {
      const data = decryptHexData(hexData, randomKey)
      fs.outputFileSync(websitesCredentials, data) // 改成Sync方法，async方法，data为null时，catch不到错误，直接抛到全局了
    }

    ossLog.info('sync websites credentials success!!!')
  } catch (err) {
    ossLog.error('sync websites credentials error ==>>>>> ', err.message)
    sendToRenderer(browserId, '同步已保存的密码失败', 'error')
  }

  // 合并全局配置
  try {
    const res = await getGlobalValueFromClient({ globalValueType: 'websitesCredentials' })
    if (res && res.globalValue && res.globalValue.length) {
      const list = safeJsonParse(res.globalValue, 'syncWebsiteCredentials:globalValue')

      let jsonFile = await getDecryptLoginData(websitesCredentials)

      // ossLog.info(jsonFile)

      // 如果不存在相同的项目，则push
      for (let item of list) {
        if (!jsonFile.entries.some(cItem => cItem.url + cItem.username + cItem.password === item.url + item.username + item.password)) {
          jsonFile.entries.push(item)
        }
      }
      await encryptFile(websitesCredentials, JSON.stringify(jsonFile), getFingerprintDectyptKey())
    }
  } catch (err) {
    ossLog.error('merge global websites credentials error ==>>> ', err)
    sendToRenderer(browserId, '同步已保存的密码失败', 'error')
  }
}

// 获取解密后的 ~LoginData
async function getDecryptLoginData(filePath) {
  let defaultObj = { entries: [] }
  try {
    const exists = await fs.pathExists(filePath)
    if (!exists) return defaultObj

    const text = await decryptFile(filePath, getFingerprintDectyptKey())
    defaultObj = safeJsonParse(text, 'getDecryptLoginData')
  } catch (err) {
    ossLog.error('read credentials json error ==>>> ', err.message)
  }

  return defaultObj
}

// 同步全局设置上传的书签
async function syncGlobalBookmarks(browserId) {
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const defaultPath = path.join(cacheDir, 'Default')

    await fs.ensureDir(defaultPath) // 确保Default目录存在

    const exist = await fs.pathExists(path.join(defaultPath, 'Bookmarks'))
    let bookmarksJson = {
      roots: {
        bookmark_bar: {
          children: [],
          name: '书签栏',
          type: 'folder'
        },
        other: {
          children: [],
          name: '其他书签',
          type: 'folder'
        },
        synced: {
          children: [],
          name: '移动设备书签',
          type: 'folder'
        }
      },
      version: 1
    }
    if (exist) {
      bookmarksJson = await fs.readJson(path.join(defaultPath, 'Bookmarks'))
    }

    const globalBookmarks = await getGlobalBookmarksObject()
    bookmarksJson.roots.bookmark_bar.children = mergeBookmarks(
      globalBookmarks.importMode === 'replace' ? [] : bookmarksJson.roots.bookmark_bar.children,
      globalBookmarks.bookmarkBar
    )
    bookmarksJson.roots.other.children = mergeBookmarks(
      globalBookmarks.importMode === 'replace' ? [] : bookmarksJson.roots.other.children,
      globalBookmarks.other
    )

    // 修改或写入Bookmarks
    await fs.outputJson(path.join(defaultPath, 'Bookmarks'), bookmarksJson, { encoding: 'utf-8' })
  } catch (err) {
    ossLog.error('sync global bookmarks error ==>>> ', err.message)
  }
}

// 合并书签
function mergeBookmarks(targetBookmarks = [], sourceBookmarks = []) {
  if (!targetBookmarks.length) return sourceBookmarks
  while (sourceBookmarks.length) {
    const sourceObj = sourceBookmarks.shift()
    if (sourceObj.type === 'url') {
      if (targetBookmarks.find(item => item.url === sourceObj.url)) continue
      targetBookmarks.push(sourceObj)
    } else {
      const target = targetBookmarks.find(item => item.type === 'folder' && item.name === sourceObj.name)
      if (!target) {
        targetBookmarks.push(sourceObj)
      } else {
        target.children = mergeBookmarks(target.children, sourceObj.children)
      }
    }
  }
  return targetBookmarks
}

/**
 * @description 上传扩展数据 Local Extension Settings 与 Sync Extension Settings, Managed Extension Settings
 * @param {String} browserId 窗口ID
 * @param {String} ossPrefix 窗口ID或者createdBy，用于oss存储目录前缀
 * @param {String} encryptKey 加密key，窗口同步用 randomKey, 跨窗口同步用 randomKeyUser
 * */
export async function uploadExtensions(browserId, ossPrefix, encryptKey) {
  apiLog.info('browser extension ids ==>>>> ', browserExtensionStore.getIds(browserId))
  await Promise.all([
    uploadExtensionSettings(browserId, ossPrefix, 'Local Extension Settings', encryptKey),
    uploadExtensionSettings(browserId, ossPrefix, 'Sync Extension Settings', encryptKey),
    uploadExtensionSettings(browserId, ossPrefix, 'Managed Extension Settings', encryptKey)
  ])

  browserExtensionStore.removeBrowser(ossPrefix)
}

/**
 * @description 上传扩展数据
 * @param {String} browserId 窗口ID
 * @param {String} ossPrefix oss prefix
 * @param {String} settingsPath Local Extension Settings |  Sync Extension Settings
 * @param {String} encryptKey 加密key
 * */
async function uploadExtensionSettings(browserId, ossPrefix, settingsPath, encryptKey) {
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const extensionSettings = path.join(cacheDir, 'Default', settingsPath)

    const exists = await fs.pathExists(extensionSettings)
    if (!exists) return

    const extensionIds = browserExtensionStore.getIds(browserId)

    const syncFn = async id => {
      const targetDir = path.join(extensionSettings, id)
      const fileExists = await fs.pathExists(targetDir)

      if (!fileExists) return Promise.resolve() // 扩展数据不存在，跳过

      const encryptFilePath = await packAndEncrypt({ targetDir, key: encryptKey })
      await uploadFileToOss(`${ossPrefix}/${settingsPath}/${id}.zip`, encryptFilePath, browserId)
      rimraf(encryptFilePath, { maxRetries: 5 })

      return Promise.resolve()
    }

    await Promise.all(extensionIds.map(id => syncFn(id)))
  } catch (err) {
    ossLog.error('upload extensions error ==>>> ', err.message)
  }
  ossLog.info(`upload ${settingsPath} success!!!`)
}

/**
 * @description 从oss同步扩展数据，直接下载 Local Extension Settings 目录
 * @param {String} browserId 窗口ID
 * @param {String} key 密钥key
 * @param {Object} ossObject oss 对象集合
 * @param {Boolean} fromUser 来自于用户目录，跨窗口
 * */
export async function syncExtensionsFromOss(browserId, key, ossObject = {}, fromUser = false) {
  // ossLog.info('sync extension from oss ==>>>>> ', browserId, key, ossObject)
  if (ossObject['Local Extension Settings'] && ossObject['Local Extension Settings'].length) {
    await syncExtensionSettings(browserId, 'Local Extension Settings', ossObject['Local Extension Settings'], key, fromUser)
  }
  if (ossObject['Sync Extension Settings'] && ossObject['Sync Extension Settings'].length) {
    await syncExtensionSettings(browserId, 'Sync Extension Settings', ossObject['Sync Extension Settings'], key, fromUser)
  }
  if (ossObject['Managed Extension Settings'] && ossObject['Managed Extension Settings'].length) {
    await syncExtensionSettings(browserId, 'Managed Extension Settings', ossObject['Managed Extension Settings'], key, fromUser)
  }
}

// extensions ['/ee9452ce878e45a7bdd2297914579a97/Local Extension Settings/aapbdbdomjkkjkaonfhkkikfgjllcleb.zip']
async function syncExtensionSettings(browserId, settingsPath, extensions = [], key, fromUser = false) {
  try {
    const cacheDir = await getBrowserCacheDir(browserId)
    const extensionSettings = path.join(cacheDir, 'Default', settingsPath)

    if (!extensions.length) return

    await fs.ensureDir(extensionSettings)

    const extensionIds = []

    // 过滤掉重复存在的相同id的 7z 与 zip 文件，只保留 7z 与 单独的 zip 文件，兼容老版本同步的zip，与新版的7z，最终保留的可能是 [aaa.7z, bbb.7z, ccc.zip]
    const filteredExtensions = extensions.filter(item => {
      if (path.extname(item) === '.7z') return true

      // 如果是zip，判断是否有相同ID的7z，如果有，丢掉即可
      const _7zFile = item.replace('.zip', '.7z')
      if (extensions.includes(_7zFile)) return false

      return true
    })

    for (let ossObjName of filteredExtensions) {
      const packFile = ossObjName.split('/').pop() // aapbdbdomjkkjkaonfhkkikfgjllcleb.zip
      if (!new Set(['.7z', '.zip']).has(path.extname(packFile))) continue

      const extensionId = packFile.split('.').shift()
      const exists = await fs.pathExists(path.join(extensionSettings, extensionId))

      // 跨窗口同步，则每次都下载
      const needSync = fromUser ? true : await needSyncNow(ossObjName)

      // 不存在扩展文件或者需要同步的时候，则下载oss文件
      if (!exists || needSync) {
        const tempPackFile = path.join(extensionSettings, packFile)
        await downloadFileFromOss(ossObjName, tempPackFile)

        await decryptAndUnpack({ sourceFile: tempPackFile, targetDir: extensionSettings, key })

        // TODO 删掉7z文件，几个大版本后，删除判断代码，只保留zip文件
        if (path.extname(packFile) === '.7z') {
          removeFileFromOss(ossObjName)
        }
      } else {
        ossLog.info('no need to sync extension data ==>>>> ', extensionId)
      }

      extensionIds.push(extensionId)
    }

    // 设置对应的 preferences bt_extensions
    await setPreferencesExtensions(browserId, extensionIds)

    ossLog.info(`sync ${settingsPath} from oss success!!!`)
  } catch (err) {
    ossLog.error(`sync ${settingsPath} from oss error ==>>>> `, err)
  }
}

export function saveFirefoxBookmarks(browserId, bookmarks) {
  firefoxBookmarksCache.add(browserId, bookmarks)
}

// 获取缓存文件内的Firefox Bookmarks
export async function getFirefoxBookmarks(browserId) {
  const defaultData = {
    bookmarkBar: [],
    other: [],
    importMode: 'replace'
  }
  try {
    const config = browserStatus.getBrowserConfig(browserId)
    if (!config || !config.syncBookmarks) return defaultData

    const cacheDir = await getBrowserCacheDir(browserId)
    const targetPath = path.join(cacheDir, 'Default/Bookmarks')

    const exists = await fs.pathExists(targetPath)
    let bookmarksRes = [{ id: 'toolbar_____' }, { id: 'unfiled_____' }] // 新建窗口时用来构建默认数据

    if (exists) {
      bookmarksRes = await fs.readJson(targetPath)
    }

    // firefox 产生的bookmarks为数组类型
    if (Array.isArray(bookmarksRes)) {
      const toolbar = bookmarksRes.find(item => item.id === 'toolbar_____')
      const otherObj = bookmarksRes.find(item => item.id === 'unfiled_____')

      // 将本地文件里的书签合并到全局书签里，由扩展直接删掉所有书签，再重建
      const globalBookmarks = await getGlobalBookmarksObject()

      if (globalBookmarks.importMode === 'replace') return globalBookmarks

      return {
        bookmarkBar: mergeBookmarks(globalBookmarks.bookmarkBar, getFirefoxBookmarksChildren(toolbar, bookmarksRes)),
        other: mergeBookmarks(globalBookmarks.other, getFirefoxBookmarksChildren(otherObj, bookmarksRes)),
        importMode: globalBookmarks.importMode
      }
    } else {
      // 如果是对象，则是老数据，老版本产生的全局书签数据
      return bookmarksRes
    }
  } catch (err) {
    ossLog.error('get firefox bookmarks error ===>>>> ', err.message)
  }
  return defaultData
}

// 获取全局的bookmarks对象
export async function getGlobalBookmarksObject() {
  try {
    const res = await getGlobalValueFromClient({ globalValueType: 'bookmarks' })

    if (res && res.globalValue && res.globalValue.length) {
      const resObj = safeJsonParse(res.globalValue, 'getGlobalBookmarksObject')

      return resObj
    }
  } catch (err) {
    ossLog.error('get global bookmarks error ==>>> ', err.message)
  }

  return {
    bookmarkBar: [],
    other: [],
    importMode: 'merage'
  }
}

// 将firefox的bookmarks数组转为tree，并返回children
function getFirefoxBookmarksChildren(treeItem, bookmarks) {
  const parentId = treeItem.id
  const children = []

  for (let item of bookmarks) {
    if (item.parentId === parentId) {
      const obj = { name: item.title, type: 'url', url: item.url }

      if (item.type === 'folder') {
        obj.type = 'folder'
        obj.children = getFirefoxBookmarksChildren(item, bookmarks)
      }

      children.push(obj)
    }
  }

  return children
}

/**
 * @description 获取完整的oss path，包含文件名，7z文件存在则返回7z文件，否则返回zip文件，都不存在，返回null
 * @param {String} ossPath oss文件路径
 * @returns {Promise<{pathWithExt: String | null, md5: String | null, is7z: Boolean}>}
 * */
async function getOssFilename(ossPath) {
  const data = {
    pathWithExt: null,
    md5: null,
    is7z: false
  }

  if (!ossPath) return data

  const _7zPath = ossPath + '.7z'
  const _zipPath = ossPath + '.zip'

  const client = await initialClient()
  const _7zMd5 = await getOssFileMd5(client, _7zPath)

  if (_7zMd5) {
    data.md5 = _7zMd5
    data.pathWithExt = _7zPath
    data.is7z = true

    return data
  }

  const _zipMd5 = await getOssFileMd5(client, _zipPath)

  if (_zipMd5) {
    data.md5 = _zipMd5
    data.pathWithExt = _zipPath

    return data
  }

  return data
}
