import { messages } from '../interface/Messages'
import { getUserInfo } from '../interface/request'

const allowedMethods = new Set(['GET', 'OPTIONS'])

export function apiAuth() {
  return async (ctx, next) => {
    if (allowedMethods.has(ctx.request.method)) {
      await next()
    } else {
      const userInfo = await getUserInfo()

      if (userInfo.isLocalToken) {
        const reqToken = ctx.request.headers['x-api-key']
        if (reqToken === userInfo.localToken) {
          await next()
        } else {
          ctx.status = 403
          ctx.throw(ctx.status, messages.getMessage('wrongApiKey'))
        }
      } else {
        await next()
      }
    }
  }
}
