import { extractDymanicIp } from '../agent'
import { getBrowserDetailForApi, rpaRunAtOpenedBrowser, updateRpaTaskStatus } from '../interface/request'
import { closeBrowser, getRpaHtml, openBrowserByApi } from '../browser'
import { rpaLogs } from '../logs'
import rpaTaskPool from './pool'
import { saveRpaLog } from '../data/rpa'
import browserStatus from '../interface/browserStatus'
import { sendWebRpaTaskChange } from '../electron-main'
import { date } from 'quasar'
import { sleep } from '../utils'
import { sendRpaTaskErrorMsg } from '../server/sse'
export class RpaTask {
  constructor({ id, concurrent, workflowId, browserIds, type, startTime, endTime, timeout = 0, intervalType, intervalValue }) {
    this.taskId = id
    this.browserIds = [] // 每次任务开始运行时，将原始 rawIds 赋值到此
    this.pool = []
    this.concurrent = concurrent
    this.workflowId = workflowId
    this.type = type // immediately | time | interval
    this.browserSeqMap = new Map() // browserId => seq
    this.startTime = startTime
    this.endTime = endTime
    this.rawIds = browserIds || [] // 原始ID，循环任务将 browserIds 执行完的时候，将rawIds再赋值给 browserIds
    this.timeout = timeout
    this.intervalType = intervalType // day|hour|minute
    this.intervalValue = intervalValue
  }

  // 收集需要运行的窗口，开始任务
  async collectAndRun() {
    try {
      if (!this.rawIds.length) {
        saveRpaLog('', '', this.taskId, 3)
        rpaTaskPool.destroyTask(this.taskId)
      } else {
        saveRpaLog('', '', this.taskId, 1) // 记录日志
        this.browserIds = [...this.rawIds] // 复制值

        this.run()
      }
      sendWebRpaTaskChange()
    } catch (err) {
      rpaLogs.error('rpa task collect error ==>>> ', err.message)
    }
  }

  // 插队运行，等待扫描即可
  jumpToFirst(browserId) {
    this.browserIds.unshift(browserId)
    this.run()
  }

  // 已打开的窗口运行rpa，直接打开一次rpa.html即可
  async runAtOpened(browserId) {
    const browser = browserStatus.getBrowser(browserId)
    const page = await browser.newPage()
    const url = await getRpaHtml(browserId, this.workflowId)
    await page.goto(url)
    await sleep(2)
    await page.close()
  }

  async run() {
    while (this.pool.length < this.concurrent) {
      if (!this.browserIds.length) return // 没有剩余的浏览器要执行，直接返回
      // 取出一个浏览器开始执行
      const browserId = this.browserIds.shift()
      this.pool.push(browserId)

      try {
        // 打开浏览器运行
        let config = await getBrowserDetailForApi(browserId)
        this.browserSeqMap.set(browserId, config.seq)

        // 正在打开直接跳过
        if (browserStatus.isOpening(browserId)) {
          saveRpaLog(browserId, config.seq, this.taskId, 2, 2)
          await this.hanleFinish(browserId, true)

          continue
        }

        // 已打开的窗口运行rpa
        if (browserStatus.hasOpened(browserId)) {
          const canRun = await rpaRunAtOpenedBrowser()
          if (canRun) {
            saveRpaLog(browserId, config.seq, this.taskId, 2, 5)
            await this.runAtOpened(browserId)
          } else {
            saveRpaLog(browserId, config.seq, this.taskId, 2, 2)
          }

          this.hanleFinish(browserId, true)
          continue
        }

        config.workflowId = this.workflowId
        config.rpaRun = true

        // 提取IP
        if (+config.proxyMethod === 3) config = await extractDymanicIp(config, true)

        await openBrowserByApi(config, [], true)

        // 设置了超时时间，则超时后关闭窗口
        if (this.timeout > 0) {
          const timeId = setTimeout(() => {
            closeBrowser(browserId)
            clearTimeout(timeId)
          }, this.timeout * 1000)
        }

        saveRpaLog(browserId, config.seq, this.taskId, 2, 1)
      } catch (err) {
        rpaLogs.error(Object.prototype.toString.call(err), 'run rpa and open browser error ==>>> ', err)
        let rpaErrLog = err
        if (Object.prototype.toString.call(err) === '[object Object]' || err instanceof Error) {
          rpaErrLog = err.message
          sendRpaTaskErrorMsg({ taskId: this.taskId, msg: rpaErrLog })
        }
        saveRpaLog(browserId, this.browserSeqMap.get(browserId), this.taskId, 2, 3, rpaErrLog)

        this.hanleFinish(browserId, true)
      }
    }
  }

  // isSkip 是否是已打开直接跳过的窗口，直接跳过的窗口，不记录关闭窗口的日志
  async hanleFinish(browserId, isSkip = false) {
    const index = this.pool.findIndex(id => browserId === id)
    if (index > -1) {
      this.pool.splice(index, 1)
      if (!isSkip) {
        saveRpaLog('', this.browserSeqMap.get(browserId), this.taskId, 2, 4)
      }
    }

    // 完成一个窗口时，再次运行一次，直到所有窗口运行完成
    await this.run()

    if (!this.pool.length) {
      this.stop(browserId)
    }
  }

  // 执行完成，将任务状态改为2
  async stop(browserId) {
    try {
      if (this.type === 'interval') {
        // 计算出下次任务执行时间，如果下次的执行时间晚于结束时间，认为任务执行完成，即 当前时间 + 循环间隔 > 结束时间
        // 用当前时间的开始整分钟，比如 2023-04-11 14:23:00
        const nextRunTime = date.addToDate(Math.floor(Date.now() / 60000) * 60000, {
          [this.intervalType + 's']: this.intervalValue || 0 // days | hours | minutes
        })
        rpaLogs.info('next run time ==>>> ', date.formatDate(nextRunTime, 'YYYY-MM-DD HH:mm:ss'))

        // 分钟级别
        if (Math.floor(nextRunTime.getTime() / 60000) > Math.floor(new Date(this.endTime).getTime() / 60000)) {
          await updateRpaTaskStatus({ id: this.taskId, status: 2 })
        }
      } else {
        await updateRpaTaskStatus({ id: this.taskId, status: 2 })
      }
    } catch (err) {
      rpaLogs.error('update rpa task update error ==>>>> ', err.message)
    }

    saveRpaLog(browserId, this.browserSeqMap.get(browserId), this.taskId, 3)
    rpaTaskPool.destroyTask(this.taskId)
  }

  // 主动关闭
  destroy() {
    this.pool.length = 0
    this.browserIds.length = 0
  }

  // 目前有正在运行的task，直接跳过
  isRuningAndSkip() {
    saveRpaLog(null, null, this.taskId, 4)
  }

  // 返回原始数据对象，传入指定 browserIds
  getRawData(browserIds = []) {
    return {
      id: this.taskId,
      workflowId: this.workflowId,
      type: this.type,
      intervalType: this.intervalType,
      concurrent: this.concurrent,
      browserIds,
      timeout: this.timeout
    }
  }
}
