import { messages } from '../interface/Messages'
import { streamJsonParse } from './streamJson'

export async function cookieFormat(cookies, hostname = '') {
  if (Array.isArray(cookies)) {
    return formatArrayCookies(cookies)
  } else {
    try {
      const arr = await streamJsonParse(cookies)
      return formatArrayCookies(arr)
    } catch (err) {
      return formatStrCookies(cookies, hostname)
    }
  }
}

function formatArrayCookies(cookies = []) {
  const everyIsObj = cookies.every(item => Object.prototype.toString.call(item) === '[object Object]')

  if (!cookies.length || !everyIsObj) {
    throw new Error(messages.getMessage('cookieFormatError'))
  }

  let newArr = cookies.map(item => {
    let obj = {}
    // 将所有key首字母转成小写
    for (let key of Object.keys(item)) {
      obj[key.replace(key[0], key[0].toLowerCase())] = item[key]
    }

    // 规范expires
    parseExpires(obj)

    // 如果有priority属性，删掉
    delete obj.priority
    delete obj.sameSite

    return obj
  })

  return newArr
}

// 用=;组合的字符串
function formatStrCookies(cookieStr = '', hostname) {
  const splitArr = cookieStr.split(/[(\r\n)\r\n]+/)
  // 如果换行分隔的数字结果大于1条，那么可以认为cookie是按照换行分隔的
  if (splitArr.length > 1) {
    return formatCookiesPerLine(splitArr, hostname)
  } else {
    // 移除有可能的 cookie: 前缀，然后分号; 分割
    let parseArr = cookieStr.replace('cookie:', '').split(';')
    parseArr = parseArr.filter(item => !!item && item.indexOf('=') > 0)

    if (!parseArr.length) throw new Error(messages.getMessage('cookieFormatError'))

    let cookieArr = []
    for (let item of parseArr) {
      const nameValues = item.split('=') // 有多个=时，只取第一个=分割的，全拼上会导致PayPal的cookie失效
      cookieArr.push({
        name: nameValues[0],
        value: nameValues[1],
        domain: '.' + hostname,
        path: '/',
        hostOnly: false,
        httpOnly: false,
        session: false,
        secure: false
      })
    }

    return cookieArr
  }
}

function parseExpires(obj) {
  ;['expires', 'expirationDate'].forEach(key => {
    if (obj.hasOwnProperty(key)) {
      // expires是null或者undefined的时候，设置为一年有效期
      if (!obj[key]) obj[key] = Math.floor(date.addToDate(new Date(), { year: 1 }).getTime() / 1000)
      // 数字类型，或者字符串数字，转为数字，日期类型，转为秒级数字
      if (/^\d+$/.test(obj[key])) {
        obj[key] = +obj[key]
      } else {
        obj[key] = new Date(obj[key]).getTime() / 1000
      }
    }
  })

  if (obj.hasOwnProperty('expiry') && /^\d+$/.test(obj.expiry)) obj.expiry = +obj.expiry
}

// 按照换行符分割每一项
function formatCookiesPerLine(splitArr = [], hostname) {
  let newArr = splitArr.map(item => {
    item = item.trim().replace(/^;|;$/g, '') // 去掉首尾的分号和空格

    // 中间以空格分割的数据，如 facebook.com True / True ...
    if (/\s/.test(item)) {
      const itemArr = item.split(/\s/)
      if (itemArr.length > 1) {
        return {
          domain: itemArr[0],
          hostOnly: itemArr[1].toLowerCase() === 'true',
          path: itemArr[2],
          secure: itemArr[3].toLowerCase() === 'true',
          expires: +itemArr[4],
          name: itemArr[5],
          value: itemArr[6]
        }
      }
    }

    // 以=号分割的，如 __bid=sdkdkk32233
    if (item.includes('=')) {
      const nameValues = item.split('=') // 有多个=时，只取第一个=分割的，全拼上会导致某些cookie失效
      return {
        name: nameValues[0],
        value: nameValues[1],
        domain: '.' + hostname,
        path: '/',
        hostOnly: false,
        httpOnly: false,
        session: false,
        secure: false
      }
    }
  })

  return newArr
}
